    }

    let req = plan(&cmd, &args.positional[1..], args.all)?;
    let res = send(&req, args.timeout_ms.unwrap_or(DEFAULT_TIMEOUT_MS))?;
    bsc_cli_util::emit(args.pretty, args.json, &res, || lean(&res));
