            let component = rest.get(1).ok_or("usage: bsc navigate component <kit> <component>")?;
            Ok(NavRequest {
                kit: Some(kit.clone()),
                component: Some(component.clone()),
                theme,
                state,
                force,
                ..Default::default()
            })
        }
        "workspace" => {
            let id = rest.first().ok_or("usage: bsc navigate workspace <id>")?;
            Ok(NavRequest { workspace: Some(id.clone()), theme, force, ..Default::default() })
        }
        "page" => {
            let id = rest.first().ok_or("usage: bsc navigate page <id>")?;
            Ok(NavRequest { page: Some(id.clone()), theme, force, ..Default::default() })
        }
        "theme" => {
            let id = rest.first().ok_or("usage: bsc navigate theme <id>")?;
            Ok(NavRequest { theme: Some(id.clone()), ..Default::default() })
        }
        "dismiss" => {
            let id = rest.first().ok_or("usage: bsc navigate dismiss <notice|all>")?;
            Ok(NavRequest { dismiss: Some(id.clone()), force, ..Default::default() })
        }
        "show" => Ok(NavRequest::default()),
        other => Err(format!("unknown command '{other}'")),
    }
}

pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    let args = parse_args(args)?;
    let cmd = args.positional.first().cloned().unwrap_or_default();

    if bsc_cli_util::handle_help(prog, TAGLINE, COMMANDS, &args.positional) {
        return Ok(());
    }
    if !COMMANDS.iter().any(|c| c.name == cmd) {
        return Err(bsc_cli_util::unknown_command(prog, TAGLINE, COMMANDS, &cmd));
    }

    let req = plan(&cmd, &args.positional[1..], args.theme.clone(), args.state.clone(), args.force)?;
    let res = send(&req, args.timeout_ms.unwrap_or(DEFAULT_TIMEOUT_MS))?;
    bsc_cli_util::emit(args.pretty, args.json, &res, || lean(&res));
    Ok(())
}

/// Steer to one component and return the view that actually landed — the reusable half of `send`,
/// exported for the baseline sweep (#a-baseline-sweep-walks-the-kit-itself).
///
/// It is EXPORTED rather than reimplemented on the caller's side because the request/reply round-trip
/// (stale sweep, id minting, the timeout message that tells you the app is not running) is the part a
/// second copy would get subtly wrong — and a duplicated resolver in this same preview stack is already
/// its own open item.
///
/// `force` is deliberately NOT a parameter. A sweep is the background loop the presence gate (#4248)
/// exists to stop, so it must never be able to take the screen from someone using the app.
pub fn navigate_component(kit: &str, component: &str, timeout: i64) -> Result<NavResult, String> {
    send(
        &NavRequest {
            kit: Some(kit.to_string()),
            component: Some(component.to_string()),
            ..Default::default()
        },
        timeout,
    )
}

/// Drop the request, wait for the frontend's ack, return the view that landed.
fn send(req: &NavRequest, timeout: i64) -> Result<NavResult, String> {
    let chan = bsc_appchan::chan_dir()?;
    let now = bsc_util::now_ms();
    let _ = bsc_appchan::sweep_stale(&chan, now, STALE_MS);

    let id = bsc_appchan::new_id(now);
    bsc_appchan::write_request(&chan, &id, KIND, now, req)?;

    let reply = bsc_appchan::poll_reply(&chan, &id, timeout, POLL_INTERVAL_MS, || {
        format!(
            "timed out after {timeout}ms waiting for the app to answer.\n\
             The request is at {}.\n\
             Is the desktop app running? `bsc` cannot navigate on its own — the app applies it. \
             `bsc shot pending` shows whether the request landed.",
            bsc_appchan::request_path(&chan, &id).display()
        )
    })?;
    bsc_appchan::take_payload(reply)
}

fn lean(r: &NavResult) -> String {
    let mut parts = vec![format!("workspace={}", r.workspace)];
    if let Some(p) = &r.page {
        parts.push(format!("page={p}"));
    }
    if let Some(k) = &r.kit {
        parts.push(format!("kit={k}"));
    }
    if let Some(c) = &r.component {
        parts.push(format!("component={c}"));
    }
    if let Some(t) = &r.theme {
        parts.push(format!("theme={t}"));
    }
    if let Some(st) = &r.state {
        parts.push(format!("state={st}"));
    }
    // The three fields a caller acts on go LAST and in full prose, because each one changes what the next
    // command should be. `mounted` is what a capture would actually photograph — printed only when it
    // disagrees with the selection, since agreement is the ordinary case and repeating it is noise.
    if r.mounted.is_some() && r.mounted != r.component {
        parts.push(format!("mounted={}", r.mounted.as_deref().unwrap_or("(nothing)")));
    }
    if let Some(e) = &r.mount_error {
        parts.push(format!("NOT ON SCREEN: {e}"));
    }
    if let Some(d) = &r.declined {
        parts.push(format!("DECLINED: {d}"));
    }
    // Printed even when EMPTY: "dismissed=(none)" is the answer to "did it work?" when no banner was up,
    // and silence would read as a failure.
    if let Some(ids) = &r.dismissed {
        parts.push(format!("dismissed={}", if ids.is_empty() { "(none)".into() } else { ids.join(",") }));
    }
    parts.join(" · ")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn s(v: &[&str]) -> Vec<String> {
        v.iter().map(|x| x.to_string()).collect()
    }

    #[test]
    fn component_takes_kit_and_component_and_can_carry_a_theme() {
        let r = plan("component", &s(&["react-d3", "Heatmap"]), Some("nord".into()), None, false).unwrap();
        assert_eq!(r.kit.as_deref(), Some("react-d3"));
        assert_eq!(r.component.as_deref(), Some("Heatmap"));
        assert_eq!(r.theme.as_deref(), Some("nord"));
        // It does NOT hard-code the workspace/page: the app resolves them, so a UI reorg can't strand
        // the CLI pointing at a page that moved.
        assert_eq!(r.workspace, None);
        assert_eq!(r.page, None);
    }

    #[test]
    fn component_carries_a_valid_state_and_rejects_a_bad_one_or_a_misplaced_flag() {
        // A valid state rides on the component request.
        let r = plan("component", &s(&["harvested", "mergequeue"]), None, Some("loading".into()), false).unwrap();
        assert_eq!(r.component.as_deref(), Some("mergequeue"));
        assert_eq!(r.state.as_deref(), Some("loading"));
        // An unknown state value fails fast at the CLI, naming the allowed set.
        let err = plan("component", &s(&["k", "c"]), None, Some("spinning".into()), false).unwrap_err();
        assert!(err.contains("loaded") && err.contains("empty") && err.contains("loading"), "{err}");
        // `--state` on a non-component command is refused (it is a component render axis).
        assert!(plan("theme", &s(&["nord"]), None, Some("loading".into()), false).is_err());
    }

    #[test]
    fn component_without_both_args_is_a_usage_error_not_a_partial_request() {
        assert!(plan("component", &s(&["react-d3"]), None, None, false).is_err());
        assert!(plan("component", &s(&[]), None, None, false).is_err());
    }

    #[test]
    fn workspace_page_and_theme_each_set_only_their_own_field() {
        assert_eq!(plan("workspace", &s(&["glance"]), None, None, false).unwrap().workspace.as_deref(), Some("glance"));
        assert_eq!(plan("page", &s(&["designs"]), None, None, false).unwrap().page.as_deref(), Some("designs"));
        let t = plan("theme", &s(&["nord"]), None, None, false).unwrap();
        assert_eq!(t.theme.as_deref(), Some("nord"));
        assert!(t.workspace.is_none() && t.page.is_none() && t.component.is_none());
    }

    #[test]
    fn show_asks_for_nothing_so_the_app_treats_it_as_a_read() {
        let r = plan("show", &s(&[]), None, None, false).unwrap();
        assert!(r.is_read_only(), "show must not mutate the view it is reporting");
    }

    #[test]
    fn unknown_flags_are_rejected_rather_than_ignored() {
        assert!(parse_args(s(&["component", "--nope"])).is_err());
    }

    #[test]
    fn the_lean_line_names_every_landed_field() {
        let out = lean(&NavResult {
            workspace: "projects".into(),
            page: Some("designs".into()),
            kit: Some("react-d3".into()),
            component: Some("Heatmap".into()),
            theme: Some("nord".into()),
            state: Some("loading".into()),
            declined: None,
            mounted: Some("Heatmap".into()),
            mount_error: None,
            dismissed: None,
        });
        assert_eq!(
            out,
            "workspace=projects · page=designs · kit=react-d3 · component=Heatmap · theme=nord · state=loading"
        );
    }

    #[test]
    fn the_lean_line_omits_what_did_not_land() {
        let out = lean(&NavResult {
            workspace: "console".into(),
            page: None,
            kit: None,
            component: None,
            theme: None,
            state: None,
            declined: None,
            mounted: None,
            mount_error: None,
            dismissed: None,
        });
        assert_eq!(out, "workspace=console");
    }

    /// `mounted` is printed only when it DISAGREES with the selection. Agreement is the ordinary case,
    /// and repeating it on every line would bury the disagreement that matters.
    #[test]
    fn the_lean_line_stays_quiet_when_the_mount_matches_the_selection() {
        let out = lean(&NavResult {
            workspace: "projects".into(),
            page: None,
            kit: None,
            component: Some("Heatmap".into()),
            theme: None,
            state: None,
            declined: None,
            mounted: Some("Heatmap".into()),
            mount_error: None,
            dismissed: None,
        });
        assert_eq!(out, "workspace=projects · component=Heatmap");
    }

    /// The whole point of the surface: a selection the preview never mounted must not read as a success.
    #[test]
    fn the_lean_line_says_what_is_not_on_screen_and_what_was_declined() {
        let out = lean(&NavResult {
            workspace: "github".into(),
            page: None,
            kit: None,
            component: Some("plan-body-deployment".into()),
            theme: None,
            state: None,
            declined: Some("view unchanged: the Studio is not showing".into()),
            mounted: None,
            mount_error: Some("the preview refused to build it".into()),
            dismissed: None,
        });
        assert!(out.contains("NOT ON SCREEN: the preview refused to build it"), "{out}");
        assert!(out.contains("DECLINED: view unchanged"), "{out}");
    }
}

