    #[test]
    fn compact_messages_leaves_a_short_conversation_unchanged() {
        let msgs = vec![
            Msg::User("hi".into()),
            Msg::Assistant { text: "hello".into(), tool_calls: vec![] },
        ];
        let (out, did) = compact_messages(10, msgs.clone(), 10_000, 100);
        assert!(!did, "well under budget ⇒ no compaction");
        assert_eq!(out.len(), msgs.len());
    }

    #[test]
    fn compact_messages_elides_the_middle_and_keeps_tool_pairing() {
        // task + 10 tool rounds (~100 tokens of content each) + a final turn; a tight budget forces
        // elision of the middle.
        let mut msgs = vec![Msg::User("TASK: do the thing".into())];
        for i in 0..10 {
            msgs.push(Msg::Assistant {
                text: String::new(),
                tool_calls: vec![ToolCall { id: format!("c{i}"), name: "read_file".into(), args: serde_json::json!({ "path": format!("file{i}") }) }],
            });
            msgs.push(Msg::ToolResult { id: format!("c{i}"), content: "x".repeat(400) });
        }
        msgs.push(Msg::User("FINAL question".into()));
        let before = msgs.len();

        let (out, did) = compact_messages(100, msgs, 600, 100); // usable = 500 tokens
        assert!(did, "over budget ⇒ compacts");
        assert!(out.len() < before, "the middle is elided");
        // Anchored: the original task first, then the elision marker.
        assert!(matches!(&out[0], Msg::User(s) if s.starts_with("TASK")));
        assert!(matches!(&out[1], Msg::User(s) if s.contains("elided")));
        // The most-recent turn survives.
        assert!(matches!(out.last(), Some(Msg::User(s)) if s.starts_with("FINAL")));
        // Pairing intact: every kept tool-result follows an assistant tool-call (or another result) —
        // never a dangling result whose call was elided.
        for w in out.windows(2) {
            if matches!(&w[1], Msg::ToolResult { .. }) {
                assert!(
                    matches!(&w[0], Msg::Assistant { tool_calls, .. } if !tool_calls.is_empty())
                        || matches!(&w[0], Msg::ToolResult { .. }),
                    "a kept tool-result must follow its assistant call (or another result)",
                );
            }
        }
        // Fits the usable budget after compaction.
        let after: usize = 100 + out.iter().map(msg_tokens).sum::<usize>();
        assert!(after <= 500, "compacted to within usable budget, got {after}");
    }

    #[test]
    fn compose_turn_system_injects_the_assigned_issues_and_they_survive_compaction() {
        // #3279: the worker's own open issues (stream-scoped) are folded into `system`, so the model
        // always sees them — and because they're in `system` and NOT in `messages`, `compact_messages`
        // (which only touches `messages`) can never elide them. This proves both halves. (Source moved
        // from the #3278-removed todo store to `plandb::scope::render_assigned_from_env`.)
        let block = "# Your open issues (stream 'ui') — work only these\n- [open] F1  Write the DDL";

        let sys = compose_turn_system("PROJECT CONTEXT", Some(block));
        assert!(sys.contains("PROJECT CONTEXT"));
        assert!(sys.contains("F1") && sys.contains("Write the DDL"));
        assert!(sys.contains(AGENT_INSTRUCTIONS), "the preamble is always present");
        assert!(sys.find(AGENT_INSTRUCTIONS) < sys.find("PROJECT CONTEXT"), "preamble comes first");

        // A None / blank block is omitted (prompt stays clean when there's nothing assigned).
        assert!(!compose_turn_system("PC", None).contains("F1"));
        assert!(!compose_turn_system("PC", Some("   ")).contains("Your open issues"));

        // Survives compaction: elide a long conversation, then confirm the block is STILL present in
        // the re-composed system for the next turn (it was never in `messages`).
        let mut msgs = vec![Msg::User("TASK".into())];
        for _ in 0..10 {
            msgs.push(Msg::Assistant { text: String::new(), tool_calls: vec![] });
            msgs.push(Msg::User("x".repeat(400)));
        }
        msgs.push(Msg::User("LATEST".into()));
        let (compacted, did) = compact_messages(estimate_tokens(&sys), msgs, 600, 100);
        assert!(did, "the middle was elided");
