import { describe, it, expect } from "vitest";
import {
  ROLE_DEFAULTS,
  type SessionRole,
  PLAN_WRITE_GLOBS,
  DOC_GLOBS,
  DB_OWNED_PLAN_FILES,
  DEP_MANIFEST_FILES,
  roleCapability,
