    fn the_ledger_shows_tax_only_where_it_is_not_a_settled_zero() {
        let usd = crate::money::Currency::USD;
        let (invoices, credits) = inv_fixture();
        let m = invoice::match_payments(&invoices, &credits, &invoice::MatchOptions::default());
        let s = invoice::settle(&invoices, &m, usd);
        let b = invoice::age(&s, &invoices, "2026-07-10", usd);
        let priced = vec![
            invoice::Priced {
                invoice: "INV-014".into(),
                net: crate::money::usd(240_000),
                tax: invoice::TaxOutcome::None { reason: "professional services are not taxable in Georgia".into(), source: "Georgia DOR".into() },
                total: Some(crate::money::usd(240_000)),
            },
            invoice::Priced {
                invoice: "INV-015".into(),
                net: crate::money::usd(240_000),
                tax: invoice::TaxOutcome::Charged { bps: 600, amount: crate::money::usd(14_400), sources: vec!["Georgia DOR".into()] },
                total: Some(crate::money::usd(254_400)),
            },
            invoice::Priced {
                invoice: "INV-016".into(),
                net: crate::money::usd(90_000),
                tax: invoice::TaxOutcome::Undetermined { what: "does not record WHAT was sold".into(), where_to: "use --supply".into() },
                total: None,
            },
        ];
        let out = render_invoices(&s, &b, &m, &priced, "2026-07-10");
        // The two that need an action get their own rows.
        assert!(out.contains("INV-015") && out.contains("144.00") && out.contains("at 6.00%"), "{out}");
        assert!(out.contains("UNDETERMINED") && out.contains("does not record WHAT was sold"), "{out}");
        assert!(out.contains("use --supply"), "the fix has to be on the report, not just in the docs: {out}");
        // The settled zero is ONE summary line, not a row that buries the other two.
        assert!(out.contains("1 invoice(s) carry none — professional services are not taxable in Georgia"), "{out}");
        // With nothing priced, the block is absent entirely rather than an empty heading.
        let bare = render_invoices(&s, &b, &m, &[], "2026-07-10");
        assert!(!bare.contains("  Tax\n"), "{bare}");
    }

