//! Statement ingest — read what a bank exports, without asking anyone what it is.
//!
//! THE INSTITUTION IS INFERRED FROM THE HEADER ROW, never from a flag. Partly because a flag is one
//! more thing to get wrong, and partly for a reason particular to this crate: the less the tool has
//! to be told about someone's accounts, the less of someone's accounts has to be said out loud.
//!
//! # The one contract every profile normalises to
//!
//! **A stored amount is signed from the ACCOUNT HOLDER's point of view: negative is money leaving.**
//!
//! That is not how the exports are written, and they disagree with each other, which is exactly why
//! this has to be stated once and enforced per profile:
//!
//! - Chase writes a purchase NEGATIVE.
//! - Discover writes a purchase POSITIVE — a charge is a positive number on the card's own terms.
//! - Capital One does not sign at all: it uses separate `Debit` and `Credit` columns.
//! - Bank of America signs like Chase, but its checking and card exports carry different columns.
//!
//! Get one of these backwards and every balance built on it is wrong by twice the amount, in the
//! direction that looks like good news. So the sign rule is per profile, named, and tested.
//!
//! # Nothing is dropped quietly
//!
//! A row that cannot be read is REPORTED, never skipped. A missing transaction is a wrong balance
//! that nobody can find by looking at the balance.
use crate::money::{money, parse_minor, Currency, Minor};

/// Which export this is. `Unknown` is a first-class outcome: a header nobody recognises should say so
/// rather than be forced through the closest-looking profile.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Institution {
    Chase,
    Discover,
    CapitalOne,
    BankOfAmerica,
    Unknown,
}

impl Institution {
    pub fn name(self) -> &'static str {
        match self {
            Institution::Chase => "chase",
            Institution::Discover => "discover",
            Institution::CapitalOne => "capital-one",
            Institution::BankOfAmerica => "bank-of-america",
            Institution::Unknown => "unknown",
        }
    }

    /// Where the export button actually lives, for a person about to go and click it.
    ///
    /// UNVERIFIED like the profiles themselves — written from published layouts. A menu path that
    /// has moved costs two minutes; a wrong COLUMN costs a wrong balance, which is why the caveats
    /// live on the profiles and this is only directions.
    pub fn export_path(self) -> &'static str {
        match self {
            Institution::Discover => "Account -> Statements & Activity -> Download Transactions (CSV)",
            Institution::CapitalOne => "Account -> View Transactions -> Download -> CSV (set the date range FIRST; the default is not the one you want)",
            Institution::BankOfAmerica => "Account -> Statements & Documents -> Download -> CSV (the file opens with a summary block above the header row)",
            Institution::Chase => "Account -> Download account activity -> CSV (chequing and card are DIFFERENT layouts; download each separately)",
            Institution::Unknown => "unknown institution",
        }
    }
}

/// How an export writes its dates. DECLARED per shape, never guessed: `03/04/2026` is 4 March or
/// 3 April and the file does not say, so a reader that guessed would move every transaction by weeks
/// half the time.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DateFormat {
    /// `YYYY-MM-DD` already.
    Iso,
    /// `MM/DD/YYYY` — every US institution here except Capital One.
    MonthDayYear,
}

/// Normalise to ISO, or `None` if the text is not that date in that format.
///
/// EVERYTHING DOWNSTREAM COMPARES DATES AS STRINGS, which is only correct for ISO. A raw
/// `06/20/2026` sorts before `2026-06-01`, so a balance would never roll forward and a coverage
/// check would report the wrong side as later — both silently, both producing plausible numbers.
pub fn to_iso(raw: &str, format: DateFormat) -> Option<String> {
    let t = raw.trim();
    let (y, m, d) = match format {
        DateFormat::Iso => {
            let mut it = t.split('-');
            (it.next()?.parse::<i64>().ok()?, it.next()?.parse::<i64>().ok()?, it.next()?.parse::<i64>().ok()?)
        }
        DateFormat::MonthDayYear => {
            let mut it = t.split(['/', '-']);
            let m = it.next()?.parse::<i64>().ok()?;
            let d = it.next()?.parse::<i64>().ok()?;
            let raw_y = it.next()?;
            let mut y = raw_y.parse::<i64>().ok()?;
            if raw_y.len() == 2 {
                y += if y >= 70 { 1900 } else { 2000 };
            }
            (y, m, d)
        }
    };
    if !(1..=12).contains(&m) || !(1..=31).contains(&d) || !(1000..=9999).contains(&y) {
        return None;
    }
    Some(format!("{y:04}-{m:02}-{d:02}"))
}

/// How one export lays its columns out, and which way its amounts point.
#[derive(Debug, Clone)]
pub struct Profile {
    pub institution: Institution,
    /// Human label for the report — which export shape matched.
    pub label: &'static str,
    /// Header names that must ALL be present for this profile to match, lowercased.
    pub required: &'static [&'static str],
    pub date: &'static str,
    pub description: &'static str,
    /// A single signed amount column…
    pub amount: Option<&'static str>,
    /// …or a separate debit/credit pair, which is Capital One's shape.
    pub debit_credit: Option<(&'static str, &'static str)>,
    /// TRUE when the export writes a purchase as a POSITIVE number, so the sign must be flipped to
    /// reach "negative is money leaving". Discover is the case this exists for.
    pub charge_is_positive: bool,
    /// A RUNNING BALANCE column, where the export carries one. It is what lets `reconcile` run at
    /// all: without it there is no opening and closing to check the transactions against, and every
    /// figure downstream is standing on an unverified ledger.
    pub balance: Option<&'static str>,
    /// How this export writes its dates, so they can be normalised to ISO at read time.
    pub date_format: DateFormat,
    /// WHICH KIND OF ACCOUNT this shape belongs to.
    ///
    /// Chase and Bank of America each export a CARD and a CHEQUING layout, and they are different
    /// ACCOUNTS — one where a positive balance is money owed and one where it is money held. The
    /// inbox names files by institution alone, so without this the two would collapse onto one id
    /// and a card balance would be added to a chequing balance.
    pub account_kind: crate::account::Kind,
}

/// The known export shapes.
///
/// DATA, not code, and deliberately: verifying these against a real export is a one-line correction
/// rather than a patch to a parser. They are written from published formats and SHOULD be checked
/// against an actual download before anyone trusts a balance built on them.
pub const PROFILES: &[Profile] = &[
    Profile {
        institution: Institution::CapitalOne,
        label: "capital-one (debit/credit columns)",
        required: &["transaction date", "description", "debit", "credit"],
        date: "transaction date",
        description: "description",
        amount: None,
        debit_credit: Some(("debit", "credit")),
        charge_is_positive: false,
        balance: None,
        date_format: DateFormat::Iso,
        account_kind: crate::account::Kind::Credit,
    },
    Profile {
        institution: Institution::Discover,
        label: "discover (charge positive)",
        required: &["trans. date", "description", "amount"],
        date: "trans. date",
        description: "description",
        amount: Some("amount"),
        debit_credit: None,
        // A charge is written POSITIVE. Without this flip every purchase would read as income.
        charge_is_positive: true,
        balance: None,
        date_format: DateFormat::MonthDayYear,
        account_kind: crate::account::Kind::Credit,
    },
    Profile {
        institution: Institution::Chase,
        label: "chase card",
        required: &["transaction date", "post date", "description", "amount"],
        date: "transaction date",
        description: "description",
        amount: Some("amount"),
        debit_credit: None,
        charge_is_positive: false,
        balance: None,
        date_format: DateFormat::MonthDayYear,
        account_kind: crate::account::Kind::Credit,
    },
    Profile {
        institution: Institution::Chase,
        label: "chase checking",
        required: &["posting date", "description", "amount"],
        date: "posting date",
        description: "description",
        amount: Some("amount"),
        debit_credit: None,
        charge_is_positive: false,
        balance: Some("balance"),
        date_format: DateFormat::MonthDayYear,
        account_kind: crate::account::Kind::Checking,
    },
    Profile {
        institution: Institution::BankOfAmerica,
        label: "bank-of-america card",
        required: &["posted date", "payee", "amount"],
        date: "posted date",
        description: "payee",
        amount: Some("amount"),
        debit_credit: None,
        charge_is_positive: false,
        balance: None,
        date_format: DateFormat::MonthDayYear,
        account_kind: crate::account::Kind::Credit,
    },
    Profile {
        institution: Institution::BankOfAmerica,
        label: "bank-of-america checking",
        required: &["date", "description", "amount", "running bal."],
        date: "date",
        description: "description",
        amount: Some("amount"),
        debit_credit: None,
        charge_is_positive: false,
        balance: Some("running bal."),
        date_format: DateFormat::MonthDayYear,
        account_kind: crate::account::Kind::Checking,
    },
];

/// One transaction, normalised.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Txn {
    /// ISO `YYYY-MM-DD`, NORMALISED HERE.
    ///
    /// This used to be "as written in the export", on the reasoning that normalising is a separate
    /// decision from reading. That was wrong once an analysis existed: everything downstream
    /// compares dates as STRINGS, which is only correct for ISO, so a raw `06/20/2026` sorted before
    /// `2026-06-01` and a balance silently never rolled forward. The shape declares its format, so
    /// this is a conversion rather than a guess.
    pub date: String,
    pub description: String,
    /// Minor units, NEGATIVE for money leaving the account holder.
    pub minor: Minor,
}

/// A row that could not be read, and why. Carried out rather than logged, so the caller decides.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rejected {
    /// 1-based line number in the file, counting the header — what a person would see in an editor.
    pub line: usize,
    pub reason: String,
}

/// The window a statement covers and the balances at each end, where the export carried a running
/// balance. The ACCOUNT and CURRENCY are absent on purpose — a row cannot know either, the same
/// reason `Txn::from_row` takes them.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PeriodBounds {
    pub opening: Minor,
    pub closing: Minor,
}

#[derive(Debug, Clone)]
pub struct Parsed {
    pub institution: Institution,
    pub profile: &'static str,
    /// The kind the matched shape says this is — carried out so a caller can offer to declare the
    /// account without re-deriving it from the label.
    pub account_kind: crate::account::Kind,
    pub txns: Vec<Txn>,
    pub rejected: Vec<Rejected>,
    /// Present only when the export carried a running balance. NONE means this file cannot be
    /// reconciled, which is a fact about the export rather than a failure.
    pub period: Option<PeriodBounds>,
}

/// The period a running-balance column asserts, SIGNED by the account's kind.
///
/// Two conversions happen here and both are load-bearing.
///
/// **The opening backs out the first row's own amount.** A running balance is stated AFTER the
/// transaction, so taking the first one as the opening double-counts the first row — and the
/// statement then fails to reconcile by exactly that amount, which reads as a missing transaction.
///
/// **The bounds are sign-normalised, because `reconcile` works in the SIGNED convention.** It checks
/// `opening + sum(txns) == closing`, and a transaction is already signed by whether money left the
/// holder. On a chequing account printed and signed coincide, which is exactly why this is easy to
/// get wrong and never notice: 1000 + (-600) = 400 either way. On a CARD they do not. A card prints
/// what you owe as a positive, so a 200 charge takes a printed 100 to a printed 300 while the signed
/// figures go -100 to -300 — and `100 + (-200) = -100`, not 300. Left printed, every card statement
/// that ever carried a running balance would fail to reconcile by twice the period's spending.
///
/// No packaged card profile carries a balance column TODAY, so this converts nothing in the shipped
/// set. It is here because the next profile someone adds must not have to know this.
pub fn period_from_running(running: &[(Minor, Minor)], kind: crate::account::Kind) -> Option<PeriodBounds> {
    let sign = |printed: Minor| crate::position::from_statement_balance(kind, money(printed, Currency::USD)).minor;
    match (running.first(), running.last()) {
        (Some((first_bal, first_amt)), Some((last_bal, _))) => {
            Some(PeriodBounds { opening: sign(first_bal - first_amt), closing: sign(*last_bal) })
        }
        _ => None,
    }
}

/// Split ONE csv line, honouring quoted fields.
///
/// A description containing a comma is not exotic — it is most of them ("SQUARE, INC"). Splitting on
/// every comma would shift every later column by one and put a date where an amount goes.
fn split_csv(line: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut quoted = false;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '"' if quoted && chars.peek() == Some(&'"') => {
                cur.push('"');
                chars.next();
            }
            '"' => quoted = !quoted,
            ',' if !quoted => out.push(std::mem::take(&mut cur)),
            c => cur.push(c),
        }
    }
    out.push(cur);
    out.into_iter().map(|s| s.trim().to_string()).collect()
}

/// The profile whose required columns are all present. Most specific first — `PROFILES` is ordered so
/// a shape with more required columns is tried before a looser one it would also satisfy.
pub fn detect(header: &[String]) -> Option<&'static Profile> {
    let have: Vec<String> = header.iter().map(|h| h.trim().to_lowercase()).collect();
    PROFILES.iter().find(|p| p.required.iter().all(|r| have.iter().any(|h| h == r)))
}

/// Parse a whole CSV export.
pub fn parse_csv(text: &str) -> Result<Parsed, String> {
    let mut lines = text.lines().enumerate().filter(|(_, l)| !l.trim().is_empty());
    let (header_line, header_raw) = lines.next().ok_or_else(|| "the file is empty".to_string())?;
    let header = split_csv(header_raw);
    let profile = detect(&header).ok_or_else(|| {
        format!(
            "no known export shape matches this header: [{}]. Add a Profile for it rather than \
             forcing it through the closest one — a mis-mapped column reads as a plausible number.",
            header.join(", ")
        )
    })?;

    let col = |name: &str| header.iter().position(|h| h.trim().eq_ignore_ascii_case(name));
    let (di, ci) = (col(profile.date), col(profile.description));
    let (Some(di), Some(ci)) = (di, ci) else {
        return Err(format!("{}: the header lost a column between detection and read", profile.label));
    };

    let mut txns = Vec::new();
    let mut rejected = Vec::new();
    // (running balance, that row's own amount) in file order, for the period derivation below.
    let mut running: Vec<(Minor, Minor)> = Vec::new();
    let balance_col = profile.balance.and_then(col);
    for (idx, raw) in lines {
        let line = idx + 1; // 1-based, as an editor shows it
        let f = split_csv(raw);
        let get = |i: usize| f.get(i).map(String::as_str).unwrap_or("").trim();
        if f.len() < header.len() {
            rejected.push(Rejected { line, reason: format!("{} columns, expected {}", f.len(), header.len()) });
            continue;
        }
        let minor = match (profile.amount, profile.debit_credit) {
            (Some(a), _) => {
                let Some(ai) = col(a) else {
                    rejected.push(Rejected { line, reason: format!("no `{a}` column") });
                    continue;
                };
                match parse_minor(get(ai)) {
                    Ok(v) => {
                        // Discover's convention: a charge is written positive. Flip so the store's
                        // rule holds — negative is money leaving.
                        if profile.charge_is_positive { -v } else { v }
                    }
                    Err(e) => {
                        rejected.push(Rejected { line, reason: e });
                        continue;
                    }
                }
            }
            (None, Some((d, c))) => {
                // Capital One: exactly one of the two carries a value. Both, or neither, is a row
                // this parser does not understand — and guessing which to believe would be inventing
                // a transaction.
                let (Some(dbi), Some(cri)) = (col(d), col(c)) else {
                    rejected.push(Rejected { line, reason: format!("no `{d}`/`{c}` columns") });
                    continue;
                };
                let (dv, cv) = (get(dbi), get(cri));
                match (dv.is_empty(), cv.is_empty()) {
                    (false, true) => match parse_minor(dv) {
                        Ok(v) => -v.abs(), // a debit is money leaving
                        Err(e) => { rejected.push(Rejected { line, reason: e }); continue; }
                    },
                    (true, false) => match parse_minor(cv) {
                        Ok(v) => v.abs(), // a credit is money arriving
                        Err(e) => { rejected.push(Rejected { line, reason: e }); continue; }
                    },
                    (true, true) => { rejected.push(Rejected { line, reason: "neither debit nor credit has a value".into() }); continue; }
                    (false, false) => { rejected.push(Rejected { line, reason: "both debit and credit have values".into() }); continue; }
                }
            }
            (None, None) => return Err(format!("{}: profile declares no amount column", profile.label)),
        };
        let Some(date) = to_iso(get(di), profile.date_format) else {
            rejected.push(Rejected { line, reason: format!("`{}` is not a date this shape writes", get(di)) });
            continue;
        };
        if date.is_empty() {
            rejected.push(Rejected { line, reason: "no date".into() });
            continue;
        }
        if let Some(bi) = balance_col {
            if let Ok(b) = parse_minor(get(bi)) {
                running.push((b, minor));
            }
        }
        txns.push(Txn { date, description: get(ci).to_string(), minor });
    }
    let _ = header_line;

    let period = period_from_running(&running, profile.account_kind);
    Ok(Parsed { institution: profile.institution, profile: profile.label, account_kind: profile.account_kind, txns, rejected, period })
}

/// The account id a matched shape suggests.
///
/// THE INBOX NAMES FILES BY INSTITUTION ALONE, and Chase and Bank of America each export a card and
/// a chequing layout. `chase-june.csv` and `chase-checking-june.csv` both read as "chase", so
/// without a wider id the two would collapse onto one account — and a card balance, where positive
/// means OWED, would be added to a chequing balance, where it means HELD. The profile knows which
/// shape it matched, so the id comes from there rather than from the filename.
pub fn suggested_account_id(p: &Parsed) -> String {
    let kind = p.account_kind.as_str();
    // A chequing account at an institution that exports only one shape needs no suffix; the two
    // that export both do.
    let ambiguous = PROFILES.iter().filter(|x| x.institution == p.institution).count() > 1;
    if ambiguous {
        format!("{}-{}", p.institution.name(), kind)
    } else {
        p.institution.name().to_string()
    }
}

#[cfg(test)]
mod tests {

    #[test]
    fn a_running_balance_becomes_a_period_that_actually_reconciles() {
        // Reference taken by running `ingest.ts` on this exact CSV: opening 100000, closing 40000.
        let csv = "Date,Description,Amount,Running Bal.\n\
06/03/2026,\"OPENING SPEND\",-100.00,\"900.00\"\n\
06/10/2026,\"PAY\",1000.00,\"1,900.00\"\n\
06/20/2026,\"RENT\",-1500.00,\"400.00\"\n";
        let p = parse_csv(csv).unwrap();
        let b = p.period.expect("a running balance should produce a period");
        assert_eq!(b.opening, 100_000, "the opening backs out the first row's own amount");
        assert_eq!(b.closing, 40_000);

        // And the whole point: it reconciles. If the sign, the amounts or the opening derivation
        // were wrong, this would not balance.
        let txns: Vec<crate::txn::Txn> = p
            .txns
            .iter()
            .map(|r| crate::txn::Txn::from_row(r, "checking", crate::money::Currency::USD))
            .collect();
        let period = crate::reconcile::usd_period("checking", &txns[0].date, &txns[txns.len() - 1].date, b.opening, b.closing);
        let rec = crate::reconcile::reconcile(&txns, &[period]);
        assert!(rec.ok, "{:?}", rec.problems);
        assert!(rec.ledger.is_some());
    }

    #[test]
    fn taking_the_running_balance_as_the_opening_would_double_count_the_first_row() {
        // Stated AFTER the transaction. Using it directly leaves the statement out by exactly that
        // first amount, which reads as a missing transaction rather than as a derivation bug.
        let csv = "Date,Description,Amount,Running Bal.\n06/03/2026,X,-100.00,\"900.00\"\n";
        let b = parse_csv(csv).unwrap().period.unwrap();
        assert_eq!(b.opening, 100_000);
        assert_ne!(b.opening, 90_000, "90000 is the running balance itself, not the opening");
    }

    #[test]
    fn a_card_periods_bounds_come_back_signed_so_reconcile_can_use_them() {
        use crate::account::Kind;
        // A card printing 100 owed, then 300 owed after a 200 charge. The rows are (running, amount)
        // in the PRINTED convention the export uses; the amount is already signed, as every Txn is.
        let running = vec![(10_000, 0), (30_000, -20_000)];
        let b = super::period_from_running(&running, Kind::Credit).expect("two rows is a period");
        // Printed 100 owed is -10000 to net worth, printed 300 owed is -30000.
        assert_eq!(b.opening, -10_000, "the opening must be NEGATED for a debt account");
        assert_eq!(b.closing, -30_000, "the closing must be NEGATED for a debt account");
        // And it reconciles: -10000 + (-20000) = -30000. Left printed it would not.
        assert_eq!(b.opening + (-20_000), b.closing, "signed bounds are what makes the arithmetic close");
    }

    #[test]
    fn a_chequing_periods_bounds_are_unchanged_because_printed_and_signed_agree_there() {
        use crate::account::Kind;
        let running = vec![(90_000, -10_000), (40_000, -30_000)];
        let b = super::period_from_running(&running, Kind::Checking).expect("two rows is a period");
        assert_eq!(b.opening, 100_000);
        assert_eq!(b.closing, 40_000);
    }

    #[test]
    fn a_card_export_carries_no_running_balance_and_says_so_by_absence() {
        // A fact about the export, not a failure: a card statement simply does not print one, so
        // that file cannot be reconciled and the ledger built from it is honestly unverified.
        let p = parse_csv("Trans. Date,Description,Amount\n06/03/2026,X,10.00\n").unwrap();
        assert!(p.period.is_none());
        for prof in PROFILES {
            assert_eq!(prof.balance.is_some(), prof.account_kind == crate::account::Kind::Checking, "{}", prof.label);
        }
    }

    #[test]
    fn every_parsed_date_comes_out_as_iso_whatever_the_export_wrote() {
        // THE BUG THIS EXISTS FOR, found by running the thing rather than by any of 152 tests: the
        // parser kept dates as written, and everything downstream compares them as STRINGS. A raw
        // `06/20/2026` sorts BEFORE `2026-06-01`, so a balance never rolled forward and a coverage
        // check reported the wrong side as later — both silently, both plausible.
        let discover = parse_csv("Trans. Date,Description,Amount\n06/20/2026,X,10.00\n").unwrap();
        assert_eq!(discover.txns[0].date, "2026-06-20");
        let cap = parse_csv("Transaction Date,Description,Debit,Credit\n2026-06-20,X,10.00,\n").unwrap();
        assert_eq!(cap.txns[0].date, "2026-06-20");
        // And ISO is what makes a string comparison correct at all.
        assert!("2026-06-01" < "2026-06-20");
    }

    #[test]
    fn every_profile_declares_how_it_writes_dates() {
        // Nothing guesses. `03/04/2026` is 4 March or 3 April and the file does not say.
        for p in PROFILES {
            let sample = match p.date_format {
                DateFormat::Iso => "2026-03-04",
                DateFormat::MonthDayYear => "03/04/2026",
            };
            assert_eq!(to_iso(sample, p.date_format).as_deref(), Some("2026-03-04"), "{}", p.label);
        }
    }

    #[test]
    fn a_date_the_shape_cannot_write_is_rejected_rather_than_kept_raw() {
        let r = parse_csv("Trans. Date,Description,Amount\n2026-06-20,X,10.00\n").unwrap();
        assert_eq!(r.txns.len(), 0);
        assert_eq!(r.rejected.len(), 1);
        assert!(r.rejected[0].reason.contains("not a date this shape writes"), "{}", r.rejected[0].reason);
    }

    #[test]
    fn to_iso_refuses_a_month_or_day_that_cannot_exist() {
        assert_eq!(to_iso("13/01/2026", DateFormat::MonthDayYear), None);
        assert_eq!(to_iso("06/32/2026", DateFormat::MonthDayYear), None);
        assert_eq!(to_iso("not a date", DateFormat::MonthDayYear), None);
        // Two-digit years, which several exports still emit.
        assert_eq!(to_iso("06/20/26", DateFormat::MonthDayYear).as_deref(), Some("2026-06-20"));
    }

    #[test]
    fn every_profile_declares_which_kind_of_account_it_is() {
        // A card and a chequing export are different ACCOUNTS: positive means OWED in one and HELD
        // in the other, so a shape that did not say which would let the two be added together.
        for p in PROFILES {
            assert!(
                matches!(p.account_kind, crate::account::Kind::Credit | crate::account::Kind::Checking),
                "{} declares neither credit nor checking",
                p.label
            );
        }
    }

    #[test]
    fn an_institution_with_two_shapes_declares_one_of_each() {
        // Chase and Bank of America each export both. If both shapes claimed the same kind, the
        // suggested ids would collide and a card balance would be summed with a chequing balance.
        for inst in [Institution::Chase, Institution::BankOfAmerica] {
            let kinds: Vec<_> = PROFILES.iter().filter(|p| p.institution == inst).map(|p| p.account_kind).collect();
            assert_eq!(kinds.len(), 2, "{}", inst.name());
            assert!(kinds.contains(&crate::account::Kind::Credit), "{}", inst.name());
            assert!(kinds.contains(&crate::account::Kind::Checking), "{}", inst.name());
        }
    }

    #[test]
    fn post_date_versus_posting_date_is_what_separates_a_chase_card_from_chase_chequing() {
        // ONE WORD, and it is the only thing distinguishing the two. Anybody "tidying" these header
        // strings would silently route a card export through the chequing profile — which parses
        // without complaint and produces a balance with the wrong sign convention behind it.
        let card = parse_csv("Transaction Date,Post Date,Description,Amount\n06/03/2026,06/04/2026,X,-10.00\n").unwrap();
        let chq = parse_csv("Posting Date,Description,Amount,Balance\n06/03/2026,X,-10.00,100.00\n").unwrap();
        assert_eq!(card.profile, "chase card");
        assert_eq!(chq.profile, "chase checking");
        assert_eq!(card.account_kind, crate::account::Kind::Credit);
        assert_eq!(chq.account_kind, crate::account::Kind::Checking);
    }

    #[test]
    fn an_institution_exporting_two_shapes_gets_two_account_ids() {
        // chase-june.csv and chase-checking-june.csv both read as "chase" from the filename alone.
        let card = parse_csv("Transaction Date,Post Date,Description,Amount\n06/03/2026,06/04/2026,X,-10.00\n").unwrap();
        let chq = parse_csv("Posting Date,Description,Amount,Balance\n06/03/2026,X,-10.00,100.00\n").unwrap();
        assert_eq!(suggested_account_id(&card), "chase-credit");
        assert_eq!(suggested_account_id(&chq), "chase-checking");
    }

    #[test]
    fn a_single_shape_institution_needs_no_suffix() {
        let p = parse_csv("Trans. Date,Description,Amount\n06/03/2026,X,10.00\n").unwrap();
        assert_eq!(p.institution, Institution::Discover);
        assert_eq!(suggested_account_id(&p), "discover");
    }

    #[test]
    fn every_institution_says_where_its_export_button_is() {
        // The whole system is idle until a file lands, so directions to the button are load-bearing
        // rather than decorative. An institution with no path is one somebody cannot act on.
        for i in [Institution::Discover, Institution::CapitalOne, Institution::BankOfAmerica, Institution::Chase] {
            let p = i.export_path();
            assert!(p.len() > 20, "{}: {p}", i.name());
            assert!(p.contains("CSV"), "{}: {p}", i.name());
        }
        assert_eq!(Institution::Unknown.export_path(), "unknown institution");
    }

    #[test]
    fn the_two_export_traps_are_stated_where_a_person_will_read_them() {
        // Capital One's default date range and Chase's two different layouts are the two ways a
        // download goes wrong BEFORE the parser ever sees it, so they belong in the directions.
        assert!(Institution::CapitalOne.export_path().contains("date range"));
        assert!(Institution::Chase.export_path().contains("DIFFERENT layouts"));
    }


    use super::*;

    // EVERY FIXTURE IS SYNTHETIC — invented merchants, round-ish amounts, no account numbers. The
    // maintainer's statements never enter this repo, and a test that needed a real one would be
    // telling us the design is wrong.

    #[test]
    fn a_quoted_comma_does_not_shift_every_later_column() {
        // "SQUARE, INC" is most descriptions, not an exotic case. Splitting on every comma puts a
        // date where an amount goes, and the row still parses — as a plausible wrong number.
        let f = split_csv(r#"01/02/2026,"SQUARE, INC",-12.34"#);
        assert_eq!(f, vec!["01/02/2026", "SQUARE, INC", "-12.34"]);
        assert_eq!(split_csv(r#""a""b",c"#), vec![r#"a"b"#, "c"]);
    }

    #[test]
    fn chase_a_purchase_is_money_leaving() {
        let csv = "Transaction Date,Post Date,Description,Category,Type,Amount,Memo\n\
                   01/02/2026,01/03/2026,COFFEE BAR,Food,Sale,-4.50,\n\
                   01/04/2026,01/05/2026,PAYMENT THANK YOU,,Payment,250.00,\n";
        let p = parse_csv(csv).unwrap();
        assert_eq!(p.institution, Institution::Chase);
        assert_eq!(p.txns[0].minor, -450, "a purchase must be negative");
        assert_eq!(p.txns[1].minor, 25000, "a payment to the card is money arriving on it");
        assert!(p.rejected.is_empty());
    }

    #[test]
    fn discover_writes_a_charge_positive_and_it_is_flipped() {
        // THE SIGN BUG THIS FILE EXISTS FOR. Without the flip every Discover purchase reads as
        // income, and the balance is wrong by twice the amount in the direction that looks like good
        // news — which is the direction nobody double-checks.
        let csv = "Trans. Date,Post Date,Description,Amount,Category\n\
                   01/02/2026,01/03/2026,HARDWARE STORE,89.99,Merchandise\n\
                   01/06/2026,01/06/2026,DIRECTPAY FULL BALANCE,-200.00,Payments\n";
        let p = parse_csv(csv).unwrap();
        assert_eq!(p.institution, Institution::Discover);
        assert_eq!(p.txns[0].minor, -8999, "a Discover charge is written positive and must flip");
        assert_eq!(p.txns[1].minor, 20000, "and a payment flips the other way");
    }

    #[test]
    fn capital_one_uses_separate_debit_and_credit_columns() {
        let csv = "Transaction Date,Posted Date,Card No.,Description,Category,Debit,Credit\n\
                   2026-01-02,2026-01-03,1234,GROCERY,Merchandise,54.20,\n\
                   2026-01-05,2026-01-06,1234,CREDIT BALANCE REFUND,Other,,15.00\n";
        let p = parse_csv(csv).unwrap();
        assert_eq!(p.institution, Institution::CapitalOne);
        assert_eq!(p.txns[0].minor, -5420, "a debit is money leaving");
        assert_eq!(p.txns[1].minor, 1500, "a credit is money arriving");
    }

    #[test]
    fn capital_one_refuses_a_row_that_fills_both_or_neither() {
        // Guessing which column to believe would be inventing a transaction.
        let csv = "Transaction Date,Posted Date,Card No.,Description,Category,Debit,Credit\n\
                   2026-01-02,2026-01-03,1234,BOTH,Other,10.00,10.00\n\
                   2026-01-04,2026-01-05,1234,NEITHER,Other,,\n";
        let p = parse_csv(csv).unwrap();
        assert!(p.txns.is_empty());
        assert_eq!(p.rejected.len(), 2);
        assert!(p.rejected[0].reason.contains("both"));
        assert!(p.rejected[1].reason.contains("neither"));
    }

    #[test]
    fn bank_of_america_checking_and_card_are_different_shapes() {
        let checking = "Date,Description,Amount,Running Bal.\n01/02/2026,RENT,-1450.00,3210.55\n";
        assert_eq!(parse_csv(checking).unwrap().institution, Institution::BankOfAmerica);
        let card = "Posted Date,Reference Number,Payee,Address,Amount\n01/02/2026,000123,PHARMACY,,-23.40\n";
        let p = parse_csv(card).unwrap();
        assert_eq!(p.institution, Institution::BankOfAmerica);
        assert_eq!(p.txns[0].description, "PHARMACY", "the card export calls it Payee, not Description");
    }

    #[test]
    fn an_unreadable_row_is_reported_not_dropped() {
        // A row that silently vanishes is a wrong balance nobody can find by looking at the balance.
        let csv = "Transaction Date,Post Date,Description,Category,Type,Amount,Memo\n\
                   01/02/2026,01/03/2026,GOOD,Food,Sale,-4.50,\n\
                   01/04/2026,01/05/2026,BAD AMOUNT,Food,Sale,N/A,\n\
                   ,01/06/2026,NO DATE,Food,Sale,-1.00,\n";
        let p = parse_csv(csv).unwrap();
        assert_eq!(p.txns.len(), 1);
        assert_eq!(p.rejected.len(), 2);
        // The line number is what a person would see in an editor, header included.
        assert_eq!(p.rejected[0].line, 3);
        assert_eq!(p.rejected[1].line, 4);
    }

    #[test]
    fn an_unknown_header_says_so_rather_than_guessing() {
        // Forcing an unrecognised export through the closest-looking profile produces numbers that
        // are wrong and plausible, which is the worst combination available.
        let err = parse_csv("Foo,Bar,Baz\n1,2,3\n").unwrap_err();
        assert!(err.contains("no known export shape"), "{err}");
        assert!(err.contains("Foo"), "the error must show the header it could not place");
    }

    #[test]
    fn every_profile_is_reachable_and_distinct() {
        // A profile no header can select is dead configuration that reads as coverage. Each one's own
        // required columns must select IT — if a looser profile shadows a stricter one, ordering is
        // wrong and some institution silently parses as another.
        for p in PROFILES {
            let header: Vec<String> = p.required.iter().map(|s| s.to_string()).collect();
            let got = detect(&header).unwrap_or_else(|| panic!("{} matches no profile", p.label));
            assert_eq!(got.label, p.label, "{} is shadowed by {}", p.label, got.label);
        }
    }

    #[test]
    fn the_empty_file_is_an_error_not_an_empty_statement() {
        // An empty result would read as "this account had no activity", which is a different claim.
        assert!(parse_csv("").is_err());
        assert!(parse_csv("   \n\n").is_err());
    }
}

tests.src:
//! Statement ingest — read what a bank exports, without asking anyone what it is.
//!
//! THE INSTITUTION IS INFERRED FROM THE HEADER ROW, never from a flag. Partly because a flag is one
//! more thing to get wrong, and partly for a reason particular to this crate: the less the tool has
//! to be told about someone's accounts, the less of someone's accounts has to be said out loud.
//!
//! # The one contract every profile normalises to
//!
//! **A stored amount is signed from the ACCOUNT HOLDER's point of view: negative is money leaving.**
//!
//! That is not how the exports are written, and they disagree with each other, which is exactly why
//! this has to be stated once and enforced per profile:
//!
//! - Chase writes a purchase NEGATIVE.
//! - Discover writes a purchase POSITIVE — a charge is a positive number on the card's own terms.
//! - Capital One does not sign at all: it uses separate `Debit` and `Credit` columns.
//! - Bank of America signs like Chase, but its checking and card exports carry different columns.
//!
//! Get one of these backwards and every balance built on it is wrong by twice the amount, in the
//! direction that looks like good news. So the sign rule is per profile, named, and tested.
//!
//! # Nothing is dropped quietly
//!
//! A row that cannot be read is REPORTED, never skipped. A missing transaction is a wrong balance
//! that nobody can find by looking at the balance.
use crate::money::{parse_minor, Minor};

/// Which export this is. `Unknown` is a first-class outcome: a header nobody recognises should say so
/// rather than be forced through the closest-looking profile.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Institution {
    Chase,
    Discover,
    CapitalOne,
    BankOfAmerica,
    Unknown,
}

impl Institution {
    pub fn name(self) -> &'static str {
        match self {
            Institution::Chase => "chase",
            Institution::Discover => "discover",
            Institution::CapitalOne => "capital-one",
            Institution::BankOfAmerica => "bank-of-america",
            Institution::Unknown => "unknown",
        }
    }
}

/// How one export lays its columns out, and which way its amounts point.
#[derive(Debug, Clone)]
pub struct Profile {
    pub institution: Institution,
    /// Human label for the report — which export shape matched.
    pub label: &'static str,
    /// Header names that must ALL be present for this profile to match, lowercased.
    pub required: &'static [&'static str],
    pub date: &'static str,
    pub description: &'static str,
    /// A single signed amount column…
    pub amount: Option<&'static str>,
    /// …or a separate debit/credit pair, which is Capital One's shape.
    pub debit_credit: Option<(&'static str, &'static str)>,
    /// TRUE when the export writes a purchase as a POSITIVE number, so the sign must be flipped to
    /// reach "negative is money leaving". Discover is the case this exists for.
    pub charge_is_positive: bool,
}

/// The known export shapes.
///
/// DATA, not code, and deliberately: verifying these against a real export is a one-line correction
/// rather than a patch to a parser. They are written from published formats and SHOULD be checked
/// against an actual download before anyone trusts a balance built on them.
pub const PROFILES: &[Profile] = &[
    Profile {
        institution: Institution::CapitalOne,
        label: "capital-one (debit/credit columns)",
        required: &["transaction date", "description", "debit", "credit"],
        date: "transaction date",
        description: "description",
        amount: None,
        debit_credit: Some(("debit", "credit")),
        charge_is_positive: false,
    },
    Profile {
        institution: Institution::Discover,
        label: "discover (charge positive)",
        required: &["trans. date", "description", "amount"],
        date: "trans. date",
        description: "description",
        amount: Some("amount"),
        debit_credit: None,
        // A charge is written POSITIVE. Without this flip every purchase would read as income.
        charge_is_positive: true,
    },
    Profile {
        institution: Institution::Chase,
        label: "chase card",
        required: &["transaction date", "post date", "description", "amount"],
        date: "transaction date",
        description: "description",
        amount: Some("amount"),
        debit_credit: None,
        charge_is_positive: false,
    },
    Profile {
        institution: Institution::Chase,
        label: "chase checking",
        required: &["posting date", "description", "amount"],
        date: "posting date",
        description: "description",
        amount: Some("amount"),
        debit_credit: None,
        charge_is_positive: false,
    },
    Profile {
        institution: Institution::BankOfAmerica,
        label: "bank-of-america card",
        required: &["posted date", "payee", "amount"],
        date: "posted date",
        description: "payee",
        amount: Some("amount"),
        debit_credit: None,
        charge_is_positive: false,
    },
    Profile {
        institution: Institution::BankOfAmerica,
        label: "bank-of-america checking",
        required: &["date", "description", "amount", "running bal."],
        date: "date",
        description: "description",
        amount: Some("amount"),
        debit_credit: None,
        charge_is_positive: false,
    },
];

/// One transaction, normalised.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Txn {
    /// As written in the export. Not reformatted here — normalising a date is a separate decision
    /// from reading one, and guessing between `01/02` conventions silently is how a year goes wrong.
    pub date: String,
    pub description: String,
    /// Minor units, NEGATIVE for money leaving the account holder.
    pub minor: Minor,
}

/// A row that could not be read, and why. Carried out rather than logged, so the caller decides.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rejected {
    /// 1-based line number in the file, counting the header — what a person would see in an editor.
    pub line: usize,
    pub reason: String,
}

#[derive(Debug, Clone)]
pub struct Parsed {
    pub institution: Institution,
    pub profile: &'static str,
    pub txns: Vec<Txn>,
    pub rejected: Vec<Rejected>,
}

/// Split ONE csv line, honouring quoted fields.
///
/// A description containing a comma is not exotic — it is most of them ("SQUARE, INC"). Splitting on
/// every comma would shift every later column by one and put a date where an amount goes.
fn split_csv(line: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut quoted = false;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '"' if quoted && chars.peek() == Some(&'"') => {
                cur.push('"');
                chars.next();
            }
            '"' => quoted = !quoted,
            ',' if !quoted => out.push(std::mem::take(&mut cur)),
            c => cur.push(c),
        }
    }
    out.push(cur);
    out.into_iter().map(|s| s.trim().to_string()).collect()
}

/// The profile whose required columns are all present. Most specific first — `PROFILES` is ordered so
/// a shape with more required columns is tried before a looser one it would also satisfy.
pub fn detect(header: &[String]) -> Option<&'static Profile> {
    let have: Vec<String> = header.iter().map(|h| h.trim().to_lowercase()).collect();
    PROFILES.iter().find(|p| p.required.iter().all(|r| have.iter().any(|h| h == r)))
}

/// Parse a whole CSV export.
pub fn parse_csv(text: &str) -> Result<Parsed, String> {
    let mut lines = text.lines().enumerate().filter(|(_, l)| !l.trim().is_empty());
    let (header_line, header_raw) = lines.next().ok_or_else(|| "the file is empty".to_string())?;
    let header = split_csv(header_raw);
    let profile = detect(&header).ok_or_else(|| {
        format!(
            "no known export shape matches this header: [{}]. Add a Profile for it rather than \
             forcing it through the closest one — a mis-mapped column reads as a plausible number.",
            header.join(", ")
        )
    })?;

    let col = |name: &str| header.iter().position(|h| h.trim().eq_ignore_ascii_case(name));
    let (di, ci) = (col(profile.date), col(profile.description));
    let (Some(di), Some(ci)) = (di, ci) else {
        return Err(format!("{}: the header lost a column between detection and read", profile.label));
    };

    let mut txns = Vec::new();
    let mut rejected = Vec::new();
    for (idx, raw) in lines {
        let line = idx + 1; // 1-based, as an editor shows it
        let f = split_csv(raw);
        let get = |i: usize| f.get(i).map(String::as_str).unwrap_or("").trim();
        if f.len() < header.len() {
            rejected.push(Rejected { line, reason: format!("{} columns, expected {}", f.len(), header.len()) });
            continue;
        }
        let minor = match (profile.amount, profile.debit_credit) {
            (Some(a), _) => {
                let Some(ai) = col(a) else {
                    rejected.push(Rejected { line, reason: format!("no `{a}` column") });
                    continue;
                };
                match parse_minor(get(ai)) {
                    Ok(v) => {
                        // Discover's convention: a charge is written positive. Flip so the store's
                        // rule holds — negative is money leaving.
                        if profile.charge_is_positive { -v } else { v }
                    }
                    Err(e) => {
                        rejected.push(Rejected { line, reason: e });
                        continue;
                    }
                }
            }
            (None, Some((d, c))) => {
                // Capital One: exactly one of the two carries a value. Both, or neither, is a row
                // this parser does not understand — and guessing which to believe would be inventing
                // a transaction.
                let (Some(dbi), Some(cri)) = (col(d), col(c)) else {
                    rejected.push(Rejected { line, reason: format!("no `{d}`/`{c}` columns") });
                    continue;
                };
                let (dv, cv) = (get(dbi), get(cri));
                match (dv.is_empty(), cv.is_empty()) {
                    (false, true) => match parse_minor(dv) {
                        Ok(v) => -v.abs(), // a debit is money leaving
                        Err(e) => { rejected.push(Rejected { line, reason: e }); continue; }
                    },
                    (true, false) => match parse_minor(cv) {
                        Ok(v) => v.abs(), // a credit is money arriving
                        Err(e) => { rejected.push(Rejected { line, reason: e }); continue; }
                    },
                    (true, true) => { rejected.push(Rejected { line, reason: "neither debit nor credit has a value".into() }); continue; }
                    (false, false) => { rejected.push(Rejected { line, reason: "both debit and credit have values".into() }); continue; }
                }
            }
            (None, None) => return Err(format!("{}: profile declares no amount column", profile.label)),
        };
        let date = get(di).to_string();
        if date.is_empty() {
            rejected.push(Rejected { line, reason: "no date".into() });
            continue;
        }
        txns.push(Txn { date, description: get(ci).to_string(), minor });
    }
    let _ = header_line;
    Ok(Parsed { institution: profile.institution, profile: profile.label, txns, rejected })
}

#[cfg(test)]
mod tests {
    use super::*;

    // EVERY FIXTURE IS SYNTHETIC — invented merchants, round-ish amounts, no account numbers. The
    // maintainer's statements never enter this repo, and a test that needed a real one would be
    // telling us the design is wrong.

    #[test]
    fn a_quoted_comma_does_not_shift_every_later_column() {
        // "SQUARE, INC" is most descriptions, not an exotic case. Splitting on every comma puts a
        // date where an amount goes, and the row still parses — as a plausible wrong number.
        let f = split_csv(r#"01/02/2026,"SQUARE, INC",-12.34"#);
        assert_eq!(f, vec!["01/02/2026", "SQUARE, INC", "-12.34"]);
        assert_eq!(split_csv(r#""a""b",c"#), vec![r#"a"b"#, "c"]);
    }

    #[test]
    fn chase_a_purchase_is_money_leaving() {
        let csv = "Transaction Date,Post Date,Description,Category,Type,Amount,Memo\n\
                   01/02/2026,01/03/2026,COFFEE BAR,Food,Sale,-4.50,\n\
                   01/04/2026,01/05/2026,PAYMENT THANK YOU,,Payment,250.00,\n";
        let p = parse_csv(csv).unwrap();
        assert_eq!(p.institution, Institution::Chase);
        assert_eq!(p.txns[0].minor, -450, "a purchase must be negative");
        assert_eq!(p.txns[1].minor, 25000, "a payment to the card is money arriving on it");
        assert!(p.rejected.is_empty());
    }

    #[test]
    fn discover_writes_a_charge_positive_and_it_is_flipped() {
        // THE SIGN BUG THIS FILE EXISTS FOR. Without the flip every Discover purchase reads as
        // income, and the balance is wrong by twice the amount in the direction that looks like good
        // news — which is the direction nobody double-checks.
        let csv = "Trans. Date,Post Date,Description,Amount,Category\n\
                   01/02/2026,01/03/2026,HARDWARE STORE,89.99,Merchandise\n\
                   01/06/2026,01/06/2026,DIRECTPAY FULL BALANCE,-200.00,Payments\n";
        let p = parse_csv(csv).unwrap();
        assert_eq!(p.institution, Institution::Discover);
        assert_eq!(p.txns[0].minor, -8999, "a Discover charge is written positive and must flip");
        assert_eq!(p.txns[1].minor, 20000, "and a payment flips the other way");
    }

    #[test]
    fn capital_one_uses_separate_debit_and_credit_columns() {
        let csv = "Transaction Date,Posted Date,Card No.,Description,Category,Debit,Credit\n\
                   2026-01-02,2026-01-03,1234,GROCERY,Merchandise,54.20,\n\
                   2026-01-05,2026-01-06,1234,CREDIT BALANCE REFUND,Other,,15.00\n";
        let p = parse_csv(csv).unwrap();
        assert_eq!(p.institution, Institution::CapitalOne);
        assert_eq!(p.txns[0].minor, -5420, "a debit is money leaving");
        assert_eq!(p.txns[1].minor, 1500, "a credit is money arriving");
    }

    #[test]
    fn capital_one_refuses_a_row_that_fills_both_or_neither() {
        // Guessing which column to believe would be inventing a transaction.
        let csv = "Transaction Date,Posted Date,Card No.,Description,Category,Debit,Credit\n\
                   2026-01-02,2026-01-03,1234,BOTH,Other,10.00,10.00\n\
                   2026-01-04,2026-01-05,1234,NEITHER,Other,,\n";
        let p = parse_csv(csv).unwrap();
        assert!(p.txns.is_empty());
        assert_eq!(p.rejected.len(), 2);
        assert!(p.rejected[0].reason.contains("both"));
        assert!(p.rejected[1].reason.contains("neither"));
    }

    #[test]
    fn bank_of_america_checking_and_card_are_different_shapes() {
        let checking = "Date,Description,Amount,Running Bal.\n01/02/2026,RENT,-1450.00,3210.55\n";
        assert_eq!(parse_csv(checking).unwrap().institution, Institution::BankOfAmerica);
        let card = "Posted Date,Reference Number,Payee,Address,Amount\n01/02/2026,000123,PHARMACY,,-23.40\n";
        let p = parse_csv(card).unwrap();
        assert_eq!(p.institution, Institution::BankOfAmerica);
        assert_eq!(p.txns[0].description, "PHARMACY", "the card export calls it Payee, not Description");
    }

    #[test]
    fn an_unreadable_row_is_reported_not_dropped() {
        // A row that silently vanishes is a wrong balance nobody can find by looking at the balance.
        let csv = "Transaction Date,Post Date,Description,Category,Type,Amount,Memo\n\
                   01/02/2026,01/03/2026,GOOD,Food,Sale,-4.50,\n\
                   01/04/2026,01/05/2026,BAD AMOUNT,Food,Sale,N/A,\n\
                   ,01/06/2026,NO DATE,Food,Sale,-1.00,\n";
        let p = parse_csv(csv).unwrap();
        assert_eq!(p.txns.len(), 1);
        assert_eq!(p.rejected.len(), 2);
        // The line number is what a person would see in an editor, header included.
        assert_eq!(p.rejected[0].line, 3);
        assert_eq!(p.rejected[1].line, 4);
    }

    #[test]
    fn an_unknown_header_says_so_rather_than_guessing() {
        // Forcing an unrecognised export through the closest-looking profile produces numbers that
        // are wrong and plausible, which is the worst combination available.
        let err = parse_csv("Foo,Bar,Baz\n1,2,3\n").unwrap_err();
        assert!(err.contains("no known export shape"), "{err}");
        assert!(err.contains("Foo"), "the error must show the header it could not place");
    }

    #[test]
    fn every_profile_is_reachable_and_distinct() {
        // A profile no header can select is dead configuration that reads as coverage. Each one's own
        // required columns must select IT — if a looser profile shadows a stricter one, ordering is
        // wrong and some institution silently parses as another.
        for p in PROFILES {
            let header: Vec<String> = p.required.iter().map(|s| s.to_string()).collect();
            let got = detect(&header).unwrap_or_else(|| panic!("{} matches no profile", p.label));
            assert_eq!(got.label, p.label, "{} is shadowed by {}", p.label, got.label);
        }
    }

    #[test]
    fn the_empty_file_is_an_error_not_an_empty_statement() {
        // An empty result would read as "this account had no activity", which is a different claim.
        assert!(parse_csv("").is_err());
        assert!(parse_csv("   \n\n").is_err());
    }
}

