import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import { detectRecurring, totalAnnualised } from "@/features/finance/lib/recurring";
import type { Txn } from "@/features/finance/lib/txn";

// EVERY FIXTURE IS SYNTHETIC — invented merchants, invented amounts. No real statement belongs here.

const usd = (major: number): Money => fromMajor(major, "USD");
const t = (date: string, description: string, major: number, account = "card"): Txn => ({
  date,
  description,
  amount: usd(-Math.abs(major)),
  account,
});

/** Twelve monthly charges, with the noise a statement actually adds to each line. */
const monthly = (merchant: string, major: number, account = "card"): Txn[] =>
  Array.from({ length: 12 }, (_, i) =>
    t(`2026-${String(i + 1).padStart(2, "0")}-14`, `${merchant} *RECURRING 1234${i}`, major, account),
  );

describe("detectRecurring — the rhythm", () => {
  it("finds a monthly charge through the noise the statement adds", () => {
    // A recurring charge rarely writes itself identically twice. Matching raw descriptions would find
    // nothing at all — the failure mode that makes a detector look like it works.
    const r = detectRecurring(monthly("STREAMSERVICE", 14.99), { asOf: "2026-12-20" });
    expect(r).toHaveLength(1);
    expect(r[0].cadence).toBe("monthly");
    expect(r[0].occurrences).toBe(12);
    expect(r[0].regularity).toBeGreaterThan(0.9);
  });

  it("ANNUALISES, because that is the number that prompts a cancellation", () => {
    const [r] = detectRecurring(monthly("STREAMSERVICE", 14.99), { asOf: "2026-12-20" });
    expect(r.typical.minor).toBe(1499);
    expect(r.annualised.minor).toBe(1499 * 12);
  });

  it("keeps a bill whose AMOUNT moves — a utility is still recurring", () => {
    // Demanding an identical amount would miss exactly the charges worth finding.
    const varying = monthly("CITY POWER", 0).map((x, i) => ({ ...x, amount: usd(-(80 + i * 3)) }));
    const [r] = detectRecurring(varying, { asOf: "2026-12-20" });
    expect(r.cadence).toBe("monthly");
    expect(r.amountStability).toBeLessThan(1);
    expect(r.regularity).toBeGreaterThan(0.9);
  });

  it("does NOT call an irregular spend recurring", () => {
    // The false positive is what kills the feature: flag someone's coffee habit as a subscription and
    // they stop reading the report.
    const coffee = ["2026-01-03", "2026-01-05", "2026-02-19", "2026-02-20", "2026-05-01"].map((d) =>
      t(d, "COFFEE BAR", 4.5),
    );
    expect(detectRecurring(coffee, { asOf: "2026-06-01" })).toEqual([]);
  });

  it("distinguishes cadences rather than calling everything monthly", () => {
    const weekly = Array.from({ length: 8 }, (_, i) =>
      t(`2026-03-${String(2 + i * 7).padStart(2, "0")}`, "GYM CLASS", 22),
    );
    expect(detectRecurring(weekly, { asOf: "2026-04-25" })[0].cadence).toBe("weekly");
  });
});

describe("detectRecurring — the once-a-year charge", () => {
  it("finds an ANNUAL renewal from two occurrences", () => {
    // Two is deliberate. An annual charge cannot show three inside a year of statements, and
    // demanding three would hide precisely the renewals that are easiest to forget.
    const annual = [t("2025-04-02", "DOMAIN RENEWAL", 240), t("2026-04-03", "DOMAIN RENEWAL", 240)];
    const [r] = detectRecurring(annual, { asOf: "2026-05-01" });
    expect(r.cadence).toBe("annual");
    expect(r.annualised.minor).toBe(24000);
  });
});

describe("detectRecurring — what it separates", () => {
  it("keeps the same subscription on TWO accounts apart", () => {
    // One subscription billed to two cards is two standing charges. Merging them would halve the
    // count and double the apparent amount — wrong in both directions at once.
    const both = [...monthly("SAME SERVICE", 9.99, "card-a"), ...monthly("SAME SERVICE", 9.99, "card-b")];
    const r = detectRecurring(both, { asOf: "2026-12-20" });
    expect(r).toHaveLength(2);
    expect(r.map((x) => x.account).sort()).toEqual(["card-a", "card-b"]);
  });

  it("ignores INCOME by default — it has its own questions", () => {
    const paydays = Array.from({ length: 12 }, (_, i) => ({
      ...t(`2026-${String(i + 1).padStart(2, "0")}-01`, "EMPLOYER PAYROLL", 0),
      amount: usd(2500),
    }));
    expect(detectRecurring(paydays, { asOf: "2026-12-20" })).toEqual([]);
    expect(detectRecurring(paydays, { asOf: "2026-12-20", outflowsOnly: false })).toHaveLength(1);
  });
});

describe("detectRecurring — lapsed", () => {
  it("flags a charge that has stopped, rather than dropping it", () => {
    // Cancelled, or about to hit? Those want different responses, so it is surfaced either way.
    const stopped = monthly("OLD SERVICE", 30).slice(0, 6); // last is 2026-06-14
    const [r] = detectRecurring(stopped, { asOf: "2026-10-01" });
    expect(r.lapsed).toBe(true);
  });

  it("does not count a lapsed charge in the annual total", () => {
    const live = monthly("LIVE ONE", 10);
    const dead = monthly("DEAD ONE", 50, "other").slice(0, 4);
    const rs = detectRecurring([...live, ...dead], { asOf: "2026-12-20" });
    expect(rs.find((r) => r.key.includes("dead"))?.lapsed).toBe(true);
    // Only the live one is money still going out.
    expect(totalAnnualised(rs, "USD").minor).toBe(1000 * 12);
  });
});

describe("detectRecurring — ordering", () => {
  it("puts the biggest ANNUAL cost first, which is the order to act in", () => {
    // Not the biggest per-charge: a $60 quarterly costs less a year than a $30 monthly, and a reader
    // ranking by the sticker price would cancel the wrong one.
    const monthlySmall = monthly("SMALL MONTHLY", 30);
    const quarterly = ["2026-01-10", "2026-04-11", "2026-07-10", "2026-10-11"].map((d) =>
      t(d, "BIG QUARTERLY", 60, "other"),
    );
    const rs = detectRecurring([...monthlySmall, ...quarterly], { asOf: "2026-11-01" });
    expect(rs[0].annualised.minor).toBe(3000 * 12);
    expect(rs[0].annualised.minor).toBeGreaterThan(rs[1].annualised.minor);
  });

  it("is deterministic — the same input twice gives the same answer", () => {
    const input = [...monthly("A SERVICE", 12), ...monthly("B SERVICE", 8, "other")];
    const a = JSON.stringify(detectRecurring(input, { asOf: "2026-12-20" }));
    const b = JSON.stringify(detectRecurring([...input].reverse(), { asOf: "2026-12-20" }));
    expect(a).toBe(b);
  });
});

implementations.code:
// DUPLICATE DETECTION — the same charge twice, which is recoverable money.
//
// THE FAILURE MODE IS THE FALSE POSITIVE, not the miss. Flag two legitimate coffees as a double
// charge and the reader learns to ignore the report; after that it finds nothing no matter how good
// it gets. So this SCORES a pair and hands the judgement to a person, rather than pronouncing.
//
// What actually separates a duplicate from a repeat is not "same merchant, same day" — it is how
// SURPRISING the coincidence is:
//
//   - An exact cent-for-cent match on an unusual amount ($47.83 twice) is very unlikely by chance.
//   - The same round amount twice ($5.00) is a habit, not an error.
//   - At a merchant you visit constantly, a repeat is expected and means nothing.
//   - At a merchant you use rarely, a same-day repeat is worth a look.
//
// So the score is built from the coincidence being improbable, and damped by how habitual the
// merchant is. That is the difference between a feature people act on and one they mute.
import { type Money, format } from "@/features/finance/lib/money";
import { type Txn, daysBetween, merchantKey } from "@/features/finance/lib/txn";

export interface Candidate {
  readonly account: string;
  /** The merchant key both share. */
  readonly key: string;
  /** The two descriptions, as written — a person recognises the charge by these, not by the key. */
  readonly descriptions: readonly [string, string];
  readonly dates: readonly [string, string];
  readonly amount: Money;
  /** Days apart. `0` is the same day. */
  readonly apart: number;
  /** 0-1. How unlikely this pair is to be an ordinary repeat. */
  readonly score: number;
  /** Why it scored that way, in words — a score with no reason cannot be argued with, and a reader
   *  who cannot argue with it cannot trust it either. */
  readonly reasons: readonly string[];
  /** What is at stake if it IS a duplicate — the amount that would come back. */
  readonly atStake: Money;
}

export interface DuplicateOptions {
  /** How far apart two charges can be and still be considered one event. Beyond a few days a repeat
   *  is much more likely to be a genuine second purchase. */
  readonly withinDays?: number;
  /** Report only pairs scoring at least this. Default deliberately high: a short list that is right
   *  beats a long list that has to be filtered by hand. */
  readonly minScore?: number;
}

/** An amount is ROUND when it looks chosen rather than computed — whole units, or a common price. */
function isRound(minor: number): boolean {
  const a = Math.abs(minor);
  return a % 100 === 0 || a % 50 === 0;
}

/**
 * Pairs of charges that might be the same charge twice.
 *
 * Only ever compares within one account: the same amount on two different cards on one day is two
 * purchases, not a double charge, and merging that judgement would produce confident nonsense.
 */
export function findDuplicates(txns: readonly Txn[], opts: DuplicateOptions = {}): Candidate[] {
  const { withinDays = 3, minScore = 0.5 } = opts;

  // How often each merchant appears at all — the damping term. A merchant seen 40 times is a habit.
  const frequency = new Map<string, number>();
  for (const t of txns) {
    const k = merchantKey(t.description);
    if (k) frequency.set(k, (frequency.get(k) ?? 0) + 1);
  }

  const out: Candidate[] = [];
  const byAccount = new Map<string, Txn[]>();
  for (const t of txns) {
    if (t.amount.minor >= 0) continue; // an inbound pair is a refund pattern, not a double charge
    const bucket = byAccount.get(t.account);
    if (bucket) bucket.push(t);
    else byAccount.set(t.account, [t]);
  }

  for (const [account, rows] of byAccount) {
    const sorted = [...rows].sort((a, b) => a.date.localeCompare(b.date));
    for (let i = 0; i < sorted.length; i++) {
      for (let j = i + 1; j < sorted.length; j++) {
        const [a, b] = [sorted[i], sorted[j]];
        const apart = daysBetween(a.date, b.date);
        if (apart > withinDays) break; // sorted, so nothing later is closer
        if (a.amount.minor !== b.amount.minor) continue;
        const key = merchantKey(a.description);
        if (!key || key !== merchantKey(b.description)) continue;

        const reasons: string[] = [];
        // Base: an exact cent-for-cent match at one merchant, close together.
        let score = 0.5;
        reasons.push(`exact match ${format(a.amount)}, ${apart === 0 ? "same day" : `${apart} day(s) apart`}`);

        if (apart === 0) {
          score += 0.2;
          reasons.push("same day");
        }
        if (!isRound(a.amount.minor)) {
          // An unusual amount repeating exactly is the strongest signal available: a habit produces
          // round prices, a duplicated transaction reproduces whatever the total happened to be.
          score += 0.25;
          reasons.push("unusual amount — an exact repeat is unlikely by chance");
        }
        const seen = frequency.get(key) ?? 0;
        if (seen > 10) {
          // A merchant you use constantly: a repeat means nothing, and saying so is the point.
          score -= 0.35;
          reasons.push(`frequent merchant (${seen} charges) — a repeat here is expected`);
        } else if (seen <= 3) {
          score += 0.15;
          reasons.push(`rare merchant (${seen} charges)`);
        }

        const clamped = Math.max(0, Math.min(1, score));
        if (clamped < minScore) continue;
        out.push({
          account,
          key,
          descriptions: [a.description, b.description],
          dates: [a.date, b.date],
          amount: a.amount,
          apart,
          score: Math.round(clamped * 100) / 100,
          reasons,
          // What comes back if it is a duplicate: ONE of the two, not both.
          atStake: a.amount,
        });
      }
    }
  }
  // Most likely first, then biggest — a reader works down this list and stops when it stops paying.
  return out.sort((a, b) => b.score - a.score || Math.abs(b.atStake.minor) - Math.abs(a.atStake.minor));
}

