//! The account registry — and, more usefully, what it CANNOT tell you.
//!
//! `position` needs to know what each account IS before a balance means anything: whether a positive
//! number is money you have or money you owe, what the credit limit is, what rate it carries. None of
//! that is in a statement export, and until now nothing recorded it — so the analysis existed and had
//! no way to be handed the one thing it needed.
//!
//! # The half that matters to an agent is `gaps`
//!
//! A session driving these systems cannot see a screen. It needs to know not just what is stored but
//! WHAT IS MISSING AND WHAT THAT COSTS — that an absent APR is why there is no interest figure, that
//! an absent credit limit is why utilisation is silent. A registry that only answered "here is what I
//! have" would leave the agent guessing at why a downstream number never appeared, and guessing is
//! how a default gets invented.
//!
//! So every gap names the capability it blocks. That is the difference between a store and an
//! instrument.
//!
//! # An account NUMBER never enters this
//!
//! Refused at any depth, the same way `bsc secret set` refuses a secret-bearing key. The registry
//! needs to know that an account is a credit card at 24.99% with a $5,000 limit; it never needs the
//! digits, and a store that accepts them becomes a file worth stealing.
use std::collections::BTreeMap;

/// What kind of thing an account is — which decides whether a positive balance is held or owed.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Kind {
    Checking,
    Savings,
    Credit,
    Loan,
    Investment,
}

impl Kind {
    pub fn as_str(self) -> &'static str {
        match self {
            Kind::Checking => "checking",
            Kind::Savings => "savings",
            Kind::Credit => "credit",
            Kind::Loan => "loan",
            Kind::Investment => "investment",
        }
    }

    pub fn parse(s: &str) -> Option<Kind> {
        Some(match s {
            "checking" => Kind::Checking,
            "savings" => Kind::Savings,
            "credit" => Kind::Credit,
            "loan" => Kind::Loan,
            "investment" => Kind::Investment,
            _ => return None,
        })
    }

    /// True where a positive printed balance means money you OWE.
    pub fn is_debt(self) -> bool {
        matches!(self, Kind::Credit | Kind::Loan)
    }

    /// True where it can pay a bill this week. An investment cannot.
    pub fn is_liquid(self) -> bool {
        matches!(self, Kind::Checking | Kind::Savings)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Account {
    /// The key everything else joins on — and the name a statement file starts with.
    pub id: String,
    pub institution: String,
    pub kind: Kind,
    pub currency: String,
    /// Minor units, positive. NONE means unknown, which is not the same as no limit.
    pub credit_limit: Option<i64>,
    /// Annual rate in basis points — 2499 for 24.99%. Integer, because a rate in a float is the
    /// same defect class as money in a float.
    pub apr_bps: Option<u32>,
    /// Minor units the institution will accept this cycle.
    pub minimum_payment: Option<i64>,
    /// Day of month the statement closes, where it is known.
    pub statement_day: Option<u8>,
    pub note: Option<String>,
}

/// Something the registry does not know, and the capability that cannot run without it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Gap {
    pub account: String,
    pub field: &'static str,
    /// What silently does not happen. Named, because the agent's next question is always "why is
    /// there no number here".
    pub blocks: &'static str,
}

/// Keys that must never be stored. The registry needs the SHAPE of an account, never its identity.
const FORBIDDEN: &[&str] = &[
    "number", "account_number", "accountnumber", "acct", "pan", "card_number", "cardnumber",
    "routing", "routing_number", "iban", "ssn", "tax_id", "taxid", "pin", "cvv", "password", "secret", "token",
];

/// Whether any key ANYWHERE in a JSON value is one the registry refuses.
///
/// A GUARD, not a filter. Silently dropping an account number would let a caller keep writing the
/// code that sends one.
pub fn forbidden_key(value: &serde_json::Value) -> Option<String> {
    match value {
        serde_json::Value::Object(map) => {
            for (k, v) in map {
                let lower = k.to_ascii_lowercase();
                if FORBIDDEN.iter().any(|f| lower == *f) {
                    return Some(k.clone());
                }
                if let Some(hit) = forbidden_key(v) {
                    return Some(hit);
                }
            }
            None
        }
        serde_json::Value::Array(xs) => xs.iter().find_map(forbidden_key),
        _ => None,
    }
}

/// Read one account from JSON, refusing what it must not hold.
pub fn from_json(v: &serde_json::Value) -> Result<Account, String> {
    if let Some(k) = forbidden_key(v) {
        return Err(format!(
            "`{k}` is not something this store will hold. The registry needs to know an account's SHAPE — kind, limit, rate — never its identity, and a store that accepts the digits becomes a file worth stealing."
        ));
    }
    let s = |k: &str| v.get(k).and_then(|x| x.as_str()).map(str::to_string);
    let n = |k: &str| v.get(k).and_then(serde_json::Value::as_i64);
    let id = s("id").ok_or_else(|| "an account needs an `id` — the name its statement files start with".to_string())?;
    let kind_raw = s("kind").ok_or_else(|| format!("{id}: `kind` is required — without it a positive balance could be money held or money owed"))?;
    let kind = Kind::parse(&kind_raw)
        .ok_or_else(|| format!("{id}: `{kind_raw}` is not a kind — one of checking, savings, credit, loan, investment"))?;
    Ok(Account {
        institution: s("institution").unwrap_or_else(|| id.clone()),
        currency: s("currency").unwrap_or_else(|| "USD".to_string()),
        credit_limit: n("creditLimit"),
        apr_bps: n("aprBps").and_then(|x| u32::try_from(x).ok()),
        minimum_payment: n("minimumPayment"),
        statement_day: n("statementDay").and_then(|x| u8::try_from(x).ok()).filter(|d| (1..=31).contains(d)),
        note: s("note"),
        id,
        kind,
    })
}

pub fn to_json(a: &Account) -> serde_json::Value {
    serde_json::json!({
        "id": a.id,
        "institution": a.institution,
        "kind": a.kind.as_str(),
        "currency": a.currency,
        "creditLimit": a.credit_limit,
        "aprBps": a.apr_bps,
        "minimumPayment": a.minimum_payment,
        "statementDay": a.statement_day,
        "note": a.note,
        // DERIVED, so a reader does not have to know the kind table to act on the row.
        "isDebt": a.kind.is_debt(),
        "isLiquid": a.kind.is_liquid(),
    })
}

pub fn all_to_json(accounts: &[Account]) -> serde_json::Value {
    serde_json::Value::Array(accounts.iter().map(to_json).collect())
}

/// Read a whole registry back. An entry that cannot be read is DROPPED with its id reported rather
/// than defaulted into something plausible.
pub fn all_from_json(v: &serde_json::Value) -> (Vec<Account>, Vec<String>) {
    let mut out = Vec::new();
    let mut rejected = Vec::new();
    for item in v.as_array().map(Vec::as_slice).unwrap_or_default() {
        match from_json(item) {
            Ok(a) => out.push(a),
            Err(e) => rejected.push(e),
        }
    }
    out.sort_by(|a, b| a.id.cmp(&b.id));
    (out, rejected)
}

/// Replace one account, keeping every other. Sorted, so the file is stable and a diff means something.
pub fn upsert(accounts: &mut Vec<Account>, next: Account) {
    match accounts.iter_mut().find(|a| a.id == next.id) {
        Some(slot) => *slot = next,
        None => accounts.push(next),
    }
    accounts.sort_by(|a, b| a.id.cmp(&b.id));
}

/// WHAT IS MISSING, AND WHAT IT COSTS.
///
/// The instrument half. Each gap names the capability that silently does not run without it, because
/// an agent's next question after a missing number is always "why", and without an answer it invents
/// one.
pub fn gaps(accounts: &[Account]) -> Vec<Gap> {
    let mut out = Vec::new();
    for a in accounts {
        if a.kind == Kind::Credit && a.credit_limit.is_none() {
            out.push(Gap {
                account: a.id.clone(),
                field: "creditLimit",
                blocks: "utilisation — which is UNKNOWN rather than 0%, and 0% is an excellent score while not knowing is not",
            });
        }
        if a.kind.is_debt() && a.apr_bps.is_none() {
            out.push(Gap {
                account: a.id.clone(),
                field: "aprBps",
                blocks: "daily interest, the weighted APR, and the avalanche order — the payoff plan cannot rank a debt whose rate it does not know",
            });
        }
        if a.kind.is_debt() && a.minimum_payment.is_none() {
            out.push(Gap {
                account: a.id.clone(),
                field: "minimumPayment",
                blocks: "the obligation calendar and the minimums-first rule — a missed minimum is a credit event",
            });
        }
        if a.kind.is_debt() && a.statement_day.is_none() {
            out.push(Gap {
                account: a.id.clone(),
                field: "statementDay",
                blocks: "the due date — the calendar falls back to the 1st, the earliest it could plausibly be, so nothing reads as late that is not",
            });
        }
    }
    out.sort_by(|x, y| x.account.cmp(&y.account).then(x.field.cmp(y.field)));
    out
}

/// How much of the picture is actually known, as a count — the one number an agent can act on
/// without reading every row.
pub fn completeness(accounts: &[Account]) -> (usize, usize) {
    let missing = gaps(accounts).len();
    let possible: usize = accounts
        .iter()
        .map(|a| match a.kind {
            Kind::Credit => 4,
            Kind::Loan => 3,
            _ => 0,
        })
        .sum();
    (possible.saturating_sub(missing), possible)
}

/// Every account referenced by a statement that the registry has never heard of.
///
/// The other direction of the same question: not "what do I not know about this account" but "what
/// account do I not know about at all".
pub fn undeclared<'a>(accounts: &[Account], seen: impl IntoIterator<Item = &'a str>) -> Vec<String> {
    let known: BTreeMap<&str, ()> = accounts.iter().map(|a| (a.id.as_str(), ())).collect();
    let mut out: Vec<String> = seen
        .into_iter()
        .filter(|s| !known.contains_key(*s))
        .map(str::to_string)
        .collect();
    out.sort();
    out.dedup();
    out
}

/// What a person reads. Gaps are NOT a footnote — they are most of the value.
pub fn render(accounts: &[Account]) -> String {
    if accounts.is_empty() {
        return "no accounts declared — `position` cannot say whether a balance is held or owed until one is\n".to_string();
    }
    let mut out = String::new();
    for a in accounts {
        let rate = a.apr_bps.map(|b| format!("{}.{:02}%", b / 100, b % 100)).unwrap_or_else(|| "rate unknown".into());
        out.push_str(&format!("  {:<18} {:<12} {:<16} {}\n", a.id, a.kind.as_str(), a.institution, rate));
    }
    let g = gaps(accounts);
    let (known, possible) = completeness(accounts);
    out.push_str(&format!("\n{known} of {possible} facts known about the debts.\n"));
    if !g.is_empty() {
        out.push_str("\nMissing, and what each one costs:\n");
        for x in &g {
            out.push_str(&format!("  {} · {} — blocks {}\n", x.account, x.field, x.blocks));
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    // SYNTHETIC FIXTURES ONLY. No real account, limit or rate belongs in this repo.
    fn card() -> Account {
        Account {
            id: "discover".into(),
            institution: "Discover".into(),
            kind: Kind::Credit,
            currency: "USD".into(),
            credit_limit: Some(500_000),
            apr_bps: Some(2499),
            minimum_payment: Some(9_000),
            statement_day: Some(14),
            note: None,
        }
    }

    fn bare_card() -> Account {
        Account { credit_limit: None, apr_bps: None, minimum_payment: None, statement_day: None, ..card() }
    }

    #[test]
    fn an_account_number_is_refused_at_any_depth() {
        // The registry needs an account's SHAPE, never its identity. A store that accepts the digits
        // becomes a file worth stealing.
        for key in ["number", "accountNumber", "routing", "ssn", "pan", "cvv"] {
            let v = serde_json::json!({ "id": "x", "kind": "credit", key: "4111111111111111" });
            let e = from_json(&v).unwrap_err();
            assert!(e.contains("worth stealing"), "{key}: {e}");
        }
        let nested = serde_json::json!({ "id": "x", "kind": "credit", "meta": { "deep": { "ssn": "1" } } });
        assert!(from_json(&nested).is_err());
    }

    #[test]
    fn the_refusal_is_a_guard_not_a_filter() {
        // Silently dropping the field would let a caller keep writing the code that sends one.
        let v = serde_json::json!({ "id": "x", "kind": "credit", "number": "4111" });
        assert!(from_json(&v).is_err());
        assert_eq!(forbidden_key(&v).as_deref(), Some("number"));
    }

    #[test]
    fn kind_is_required_because_a_balance_is_meaningless_without_it() {
        let e = from_json(&serde_json::json!({ "id": "x" })).unwrap_err();
        assert!(e.contains("money held or money owed"), "{e}");
        let e2 = from_json(&serde_json::json!({ "id": "x", "kind": "brokerage" })).unwrap_err();
        assert!(e2.contains("not a kind"), "{e2}");
    }

    #[test]
    fn a_round_trip_loses_nothing() {
        let back = from_json(&to_json(&card())).unwrap();
        assert_eq!(back, card());
        let bare = from_json(&to_json(&bare_card())).unwrap();
        assert_eq!(bare, bare_card());
    }

    #[test]
    fn the_wire_shape_carries_the_derived_facts_so_a_reader_need_not_know_the_kind_table() {
        let v = to_json(&card());
        assert_eq!(v["isDebt"], true);
        assert_eq!(v["isLiquid"], false);
        let cash = Account { id: "checking".into(), kind: Kind::Checking, ..card() };
        assert_eq!(to_json(&cash)["isLiquid"], true);
        assert_eq!(to_json(&cash)["isDebt"], false);
    }

    #[test]
    fn every_gap_names_what_it_blocks() {
        // An agent's next question after a missing number is always "why", and without an answer it
        // invents one.
        let g = gaps(&[bare_card()]);
        assert_eq!(g.len(), 4);
        assert!(g.iter().all(|x| !x.blocks.is_empty()));
        let by_field: Vec<&str> = g.iter().map(|x| x.field).collect();
        assert_eq!(by_field, ["aprBps", "creditLimit", "minimumPayment", "statementDay"]);
        assert!(g.iter().find(|x| x.field == "creditLimit").unwrap().blocks.contains("0% is an excellent score"));
        assert!(g.iter().find(|x| x.field == "aprBps").unwrap().blocks.contains("avalanche order"));
    }

    #[test]
    fn a_complete_card_has_no_gaps_and_a_cash_account_never_does() {
        assert_eq!(gaps(&[card()]), vec![]);
        let cash = Account { id: "checking".into(), kind: Kind::Checking, ..bare_card() };
        // A chequing account has no rate, no limit and no minimum, and demanding them would fill the
        // report with work nobody can do.
        assert_eq!(gaps(&[cash]), vec![]);
    }

    #[test]
    fn completeness_counts_only_what_could_be_known() {
        assert_eq!(completeness(&[card()]), (4, 4));
        assert_eq!(completeness(&[bare_card()]), (0, 4));
        let cash = Account { id: "checking".into(), kind: Kind::Checking, ..bare_card() };
        assert_eq!(completeness(&[cash]), (0, 0));
    }

    #[test]
    fn undeclared_answers_the_other_direction_of_the_question() {
        // Not "what do I not know about this account" but "what account do I not know about at all".
        let out = undeclared(&[card()], ["discover", "chase", "chase", "capital-one"]);
        assert_eq!(out, ["capital-one", "chase"]);
        assert!(undeclared(&[card()], ["discover"]).is_empty());
    }

    #[test]
    fn a_row_that_cannot_be_read_is_dropped_with_its_reason_not_defaulted() {
        let v = serde_json::json!([
            { "id": "good", "kind": "credit" },
            { "id": "bad" },
            { "id": "worse", "kind": "credit", "ssn": "1" },
        ]);
        let (ok, rejected) = all_from_json(&v);
        assert_eq!(ok.len(), 1);
        assert_eq!(ok[0].id, "good");
        assert_eq!(rejected.len(), 2);
    }

    #[test]
    fn upsert_replaces_one_and_keeps_the_rest_sorted() {
        let mut xs = vec![card()];
        upsert(&mut xs, Account { id: "amex".into(), ..bare_card() });
        upsert(&mut xs, Account { apr_bps: Some(1999), ..card() });
        assert_eq!(xs.len(), 2);
        assert_eq!(xs.iter().map(|a| a.id.as_str()).collect::<Vec<_>>(), ["amex", "discover"]);
        assert_eq!(xs[1].apr_bps, Some(1999));
    }

    #[test]
    fn the_render_leads_with_what_is_missing_rather_than_burying_it() {
        let out = render(&[bare_card()]);
        assert!(out.contains("0 of 4 facts known"), "{out}");
        assert!(out.contains("Missing, and what each one costs"), "{out}");
        assert!(out.contains("rate unknown"), "{out}");
    }

    #[test]
    fn an_empty_registry_says_what_that_costs() {
        assert!(render(&[]).contains("cannot say whether a balance is held or owed"));
    }
}

//! The shared transaction shape — ported from `@/features/finance/lib/txn`.
//!
//! One definition, because the alternative is each capability inventing its own and the crate
//! carrying six subtly different ideas of what a transaction is. The fields are the ones a statement
//! actually gives you and nothing more: anything richer — category, merchant identity, account type
//! — is DERIVED by a capability that says so, rather than assumed to be present.
use crate::money::{Currency, Money};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Txn {
    /// ISO `YYYY-MM-DD`. Normalised at ingest, because comparing dates written three ways is not
    /// analysis, it is guessing.
    pub date: String,
    /// The description exactly as the statement wrote it. Normalisation is a capability's job and is
    /// always reversible to this.
    pub description: String,
    /// NEGATIVE is money leaving the account holder — the one contract ingest normalises to.
    pub amount: Money,
    /// Which account it belongs to. Two accounts can hold the same charge on the same day.
    pub account: String,
}

impl Txn {
    /// Lift a parsed statement row into the analysis shape, attaching the account the file belongs
    /// to and the currency it is denominated in — neither of which a row can know on its own.
    pub fn from_row(row: &crate::statement::Txn, account: &str, currency: Currency) -> Txn {
        Txn {
            date: row.date.clone(),
            description: row.description.clone(),
            amount: Money { minor: row.minor, currency },
            account: account.to_string(),
        }
    }
}

/// Days between two ISO dates. UTC, so a DST boundary cannot make a 30-day month 29.96 days.
///
/// Returns 0 for anything that is not a pair of dates rather than guessing a distance — a bad date
/// producing a plausible gap is how a cadence gets misclassified.
pub fn days_between(a: &str, b: &str) -> i64 {
    let (Some(x), Some(y)) = (
        crate::session::epoch_seconds(&format!("{a}T00:00:00Z")),
        crate::session::epoch_seconds(&format!("{b}T00:00:00Z")),
    ) else {
        return 0;
    };
    (y - x) / 86_400
}

/// `YYYY-MM` — the period most statement analysis groups by.
pub fn month_of(date: &str) -> &str {
    if date.len() >= 7 { &date[..7] } else { date }
}

/// Tokens that appear in descriptions without identifying the merchant.
const NOISE: &[&str] = &[
    "purchase", "payment", "pos", "debit", "credit", "card", "recurring", "autopay", "auto",
    "transaction", "ach", "web", "id", "ref", "the", "inc", "llc", "co", "com", "www", "usa", "us",
];

/// A merchant key: the description reduced to what is STABLE across occurrences.
///
/// A recurring charge rarely writes itself identically twice — statements append dates, store
/// numbers, transaction ids and city names. Matching on the raw description would find no recurrence
/// at all, which is the failure mode that makes a subscription detector look like it works while
/// finding nothing.
///
/// SPLIT FIRST, THEN DISCARD ANY TOKEN THAT CARRIED A DIGIT. Stripping digits before splitting
/// leaves the LETTER FRAGMENTS of an alphanumeric id behind: `AMZN Mktp US*2X4TY1` would reduce to
/// `amzn mktp ty` and `AMZN Mktp US*9KK2P0` to `amzn mktp kk`, so one merchant produces a different
/// key on every occurrence and matches itself never.
///
/// Deliberately crude and DETERMINISTIC. A smarter matcher would need a model, and a model here
/// would mean sending somebody's merchant list somewhere.
pub fn merchant_key(description: &str, words: usize) -> String {
    description
        .to_ascii_lowercase()
        .split(|c: char| !c.is_ascii_alphanumeric())
        .filter(|w| !w.is_empty())
        .filter(|w| !w.bytes().any(|b| b.is_ascii_digit()))
        .filter(|w| w.len() > 1)
        .filter(|w| !NOISE.contains(w))
        .take(words)
        .collect::<Vec<_>>()
        .join(" ")
}

/// The default width — three words, which is what the TypeScript uses everywhere it calls this.
pub fn merchant_key_default(description: &str) -> String {
    merchant_key(description, 3)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    /// EVERY VALUE HERE CAME FROM RUNNING `@/features/finance/lib/txn`, not from reading it — the
    /// same discipline the money parity table records, and for the same reason: the first pass of
    /// that port diverged in four places because it was written from a reading.
    #[test]
    fn merchant_key_matches_the_typescript_value_for_value() {
        let cases: &[(&str, &str)] = &[
            ("AMZN Mktp US*2X4TY1", "amzn mktp"),
            ("AMZN Mktp US*9KK2P0", "amzn mktp"),
            ("SQUARE, INC COFFEE", "square coffee"),
            ("NETFLIX.COM", "netflix"),
            ("SAFEWAY #221", "safeway"),
            ("PAYMENT - THANK YOU", "thank you"),
            ("SHELL OIL 4471", "shell oil"),
            ("RENT PAYMENT LANDLORD", "rent landlord"),
            ("TST* CORNER CAFE 09", "tst corner cafe"),
            ("ACH WEB PMT ID 12345 ACME", "pmt acme"),
            ("a", ""),
            ("  ", ""),
            ("USA INC LLC CO", ""),
        ];
        for (input, expected) in cases {
            assert_eq!(merchant_key_default(input), *expected, "merchantKey({input:?})");
        }
    }

    #[test]
    fn one_merchant_gives_one_key_however_the_statement_dresses_it_up() {
        // THE WHOLE POINT. Two Amazon rows with different order ids must collapse to one key, or a
        // subscription detector looks like it works while finding nothing.
        assert_eq!(merchant_key_default("AMZN Mktp US*2X4TY1"), merchant_key_default("AMZN Mktp US*9KK2P0"));
        assert_ne!(merchant_key_default("SAFEWAY #221"), merchant_key_default("SHELL OIL 4471"));
    }

    #[test]
    fn a_digit_bearing_token_is_dropped_whole_rather_than_stripped() {
        // Stripping digits first would leave `ty` and `kk` behind — letter fragments of an id, which
        // differ on every occurrence.
        assert!(!merchant_key_default("AMZN Mktp US*2X4TY1").contains("ty"));
        assert!(!merchant_key_default("STORE 4A7B").contains("a7b"));
        assert_eq!(merchant_key_default("STORE 4A7B"), "store");
    }

    #[test]
    fn the_width_is_a_parameter_and_three_is_the_default() {
        assert_eq!(merchant_key("TST* CORNER CAFE 09", 1), "tst");
        assert_eq!(merchant_key("TST* CORNER CAFE 09", 2), "tst corner");
        assert_eq!(merchant_key_default("TST* CORNER CAFE 09"), merchant_key("TST* CORNER CAFE 09", 3));
    }

    #[test]
    fn days_between_matches_the_typescript_and_signs_correctly() {
        assert_eq!(days_between("2026-01-01", "2026-03-01"), 59);
        assert_eq!(days_between("2026-03-01", "2026-01-01"), -59);
        // A leap day is a real day.
        assert_eq!(days_between("2024-02-28", "2024-03-01"), 2);
        assert_eq!(days_between("2026-02-28", "2026-03-01"), 1);
        assert_eq!(days_between("2026-06-01", "2026-06-01"), 0);
    }

    #[test]
    fn a_date_it_cannot_read_is_zero_rather_than_a_plausible_gap() {
        // A bad date producing a plausible distance is how a cadence gets misclassified, and the
        // wrong cadence misstates annual income by two whole payments.
        assert_eq!(days_between("not-a-date", "2026-03-01"), 0);
        assert_eq!(days_between("2026-13-01", "2026-03-01"), 0);
    }

    #[test]
    fn month_of_is_the_first_seven_characters_and_survives_a_short_string() {
        assert_eq!(month_of("2026-07-15"), "2026-07");
        assert_eq!(month_of("2026-07"), "2026-07");
        assert_eq!(month_of("bad"), "bad");
    }

    #[test]
    fn a_statement_row_lifts_into_the_analysis_shape_with_its_account_and_currency() {
        // Neither is knowable from the row itself: the account comes from which FILE it was in, and
        // the currency from what the account is denominated in.
        let row = crate::statement::Txn {
            date: "2026-06-03".into(),
            description: "SAFEWAY #221".into(),
            minor: -8410,
        };
        let t = Txn::from_row(&row, "chase-credit", Currency::USD);
        assert_eq!(t.account, "chase-credit");
        assert_eq!(t.amount, usd(-8410));
        assert_eq!(t.date, "2026-06-03");
        assert_eq!(t.description, "SAFEWAY #221");
    }
}

//! RECONCILIATION — the gate every derived figure has to pass through.
//!
//! Ported from `@/features/finance/lib/reconcile`. Every other capability here is arithmetic over a
//! list of transactions, and arithmetic over an INCOMPLETE list is not wrong in a way anybody can
//! see. A missing week of a statement does not produce an error; it produces a spending total that
//! is quietly too low, a runway that is quietly too long, and a payoff schedule that quietly does
//! not work. The numbers stay plausible, which is exactly what makes them dangerous.
//!
//! So reconciliation is not a report — it is a TYPE. [`reconcile`] is the only function that can
//! mint a [`ReconciledLedger`], and a capability that takes one cannot be handed transactions
//! nobody checked.
//!
//! # The brand is STRONGER here than in the TypeScript
//!
//! There it is a phantom symbol — a compile-time fiction that a cast can defeat. Here the fields are
//! private, so a struct literal outside this module is a COMPILE ERROR with no escape hatch at all.
//! The port gains something rather than approximating it.
//!
//! THERE IS NO TOLERANCE, and that is deliberate. Money is an integer count of minor units, so a
//! one-cent discrepancy has no rounding to blame — it is a real transaction that is missing,
//! doubled, or signed the wrong way. A tolerance would be a setting whose only function is to hide
//! the class of defect this module exists to find.
use crate::money::{money, subtract, sum, Currency, Money};
use crate::txn::{days_between, Txn};

/// One statement: what the institution says the account held at each end of a window.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StatementPeriod {
    pub account: String,
    /// `YYYY-MM-DD`, INCLUSIVE.
    pub from: String,
    /// `YYYY-MM-DD`, INCLUSIVE.
    pub to: String,
    pub opening: Money,
    pub closing: Money,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProblemKind {
    /// Opening + the period's transactions does not reach closing.
    Unbalanced,
    /// Consecutive statements leave days uncovered — transactions in them are simply absent.
    Gap,
    /// Two statements for one account claim the same days.
    Overlap,
    /// One statement's opening disagrees with the previous statement's closing.
    Continuity,
    /// A transaction's currency is not the period's.
    CurrencyMismatch,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Problem {
    pub kind: ProblemKind,
    pub account: String,
    /// Written for a person to act on, not for a log.
    pub detail: String,
    pub amount: Option<Money>,
    /// Transactions this problem points at — the shortlist to go and look at.
    pub suspects: Vec<Txn>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PeriodReport {
    pub account: String,
    pub from: String,
    pub to: String,
    pub balanced: bool,
    pub opening: Money,
    pub closing: Money,
    /// opening + everything dated inside the window.
    pub computed: Money,
    /// closing − computed. Zero, or the exact size of what is wrong.
    pub discrepancy: Money,
    pub counted: usize,
}

/// Transactions something has actually checked, and the date they are checked THROUGH.
///
/// EVERY FIELD IS PRIVATE. That is the enforcement: only this module can build one, so a capability
/// that asks for a `ReconciledLedger` cannot be handed a raw list by any means at all.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ReconciledLedger {
    txns: Vec<Txn>,
    through: String,
    accounts: Vec<String>,
    unverified: bool,
    caveat: Option<String>,
}

impl ReconciledLedger {
    pub fn txns(&self) -> &[Txn] {
        &self.txns
    }

    /// The last date EVERY account is covered through — see [`coverage_through`].
    pub fn through(&self) -> &str {
        &self.through
    }

    pub fn accounts(&self) -> &[String] {
        &self.accounts
    }

    /// True when this came from [`unverified_ledger`] rather than a passing reconcile.
    pub fn unverified(&self) -> bool {
        self.unverified
    }

    pub fn caveat(&self) -> Option<&str> {
        self.caveat.as_deref()
    }

    /// The transactions a derived figure may use: everything up to the date coverage actually reaches.
    pub fn covered(&self) -> Vec<Txn> {
        self.txns.iter().filter(|t| t.date <= self.through).cloned().collect()
    }

    /// A one-line statement of what a figure derived from this ledger is standing on.
    pub fn provenance(&self) -> String {
        let base = format!(
            "{} transaction(s) across {} account(s), covered through {}",
            self.txns.len(),
            self.accounts.len(),
            self.through
        );
        match &self.caveat {
            Some(c) if self.unverified => format!("UNVERIFIED — {c} · {base}"),
            _ => format!("reconciled · {base}"),
        }
    }
}

#[derive(Debug, Clone)]
pub struct ReconcileResult {
    pub ok: bool,
    /// Present only when every period balanced and nothing is missing between them.
    pub ledger: Option<ReconciledLedger>,
    pub periods: Vec<PeriodReport>,
    pub problems: Vec<Problem>,
    /// Transactions belonging to no supplied period. Not counted, and not silently dropped either.
    pub uncovered: Vec<Txn>,
}

fn next_day(d: &str) -> String {
    match crate::session::epoch_seconds(&format!("{d}T00:00:00Z")) {
        Some(s) => crate::session::iso_from_epoch(s + 86_400)[..10].to_string(),
        None => d.to_string(),
    }
}

fn in_period(t: &Txn, p: &StatementPeriod) -> bool {
    t.account == p.account && t.date >= p.from && t.date <= p.to
}

/// The last date the WHOLE picture is trustworthy through — the EARLIEST of each account's coverage.
///
/// A ledger is only as complete as its least-covered account. Checking reconciled through August and
/// a credit card only through July does not give you an August position: August's card spending is
/// missing, so every August figure is too flattering. Taking the maximum here would be the specific
/// mistake that produces a confident, wrong number.
pub fn coverage_through(periods: &[StatementPeriod]) -> Option<String> {
    let mut last: std::collections::BTreeMap<&str, &str> = std::collections::BTreeMap::new();
    for p in periods {
        let e = last.entry(p.account.as_str()).or_insert(p.to.as_str());
        if p.to.as_str() > *e {
            *e = p.to.as_str();
        }
    }
    last.values().min().map(|s| s.to_string())
}

/// Explain a discrepancy by pointing at the transactions that would produce exactly it.
fn explain(discrepancy: i64, rows: &[Txn]) -> (String, Vec<Txn>) {
    // A SIGN ERROR IS TWICE THE AMOUNT, and it is checked FIRST. Booking −$50 as +$50 moves the
    // balance by $100, so a $100 discrepancy with a $50 transaction present is far more likely a
    // sign error than a missing $100 charge — and the two want completely different fixes.
    let halved: Vec<Txn> = rows.iter().filter(|t| t.amount.minor.abs() * 2 == discrepancy.abs()).cloned().collect();
    if !halved.is_empty() {
        let what = if halved.len() == 1 { "one transaction".to_string() } else { format!("{} transactions", halved.len()) };
        return (
            format!("the discrepancy is exactly twice {what} — a sign error, not a missing row: money leaving the account must be negative"),
            halved,
        );
    }
    let exact: Vec<Txn> = rows.iter().filter(|t| t.amount.minor.abs() == discrepancy.abs()).cloned().collect();
    if !exact.is_empty() {
        let what = if exact.len() == 1 { "one transaction".to_string() } else { format!("{} transactions", exact.len()) };
        return (
            format!("the discrepancy is exactly {what} in this period — check whether it was counted twice, or a matching one is missing"),
            exact,
        );
    }
    ("no single transaction accounts for it — the statement is probably missing rows".to_string(), Vec::new())
}

pub fn reconcile(txns: &[Txn], periods: &[StatementPeriod]) -> ReconcileResult {
    let mut problems: Vec<Problem> = Vec::new();
    let mut reports: Vec<PeriodReport> = Vec::new();
    let mut claimed: Vec<bool> = vec![false; txns.len()];

    for p in periods {
        let rows: Vec<Txn> = txns
            .iter()
            .enumerate()
            .filter(|(i, t)| {
                let hit = in_period(t, p);
                if hit {
                    claimed[*i] = true;
                }
                hit
            })
            .map(|(_, t)| t.clone())
            .collect();

        let wrong_currency: Vec<Txn> = rows.iter().filter(|t| t.amount.currency != p.opening.currency).cloned().collect();
        for t in &wrong_currency {
            problems.push(Problem {
                kind: ProblemKind::CurrencyMismatch,
                account: p.account.clone(),
                detail: format!(
                    "a {} transaction on {} sits in a {} statement — converting it is a decision, not an assumption this can make",
                    t.amount.currency, t.date, p.opening.currency
                ),
                amount: None,
                suspects: vec![t.clone()],
            });
        }

        let same: Vec<Money> = rows.iter().filter(|t| t.amount.currency == p.opening.currency).map(|t| t.amount).collect();
        let movement = sum(&same, p.opening.currency).unwrap_or(money(0, p.opening.currency));
        let computed = money(p.opening.minor + movement.minor, p.opening.currency);
        let discrepancy = subtract(p.closing, computed).unwrap_or(money(0, p.opening.currency));
        let balanced = discrepancy.minor == 0 && wrong_currency.is_empty();

        if discrepancy.minor != 0 {
            let (detail, suspects) = explain(discrepancy.minor, &rows);
            problems.push(Problem {
                kind: ProblemKind::Unbalanced,
                account: p.account.clone(),
                detail: format!("{}..{} is out by {} minor units — {detail}", p.from, p.to, discrepancy.minor),
                amount: Some(discrepancy),
                suspects,
            });
        }

        reports.push(PeriodReport {
            account: p.account.clone(),
            from: p.from.clone(),
            to: p.to.clone(),
            balanced,
            opening: p.opening,
            closing: p.closing,
            computed,
            discrepancy,
            counted: rows.len(),
        });
    }

    // BETWEEN the statements, per account: a gap, an overlap, or an opening that disagrees with the
    // previous closing. Each period can balance perfectly and the SET still be missing a month.
    let mut by_account: std::collections::BTreeMap<&str, Vec<&StatementPeriod>> = std::collections::BTreeMap::new();
    for p in periods {
        by_account.entry(p.account.as_str()).or_default().push(p);
    }
    for (account, ps) in &by_account {
        let mut sorted = ps.clone();
        sorted.sort_by(|a, b| a.from.cmp(&b.from));
        for w in sorted.windows(2) {
            let (prev, next) = (w[0], w[1]);
            if next.from <= prev.to {
                problems.push(Problem {
                    kind: ProblemKind::Overlap,
                    account: (*account).to_string(),
                    detail: format!(
                        "{}..{} overlaps {}..{} — the shared days would be counted twice",
                        next.from, next.to, prev.from, prev.to
                    ),
                    amount: None,
                    suspects: Vec::new(),
                });
                continue;
            }
            let missing = days_between(&prev.to, &next.from) - 1;
            if missing > 0 {
                problems.push(Problem {
                    kind: ProblemKind::Gap,
                    account: (*account).to_string(),
                    detail: format!(
                        "{missing} day(s) uncovered between {} and {} — anything spent in them is absent, and every total below is too low by however much that was",
                        prev.to, next.from
                    ),
                    amount: None,
                    suspects: Vec::new(),
                });
                continue;
            }
            if next.opening.minor != prev.closing.minor {
                problems.push(Problem {
                    kind: ProblemKind::Continuity,
                    account: (*account).to_string(),
                    detail: format!(
                        "{} opens at {} but {} closed at {} — consecutive statements disagree about the same moment",
                        next_day(&prev.to),
                        next.opening.minor,
                        prev.to,
                        prev.closing.minor
                    ),
                    amount: subtract(next.opening, prev.closing).ok(),
                    suspects: Vec::new(),
                });
            }
        }
    }

    let uncovered: Vec<Txn> = txns.iter().zip(&claimed).filter(|(_, c)| !**c).map(|(t, _)| t.clone()).collect();
    let ok = problems.is_empty() && uncovered.is_empty() && !periods.is_empty();
    let through = coverage_through(periods);

    let ledger = match (ok, through) {
        (true, Some(through)) => {
            let mut sorted = txns.to_vec();
            sorted.sort_by(|a, b| a.date.cmp(&b.date));
            Some(ReconciledLedger {
                txns: sorted,
                through,
                accounts: by_account.keys().map(|k| (*k).to_string()).collect(),
                unverified: false,
                caveat: None,
            })
        }
        _ => None,
    };

    ReconcileResult { ok, ledger, periods: reports, problems, uncovered }
}

/// A ledger accepted WITHOUT a reconcile, because sometimes there is no opening balance to check
/// against and a system that refuses outright is a system nobody uses.
///
/// Deliberately ugly to reach for: it demands a reason, marks the ledger `unverified`, and its name
/// is greppable — so "which of these figures rests on unchecked data?" is a question with an answer.
pub fn unverified_ledger(txns: &[Txn], through: &str, caveat: &str) -> Result<ReconciledLedger, String> {
    if caveat.trim().is_empty() {
        return Err("an unverified ledger must say why it could not be reconciled".to_string());
    }
    let mut sorted = txns.to_vec();
    sorted.sort_by(|a, b| a.date.cmp(&b.date));
    let mut accounts: Vec<String> = sorted.iter().map(|t| t.account.clone()).collect();
    accounts.sort();
    accounts.dedup();
    Ok(ReconciledLedger {
        txns: sorted,
        through: through.to_string(),
        accounts,
        unverified: true,
        caveat: Some(caveat.to_string()),
    })
}

/// A currency for a period, so a caller does not have to reach into `money` for the common case.
pub fn usd_period(account: &str, from: &str, to: &str, opening: i64, closing: i64) -> StatementPeriod {
    StatementPeriod {
        account: account.to_string(),
        from: from.to_string(),
        to: to.to_string(),
        opening: money(opening, Currency::USD),
        closing: money(closing, Currency::USD),
    }
}

