        assert_eq!(from_statement_balance(Kind::Credit, usd(-5_000)).minor, 5_000);
        assert_eq!(from_statement_balance(Kind::Checking, usd(120_000)).minor, 120_000);

        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), card()],
            &[bal("checking", 120_000), bal("card", -243_107)],
            Currency::USD,
        );
        assert_eq!(p.net_worth.minor, -123_107);
        assert_eq!(p.liquid.minor, 120_000);
        assert_eq!(p.total_debt.minor, 243_107);

        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), card(), loan()],
            &[bal("checking", 120_000), bal("card", -200_000), bal("loan", -800_000)],
            Currency::USD,
        );
        let c = p.accounts.iter().find(|a| a.account == "card").unwrap();
        assert_eq!(c.utilisation, Some(0.333));
        assert_eq!(c.available.unwrap().minor, 400_000);
        assert_eq!(c.daily_interest.unwrap().minor, 137);
        assert_eq!(p.weighted_apr, Some(0.1059));
        assert_eq!(p.minimums_due.minor, 31_000);
        assert_eq!(p.daily_interest.minor, 290);
        assert_eq!(annual_interest_cost(&p).minor, 105_850);
        assert_eq!(overall_utilisation(&p), Some(0.333));
        assert_eq!(by_cost(&p).iter().map(|a| a.account.as_str()).collect::<Vec<_>>(), ["card", "loan"]);
    }

    #[test]
    fn a_payment_from_chequing_to_a_card_moves_nothing() {
        // The proof the sign contract holds end to end. A model that reports an improvement in net
        // worth here is wrong in a way that feels like progress.
        let accounts = [acct("checking", Kind::Checking), card()];
        let balances = [bal("checking", 120_000), bal("card", -200_000)];
        let before = position(&led(&[]), &accounts, &balances, Currency::USD);
        let after = position(
            &led(&[tx("2026-06-10", "PAYMENT TO CARD", -30_000, "checking"), tx("2026-06-10", "PAYMENT RECEIVED", 30_000, "card")]),
            &accounts,
            &balances,
            Currency::USD,
        );
        assert_eq!(after.net_worth.minor, before.net_worth.minor);
        // Not a no-op though: liquidity fell and the debt shrank.
        assert_eq!(after.liquid.minor, 90_000);
        assert_eq!(after.total_debt.minor, 170_000);
    }

    #[test]
    fn only_what_came_after_the_stated_balance_is_applied() {
        // A transaction dated ON the balance date is already inside it. Applying it again
        // double-counts, and the result is still a plausible number.
        let p = position(
            &led(&[
                tx("2026-05-20", "BEFORE", -10_000, "checking"),
                tx("2026-06-01", "ON THE DATE", -5_000, "checking"),
                tx("2026-06-10", "AFTER", -2_500, "checking"),
            ]),
            &[acct("checking", Kind::Checking)],
            &[bal("checking", 120_000)],
            Currency::USD,
        );
        assert_eq!(p.accounts[0].rolled_forward, 1);
        assert_eq!(p.accounts[0].balance.minor, 117_500);
    }

    #[test]
    fn what_is_unknown_is_none_rather_than_zero() {
        // 0% utilised is an excellent score. Not knowing is not an excellent score.
        let no_limit = Account { credit_limit: None, ..card() };
        let p = position(&led(&[]), &[no_limit], &[bal("card", -200_000)], Currency::USD);
        assert_eq!(p.accounts[0].utilisation, None);
        assert_eq!(p.accounts[0].available, None);
        assert!(!p.complete);
        assert!(p.problems.iter().any(|x| x.contains("UNKNOWN")));

        let no_apr = Account { apr_bps: None, ..card() };
        let p = position(&led(&[]), &[no_apr], &[bal("card", -200_000)], Currency::USD);
        assert_eq!(p.accounts[0].daily_interest, None);
        assert_eq!(p.weighted_apr, None);
        assert!(p.problems.iter().any(|x| x.contains("understate")));
    }

    #[test]
    fn a_cleared_debt_owes_nothing_costs_nothing_and_is_not_due_a_minimum() {
        let p = position(&led(&[]), &[card()], &[bal("card", 0)], Currency::USD);
        assert_eq!(p.accounts[0].owed, None);
        assert_eq!(p.accounts[0].utilisation, Some(0.0));
        assert_eq!(p.minimums_due.minor, 0);
        assert_eq!(p.daily_interest.minor, 0);
        assert_eq!(p.total_debt.minor, 0);
    }

    #[test]
    fn an_undeclared_account_is_named_and_left_out_rather_than_given_an_invented_sign() {
        let p = position(
            &led(&[tx("2026-06-10", "MYSTERY", -30_000, "unknown-account")]),
            &[acct("checking", Kind::Checking)],
            &[bal("checking", 120_000)],
            Currency::USD,
        );
        assert!(!p.complete);
        assert!(p.problems.iter().any(|x| x.contains("'unknown-account'")));
        assert_eq!(p.net_worth.minor, 120_000);
    }

    #[test]
    fn another_currency_is_excluded_rather_than_converted() {
        let eur = Account { currency: "EUR".into(), ..acct("eu", Kind::Checking) };
        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), eur],
            &[bal("checking", 120_000), bal("eu", 90_000)],
            Currency::USD,
        );
        assert_eq!(p.accounts.len(), 1);
        assert_eq!(p.net_worth.minor, 120_000);
        assert!(p.problems.iter().any(|x| x.contains("not one number")));
    }

    #[test]
    fn an_investment_counts_toward_net_worth_but_never_toward_liquidity() {
        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), acct("broker", Kind::Investment)],
            &[bal("checking", 120_000), bal("broker", 4_000_000)],
            Currency::USD,
        );
        assert_eq!(p.net_worth.minor, 4_120_000);
        assert_eq!(p.liquid.minor, 120_000);
    }

    #[test]
    fn an_unreconciled_ledger_carries_its_caveat_forward_instead_of_being_laundered() {
        let l = unverified_ledger(&[], "2026-06-30", "Chase export has no opening balance").unwrap();
        let p = position(&l, &[acct("checking", Kind::Checking)], &[bal("checking", 120_000)], Currency::USD);
        assert!(!p.complete);
        assert!(p.problems.iter().any(|x| x.contains("Chase export has no opening balance")));
        assert!(p.provenance.starts_with("UNVERIFIED"));
    }

    #[test]
    fn the_weighted_apr_weights_by_balance_not_by_account_count() {
        // $8,000 at 6.99% and $2,000 at 24.99% is not a 15.99% problem, and averaging the rates
        // would send somebody at the wrong debt first.
        let p = position(
            &led(&[]),
            &[card(), loan()],
            &[bal("card", -200_000), bal("loan", -800_000)],
            Currency::USD,
        );
        let w = p.weighted_apr.unwrap();
        assert!(w < (0.2499 + 0.0699) / 2.0, "weighted {w} should be below the plain mean");
        assert_eq!(w, 0.1059);
    }
}

//! Balances — and the conversion that has to happen at the boundary, not in somebody's head.
//!
//! # A person types what the statement prints
//!
//! That is the whole design constraint. A card statement says `2,431.07` and means you OWE it; a
//! chequing statement says `1,200.00` and means you HAVE it. The analysis needs both SIGNED by their
//! contribution to net worth, so something must convert — and asking a person to pre-negate a card
//! balance is asking them to get it wrong. They will type what they are looking at.
//!
//! So [`set_printed`] takes the printed figure and the account's KIND, and converts. Which means it
//! cannot store a balance for an account the registry has never heard of: without the kind, the sign
//! is not merely unknown, it is unknowable, and storing the number unconverted would put a debt into
//! net worth as an asset. The refusal is principled rather than fussy.
//!
//! # History is kept, and the LATEST is what gets used
//!
//! `position` rolls a balance forward with the transactions after it, so the most recent balance is
//! the one with the least rolling to do and therefore the least room for drift. Older ones are kept
//! rather than overwritten — a balance is an observation, and a store that forgets observations
//! cannot answer why a figure changed.
use crate::account::{Account, Kind};
use crate::money::{money, Currency, Money};
use crate::position::AccountBalance;
use crate::reconcile::StatementPeriod;

/// Record a balance from the figure a statement PRINTS.
///
/// The `kind` decides the sign, so this is the only place a printed number becomes a signed one.
pub fn from_printed(account: &str, as_of: &str, printed: Money, kind: Kind) -> AccountBalance {
    AccountBalance {
        account: account.to_string(),
        as_of: as_of.to_string(),
        balance: crate::position::from_statement_balance(kind, printed),
    }
}

/// The most recent balance for one account, or none.
///
/// LATEST, because `position` rolls forward from it: the nearer the observation, the fewer
/// transactions have to be applied on top and the less there is to get wrong.
pub fn latest_for<'a>(balances: &'a [AccountBalance], account: &str) -> Option<&'a AccountBalance> {
    balances.iter().filter(|b| b.account == account).max_by(|a, b| a.as_of.cmp(&b.as_of))
}

/// One balance per account — the set `position` actually consumes.
pub fn latest_each(balances: &[AccountBalance]) -> Vec<AccountBalance> {
    let mut ids: Vec<&str> = balances.iter().map(|b| b.account.as_str()).collect();
    ids.sort();
    ids.dedup();
    ids.iter().filter_map(|id| latest_for(balances, id).cloned()).collect()
}

/// Add an observation, keeping every earlier one — unless it is the same account on the same DAY, in
/// which case it is a correction rather than a new observation and replaces it.
pub fn record(balances: &mut Vec<AccountBalance>, next: AccountBalance) {
    match balances.iter_mut().find(|b| b.account == next.account && b.as_of == next.as_of) {
        Some(slot) => *slot = next,
        None => {
            balances.push(next);
            balances.sort_by(|a, b| a.account.cmp(&b.account).then(a.as_of.cmp(&b.as_of)));
        }
    }
}

/// Accounts the registry declares that have no balance at all — the reason a position is missing a
/// row rather than showing it as zero.
pub fn without_balance(accounts: &[Account], balances: &[AccountBalance]) -> Vec<String> {
    accounts
        .iter()
        .filter(|a| latest_for(balances, &a.id).is_none())
        .map(|a| a.id.clone())
        .collect()
}

pub fn to_json(balances: &[AccountBalance]) -> serde_json::Value {
    serde_json::Value::Array(
        balances
            .iter()
            .map(|b| {
                serde_json::json!({
                    "account": b.account,
                    "asOf": b.as_of,
                    // SIGNED, and labelled as such — a reader that took this for a printed figure
                    // would negate every card balance back to wrong.
                    "signedMinor": b.balance.minor,
                    "currency": b.balance.currency.as_str(),
                })
            })
            .collect(),
    )
}

pub fn from_json(v: &serde_json::Value) -> Vec<AccountBalance> {
    let mut out: Vec<AccountBalance> = v
        .as_array()
        .map(Vec::as_slice)
        .unwrap_or_default()
        .iter()
        .filter_map(|b| {
            Some(AccountBalance {
                account: b.get("account")?.as_str()?.to_string(),
                as_of: b.get("asOf")?.as_str()?.to_string(),
                balance: money(
                    b.get("signedMinor")?.as_i64()?,
                    Currency::new(b.get("currency").and_then(|c| c.as_str()).unwrap_or("USD")).unwrap_or(Currency::USD),
                ),
            })
        })
        .collect();
    out.sort_by(|a, b| a.account.cmp(&b.account).then(a.as_of.cmp(&b.as_of)));
    out
}

/// The balances the STATEMENTS themselves assert.
///
/// A running-balance column is the institution stating what the account held when the period closed,
/// so a period's closing figure is an observation of exactly the kind a person supplies by typing
/// what the statement prints — arriving by a path that cannot mistype it. Deriving it is why
/// `bsc fin position` can answer at all from an export alone, instead of declaring an account and
/// then reporting that it has no balance.
///
/// The bounds arrive ALREADY SIGNED (`statement::period_from_running` converts at the boundary, for
/// `reconcile`'s sake), so nothing here converts. That is the one thing to know before editing this:
/// routing these through [`from_printed`] would negate every card balance a second time.
pub fn from_periods(periods: &[StatementPeriod]) -> Vec<AccountBalance> {
    periods
        .iter()
        .map(|p| AccountBalance { account: p.account.clone(), as_of: p.to.clone(), balance: p.closing })
        .collect()
}

/// Merge derived balances under observed ones — **the observed wins on the same day**.
///
/// Both are observations, so neither is categorically better; the tie-break is which one a person
/// can correct. A statement's closing figure is fixed by the export, while a balance somebody typed
/// is what they were looking at in the account — often BECAUSE the derived one looked wrong. Letting
/// the derivation overwrite that would make the correction impossible to express, and it would do it
/// silently, which is the part that matters.
///
/// A stored balance on any OTHER day is kept as its own observation rather than replacing anything —
/// [`record`]'s same-account-same-day rule is the whole of the collision policy.
pub fn prefer_observed(stored: &[AccountBalance], derived: &[AccountBalance]) -> Vec<AccountBalance> {
    let mut out = derived.to_vec();
    for b in stored {
        record(&mut out, b.clone());
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY.
    fn period(account: &str, to: &str, closing: i64) -> StatementPeriod {
        crate::reconcile::usd_period(account, "2026-06-01", to, 0, closing)
    }

    #[test]
    fn a_statements_closing_figure_becomes_a_balance_at_the_period_end() {
        let out = from_periods(&[period("chase-checking", "2026-06-20", 40_000)]);
        assert_eq!(out.len(), 1);
        assert_eq!(out[0].as_of, "2026-06-20", "the balance is observed when the period CLOSED");
        assert_eq!(out[0].balance.minor, 40_000);
    }

    #[test]
    fn a_balance_a_person_typed_beats_the_one_derived_for_that_same_day() {
        let derived = from_periods(&[period("chase-checking", "2026-06-20", 40_000)]);
        // They looked at the account and it said 385.12 — the export was stale, or a fee landed after.
        let stored = vec![AccountBalance {
            account: "chase-checking".to_string(),
            as_of: "2026-06-20".to_string(),
            balance: usd(38_512),
        }];
        let out = prefer_observed(&stored, &derived);
        assert_eq!(out.len(), 1, "same account, same day is ONE observation, not two");
        assert_eq!(out[0].balance.minor, 38_512, "the correction must survive the derivation");
    }

    #[test]
    fn a_stored_balance_on_another_day_is_kept_alongside_the_derived_one() {
        let derived = from_periods(&[period("chase-checking", "2026-06-20", 40_000)]);
        let stored = vec![AccountBalance {
            account: "chase-checking".to_string(),
            as_of: "2026-07-02".to_string(),
            balance: usd(12_000),
        }];
        let out = prefer_observed(&stored, &derived);
        assert_eq!(out.len(), 2, "different days are different observations");
        assert_eq!(latest_for(&out, "chase-checking").unwrap().balance.minor, 12_000);
    }

    fn acct(id: &str, kind: Kind) -> Account {
        Account {
            id: id.into(),
            institution: id.into(),
            kind,
            currency: "USD".into(),
            credit_limit: None,
            apr_bps: None,
            minimum_payment: None,
            statement_day: None,
            note: None,
        }
    }

    #[test]
    fn a_card_balance_typed_as_printed_becomes_a_debt() {
        // THE WHOLE POINT. A person types 2431.07 because that is what they are looking at. Stored
        // unconverted it would be $2,431 of net worth in the wrong direction — a $4,862 error on one
        // account, and it would look entirely plausible.
        let b = from_printed("card", "2026-06-30", usd(243_107), Kind::Credit);
        assert_eq!(b.balance.minor, -243_107);
    }

    #[test]
    fn a_chequing_balance_typed_as_printed_is_left_alone() {
        assert_eq!(from_printed("checking", "2026-06-30", usd(120_000), Kind::Checking).balance.minor, 120_000);
    }

    #[test]
    fn an_overpaid_card_prints_negative_and_becomes_money_you_have() {
        // The rule holds in both directions rather than being a special case for the common one.
        assert_eq!(from_printed("card", "2026-06-30", usd(-5_000), Kind::Credit).balance.minor, 5_000);
    }

    #[test]
    fn the_latest_observation_is_the_one_used() {
        // position rolls forward from it, so the nearer the observation the less there is to get
        // wrong on top of it.
        let mut bs = Vec::new();
        record(&mut bs, from_printed("card", "2026-04-30", usd(300_000), Kind::Credit));
        record(&mut bs, from_printed("card", "2026-06-30", usd(243_107), Kind::Credit));
        record(&mut bs, from_printed("card", "2026-05-31", usd(280_000), Kind::Credit));
        assert_eq!(latest_for(&bs, "card").unwrap().as_of, "2026-06-30");
        assert_eq!(bs.len(), 3, "earlier observations are kept, not overwritten");
    }

    #[test]
    fn the_same_account_on_the_same_day_is_a_correction_not_a_second_observation() {
        let mut bs = Vec::new();
        record(&mut bs, from_printed("card", "2026-06-30", usd(999_999), Kind::Credit));
        record(&mut bs, from_printed("card", "2026-06-30", usd(243_107), Kind::Credit));
        assert_eq!(bs.len(), 1);
        assert_eq!(bs[0].balance.minor, -243_107);
    }

    #[test]
    fn latest_each_gives_position_exactly_one_row_per_account() {
        let mut bs = Vec::new();
        record(&mut bs, from_printed("card", "2026-04-30", usd(300_000), Kind::Credit));
        record(&mut bs, from_printed("card", "2026-06-30", usd(243_107), Kind::Credit));
        record(&mut bs, from_printed("checking", "2026-06-30", usd(120_000), Kind::Checking));
        let latest = latest_each(&bs);
