            got,
            vec![
                ("2026-07", 500_000, 300_000, -50_000, 450_000),
                ("2026-08", 450_000, 280_000, -70_000, 380_000),
                ("2026-09", 380_000, 260_000, -90_000, 290_000),
                ("2026-10", 290_000, 240_000, -110_000, 180_000)
            ]
        );
        assert!(survives_horizon(&r.low));
        assert_eq!(r.low.exhausts_in, None);
        assert_eq!(r.low.monthly_gap.minor, 0);
        assert_eq!(r.through.as_deref(), Some("2026-10"));
        // ZERO discretionary is allowed and is SAID OUT LOUD, because a runway that quietly assumes
        // groceries are free is the flattering kind of wrong.
        assert_eq!(r.problems.len(), 1);
        assert!(r.problems[0].contains("groceries"));
        assert!(summarise(&r).starts_with("on the LOW income band the money holds through 2026-10, tightest at 2026-10 with 180000"));
    }

    #[test]
    fn the_headline_is_the_low_band_and_that_is_the_modules_position() {
        let r = runway(&position(100_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &opts(80_000));
        // The same data on EXPECTED income needs 5000 a month; on LOW it needs 135000. A headline on
        // expected would be right on average and useless in the case that matters.
        assert_eq!(r.low.monthly_gap.minor, 135_000);
        assert_eq!(r.expected.monthly_gap.minor, 5_000);
        assert_eq!(r.headline.monthly_gap.minor, r.low.monthly_gap.minor);
        assert_eq!(r.headline.scenario, Scenario::Low);
        assert!(r.high.monthly_gap.minor < r.low.monthly_gap.minor);
    }

    #[test]
    fn the_monthly_gap_is_solved_exactly_rather_than_searched_for() {
        let r = runway(&position(100_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &opts(80_000));
        let closings: Vec<i64> = r.low.months.iter().map(|m| m.closing.minor).collect();
        assert_eq!(closings, vec![-30_000, -180_000, -350_000, -540_000]);
        // Adding x per month raises month i by x*(i+1), so the binding constraint is the LARGEST
        // per-month share: max(30000/1, 180000/2, 350000/3, 540000/4) = 135000, from the LAST month
        // rather than the deepest ratio.
        assert_eq!(r.low.monthly_gap.minor, 135_000);
        // And it holds: 135000 a month clears every month.
        for (i, c) in closings.iter().enumerate() {
            assert!(c + 135_000 * (i as i64 + 1) >= 0, "month {i} still short");
        }
        assert_eq!(annual_gap(&r).minor, 1_620_000);
    }

    #[test]
    fn the_first_short_month_is_the_answer_not_the_worst_one() {
        let r = runway(&position(100_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &opts(80_000));
        assert_eq!(r.low.exhausts_in.as_deref(), Some("2026-07"), "the FIRST month that ends short");
        assert_eq!(r.low.months_of_cover, Some(0));
        // The TIGHTEST month is later and deeper. Both are reported because they answer different
        // questions: when do I run out, and how bad does it get.
        assert_eq!(r.low.tightest.as_ref().unwrap().month, "2026-10");
        assert_eq!(r.low.months[0].shortfall.unwrap().minor, 30_000, "the shortfall is POSITIVE");
        assert!(!survives_horizon(&r.low));
    }

    #[test]
    fn the_horizon_is_cut_to_the_calendar_and_the_cut_is_stated() {
        let r = runway(&position(500_000, true, vec![]), &projection(), &calendar("2026-08-31", 350_000), &opts(50_000));
        assert_eq!(r.low.months.len(), 2, "four months projected, two covered");
        assert_eq!(r.through.as_deref(), Some("2026-08"));
        // Without truncation the last two months would cost NOTHING and the runway would extend on
        // a gap in the data rather than on money.
        assert!(r.problems.iter().any(|p| p.contains("not the same as nothing being due")));
    }

    #[test]
    fn no_projection_is_a_refusal_that_carries_the_projections_own_reason() {
        let bad = IncomeProjection {
            projectable: false,
            reason: Some("2 whole month(s) of history; 3 are needed".to_string()),
            months: Vec::new(),
            total: None,
            assumptions: Vec::new(),
            excluded: Vec::new(),
            sources_used: 0,
        };
        let r = runway(&position(500_000, true, vec![]), &bad, &calendar("2026-10-31", 350_000), &opts(50_000));
        assert!(r.low.months.is_empty());
        assert!(!survives_horizon(&r.low), "an empty walk has not survived anything");
        assert_eq!(r.through, None);
        assert!(r.problems.last().unwrap().contains("2 whole month(s) of history"));
        assert_eq!(summarise(&r), "no runway could be computed — no runway without an income projection: 2 whole month(s) of history; 3 are needed");
    }

    #[test]
    fn a_calendar_that_does_not_overlap_the_projection_refuses_rather_than_assuming_free_months() {
        let far = ObligationCalendar { from: "2027-01-01".to_string(), to: "2027-03-31".to_string(), obligations: Vec::new(), by_month: Vec::new(), heaviest: None, notes: Vec::new() };
        let r = runway(&position(500_000, true, vec![]), &projection(), &far, &opts(50_000));
        assert!(r.low.months.is_empty());
        assert_eq!(r.problems.len(), 2, "the truncation AND the refusal are both stated");
        assert!(r.problems[1].contains("covers none of the projected months"));
    }

    #[test]
    fn an_incomplete_position_is_inherited_along_with_its_own_problems() {
        let r = runway(&position(500_000, false, vec!["a balance is stale".to_string()]), &projection(), &calendar("2026-10-31", 350_000), &opts(50_000));
        // The position's own problems come FIRST and are not replaced — a runway cannot be sounder
        // than the position under it.
        assert_eq!(r.problems[0], "a balance is stale");
        assert!(r.problems[1].contains("incomplete"));
        assert_eq!(r.low.exhausts_in.as_deref(), Some("2026-10"));
        assert_eq!(r.low.months_of_cover, Some(3));
        assert_eq!(r.low.monthly_gap.minor, 5_000);
        assert_eq!(r.provenance, "reconciled", "the provenance travels with the figure");
    }

    #[test]
    fn a_mismatched_discretionary_currency_refuses_rather_than_subtracting_it_anyway() {
        let eur = Currency::new("EUR").expect("a three-letter code");
        let r = runway(&position(500_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &RunwayOptions { discretionary: money(50_000, eur) });
        assert!(r.low.months.is_empty());
        assert!(r.problems.last().unwrap().contains("EUR"));
    }
}

//! Debt payoff — which debt to attack first, and what the choice actually costs.
//!
//! Two orderings are in common use and they optimise different things:
//!
//! - **Avalanche** — highest interest RATE first. Mathematically optimal: it always pays the least
//!   total interest and is never slower.
//! - **Snowball** — smallest BALANCE first. Pays more, sometimes much more — but clears whole
//!   accounts sooner, and finishing one is what makes people keep going.
//!
//! This module does not pick for you. It runs both and reports the difference in money and months, so
//! the trade is a NUMBER rather than a slogan. That is the honest framing: snowball's cost is real
//! and so is its benefit, and only the person paying can weigh them.
//!
//! Everything is integer MINOR UNITS. A payoff schedule is exactly where float drift shows up as a
//! final instalment that is a cent off and a total that will not reconcile.
use crate::money::{money, sum, Money, Rounding};

/// One debt, as the payer knows it.
#[derive(Debug, Clone, PartialEq)]
pub struct Debt {
    /// How the payer refers to it — shown back in the schedule.
    pub name: String,
    /// What is owed now.
    pub balance: Money,
    /// NOMINAL annual rate as a fraction: 0.2299 for 22.99% APR.
    pub apr: f64,
    /// The contractual minimum for a period. Paying less is default, so it is never skipped.
    pub minimum: Money,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Strategy {
    Avalanche,
    Snowball,
}

impl Strategy {
    pub fn label(self) -> &'static str {
        match self {
            Strategy::Avalanche => "avalanche",
            Strategy::Snowball => "snowball",
        }
    }
}

/// What happened to one debt in one period.
#[derive(Debug, Clone, PartialEq)]
pub struct Payment {
    pub name: String,
    pub interest: Money,
    pub principal: Money,
    pub balance: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Period {
    /// 1-based; period 1 is the first payment made.
    pub period: usize,
    pub payments: Vec<Payment>,
    /// Debts that reached zero in THIS period — the moment a snowball payer is waiting for.
    pub cleared_this_period: Vec<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Plan {
    pub strategy: Strategy,
    pub periods: Vec<Period>,
    /// How many periods until every balance is zero.
    pub months: usize,
    pub total_interest: Money,
    pub total_paid: Money,
    /// Payoff order, in the order each debt actually cleared.
    pub order: Vec<String>,
}

/// Why no schedule exists. A REFUSAL, never a truncated plan that stops at an arbitrary horizon and
/// reads as one.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Unpayable(pub String);

impl std::fmt::Display for Unpayable {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for Unpayable {}

/// Periodic rate from a nominal annual rate. 12 periods a year unless stated.
pub fn periodic_rate(apr: f64, periods_per_year: f64) -> f64 {
    apr / periods_per_year
}

pub struct PayoffOptions {
    pub periods_per_year: f64,
    pub max_periods: usize,
}

impl Default for PayoffOptions {
    fn default() -> Self {
        PayoffOptions { periods_per_year: 12.0, max_periods: 1200 }
    }
}

/// The ORDER the strategy attacks in.
///
/// Ties are broken by the other key, then by NAME, so a run is deterministic — two runs of the same
/// input must produce the same schedule or the comparison below is not reproducible.
pub fn payoff_order(debts: &[Debt], strategy: Strategy) -> Vec<Debt> {
    let mut out = debts.to_vec();
    out.sort_by(|a, b| {
        let by_rate = b.apr.partial_cmp(&a.apr).unwrap_or(std::cmp::Ordering::Equal);
        let by_balance = a.balance.minor.cmp(&b.balance.minor);
        let first = match strategy {
            Strategy::Avalanche => by_rate.then(by_balance),
            Strategy::Snowball => by_balance.then(by_rate),
        };
        first.then_with(|| a.name.cmp(&b.name))
    });
    out
}

/// Run one strategy to completion.
///
/// The mechanics, which are the same either way and are what actually retires debt:
///
/// - every debt accrues interest on its balance, then takes at least its minimum;
/// - whatever is left of `monthly_payment` goes ENTIRELY to the target — the first unpaid debt in
///   strategy order;
/// - when a debt clears, its minimum is NOT saved. It rolls into the next target. That rolling is
///   the "snowball", and it is why both strategies accelerate rather than run at a constant rate.
///
/// REFUSES an unpayable plan rather than looping. If the budget cannot cover the minimums, or a
/// balance grows despite paying them, no schedule exists.
pub fn payoff(debts: &[Debt], monthly_payment: Money, strategy: Strategy, opts: &PayoffOptions) -> Result<Plan, Unpayable> {
    if debts.is_empty() {
        return Err(Unpayable("payoff needs at least one debt".to_string()));
    }
    let currency = monthly_payment.currency;

    let mins: Vec<Money> = debts.iter().map(|d| d.minimum).collect();
    let minimums = sum(&mins, currency).map_err(|e| Unpayable(e.to_string()))?;
    if monthly_payment.minor < minimums.minor {
        return Err(Unpayable(format!(
            "the budget cannot cover the minimum payments ({} minor units of {}); a plan that ignores that is not a plan — the shortfall has to be closed first",
            minimums.minor, currency
        )));
    }

    let mut live = payoff_order(debts, strategy);
    let mut periods: Vec<Period> = Vec::new();
    let mut order: Vec<String> = Vec::new();
    let mut total_interest = money(0, currency);
    let mut total_paid = money(0, currency);

    let mut p = 0usize;
    while live.iter().any(|d| d.balance.minor != 0) {
        p += 1;
        if p > opts.max_periods {
            return Err(Unpayable(format!(
                "no payoff within {} periods — at this budget the interest is outrunning the payments, which is a fact worth stating rather than a schedule worth returning",
                opts.max_periods
            )));
        }
        let mut budget = monthly_payment.minor;
        let mut payments: Vec<Payment> = Vec::new();
        let mut cleared: Vec<String> = Vec::new();

        // 1 — interest, then the contractual minimum on every live debt.
        for d in live.iter_mut() {
            if d.balance.minor == 0 {
                continue;
            }
            let interest = crate::money::scale(d.balance, periodic_rate(d.apr, opts.periods_per_year), Rounding::HalfUp);
            let owed = d.balance.minor + interest.minor;
            // Never pay more than clears it, and never less than the minimum — unless the debt is
            // SMALLER than its own minimum, in which case the payoff amount IS the payment.
            let wanted = if d.minimum.minor < owed { d.minimum.minor } else { owed };
            let pay = wanted.min(budget);
            budget -= pay;
            let principal = pay - interest.minor;
            d.balance = money(owed - pay, currency);
            total_interest = money(total_interest.minor + interest.minor, currency);
            total_paid = money(total_paid.minor + pay, currency);
            payments.push(Payment { name: d.name.clone(), interest, principal: money(principal, currency), balance: d.balance });
        }

        // 2 — everything left attacks the TARGET, in strategy order.
        for d in live.iter_mut() {
            if budget == 0 {
                break;
            }
            if d.balance.minor == 0 {
                continue;
            }
            let extra = d.balance.minor.min(budget);
            budget -= extra;
            d.balance = money(d.balance.minor - extra, currency);
            total_paid = money(total_paid.minor + extra, currency);
            if let Some(row) = payments.iter_mut().find(|x| x.name == d.name) {
                row.principal = money(row.principal.minor + extra, currency);
                row.balance = d.balance;
            }
        }

        for d in live.iter() {
            if d.balance.minor == 0 && !order.contains(&d.name) {
                order.push(d.name.clone());
                cleared.push(d.name.clone());
            }
        }
        periods.push(Period { period: p, payments, cleared_this_period: cleared });
    }

    Ok(Plan { strategy, months: periods.len(), periods, total_interest, total_paid, order })
}

/// What choosing snowball over avalanche costs — the number the decision actually turns on.
#[derive(Debug, Clone, PartialEq)]
pub struct Comparison {
    pub avalanche: Plan,
    pub snowball: Plan,
    /// Extra interest snowball pays. Never negative: avalanche is optimal on interest by construction.
    pub extra_interest: Money,
    /// Extra periods snowball takes. Never negative.
    pub extra_months: i64,
    /// How much SOONER snowball clears its first debt — what it buys for that cost.
    pub first_cleared_sooner: i64,
}

pub fn compare_strategies(debts: &[Debt], monthly_payment: Money, opts: &PayoffOptions) -> Result<Comparison, Unpayable> {
    let avalanche = payoff(debts, monthly_payment, Strategy::Avalanche, opts)?;
    let snowball = payoff(debts, monthly_payment, Strategy::Snowball, opts)?;
    let first_cleared = |p: &Plan| -> i64 {
        p.periods.iter().find(|x| !x.cleared_this_period.is_empty()).map(|x| x.period as i64).unwrap_or(p.months as i64)
    };
    Ok(Comparison {
        extra_interest: money(snowball.total_interest.minor - avalanche.total_interest.minor, monthly_payment.currency),
        extra_months: snowball.months as i64 - avalanche.months as i64,
        first_cleared_sooner: first_cleared(&avalanche) - first_cleared(&snowball),
        avalanche,
        snowball,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY.
    fn d(name: &str, balance: i64, apr: f64, minimum: i64) -> Debt {
        Debt { name: name.to_string(), balance: usd(balance), apr, minimum: usd(minimum) }
    }

    /// The store card has the SMALLEST balance and the LOWEST rate; medical has the HIGHEST rate at a
    /// middling balance. That is what makes the two strategies actually disagree — a fixture where
    /// the smallest debt is also the dearest one proves nothing, and my first one was exactly that.
    fn debts() -> Vec<Debt> {
        vec![d("visa", 300_000, 0.2299, 6_000), d("store", 80_000, 0.0999, 2_500), d("medical", 150_000, 0.2999, 4_000)]
    }

    #[test]
    fn avalanche_attacks_the_dearest_and_snowball_the_smallest() {
        let names = |s: Strategy| payoff_order(&debts(), s).iter().map(|d| d.name.clone()).collect::<Vec<_>>();
        assert_eq!(names(Strategy::Avalanche), vec!["medical", "visa", "store"], "by RATE");
        assert_eq!(names(Strategy::Snowball), vec!["store", "medical", "visa"], "by BALANCE");
    }

    #[test]
    fn the_cost_of_snowball_is_a_number_rather_than_a_slogan() {
        // Measured by running finance-payoff.ts on this exact fixture.
        let c = compare_strategies(&debts(), usd(40_000), &PayoffOptions::default()).expect("payable");
        assert_eq!(c.avalanche.months, 16);
        assert_eq!(c.avalanche.total_interest.minor, 78_043);
        assert_eq!(c.avalanche.total_paid.minor, 608_043);
        assert_eq!(c.snowball.months, 16);
        assert_eq!(c.snowball.total_interest.minor, 91_364);
        // Snowball costs $133.21 more and takes the same time — and clears its first debt three
        // months sooner. Both halves of the trade are reported; neither is chosen here.
        assert_eq!(c.extra_interest.minor, 13_321);
        assert_eq!(c.extra_months, 0);
        assert_eq!(c.first_cleared_sooner, 3);
        assert!(c.extra_interest.minor >= 0, "avalanche is optimal on interest BY CONSTRUCTION");
    }

    #[test]
    fn each_strategy_clears_its_debts_in_its_own_order() {
        let opts = PayoffOptions::default();
        let a = payoff(&debts(), usd(40_000), Strategy::Avalanche, &opts).expect("payable");
        let s = payoff(&debts(), usd(40_000), Strategy::Snowball, &opts).expect("payable");
        assert_eq!(a.order, vec!["medical", "visa", "store"]);
        assert_eq!(s.order, vec!["store", "medical", "visa"]);
        let cleared = |p: &Plan| p.periods.iter().filter(|x| !x.cleared_this_period.is_empty()).map(|x| (x.period, x.cleared_this_period.clone())).collect::<Vec<_>>();
        assert_eq!(cleared(&a), vec![(6, vec!["medical".to_string()]), (14, vec!["visa".to_string()]), (16, vec!["store".to_string()])]);
        assert_eq!(cleared(&s), vec![(3, vec!["store".to_string()]), (8, vec!["medical".to_string()]), (16, vec!["visa".to_string()])]);
    }

    #[test]
    fn the_first_period_pays_every_minimum_then_throws_the_rest_at_the_target() {
        let a = payoff(&debts(), usd(40_000), Strategy::Avalanche, &PayoffOptions::default()).expect("payable");
        let p1: Vec<(&str, i64, i64, i64)> = a.periods[0].payments.iter().map(|x| (x.name.as_str(), x.interest.minor, x.principal.minor, x.balance.minor)).collect();
        // medical is the target, so it takes its own minimum PLUS everything left over.
        assert_eq!(p1, vec![("medical", 3_749, 27_751, 122_249), ("visa", 5_748, 252, 299_748), ("store", 666, 1_834, 78_166)]);
        // Every minimum was still paid: 4000 + 6000 + 2500 = 12500, and the other 27500 went to the
        // target. Skipping a minimum to attack faster is default, not strategy.
        let paid: i64 = a.periods[0].payments.iter().map(|x| x.interest.minor + x.principal.minor).sum();
        assert_eq!(paid, 40_000, "the whole budget is spent, nothing is idle");
    }

    #[test]
    fn a_budget_below_the_minimums_is_refused_rather_than_scheduled() {
        let e = payoff(&debts(), usd(1_000), Strategy::Avalanche, &PayoffOptions::default()).expect_err("unpayable");
        assert!(e.0.contains("cannot cover the minimum payments (12500 minor units of USD)"));
        assert!(e.0.contains("the shortfall has to be closed first"), "it says what to DO");
    }

    #[test]
    fn interest_outrunning_the_payment_is_stated_rather_than_truncated() {
        let opts = PayoffOptions { max_periods: 24, ..PayoffOptions::default() };
        let e = payoff(&[d("runaway", 1_000_000, 0.99, 100)], usd(100), Strategy::Avalanche, &opts).expect_err("unpayable");
        assert!(e.0.contains("no payoff within 24 periods"));
        // A truncated 24-period schedule would LOOK like a plan while being none. That is the whole
        // reason this returns an error rather than the periods it managed to compute.
        assert!(e.0.contains("worth stating rather than a schedule worth returning"));
    }

    #[test]
    fn no_debts_is_refused_because_there_is_nothing_to_schedule() {
        let e = payoff(&[], usd(40_000), Strategy::Avalanche, &PayoffOptions::default()).expect_err("unpayable");
        assert_eq!(e.0, "payoff needs at least one debt");
    }

    #[test]
    fn a_debt_smaller_than_its_own_minimum_pays_only_what_clears_it() {
        // Balance 500, minimum 2500. Paying the minimum would overpay by 2000.
        let p = payoff(&[d("tiny", 500, 0.2, 2_500)], usd(2_500), Strategy::Avalanche, &PayoffOptions::default()).expect("payable");
        assert_eq!(p.months, 1);
        assert_eq!(p.total_interest.minor, 8);
        assert_eq!(p.total_paid.minor, 508, "500 principal + 8 interest, NOT the 2500 minimum");
        let row = &p.periods[0].payments[0];
        assert_eq!((row.interest.minor, row.principal.minor, row.balance.minor), (8, 500, 0));
    }

    #[test]
    fn ties_break_deterministically_so_two_runs_agree() {
        let same = vec![d("b", 50_000, 0.2, 1_000), d("a", 50_000, 0.2, 1_000)];
        assert_eq!(payoff_order(&same, Strategy::Avalanche).iter().map(|d| d.name.clone()).collect::<Vec<_>>(), vec!["a", "b"], "by NAME once rate and balance tie");
        // Equal balances under avalanche fall back to the rate.
        let by_rate = vec![d("hi", 50_000, 0.3, 1_000), d("lo", 50_000, 0.1, 1_000)];
        assert_eq!(payoff_order(&by_rate, Strategy::Avalanche)[0].name, "hi");
        // Equal-ish rates under snowball fall back to the balance.
        let by_balance = vec![d("big", 90_000, 0.3, 1_000), d("small", 10_000, 0.1, 1_000)];
        assert_eq!(payoff_order(&by_balance, Strategy::Snowball)[0].name, "small");
    }

    #[test]
    fn the_periodic_rate_divides_the_nominal_annual_one() {
        assert!((periodic_rate(0.2299, 12.0) - 0.019158333333333333).abs() < 1e-15);
        assert!((periodic_rate(0.2299, 26.0) - 0.008842307692307693).abs() < 1e-15);
    }

    #[test]
    fn the_schedule_reconciles_to_the_cent() {
        // The reason this is integer minor units: principal + interest across every period must
        // equal what was paid, and the balances must reach exactly zero rather than nearly zero.
        let a = payoff(&debts(), usd(40_000), Strategy::Avalanche, &PayoffOptions::default()).expect("payable");
        let principal: i64 = a.periods.iter().flat_map(|p| p.payments.iter()).map(|x| x.principal.minor).sum();
        let interest: i64 = a.periods.iter().flat_map(|p| p.payments.iter()).map(|x| x.interest.minor).sum();
        assert_eq!(interest, a.total_interest.minor);
        assert_eq!(principal + interest, a.total_paid.minor);
        // And the principal repaid equals exactly what was owed at the start.
        assert_eq!(principal, 300_000 + 80_000 + 150_000);
        for p in a.periods.last().expect("periods").payments.iter() {
            assert_eq!(p.balance.minor, 0, "{} did not reach exactly zero", p.name);
        }
    }
}

//! Spending analysis — and the one thing it exists to get right: **a transfer is not spending**.
//!
//! Paying $300 from chequing to a credit card looks exactly like a $300 outflow. It is not
//! consumption — it is the same money in a different place, and the card minimum is ALREADY on the
//! obligation calendar. Counting it here as well subtracts it twice from the runway, which shortens
//! the answer in a way that looks like prudence and is simply wrong. Moving money between your own
//! accounts is the same mistake with no upside at all.
//!
//! So outflows are classified before anything is totalled: PAIRED (an outflow matched by an inflow of
//! the same size on another account within a few days), DEBT (a payment to an account declared as a
//! debt), FIXED (matched to a detected recurring charge), or VARIABLE. Only variable spending is
//! discretionary, and [`discretionary_monthly`] is the figure `runway` asks for.
//!
//! # Categorisation is data, deterministic, and local
//!
//! A table of keywords, not a model — a model here would mean sending somebody's merchant list
//! somewhere. What it cannot place is reported as UNCATEGORISED rather than dropped into an "other"
//! bucket, because a large "other" is a finding and a large "uncategorised" is an admission.
use crate::money::{money, sum, Currency, Money};
use crate::position::Position;
use crate::reconcile::ReconciledLedger;
use crate::recurring::Recurring;
use crate::txn::{days_between, merchant_key_default, month_of, Txn};

/// Why an outflow is or is not discretionary spending.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OutflowClass {
    Paired,
    Debt,
    Fixed,
    Variable,
}

impl OutflowClass {
    pub fn label(self) -> &'static str {
        match self {
            OutflowClass::Paired => "paired",
            OutflowClass::Debt => "debt",
            OutflowClass::Fixed => "fixed",
            OutflowClass::Variable => "variable",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct ClassifiedOutflow {
    pub txn: Txn,
    pub kind: OutflowClass,
    /// Present for `Variable` and `Fixed`; NONE means nothing in the table matched — which is not
    /// the same as "other".
    pub category: Option<&'static str>,
    /// For `Paired`, the transaction on the other side.
    pub counterpart: Option<Txn>,
    /// For `Fixed`, the recurring charge it belongs to.
    pub recurring: Option<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct CategoryTotal {
    pub category: &'static str,
    pub total: Money,
    pub count: usize,
    /// Median across the whole months observed — the usual month for this category.
    pub typical_month: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct SpendingAnalysis {
    pub from: String,
    pub to: String,
    /// WHOLE months the medians are computed over.
    pub months_observed: usize,
    pub outflows: Vec<ClassifiedOutflow>,
    /// Standing charges — rent, subscriptions, insurance. Not a choice this month.
    pub fixed_monthly: Money,
    /// Everything else that was actually consumed. What `runway` wants.
    pub variable_monthly: Money,
    pub categories: Vec<CategoryTotal>,
    /// The same totals over VARIABLE outflows only.
    ///
    /// `categories` covers everything that was spent, fixed charges included, because "where does my
    /// money go" wants rent in the answer. Anything downstream that ALSO counts the obligation
    /// calendar must use this one instead — rent appears in both, and adding them counts it twice.
    /// That is not hypothetical: `viable` did exactly that and overstated every tier by the whole of
    /// the rent, which tells somebody they need to earn far more than they do.
    pub variable_categories: Vec<CategoryTotal>,
    /// Money that MOVED rather than left. Named so the exclusion is visible, never silent.
    pub transferred: Money,
    pub transfer_count: usize,
    /// Payments to declared debts, excluded because the calendar already has them.
    pub debt_payments: Money,
    /// Outflows nothing in the table could place. Reported, never bucketed as "other".
    pub uncategorised: Vec<Txn>,
    pub notes: Vec<String>,
}

/// The category table. DATA, so it can be read, argued with and extended without touching logic.
///
/// FIRST MATCH WINS, so the order is meaningful: fuel before transport, groceries before shopping.
pub const CATEGORY_RULES: &[(&str, &[&str])] = &[
    ("housing", &["rent", "mortgage", "landlord", "property mgmt", "hoa"]),
    ("utilities", &["electric", "power", "gas company", "water", "sewer", "internet", "broadband", "mobile", "wireless", "phone"]),
    ("insurance", &["insurance", "assurance", "geico", "allstate"]),
    ("healthcare", &["pharmacy", "dental", "clinic", "medical", "hospital", "optical", "vision"]),
    ("childcare", &["daycare", "childcare", "nursery", "preschool"]),
    ("education", &["tuition", "university", "college", "student loan", "bookstore"]),
    ("fuel", &["shell", "chevron", "exxon", "bp", "texaco", "fuel", "petrol", "gas station"]),
    ("transport", &["uber", "lyft", "transit", "metro", "parking", "toll", "rail", "airline", "airlines"]),
    ("groceries", &["grocery", "market", "supermarket", "safeway", "kroger", "aldi", "trader", "whole foods", "food store"]),
    ("dining", &["restaurant", "cafe", "coffee", "pizza", "grill", "diner", "bar", "brewing", "doordash", "grubhub", "seamless"]),
    ("subscriptions", &["netflix", "spotify", "hulu", "prime", "membership", "subscription", "patreon"]),
    ("entertainment", &["cinema", "theatre", "theater", "concert", "steam", "playstation", "xbox", "nintendo"]),
    ("shopping", &["amzn", "amazon", "target", "walmart", "costco", "store", "shop", "retail"]),
    ("fees", &["fee", "interest", "overdraft", "service charge", "atm"]),
    ("cash", &["withdrawal", "cash", "atm withdrawal"]),
];

/// The category a description falls in, or NONE — which is not the same as "other".
pub fn categorise(description: &str) -> Option<&'static str> {
    let text = description.to_lowercase();
    CATEGORY_RULES.iter().find(|(_, matches)| matches.iter().any(|m| text.contains(m))).map(|(c, _)| *c)
}

pub struct SpendingOptions {
    /// How far apart the two halves of an internal transfer may be dated.
    pub transfer_window_days: i64,
}

impl Default for SpendingOptions {
    fn default() -> Self {
        SpendingOptions { transfer_window_days: 3 }
    }
}

fn median(xs: &[i64]) -> i64 {
    if xs.is_empty() {
        return 0;
    }
    let mut s = xs.to_vec();
    s.sort_unstable();
    let m = s.len() / 2;
    if s.len() % 2 == 1 {
        s[m]
    } else {
        let total = s[m - 1] + s[m];
        if total >= 0 { (total + 1).div_euclid(2) } else { -((-total).div_euclid(2)) }
    }
}

/// The months a median may be taken over: WHOLE ones only, dropping a partial at either end.
fn whole_months(dates: &[String]) -> Vec<String> {
    let mut months: Vec<String> = dates.iter().map(|d| month_of(d).to_string()).collect();
    months.sort();
    months.dedup();
    if months.len() > 2 { months[1..months.len() - 1].to_vec() } else { months }
}

pub fn analyse_spending(ledger: &ReconciledLedger, position: Option<&Position>, recurring: &[Recurring], currency: Currency, opts: &SpendingOptions) -> SpendingAnalysis {
    let rows = ledger.covered();
    let outflow_rows: Vec<&Txn> = rows.iter().filter(|t| t.amount.minor < 0).collect();
    let inflow_rows: Vec<&Txn> = rows.iter().filter(|t| t.amount.minor > 0).collect();
    let mut notes: Vec<String> = Vec::new();

    // PAIRING FIRST. An outflow matched by an inflow of the same size on ANOTHER account within a few
    // days is money that moved, not money that left. Each inflow can be claimed ONCE — otherwise two
    // identical outflows both match one deposit and one of them is wrongly excluded.
    let mut taken_inflow = vec![false; inflow_rows.len()];
    let mut pair_of: Vec<Option<Txn>> = vec![None; outflow_rows.len()];
    for (oi, out) in outflow_rows.iter().enumerate() {
        let hit = inflow_rows.iter().enumerate().find(|(ii, i)| {
            !taken_inflow[*ii] && i.account != out.account && i.amount.minor == -out.amount.minor && days_between(&out.date, &i.date).abs() <= opts.transfer_window_days
        });
        if let Some((ii, i)) = hit {
            taken_inflow[ii] = true;
            pair_of[oi] = Some((*i).clone());
        }
    }

    let empty: &[crate::position::AccountPosition] = &[];
    let accounts = position.map(|p| p.accounts.as_slice()).unwrap_or(empty);
    let debt_accounts: Vec<&str> = accounts.iter().filter(|a| a.is_debt).map(|a| a.account.as_str()).collect();
    let debt_names: Vec<String> = accounts.iter().filter(|a| a.is_debt).map(|a| a.institution.to_lowercase()).filter(|s| !s.is_empty()).collect();

    // Keyed on the PAIR, as `recurring` groups them — a joined string would need a separator that
    // neither an account name nor a merchant key can contain.
    let recurring_keys: Vec<((String, String), String)> = recurring.iter().map(|r| ((r.account.clone(), r.key.clone()), r.label.clone())).collect();

    let outflows: Vec<ClassifiedOutflow> = outflow_rows
        .iter()
        .enumerate()
        .map(|(oi, txn)| {
            if let Some(counterpart) = pair_of[oi].clone() {
                return ClassifiedOutflow { txn: (*txn).clone(), kind: OutflowClass::Paired, category: None, counterpart: Some(counterpart), recurring: None };
            }

            // A payment to a card the ledger does not contain has no inflow to pair with, so the only
            // remaining signal is the institution's own name in the description.
            let text = txn.description.to_lowercase();
            if !debt_accounts.contains(&txn.account.as_str()) && debt_names.iter().any(|n| text.contains(n)) {
                return ClassifiedOutflow { txn: (*txn).clone(), kind: OutflowClass::Debt, category: None, counterpart: None, recurring: None };
            }

            let key = (txn.account.clone(), merchant_key_default(&txn.description));
            if let Some((_, label)) = recurring_keys.iter().find(|(k, _)| *k == key) {
                return ClassifiedOutflow { txn: (*txn).clone(), kind: OutflowClass::Fixed, category: categorise(&txn.description), counterpart: None, recurring: Some(label.clone()) };
            }

            ClassifiedOutflow { txn: (*txn).clone(), kind: OutflowClass::Variable, category: categorise(&txn.description), counterpart: None, recurring: None }
        })
        .collect();

    let spent: Vec<&ClassifiedOutflow> = outflows.iter().filter(|o| o.kind == OutflowClass::Fixed || o.kind == OutflowClass::Variable).collect();
    let months = whole_months(&spent.iter().map(|o| o.txn.date.clone()).collect::<Vec<_>>());

    let per_month = |rows_in: &[&ClassifiedOutflow]| -> i64 {
        let totals: Vec<i64> = months
            .iter()
            .map(|m| rows_in.iter().filter(|o| month_of(&o.txn.date) == m).map(|o| -o.txn.amount.minor).sum())
            .collect();
        median(&totals)
    };

    let in_whole_months: Vec<&ClassifiedOutflow> = spent.iter().filter(|o| months.iter().any(|m| m == month_of(&o.txn.date))).copied().collect();
    let mut by_category: Vec<(&'static str, Vec<&ClassifiedOutflow>)> = Vec::new();
    for o in &in_whole_months {
        let Some(c) = o.category else { continue };
        match by_category.iter_mut().find(|(k, _)| *k == c) {
            Some((_, b)) => b.push(o),
            None => by_category.push((c, vec![o])),
        }
    }

    let mut by_variable_category: Vec<(&'static str, Vec<&ClassifiedOutflow>)> = Vec::new();
    for o in &in_whole_months {
        let Some(c) = o.category else { continue };
        if o.kind != OutflowClass::Variable {
            continue;
        }
        match by_variable_category.iter_mut().find(|(k, _)| *k == c) {
            Some((_, b)) => b.push(o),
            None => by_variable_category.push((c, vec![o])),
        }
    }

    let uncategorised: Vec<Txn> = in_whole_months.iter().filter(|o| o.category.is_none()).map(|o| o.txn.clone()).collect();
    if !uncategorised.is_empty() {
        let share = ((uncategorised.len() as f64 / in_whole_months.len().max(1) as f64) * 100.0).round();
        notes.push(format!(
            "{} outflow(s) — {}% of them — matched no category rule and are listed rather than bucketed as \"other\"; the category totals below do not add up to the monthly figures because of it",
            uncategorised.len(),
            share
        ));
    }
    if months.len() < 3 {
        notes.push(format!("only {} whole month(s) here — a median over that is a description of those months, not a pattern", months.len()));
    }

    let transfers: Vec<&ClassifiedOutflow> = outflows.iter().filter(|o| o.kind == OutflowClass::Paired).collect();
    let debts: Vec<&ClassifiedOutflow> = outflows.iter().filter(|o| o.kind == OutflowClass::Debt).collect();
    if !transfers.is_empty() {
        notes.push(format!(
            "{} outflow(s) were matched to an inflow elsewhere and are EXCLUDED — moving money between your own accounts is not spending",
            transfers.len()
        ));
    }
    if !debts.is_empty() {
        notes.push(format!(
            "{} payment(s) to a declared debt are EXCLUDED — the obligation calendar already carries them, and counting them here would subtract the same money twice",
            debts.len()
        ));
    }

    let total_of = |os: &[&ClassifiedOutflow]| -> Money {
        let amounts: Vec<Money> = os.iter().map(|o| money(-o.txn.amount.minor, currency)).collect();
        sum(&amounts, currency).unwrap_or_else(|_| money(0, currency))
    };

    let mut categories: Vec<CategoryTotal> = by_category
        .iter()
        .map(|(category, os)| CategoryTotal { category, total: total_of(os), count: os.len(), typical_month: money(per_month(os), currency) })
        .collect();
    categories.sort_by_key(|c| std::cmp::Reverse(c.total.minor));
    let mut variable_categories: Vec<CategoryTotal> = by_variable_category
        .iter()
        .map(|(category, os)| CategoryTotal { category, total: total_of(os), count: os.len(), typical_month: money(per_month(os), currency) })
        .collect();
    variable_categories.sort_by_key(|c| std::cmp::Reverse(c.total.minor));

    let fixed: Vec<&ClassifiedOutflow> = spent.iter().filter(|o| o.kind == OutflowClass::Fixed).copied().collect();
    let variable: Vec<&ClassifiedOutflow> = spent.iter().filter(|o| o.kind == OutflowClass::Variable).copied().collect();

    SpendingAnalysis {
        from: rows.first().map(|t| t.date.clone()).unwrap_or_else(|| ledger.through().to_string()),
        to: ledger.through().to_string(),
        months_observed: months.len(),
        fixed_monthly: money(per_month(&fixed), currency),
        variable_monthly: money(per_month(&variable), currency),
        categories,
        variable_categories,
        transferred: total_of(&transfers),
        transfer_count: transfers.len(),
        debt_payments: total_of(&debts),
        uncategorised,
        notes,
        outflows,
    }
}

/// The figure `runway` asks for: what an ordinary month costs BEYOND the standing obligations.
///
/// Fixed spending is deliberately NOT included — the obligation calendar already carries it, and a
/// runway that subtracted both would double-count every subscription it knows about.
pub fn discretionary_monthly(s: &SpendingAnalysis) -> Money {
    s.variable_monthly
}

/// Where the variable money actually goes, biggest first — the list to act on.
pub fn top_categories(s: &SpendingAnalysis, n: usize) -> &[CategoryTotal] {
    &s.categories[..n.min(s.categories.len())]
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::account::Kind;
    use crate::money::usd;
    use crate::position::AccountPosition;
    use crate::recurring::Cadence;

    // SYNTHETIC FIXTURES ONLY — no real merchant or account reaches this repo.
    fn t(date: &str, description: &str, minor: i64, account: &str) -> Txn {
        Txn { account: account.to_string(), date: date.to_string(), description: description.to_string(), amount: usd(minor) }
    }

    fn rec(label: &str, account: &str, key: &str, minor: i64) -> Recurring {
        Recurring {
            key: key.to_string(),
            label: label.to_string(),
            account: account.to_string(),
            cadence: Cadence::Monthly,
            typical: usd(minor),
            annualised: usd(0),
            occurrences: 3,
            first_seen: "2026-01-01".to_string(),
            last_seen: "2026-03-05".to_string(),
            regularity: 1.0,
            amount_stability: 1.0,
            lapsed: false,
        }
    }

    fn card_position() -> Position {
        Position {
            as_of: "2026-04-30".to_string(),
            currency: Currency::USD,
            accounts: vec![AccountPosition {
                account: "visa".to_string(),
                institution: "chase".to_string(),
                kind: Kind::Credit,
                balance: usd(-100_000),
                as_of: "2026-04-30".to_string(),
                rolled_forward: 0,
                is_debt: true,
                owed: Some(usd(100_000)),
                credit_limit: None,
                available: None,
                utilisation: None,
                apr: None,
                daily_interest: None,
                minimum_payment: None,
            }],
            net_worth: usd(0),
            liquid: usd(0),
            total_debt: usd(100_000),
            daily_interest: usd(0),
            minimums_due: usd(0),
            weighted_apr: None,
            complete: true,
            provenance: "x".to_string(),
            problems: Vec::new(),
        }
    }

    fn rows() -> Vec<Txn> {
        vec![
            t("2026-01-05", "RENT LANDLORD LLC", -120_000, "chk"),
            t("2026-01-10", "TRADER JOES #22", -8_000, "chk"),
            t("2026-01-12", "NETFLIX.COM", -1_599, "chk"),
            t("2026-01-15", "SHELL OIL 4412", -5_000, "chk"),
            t("2026-01-20", "TRANSFER TO SAVINGS", -50_000, "chk"),
            t("2026-01-21", "TRANSFER FROM CHECKING", 50_000, "sav"),
            t("2026-01-25", "CHASE CREDIT CRD EPAY", -30_000, "chk"),
            t("2026-01-28", "ZZZ MYSTERY VENDOR", -2_500, "chk"),
            t("2026-02-05", "RENT LANDLORD LLC", -120_000, "chk"),
            t("2026-02-10", "TRADER JOES #22", -9_500, "chk"),
            t("2026-02-12", "NETFLIX.COM", -1_599, "chk"),
            t("2026-02-15", "SHELL OIL 4412", -5_500, "chk"),
            t("2026-02-25", "CHASE CREDIT CRD EPAY", -30_000, "chk"),
            t("2026-03-05", "RENT LANDLORD LLC", -120_000, "chk"),
            t("2026-03-10", "TRADER JOES #22", -7_000, "chk"),
            t("2026-03-12", "NETFLIX.COM", -1_599, "chk"),
            t("2026-03-15", "SHELL OIL 4412", -6_000, "chk"),
            t("2026-04-05", "RENT LANDLORD LLC", -120_000, "chk"),
        ]
    }

    fn analyse() -> SpendingAnalysis {
        let rows = rows();
        let ledger = crate::reconcile::unverified_ledger(&rows, "2026-04-30", "test").expect("a ledger");
        let recurring = vec![rec("RENT LANDLORD LLC", "chk", "rent landlord", 120_000), rec("NETFLIX.COM", "chk", "netflix", 1_599)];
        analyse_spending(&ledger, Some(&card_position()), &recurring, Currency::USD, &SpendingOptions::default())
    }

    #[test]
    fn the_category_table_places_what_it_can_and_admits_what_it_cannot() {
        // Measured against the TypeScript, first-match-wins order included.
        assert_eq!(categorise("RENT LANDLORD LLC"), Some("housing"));
        assert_eq!(categorise("SHELL OIL 4412"), Some("fuel"));
        assert_eq!(categorise("TRADER JOES #22"), Some("groceries"));
        assert_eq!(categorise("AMZN Mktp US"), Some("shopping"));
        assert_eq!(categorise("NETFLIX.COM"), Some("subscriptions"));
        assert_eq!(categorise("DOORDASH*BURGER"), Some("dining"));
        // "ATM WITHDRAWAL" hits `fees` before `cash` — fees is EARLIER in the table, and first match
        // wins. That is the table being data rather than logic, and it is worth pinning.
        assert_eq!(categorise("ATM WITHDRAWAL"), Some("fees"));
        assert_eq!(categorise("Target RedCard"), Some("shopping"), "matching is case-insensitive");
        // NONE, not "other". A large uncategorised pile is an admission; a large "other" hides it.
        assert_eq!(categorise("CHASE CREDIT CRD EPAY"), None);
        assert_eq!(categorise("ZZZ UNKNOWN THING"), None);
        assert_eq!(CATEGORY_RULES.len(), 15, "the table lost or gained a rule");
    }

    #[test]
    fn a_transfer_between_your_own_accounts_is_not_spending() {
        let a = analyse();
        assert_eq!(a.transfer_count, 1);
        assert_eq!(a.transferred.minor, 50_000);
        let paired: Vec<&ClassifiedOutflow> = a.outflows.iter().filter(|o| o.kind == OutflowClass::Paired).collect();
        assert_eq!(paired.len(), 1);
        assert_eq!(paired[0].counterpart.as_ref().expect("the other side").account, "sav");
        // It is NOT in the monthly figures. Counting it would subtract the same money twice from
        // the runway, which looks like prudence and is simply wrong.
        assert!(a.notes.iter().any(|n| n.contains("moving money between your own accounts is not spending")));
    }

    #[test]
    fn a_payment_to_a_declared_debt_is_excluded_because_the_calendar_already_has_it() {
        let a = analyse();
        assert_eq!(a.debt_payments.minor, 60_000, "two payments of 30000");
        let debts: Vec<&ClassifiedOutflow> = a.outflows.iter().filter(|o| o.kind == OutflowClass::Debt).collect();
        assert_eq!(debts.len(), 2);
        // Matched by the INSTITUTION's name in the description — "CHASE CREDIT CRD EPAY" against a
        // declared chase card — because a payment to a card the ledger does not hold has no inflow
        // to pair with.
        assert!(debts.iter().all(|d| d.txn.description.contains("CHASE")));
        assert!(a.notes.iter().any(|n| n.contains("subtract the same money twice")));
    }

    #[test]
    fn fixed_and_variable_are_separated_because_only_one_of_them_is_a_choice() {
        let a = analyse();
        // Measured by running finance-spending.ts on this exact fixture.
        assert_eq!(a.months_observed, 2, "Jan and Apr are partial and are dropped");
        assert_eq!(a.fixed_monthly.minor, 121_599, "rent + netflix, matched to detected recurring charges");
        assert_eq!(a.variable_monthly.minor, 14_000, "groceries + fuel");
        assert_eq!(discretionary_monthly(&a).minor, 14_000, "runway gets the VARIABLE figure only");
        // The fixed half is deliberately excluded: the obligation calendar already carries it, and a
        // runway subtracting both would double-count every subscription it knows about.
        assert_ne!(discretionary_monthly(&a).minor, a.fixed_monthly.minor + a.variable_monthly.minor);
    }

    #[test]
    fn the_variable_split_excludes_the_fixed_charges_the_calendar_already_carries() {
        let a = analyse();
        // `categories` answers "where does my money go" and RIGHTLY includes rent and the
        // subscription. Anything that also counts the obligation calendar must not.
        assert_eq!(a.categories.iter().map(|c| c.category).collect::<Vec<_>>(), vec!["housing", "groceries", "fuel", "subscriptions"]);
        assert_eq!(a.variable_categories.iter().map(|c| c.category).collect::<Vec<_>>(), vec!["groceries", "fuel"]);
        // The gap between the two IS the double-count that `viable` used to make: 120000 of rent
        // plus 1599 of subscription, counted once on the calendar and again as "variable".
        let all: i64 = a.categories.iter().map(|c| c.typical_month.minor).sum();
        let var: i64 = a.variable_categories.iter().map(|c| c.typical_month.minor).sum();
        assert_eq!(all - var, 121_599);
        assert_eq!(var, 14_000, "and this matches the honest variableMonthly figure");
        assert_eq!(var, a.variable_monthly.minor);
    }

    #[test]
    fn the_categories_are_biggest_first_because_that_is_the_order_to_act_in() {
        let a = analyse();
        let got: Vec<(&str, i64, usize, i64)> = a.categories.iter().map(|c| (c.category, c.total.minor, c.count, c.typical_month.minor)).collect();
        assert_eq!(
            got,
            vec![("housing", 240_000, 2, 120_000), ("groceries", 16_500, 2, 8_250), ("fuel", 11_500, 2, 5_750), ("subscriptions", 3_198, 2, 1_599)]
        );
        assert_eq!(top_categories(&a, 3).iter().map(|c| c.category).collect::<Vec<_>>(), vec!["housing", "groceries", "fuel"]);
        // Asking for more than there are is not an error and does not panic.
        assert_eq!(top_categories(&a, 99).len(), 4);
        assert_eq!(top_categories(&a, 0).len(), 0);
    }

    #[test]
    fn an_unplaceable_outflow_is_listed_rather_than_bucketed_as_other() {
        // The mystery vendor is in JANUARY, which is a partial month and therefore outside the
        // medians — so it is correctly absent here.
        let a = analyse();
        assert!(a.uncategorised.is_empty(), "the only unplaceable row is in a trimmed partial month");

        // Move it into a whole month and it surfaces, with the share it represents.
        let mut r = rows();
        r.push(t("2026-02-18", "ZZZ MYSTERY VENDOR", -2_500, "chk"));
        r.sort_by(|a, b| a.date.cmp(&b.date));
        let ledger = crate::reconcile::unverified_ledger(&r, "2026-04-30", "test").expect("a ledger");
        let a2 = analyse_spending(&ledger, Some(&card_position()), &[rec("RENT LANDLORD LLC", "chk", "rent landlord", 120_000)], Currency::USD, &SpendingOptions::default());
        assert_eq!(a2.uncategorised.len(), 1);
        assert_eq!(a2.uncategorised[0].description, "ZZZ MYSTERY VENDOR");
        assert!(a2.notes.iter().any(|n| n.contains("rather than bucketed as \"other\"")));
        assert!(a2.notes.iter().any(|n| n.contains("do not add up")), "the shortfall in the category totals is stated");
    }

    #[test]
    fn one_inflow_can_only_pair_with_one_outflow() {
        // Two identical outflows and ONE matching deposit. Without the claim, both would read as
        // transfers and real spending would vanish from the analysis.
        let r = vec![
            t("2026-02-01", "TRANSFER TO SAVINGS", -50_000, "chk"),
            t("2026-02-02", "PAYMENT TO SOMEONE", -50_000, "chk"),
            t("2026-02-02", "TRANSFER FROM CHECKING", 50_000, "sav"),
        ];
        let ledger = crate::reconcile::unverified_ledger(&r, "2026-02-28", "test").expect("a ledger");
        let a = analyse_spending(&ledger, None, &[], Currency::USD, &SpendingOptions::default());
        assert_eq!(a.transfer_count, 1, "exactly one of the two is paired");
        assert_eq!(a.outflows.iter().filter(|o| o.kind == OutflowClass::Variable).count(), 1);
    }

    #[test]
    fn a_same_account_move_is_not_a_transfer_and_a_distant_one_is_not_either() {
        let same = vec![t("2026-02-01", "MOVE", -50_000, "chk"), t("2026-02-02", "MOVE BACK", 50_000, "chk")];
        let l1 = crate::reconcile::unverified_ledger(&same, "2026-02-28", "test").expect("a ledger");
        assert_eq!(analyse_spending(&l1, None, &[], Currency::USD, &SpendingOptions::default()).transfer_count, 0, "the inflow must be on ANOTHER account");

        let distant = vec![t("2026-02-01", "MOVE", -50_000, "chk"), t("2026-02-20", "ARRIVE", 50_000, "sav")];
        let l2 = crate::reconcile::unverified_ledger(&distant, "2026-02-28", "test").expect("a ledger");
        assert_eq!(analyse_spending(&l2, None, &[], Currency::USD, &SpendingOptions::default()).transfer_count, 0, "19 days apart is not one transfer");
        // Widen the window and the same pair matches — the threshold is a policy, not a fact.
        let wide = SpendingOptions { transfer_window_days: 30 };
        assert_eq!(analyse_spending(&l2, None, &[], Currency::USD, &wide).transfer_count, 1);
    }

    #[test]
    fn thin_coverage_is_stated_rather_than_presented_as_a_pattern() {
        let a = analyse();
        assert!(a.notes.iter().any(|n| n.contains("a description of those months, not a pattern")));
        assert_eq!(a.from, "2026-01-05", "the first covered row");
        assert_eq!(a.to, "2026-04-30", "the ledger's coverage, not the last row");
    }
}

//! Minimum viable income — the smallest monthly income that holds, in TIERS, on the WORST month.
//!
//! "How much do I need to earn?" has no single answer, and pretending it does is what makes the
//! answer useless. Needing $2,100 to keep the lights on and $4,300 to stop the debt growing are both
//! true and they lead to completely different decisions. So this reports a ladder:
//!
//! - **Survival** — what cannot lapse: housing, utilities, insurance, healthcare, debt minimums, and
//!   the groceries and transport that get you to work. Everything else is given up, and the list of
//!   what you gave up is part of the answer.
//! - **Current** — survival plus every standing obligation, so nothing goes delinquent. This is the
//!   headline: it is the line below which NEW damage starts.
//! - **Stable** — current plus ordinary discretionary spending, so nothing is drawn from savings.
//! - **Progress** — stable plus a deliberate payment above the minimums.
//!
//! # The headline is the worst month, not the average
//!
//! The same discipline the runway uses. An annual insurance renewal makes one month cost $900 more
//! than the other eleven; an income that covers the median clears every month except the one it does
//! not, and that month is a missed payment. The median is reported too, because THE GAP BETWEEN THE
//! TWO IS THE SAVING-UP PROBLEM.
use crate::money::{money, sum, Currency, Money};
use crate::obligations::{months_between, ObligationCalendar, ObligationKind};
use crate::projection::IncomeProjection;
use crate::spending::{categorise, SpendingAnalysis};
use crate::txn::month_of;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tier {
    Survival,
    Current,
    Stable,
    Progress,
}

impl Tier {
    pub fn label(self) -> &'static str {
        match self {
            Tier::Survival => "survival",
            Tier::Current => "current",
            Tier::Stable => "stable",
            Tier::Progress => "progress",
        }
    }
}

/// What cannot be given up without losing something that costs more than it saves — a home, a car
/// that gets you to work, cover against a bill that would end this. DATA, so it can be argued with.
pub const ESSENTIAL_CATEGORIES: &[&str] = &["housing", "utilities", "insurance", "healthcare", "childcare", "groceries", "transport", "fuel"];

fn is_essential_category(c: &str) -> bool {
    ESSENTIAL_CATEGORIES.contains(&c)
}

#[derive(Debug, Clone, PartialEq)]
pub struct TierRequirement {
    pub tier: Tier,
    /// The usual month. What the ladder looks like most of the time.
    pub typical_month: Money,
    /// The month that costs MOST. This is what an income has to clear.
    pub worst_month: Money,
    pub worst_month_name: String,
    /// In this tier's words, what it buys.
    pub includes: Vec<String>,
    /// What is given up at this tier, so the trade is VISIBLE rather than implied.
    pub excludes: Vec<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct TierGap {
    pub tier: Tier,
    /// POSITIVE shortfall against the LOW income band in the worst month. Zero when already clear.
    pub shortfall: Money,
    pub clears: bool,
}

#[derive(Debug, Clone, PartialEq)]
pub struct ViableIncome {
    pub currency: Currency,
    pub from: String,
    pub to: String,
    pub tiers: Vec<TierRequirement>,
    /// The absolute floor: what cannot lapse.
    pub floor: TierRequirement,
    /// The line below which NEW damage starts — the number to quote when asked one.
    pub headline: TierRequirement,
    /// Against the projection's LOW band, tier by tier. ABSENT when there is no projection to
    /// compare against — not a row of zeroes, which would read as "you clear everything".
    pub gaps: Option<Vec<TierGap>>,
    pub notes: Vec<String>,
}

pub struct ViableOptions {
    /// A deliberate payment above the minimums — what turns holding on into getting out.
    pub progress_target: Money,
}

fn median(xs: &[i64]) -> i64 {
    if xs.is_empty() {
        return 0;
    }
    let mut s = xs.to_vec();
    s.sort_unstable();
    let m = s.len() / 2;
    if s.len() % 2 == 1 {
        s[m]
    } else {
        let total = s[m - 1] + s[m];
        if total >= 0 { (total + 1).div_euclid(2) } else { -((-total).div_euclid(2)) }
    }
}

/// Whether an obligation is essential, and whether the table could place it at all.
///
/// An obligation nothing can place is treated as ESSENTIAL — for a floor, over-stating is the safe
/// direction and under-stating is a missed payment. It is NAMED rather than quietly promoted.
fn obligation_is_essential(label: &str, kind: ObligationKind) -> (bool, bool) {
    // A missed minimum is a credit event, not a cancelled luxury. Essential regardless of wording.
    if kind == ObligationKind::Minimum {
        return (true, true);
    }
    match categorise(label) {
        None => (true, false),
        Some(c) => (is_essential_category(c), true),
    }
}

pub fn minimum_viable_income(
    calendar: &ObligationCalendar,
    spending: &SpendingAnalysis,
    currency: Currency,
    projection: Option<&IncomeProjection>,
    opts: &ViableOptions,
) -> ViableIncome {
    let mut notes: Vec<String> = Vec::new();
    let months = months_between(&calendar.from, &calendar.to);

    let mut unplaced: Vec<String> = Vec::new();
    let mut essential_by_month: Vec<(String, i64)> = months.iter().map(|m| (m.clone(), 0)).collect();
    let mut all_by_month: Vec<(String, i64)> = months.iter().map(|m| (m.clone(), 0)).collect();
    for o in &calendar.obligations {
        let m = &o.date[..7.min(o.date.len())];
        let Some(slot) = all_by_month.iter_mut().find(|(k, _)| k == m) else { continue };
        slot.1 += o.amount.minor;
        let (essential, placed) = obligation_is_essential(&o.label, o.kind);
        if !placed && !unplaced.contains(&o.label) {
            unplaced.push(o.label.clone());
        }
        if essential {
            if let Some(e) = essential_by_month.iter_mut().find(|(k, _)| k == m) {
                e.1 += o.amount.minor;
            }
        }
    }
    if !unplaced.is_empty() {
        notes.push(format!(
            "{} obligation(s) matched no category and are counted as ESSENTIAL — for a floor, over-stating costs you a bigger target and under-stating costs you a missed payment: {}",
            unplaced.len(),
            unplaced.join(", ")
        ));
    }

    // VARIABLE SPENDING IS SUMMED FROM THE SAME PARTS ON BOTH SIDES, deliberately. Medians do not
    // add, so `spending.variable_monthly` (a median of totals) and the sum of per-category medians
    // are different numbers — and mixing the two would let the essential half exceed the whole,
    // which would put the ladder out of order for reasons nobody could see in the output.
    // VARIABLE CATEGORIES ONLY. `categories` covers every outflow that was spent, fixed charges
    // included — so rent appears BOTH there and on the obligation calendar, and summing the two
    // counted it twice. Every tier came out overstated by the whole of the rent, which tells
    // somebody they need to earn far more than they do. Found by running the binary, not by tests.
    let essential_variable: i64 = spending.variable_categories.iter().filter(|c| is_essential_category(c.category)).map(|c| c.typical_month.minor).sum();
    let categorised_variable: i64 = spending.variable_categories.iter().map(|c| c.typical_month.minor).sum();

    let mut uncat_by_month: Vec<(String, i64)> = Vec::new();
    for t in &spending.uncategorised {
        let m = month_of(&t.date).to_string();
        match uncat_by_month.iter_mut().find(|(k, _)| *k == m) {
            Some((_, v)) => *v += -t.amount.minor,
            None => uncat_by_month.push((m, -t.amount.minor)),
        }
    }
    let uncategorised_variable = median(&uncat_by_month.iter().map(|(_, v)| *v).collect::<Vec<_>>());
    let all_variable = categorised_variable + uncategorised_variable;

    if all_variable != spending.variable_monthly.minor {
        notes.push(format!(
            "variable spending here is {} minor units, against {} reported by the spending analysis — medians do not add, and this figure is built from the same parts as the essential half so the ladder cannot come out of order",
            all_variable, spending.variable_monthly.minor
        ));
    }

    let build = |tier: Tier, per: &dyn Fn(&str) -> i64, includes: Vec<String>, excludes: Vec<String>| -> TierRequirement {
        let totals: Vec<i64> = months.iter().map(|m| per(m)).collect();
        // The FIRST maximum wins on a tie — strictly greater, so the earliest month is named and a
        // reader is pointed at the one arriving soonest.
        let mut worst_at = 0usize;
        for i in 1..totals.len() {
            if totals[i] > totals[worst_at] {
                worst_at = i;
            }
        }
        TierRequirement {
            tier,
            typical_month: money(median(&totals), currency),
            worst_month: money(totals.get(worst_at).copied().unwrap_or(0), currency),
            worst_month_name: months.get(worst_at).cloned().unwrap_or_else(|| calendar.from[..7.min(calendar.from.len())].to_string()),
            includes,
            excludes,
        }
    };

    let ess = |m: &str| essential_by_month.iter().find(|(k, _)| k == m).map(|(_, v)| *v).unwrap_or(0);
    let all = |m: &str| all_by_month.iter().find(|(k, _)| k == m).map(|(_, v)| *v).unwrap_or(0);
    let s = |v: &[&str]| v.iter().map(|x| x.to_string()).collect::<Vec<String>>();

    let survival = build(
        Tier::Survival,
        &|m| ess(m) + essential_variable,
        s(&["housing, utilities, insurance, healthcare and childcare", "every debt MINIMUM — a missed one is a credit event", "groceries, transport and fuel"]),
        s(&["every subscription and membership", "dining, entertainment and shopping", "anything paid above a minimum"]),
    );
    let current = build(
        Tier::Current,
        &|m| all(m) + essential_variable,
        s(&["everything in survival", "every standing obligation, so nothing goes delinquent"]),
        s(&["dining, entertainment and shopping", "anything paid above a minimum"]),
    );
    let stable = build(
        Tier::Stable,
        &|m| all(m) + all_variable,
        s(&["everything in current", "ordinary discretionary spending, so nothing is drawn from savings"]),
        s(&["anything paid above a minimum — the debt stops growing but does not shrink"]),
    );
    let progress = build(
        Tier::Progress,
        &|m| all(m) + all_variable + opts.progress_target.minor,
        vec!["everything in stable".to_string(), format!("a deliberate {} minor units a month above the minimums", opts.progress_target.minor)],
        Vec::new(),
    );

    if opts.progress_target.minor == 0 {
        notes.push("no progress target was given, so PROGRESS equals STABLE — a stable position is one where the debt stops growing, not one where it shrinks".to_string());
    }
    let spread = current.worst_month.minor - current.typical_month.minor;
    if spread > 0 {
        notes.push(format!(
            "{} costs {} minor units more than the usual month — an income that only clears the median misses that month, and the gap between the two is the amount to have put aside before it arrives",
            current.worst_month_name, spread
        ));
    }

    let tiers = vec![survival.clone(), current.clone(), stable, progress];
    let gaps = match projection {
        Some(p) if p.projectable => Some(
            tiers
                .iter()
                .map(|t| {
                    let band = p.months.iter().find(|b| b.month == t.worst_month_name).or_else(|| p.months.first());
                    let income = band.map(|b| b.low.minor).unwrap_or(0);
                    let short = (t.worst_month.minor - income).max(0);
                    TierGap { tier: t.tier, shortfall: money(short, currency), clears: short == 0 }
                })
                .collect(),
        ),
        _ => None,
    };

    ViableIncome {
        currency,
        from: calendar.from.clone(),
        to: calendar.to.clone(),
        floor: survival,
        // CURRENT is the headline. Survival means letting things lapse, which has consequences that
        // outlast the month it saved; current is the line below which NEW damage starts.
        headline: current,
        tiers,
        gaps,
        notes,
    }
}

/// The tiers a projected income already clears — what is actually secured today.
pub fn cleared_tiers(v: &ViableIncome) -> Vec<Tier> {
    v.gaps.as_ref().map(|gs| gs.iter().filter(|g| g.clears).map(|g| g.tier).collect()).unwrap_or_default()
}

/// One sentence, in the terms the question was asked in.
pub fn summarise_viable(v: &ViableIncome) -> String {
    let base = format!(
        "{} minor units a month keeps everything current, measured on {} — the worst month, not the average",
        v.headline.worst_month.minor, v.headline.worst_month_name
    );
    match v.gaps.as_ref().and_then(|gs| gs.iter().find(|g| g.tier == Tier::Current)) {
        None => base,
        Some(g) if g.clears => format!("{base}; the low income band already clears it"),
        Some(g) => format!("{base}; the low income band is short by {}", g.shortfall.minor),
    }
}

/// Every tier's requirement is at least the one below it.
///
/// Stated as a FUNCTION so a caller can assert it on real data, not only in a test — the ladder
/// coming out of order would mean the tiers were built from figures that do not compose.
pub fn ladder_is_ordered(v: &ViableIncome) -> bool {
    v.tiers.windows(2).all(|w| w[1].worst_month.minor >= w[0].worst_month.minor)
}

/// What one tier costs over `months` months — the annual framing.
pub fn over_window(v: &ViableIncome, t: &TierRequirement, months: usize) -> Money {
    let each = vec![t.typical_month; months];
    sum(&each, v.currency).unwrap_or_else(|_| money(0, v.currency))
}

