//! The `bsc compliance` subcommand (#1877) — the session-facing CLI over the compliance **standards
//! store** (#1718, an instance of #1325 "all application state reachable via `bsc-*`"). The corpus
//! (`~/.base-studio-code/compliance/store.db`) was previously reachable only through the
//! `bsc-compliance-mcp` server's READ-only tools, and only from sessions that get `.mcp.json`
//! (planner/director/workers). This CLI exposes the **same** projections to ANY shell session —
//! plus the WRITE side the MCP server lacks (`upsert` / `remove` / `reseed`).
//!
//! Extracted from the old `bsc-compliance` binary so the unified `bsc` umbrella dispatches into it
//! via [`run`]; the legacy `bsc-compliance` shim delegates here too.
//!
//! The store is located via `--db <path>`, the `BSC_COMPLIANCE_STORE` env var (set per-session at
//! launch), or the default `~/.base-studio-code/compliance/store.db` (the same precedence
//! [`crate::store::Store::default_path`] uses). Output is JSON to stdout — compact by default,
//! indented with `--pretty` (the `--json` flag is accepted as an explicit no-op, since output is
//! always JSON). Read projections reuse [`crate::engine::Engine`] / `Store`; nothing is re-queried by
//! hand.
//!
//! Help is per-command so a model loads only what it needs (#1762):
//!   bsc compliance help              # compact menu (the small "what commands exist" prompt)
//!   bsc compliance standards help    # detailed help for ONE command
//!   bsc compliance <cmd> help        # same, after any command

use crate::engine::Engine;
use crate::store::Store;
use crate::types::{Domain, Standard};
use bsc_cli_util::CmdDoc;
use bsc_sqlite_util::{print_json, read_stdin_json};
use std::path::PathBuf;

const TAGLINE: &str = "the compliance standards store — accessibility/privacy/security obligations (#1718)";

/// The command catalog — drives the shared help system. One detailed `usage` block per top-level
/// command keeps the overview tiny; `standards`' subcommands live in its own usage block. Output is
/// JSON throughout (compact; `--pretty` indents).
/// The crate's own verb catalog. `pub` so `bsc surface verbs` can PROJECT it rather than
/// restate it — a generated catalog cannot drift, a second list does.
pub const COMMANDS: &[CmdDoc] = &[
    CmdDoc {
        name: "standards",
        summary: "list/get the raw standards corpus",
        usage: "\
USAGE:
  bsc compliance standards list [--domain <d>]   # every standard, or one domain, JSON
  bsc compliance standards get <id>              # one standard's full record (or null)

<d> is one of: accessibility | privacy | security | user_protection.",
    },
    CmdDoc {
        name: "requirements",
        summary: "the applicable obligation set, scoped by jurisdiction + data",
        usage: "\
USAGE:
  bsc compliance requirements [--regions a,b] [--data-types x,y] [--domains d1,d2]

The requirements_for projection: the obligations that apply given the regions, data types, and an
optional domain filter.",
    },
    CmdDoc {
        name: "accessibility",
        summary: "the WCAG checklist a UI target must meet",
        usage: "\
USAGE:
  bsc compliance accessibility <target>

The WCAG checklist for a UI target (the accessibility_checklist projection).",
    },
    CmdDoc {
        name: "privacy",
        summary: "privacy/data-protection obligations for given data types",
        usage: "\
USAGE:
  bsc compliance privacy <data-types> [--regions a,b]

<data-types> is a positional comma-separated list (e.g. pii,health). Prints the privacy obligations
for that data, optionally scoped to --regions.",
    },
    CmdDoc {
        name: "meta",
        summary: "corpus version + last-updated stamp + standard count",
        usage: "\
USAGE:
  bsc compliance meta

Prints the corpus metadata: version, last-updated stamp, and standard count.",
    },
    CmdDoc {
        name: "reseed",
        summary: "re-apply the baseline corpus; prints count",
        usage: "\
USAGE:
  bsc compliance reseed

Re-applies the baseline corpus (a refresh without a release). Prints the resulting standard count.",
    },
    CmdDoc {
        name: "upsert",
        summary: "upsert Standard(s) from JSON on stdin; prints id(s)",
        usage: "\
USAGE:
  bsc compliance upsert   # a Standard object (or an array) as JSON on stdin

Upserts each standard by its (required, non-empty) \"id\". Prints the id(s) written.",
    },
    CmdDoc {
        name: "remove",
        summary: "delete a standard; prints whether a row existed",
        usage: "\
USAGE:
  bsc compliance remove <id>

Deletes the standard keyed by <id>; prints whether a row existed.",
    },
];

/// Parsed global flags + the value-bearing flags any verb may use + leftover positional args.
struct Args {
    db: Option<String>,
    pretty: bool,
    domain: Option<String>,
    regions: Vec<String>,
    data_types: Vec<String>,
    domains: Vec<String>,
    positional: Vec<String>,
}

/// Split a comma-separated flag value into trimmed, non-empty tokens (`eu, us-ca` → `["eu","us-ca"]`).
fn csv(s: &str) -> Vec<String> {
    s.split(',').map(|t| t.trim().to_string()).filter(|t| !t.is_empty()).collect()
}

fn parse_args(raw: Vec<String>) -> Result<Args, String> {
    let a = Args {
        db: None,
        pretty: false,
        domain: None,
        regions: Vec::new(),
        data_types: Vec::new(),
        domains: Vec::new(),
        positional: Vec::new(),
    };
    let (mut a, positional) = bsc_cli_util::args::walk(raw, a, |flag, a: &mut Args, v| {
        match flag {
            "--db" => a.db = Some(v.value("--db needs a path")?),
            "--pretty" => a.pretty = true,
            // Output is always JSON; --json is accepted so callers can be explicit.
            "--json" => {}
            "--domain" => a.domain = Some(v.value("--domain needs a value")?),
            "--regions" => a.regions = csv(&v.value("--regions needs a comma-separated value")?),
            "--data-types" => a.data_types = csv(&v.value("--data-types needs a comma-separated value")?),
            "--domains" => a.domains = csv(&v.value("--domains needs a comma-separated value")?),
            _ => return Ok(false),
        }
        Ok(true)
    })?;
    a.positional = positional;
    Ok(a)
}

/// Parse a domain token into a [`Domain`], with a clear error listing the accepted values.
fn parse_domain(s: &str) -> Result<Domain, String> {
    Domain::parse(s).ok_or_else(|| {
        format!("unknown domain '{s}' (expected accessibility | privacy | security | user_protection)")
    })
}

/// The `compliance` subcommand entrypoint: `args` is everything after `bsc compliance`; `prog` is the
/// display name for help/errors (`"bsc compliance"` from the umbrella, `"bsc-compliance"` from the
/// legacy shim).
pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    let args = parse_args(args)?;
    let cmd = args.positional.first().cloned().unwrap_or_default();

    // Top-level + per-command help (no command / `help` / `help <cmd>` / `<cmd> help`) — the shared
    // dispatch in bsc-cli-util, run before opening the store (help works without a store.db).
    if bsc_cli_util::handle_help(prog, TAGLINE, COMMANDS, &args.positional) {
        return Ok(());
    }

    let open_store = || -> Result<Store, String> {
        let path = resolve_db(&args.db)?;
        Store::open(&path).map_err(|e| format!("opening {}: {e}", path.display()))
    };

    match cmd.as_str() {
        "standards" => {
            let sub = args.positional.get(1).map(String::as_str).unwrap_or("");
            match sub {
                "list" => {
                    let s = open_store()?;
                    let standards = match args.domain.as_deref() {
                        Some(d) => s.list_by_domain(parse_domain(d)?),
                        None => s.all(),
                    };
                    print_json(&standards, args.pretty);
                    Ok(())
                }
                "get" => {
                    let id = args.positional.get(2).ok_or("usage: bsc compliance standards get <id>")?;
                    let s = open_store()?;
                    // Print `null` for a miss (mirrors `bsc skill group get`).
                    print_json(&s.get(id), args.pretty);
                    Ok(())
                }
                "" => Err(format!(
                    "usage: bsc compliance standards <list|get>\n\n{}",
                    bsc_cli_util::surface::help_for(prog, TAGLINE, COMMANDS, "standards")
                )),
                other => Err(format!(
                    "unknown standards command '{other}'\n\n{}",
                    bsc_cli_util::surface::help_for(prog, TAGLINE, COMMANDS, "standards")
                )),
            }
        }
        "requirements" => {
            let domains = args
                .domains
                .iter()
                .map(|d| parse_domain(d))
                .collect::<Result<Vec<_>, _>>()?;
            let engine = Engine::with_store(open_store()?);
            let set = engine.requirements_for(&args.regions, &args.data_types, &domains);
            print_json(&set, args.pretty);
            Ok(())
        }
        "accessibility" => {
            let target = args
                .positional
                .get(1)
                .ok_or("usage: bsc compliance accessibility <target>")?;
            let engine = Engine::with_store(open_store()?);
            print_json(&engine.accessibility_checklist(target), args.pretty);
            Ok(())
        }
        "privacy" => {
            // `<data-types>` is a positional comma-separated list (e.g. `pii,health`).
            let data_types = csv(args.positional.get(1).map(String::as_str).unwrap_or(""));
            if data_types.is_empty() {
                return Err("usage: bsc compliance privacy <data-types> [--regions a,b]".into());
            }
            let engine = Engine::with_store(open_store()?);
            print_json(&engine.privacy_requirements(&data_types, &args.regions), args.pretty);
            Ok(())
        }
        "meta" => {
            let s = open_store()?;
            print_json(&s.meta(), args.pretty);
            Ok(())
        }
        "reseed" => {
            let s = open_store()?;
            let n = s.reseed()?;
            print_json(&n, args.pretty);
            Ok(())
        }
        "upsert" => {
            // One Standard object (or an array) on stdin; upsert each, print the ids.
            let standards: Vec<Standard> = read_stdin_json("standard")?;
            let s = open_store()?;
            let mut ids = Vec::new();
            for standard in &standards {
                if standard.id.trim().is_empty() {
                    return Err("upsert: each standard needs a non-empty \"id\"".into());
                }
                s.upsert(standard)?;
                ids.push(standard.id.clone());
            }
            print_json(&ids, args.pretty);
            Ok(())
        }
        "remove" => {
            let id = args.positional.get(1).ok_or("usage: bsc compliance remove <id>")?;
            let s = open_store()?;
            print_json(&s.remove(id)?, args.pretty);
            Ok(())
        }
        other => Err(bsc_cli_util::unknown_command(prog, TAGLINE, COMMANDS, other)),
    }
}

/// Resolve the store path via the shared `--db` → `$BSC_COMPLIANCE_STORE` → default precedence
/// ([`bsc_cli_util::resolve_store_path`]). The default is [`Store::default_path`], which falls back to
/// `~/.base-studio-code/compliance/store.db` (it re-checks the env var, a harmless redundancy since
/// the shared resolver only reaches the default when the env var is unset/empty).
fn resolve_db(flag: &Option<String>) -> Result<PathBuf, String> {
    bsc_cli_util::resolve_store_path(flag, "BSC_COMPLIANCE_STORE", || {
        Store::default_path()
            .ok_or_else(|| "could not resolve a store path; pass --db <path> or set BSC_COMPLIANCE_STORE".to_string())
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn csv_trims_and_drops_empties() {
        assert_eq!(csv("eu, us-ca ,,"), vec!["eu".to_string(), "us-ca".to_string()]);
        assert!(csv("").is_empty());
        assert!(csv("  ,  ").is_empty());
    }

    #[test]
    fn parse_args_collects_flags_and_positionals() {
        let a = parse_args(
            ["standards", "list", "--domain", "privacy", "--db", "x.db", "--pretty"]
                .iter()
                .map(|s| s.to_string())
                .collect(),
        )
        .unwrap();
        assert_eq!(a.positional, vec!["standards".to_string(), "list".to_string()]);
        assert_eq!(a.domain.as_deref(), Some("privacy"));
        assert_eq!(a.db.as_deref(), Some("x.db"));
        assert!(a.pretty);
    }

    #[test]
    fn parse_args_splits_comma_lists_and_accepts_json_noop() {
        let a = parse_args(
            ["requirements", "--regions", "eu,us-ca", "--data-types", "pii,health", "--domains", "privacy", "--json"]
                .iter()
                .map(|s| s.to_string())
                .collect(),
        )
        .unwrap();
        assert_eq!(a.regions, vec!["eu".to_string(), "us-ca".to_string()]);
        assert_eq!(a.data_types, vec!["pii".to_string(), "health".to_string()]);
        assert_eq!(a.domains, vec!["privacy".to_string()]);
        assert!(!a.pretty, "--json must not imply --pretty");
    }

    #[test]
    fn parse_args_rejects_unknown_flag() {
        let err = parse_args(vec!["meta".into(), "--nope".into()])
            .err()
            .expect("an unknown flag must error");
        assert!(err.contains("unknown flag"));
    }

    #[test]
    fn parse_domain_maps_aliases_and_rejects_garbage() {
        assert_eq!(parse_domain("privacy").unwrap(), Domain::Privacy);
        assert_eq!(parse_domain("a11y").unwrap(), Domain::Accessibility);
        assert!(parse_domain("nonsense").is_err());
    }

    #[test]
    fn parse_args_routes_help_flag_to_the_help_command() {
        let a = parse_args(vec!["--help".into()]).unwrap();
        assert_eq!(a.positional.first().map(String::as_str), Some("help"));
    }

    #[test]
    fn help_overview_lists_commands_and_per_command_help_drills_in() {
        let ov = bsc_cli_util::help_overview("bsc compliance", TAGLINE, COMMANDS);
        for c in ["standards", "requirements", "accessibility", "privacy", "meta", "reseed", "upsert", "remove"] {
            assert!(ov.contains(c), "overview lists {c}");
        }
        // `standards help` shows the standards subcommands, not the whole menu.
        let s = bsc_cli_util::help_for("bsc compliance", TAGLINE, COMMANDS, "standards");
        assert!(s.contains("bsc compliance standards"));
        assert!(s.contains("get <id>"));
        assert!(!s.contains("reseed"));
        // An unknown command falls back to the overview.
        assert!(bsc_cli_util::help_for("bsc compliance", TAGLINE, COMMANDS, "nope").contains("COMMANDS:"));
    }
}

implementations.code:
//! The compliance engine (#1005) — wires [`crate::store`] into the operations the MCP server
//! exposes: `list_standards`, `get_standard`, `requirements_for`, `accessibility_checklist`, and
//! `privacy_requirements`. The store is the source of truth (seeded baseline, user-updatable); the
//! engine is pure query + scoping logic over it, so the matching rules are unit-testable in-memory.

use crate::store::{Store, StoreMeta};
use crate::types::{Domain, Requirement, Standard};
use serde::Serialize;

pub struct Engine {
    store: Store,
}

/// A single applicable obligation, flattened from a standard for the planner: which standard it
/// comes from + the requirement itself, so the plan can cite `wcag-2.2 / 1.4.3`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct AppliedRequirement {
    pub standard_id: String,
    pub standard_name: String,
    pub domain: Domain,
    pub requirement: Requirement,
}

/// The resolved obligation set for a project: the flattened requirements plus the standards they
/// came from, with the corpus stamp so the planner can record how current the rules are.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct RequirementSet {
    pub standards: Vec<Standard>,
    pub requirements: Vec<AppliedRequirement>,
    pub meta: StoreMeta,
}

impl Engine {
    /// Build the engine from the environment (default store path, seeded on first open).
    pub fn from_env() -> Result<Engine, String> {
        let path = Store::default_path().ok_or("compliance: cannot resolve store path (no HOME/USERPROFILE)")?;
        let store = Store::open(&path)?;
        Ok(Engine { store })
    }

    /// Engine over an explicit (e.g. in-memory) store — used by tests.
    pub fn with_store(store: Store) -> Engine {
        Engine { store }
    }

    /// The corpus version + last-updated stamp.
    pub fn meta(&self) -> StoreMeta {
        self.store.meta()
    }

    /// List standards, optionally filtered to one domain. `None` → every standard.
    pub fn list_standards(&self, domain: Option<Domain>) -> Vec<Standard> {
        match domain {
            Some(d) => self.store.list_by_domain(d),
            None => self.store.all(),
        }
    }

    /// One standard's full record (with its requirements) by canonical id.
    pub fn get_standard(&self, id: &str) -> Option<Standard> {
        self.store.get(id)
    }

    /// The obligations that apply to a project, scoped by jurisdiction (regions), data types, and an
    /// optional domain filter. A standard is included when it applies in ANY requested region (or all,
    /// when none given) and — for data-typed standards — touches one of the project's data types. The
    /// requirements are flattened + tagged with their standard for citation.
    pub fn requirements_for(
        &self,
        regions: &[String],
        data_types: &[String],
        domains: &[Domain],
    ) -> RequirementSet {
        let candidates: Vec<Standard> = if domains.is_empty() {
            self.store.all()
        } else {
            domains.iter().flat_map(|d| self.store.list_by_domain(*d)).collect()
        };

        let mut standards = Vec::new();
        let mut requirements = Vec::new();
        for s in candidates {
            if !applies_in_any(&s, regions) {
                continue;
            }
            if s.domain == Domain::Privacy && !s.touches_data(data_types) {
                continue;
            }
            for r in scoped_requirements(&s, data_types) {
                requirements.push(AppliedRequirement {
                    standard_id: s.id.clone(),
                    standard_name: s.name.clone(),
                    domain: s.domain,
                    requirement: r,
                });
            }
            standards.push(s);
        }
        RequirementSet { standards, requirements, meta: self.store.meta() }
    }

    /// The accessibility (WCAG) success criteria a UI screen/component must meet. `target` is free
    /// text (e.g. "checkout form") returned with the checklist so the planner can attribute it; the
    /// full AA criteria set is returned regardless (every component must meet them).
    pub fn accessibility_checklist(&self, target: &str) -> AccessibilityChecklist {
        let standards = self.store.list_by_domain(Domain::Accessibility);
        let criteria: Vec<AppliedRequirement> = standards
            .iter()
            .flat_map(|s| {
                s.requirements.iter().map(move |r| AppliedRequirement {
                    standard_id: s.id.clone(),
                    standard_name: s.name.clone(),
                    domain: Domain::Accessibility,
                    requirement: r.clone(),
                })
            })
            .collect();
        AccessibilityChecklist { target: target.to_string(), criteria, meta: self.store.meta() }
    }

    /// The privacy/data-protection obligations for the given data types + regions — a domain-pinned
    /// `requirements_for` so the planner can ask the narrow question directly.
    pub fn privacy_requirements(&self, data_types: &[String], regions: &[String]) -> RequirementSet {
        self.requirements_for(regions, data_types, &[Domain::Privacy])
    }
}

/// A standard applies when it's valid in ANY requested region (empty `regions` ⇒ unrestricted).
fn applies_in_any(s: &Standard, regions: &[String]) -> bool {
    if regions.is_empty() {
        return true;
    }
    regions.iter().any(|r| s.applies_in(r))
}

/// A standard's requirements, dropping data-typed ones that don't match the project's data types.
/// An untyped requirement is always kept; when `data_types` is empty everything is kept.
fn scoped_requirements(s: &Standard, data_types: &[String]) -> Vec<Requirement> {
    if data_types.is_empty() {
        return s.requirements.clone();
    }
    let wanted: Vec<String> = data_types.iter().map(|d| d.trim().to_ascii_lowercase()).collect();
    s.requirements
        .iter()
        .filter(|r| {
            r.data_types.is_empty() || r.data_types.iter().any(|d| wanted.contains(&d.to_ascii_lowercase()))
        })
        .cloned()
        .collect()
}

/// The WCAG checklist for a UI target.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct AccessibilityChecklist {
    pub target: String,
    pub criteria: Vec<AppliedRequirement>,
    pub meta: StoreMeta,
}

#[cfg(test)]
mod tests {
    use super::*;

    fn engine() -> Engine {
        Engine::with_store(Store::in_memory().unwrap())
    }

    #[test]
    fn list_standards_filters_by_domain() {
        let e = engine();
        assert!(e.list_standards(None).len() >= 5);
        let sec = e.list_standards(Some(Domain::Security));
        assert!(sec.iter().all(|s| s.domain == Domain::Security));
        assert!(sec.iter().any(|s| s.id == "soc2"));
    }

    #[test]
    fn get_standard_returns_requirements() {
        let e = engine();
        let wcag = e.get_standard("wcag-2.2").unwrap();
        assert_eq!(wcag.domain, Domain::Accessibility);
        assert!(wcag.requirements.iter().any(|r| r.id == "1.4.3"));
        assert!(e.get_standard("nonexistent").is_none());
    }

    #[test]
    fn requirements_for_scopes_by_region() {
        let e = engine();
        // EU project → GDPR applies, CCPA (us-ca only) does not.
        let eu = e.requirements_for(&["eu".into()], &["pii".into()], &[]);
        let ids: Vec<&str> = eu.standards.iter().map(|s| s.id.as_str()).collect();
        assert!(ids.contains(&"gdpr"));
        assert!(!ids.contains(&"ccpa"));
        // Global standards (WCAG, SOC2, user-protection) still apply everywhere.
        assert!(ids.contains(&"soc2"));
        assert!(ids.contains(&"wcag-2.2"));

        let ca = e.requirements_for(&["us-ca".into()], &["pii".into()], &[]);
        let ca_ids: Vec<&str> = ca.standards.iter().map(|s| s.id.as_str()).collect();
        assert!(ca_ids.contains(&"ccpa"));
        assert!(!ca_ids.contains(&"gdpr"));
    }

    #[test]
    fn requirements_for_drops_unmatched_data_typed_obligations() {
        let e = engine();
        // Generic personal data, no special categories → GDPR's health/biometric obligation is
        // dropped, but the generic PII ones stay.
        let set = e.privacy_requirements(&["pii".into()], &["eu".into()]);
        let gdpr_reqs: Vec<&str> = set
            .requirements
            .iter()
            .filter(|r| r.standard_id == "gdpr")
            .map(|r| r.requirement.id.as_str())
            .collect();
        assert!(gdpr_reqs.contains(&"transparency"));
        assert!(!gdpr_reqs.contains(&"special-category"));

        // With health data, the special-category obligation appears.
        let health = e.privacy_requirements(&["health".into()], &["eu".into()]);
        assert!(health
            .requirements
            .iter()
            .any(|r| r.standard_id == "gdpr" && r.requirement.id == "special-category"));
    }

    #[test]
    fn accessibility_checklist_returns_wcag_criteria() {
        let e = engine();
        let cl = e.accessibility_checklist("checkout form");
        assert_eq!(cl.target, "checkout form");
        assert!(cl.criteria.iter().all(|c| c.domain == Domain::Accessibility));
        assert!(cl.criteria.iter().any(|c| c.requirement.id == "1.4.3"));
    }

    #[test]
    fn requirements_for_respects_domain_filter() {
        let e = engine();
        let only_a11y = e.requirements_for(&[], &[], &[Domain::Accessibility]);
        assert!(only_a11y.standards.iter().all(|s| s.domain == Domain::Accessibility));
    }
}

