pub enum EveError {
    #[error("line is {got} bytes, over the {max}-byte limit -- refused before parsing")]
    TooLong { got: usize, max: usize },
    #[error("not valid JSON: {0}")]
    NotJson(String),
    #[error("no event_type field")]
    NoEventType,
    #[error("event_type {0:?} is missing the fields it needs")]
    Incomplete(String),
