//! Parsing `/proc/net/{tcp,udp,tcp6,udp6}` into sockets.
//!
//! Pure text in, structured sockets out. The sensor is emit-only and updated
//! by swapping its SD card, so the ONLY way to have confidence in this code is
//! to test it exhaustively from fixtures -- there is no logging in to check.
//!
//! ## The formats, from the real files rather than from memory
//!
//! ```text
//!   sl  local_address rem_address   st tx_queue rx_queue tr tm->when retrnsmt   uid ...
//!    0: 0100007F:0BB7 00000000:0000 0A 00000000:00000000 00:00000000 00000000  1000 ...
//! ```
//!
//! `local_address` is `HEXADDR:HEXPORT`. The address is hex **little-endian
//! per 32-bit word**, so `0100007F` is 127.0.0.1 and `00000000` is the
//! wildcard `0.0.0.0`. IPv6 packs four such words into 32 hex characters.
//! The port is plain big-endian hex.

use crate::error::ProcNetError;

/// TCP socket in `LISTEN`.
const TCP_LISTEN: &str = "0A";
/// UDP socket that is bound but not connected.
const UDP_UNCONNECTED: &str = "07";

#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum Protocol {
    Tcp,
    Udp,
}

/// What a row in one of the tables actually represents.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum Role {
    /// TCP `LISTEN`, or UDP bound with no peer: something can arrive here.
    Inbound,
    /// A socket with a peer address set. On this sensor that is the outbound
    /// multicast emitter doing its job -- NOT an inbound surface. Conflating
    /// the two would have the sensor report itself exposed for transmitting.
    ConnectedOutbound,
}

/// How reachable a bound address is.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum Reach {
    /// `0.0.0.0` / `::` -- bound to every interface. The binding that matters.
    Wildcard,
    /// A specific, routable address.
    Routable,
    /// `127.0.0.0/8` or `::1`: not reachable across the network.
    Loopback,
}

#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct Socket {
    pub transport: Protocol,
    pub role: Role,
    pub reach: Reach,
    pub local_port: u16,
    /// Rendered for humans; the verdict never parses this back.
    pub local_addr: String,
}

impl Socket {
    /// Whether this socket is a way INTO the box from the network.
    pub fn is_network_reachable_inbound(&self) -> bool {
        match self.role {
            Role::ConnectedOutbound => false,
            Role::Inbound => match self.reach {
                Reach::Wildcard | Reach::Routable => true,
                Reach::Loopback => false,
            },
        }
    }
}

/// One parsed table, carrying how many rows it actually understood.
///
/// The count is not decoration. A parser that has stopped matching returns an
/// empty socket list, which is indistinguishable from a hardened box unless
/// the caller can see that zero rows were read.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Table {
    pub sockets: Vec<Socket>,
    /// Data rows present in the input, whether or not they were understood.
    pub rows_seen: usize,
    /// Rows successfully parsed.
    pub rows_parsed: usize,
}

/// Decode a `/proc/net` hex address into a display string and its reach.
fn decode_addr(hex: &str) -> Result<(String, Reach), ProcNetError> {
    match hex.len() {
        8 => {
            let raw = u32::from_str_radix(hex, 16)
                .map_err(|_| ProcNetError::BadAddress(hex.to_string()))?;
            // Little-endian per word: the first hex pair is the LAST octet.
            let o = raw.to_le_bytes();
            let text = format!("{}.{}.{}.{}", o[0], o[1], o[2], o[3]);
            let reach = if raw == 0 {
                Reach::Wildcard
            } else if o[0] == 127 {
                Reach::Loopback
            } else {
                Reach::Routable
            };
            Ok((text, reach))
        }
        32 => {
            let mut words = [0u32; 4];
            for (i, w) in words.iter_mut().enumerate() {
                *w = u32::from_str_radix(&hex[i * 8..i * 8 + 8], 16)
                    .map_err(|_| ProcNetError::BadAddress(hex.to_string()))?;
            }
            let bytes: Vec<u8> = words.iter().flat_map(|w| w.to_le_bytes()).collect();
            let all_zero = bytes.iter().all(|b| *b == 0);
            // ::1 -- fifteen zero bytes then 1.
            let loopback = bytes[..15].iter().all(|b| *b == 0) && bytes[15] == 1;
            // The two cases that actually show up are the ones an operator most
            // needs to recognise instantly, and they are the least readable
            // fully expanded: a wildcard bind and loopback.
            let text = if all_zero {
                "::".to_string()
            } else if loopback {
                "::1".to_string()
            } else {
                bytes
                    .chunks(2)
                    .map(|c| format!("{:02x}{:02x}", c[0], c[1]))
                    .collect::<Vec<_>>()
                    .join(":")
            };
            let reach = if all_zero {
                Reach::Wildcard
            } else if loopback {
                Reach::Loopback
            } else {
                Reach::Routable
            };
            Ok((text, reach))
        }
        _ => Err(ProcNetError::BadAddress(hex.to_string())),
    }
}

fn split_addr(field: &str) -> Result<(&str, u16), ProcNetError> {
    let (a, p) = field
        .split_once(':')
        .ok_or_else(|| ProcNetError::BadAddress(field.to_string()))?;
    let port = u16::from_str_radix(p, 16).map_err(|_| ProcNetError::BadAddress(field.to_string()))?;
    Ok((a, port))
}

/// Parse one `/proc/net` table.
///
/// Never returns `Ok` with a silently-empty result for input it did not
/// understand: a row it cannot parse increments `rows_seen` without
/// incrementing `rows_parsed`, and the caller compares the two.
pub fn parse_table(text: &str, transport: Protocol) -> Result<Table, ProcNetError> {
    let mut lines = text.lines();
    let header = lines.next().ok_or(ProcNetError::Empty)?;
    // The header is the one thing every kernel version has kept stable, so it
    // is the cheapest way to notice we are reading something else entirely.
    if !header.contains("local_address") {
        return Err(ProcNetError::UnrecognisedHeader(
            header.chars().take(60).collect(),
        ));
    }

    let mut sockets = Vec::new();
    let mut rows_seen = 0usize;
    let mut rows_parsed = 0usize;

    for line in lines {
        if line.trim().is_empty() {
            continue;
        }
        rows_seen += 1;

        let f: Vec<&str> = line.split_whitespace().collect();
        // sl, local, rem, st -- the four fields this parser needs.
        if f.len() < 4 {
            continue;
        }

        let (Ok((local_hex, local_port)), Ok((rem_hex, rem_port))) =
            (split_addr(f[1]), split_addr(f[2]))
        else {
            continue;
        };
        let Ok((local_addr, reach)) = decode_addr(local_hex) else {
            continue;
        };
        let Ok((_, _)) = decode_addr(rem_hex) else {
            continue;
        };

        let state = f[3];
        let has_peer = rem_port != 0;

        let role = match transport {
            Protocol::Tcp => {
                if state == TCP_LISTEN {
                    Role::Inbound
                } else {
                    // Every other TCP state implies an established or closing
                    // conversation, which is not a listening surface.
                    Role::ConnectedOutbound
                }
            }
            Protocol::Udp => {
                if state == UDP_UNCONNECTED && !has_peer {
                    Role::Inbound
                } else {
                    Role::ConnectedOutbound
                }
            }
        };

        rows_parsed += 1;
        sockets.push(Socket { transport, role, reach, local_port, local_addr });
    }

    Ok(Table { sockets, rows_seen, rows_parsed })
}

//! Where a datagram goes once it is sealed.
//!
//! A seam, so that everything worth testing in [`crate::emit`] -- sequencing,
//! nonce derivation, snapshot scheduling, posture wiring -- runs without a
//! socket, and the real implementation stays a thin shell over the standard
//! library with nothing clever in it.

use std::io;
use std::net::{Ipv4Addr, SocketAddrV4, UdpSocket};

/// Somewhere to put a finished datagram.
pub trait Transport {
    fn send(&self, datagram: &[u8]) -> io::Result<()>;
}

/// Multicast UDP over one named interface.
///
/// ## `connect`, not `sendto` -- for two independent reasons
///
/// The posture checker in [`crate::procnet`] classifies a UDP socket **with**
/// a peer as connected-outbound and one **without** as a bound inbound
/// surface, because that is exactly how the kernel distinguishes them in
/// `/proc/net/udp`. An emitter using `send_to` on an unconnected socket would
/// therefore appear in the sensor's own attestation as a socket bound with no
/// peer -- the sensor would report itself `Exposed` for the act of
/// transmitting, and whoever watches the posture would learn to ignore it.
///
/// Independently, a connected UDP socket discards datagrams from anyone but
/// its peer, which narrows what can even reach the socket on a box whose whole
/// premise is that nothing reaches it.
///
/// ## TTL 1 is a security property, not a default
///
/// A multicast TTL of one means the telemetry **physically cannot be routed
/// off the local segment**, whatever some router elsewhere is configured to
/// do with the group. It bounds the blast radius of a misconfigured multicast
/// route to nothing.
/// Whether the kernel loops our own multicast back to this host.
///
/// The sensor wants this OFF: it has no receive path at all, so looping its
/// own traffic back up the stack is pure cost on a thermally-saturated box.
///
/// ## What this setting does NOT do, measured rather than assumed
///
/// An earlier version of this comment claimed a same-host end-to-end test
/// needs the loop enabled. **That is false**, and a bite test proved it: the
/// end-to-end test in [`crate::receive`] passes with `Loopback::Off`.
/// `IP_MULTICAST_LOOP` has no observable effect when the outgoing interface is
/// loopback — the datagram is delivered either way — so the setting is
/// meaningful on a real NIC and indifferent on `lo`.
///
/// It is kept as a named parameter because Off is a deliberate choice for the
/// sensor that a future reader should see and not "optimise" away, not because
/// the tests depend on it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Loopback {
    /// The sensor. Nothing on this host listens.
    Off,
    /// Same-host tests.
    On,
}

pub struct UdpMulticast {
    socket: UdpSocket,
}

impl UdpMulticast {
    /// Bind to `interface_addr` and connect to the multicast `group`.
    ///
    /// There is deliberately no receive path on this type. Not "unused" -- 
    /// absent, so that no future edit can casually add a read to the sensor's
    /// one outbound socket.
    pub fn bind(interface_addr: Ipv4Addr, group: SocketAddrV4) -> io::Result<Self> {
        Self::bind_with(interface_addr, group, Loopback::Off)
    }

    /// As [`bind`](Self::bind), choosing whether our own multicast loops back.
    pub fn bind_with(
        interface_addr: Ipv4Addr,
        group: SocketAddrV4,
        loopback: Loopback,
    ) -> io::Result<Self> {
        // Port 0: the kernel picks the source port. The sensor is never
        // addressed, so a fixed source port would buy nothing and would be one
        // more stable thing to aim at.
        let socket = UdpSocket::bind(SocketAddrV4::new(interface_addr, 0))?;
        // NOTE: std exposes no `IP_MULTICAST_IF`. Binding the socket to the
        // interface's own address is the std-only lever for selecting the
        // egress interface, and on this Pi -- one routable interface -- that
        // is unambiguous. If the sensor ever becomes multi-homed, this is the
        // line that needs `socket2::Socket::set_multicast_if_v4`, and the
        // symptom of not fixing it would be telemetry leaving the wrong NIC.
        socket.set_multicast_ttl_v4(1)?;
        socket.set_multicast_loop_v4(matches!(loopback, Loopback::On))?;
        socket.connect(group)?;
        Ok(Self { socket })
    }

    /// The multicast TTL actually set on the socket. Exposed so the
    /// segment-confinement property can be asserted rather than assumed.
    pub fn multicast_ttl(&self) -> io::Result<u32> {
        self.socket.multicast_ttl_v4()
    }

    /// The local address the kernel assigned. Only for reporting.
    pub fn local_addr(&self) -> io::Result<std::net::SocketAddr> {
        self.socket.local_addr()
    }
}

impl Transport for UdpMulticast {
    fn send(&self, datagram: &[u8]) -> io::Result<()> {
        // `send`, not `send_to` -- the socket is connected, and using the
        // unconnected form here would defeat the reasoning above.
        self.socket.send(datagram).map(|_| ())
    }
}

//! The `bsc persona` subcommand (#2094) — the persona-specific shim over the shared
//! verbatim-JSON-per-id store CLI ([`bsc_json_store::cli`], #2158). The persona library
//! (`~/.base-studio-code/personas/<id>.json`) is list/get/set/remove-able from a session's own shell
//! — the same store the desktop Personas library reads/writes and the planner can author into (mint a
//! persona like it mints a skill).
//!
//! Dispatched by the unified `bsc` binary (#1877) via [`run`]; the shared per-command help (#1762):
//!   bsc persona help          # compact menu
//!   bsc persona get help      # detailed help for ONE command
//!
//! The store is located via `--dir <path>` or the `BSC_PERSONA_DIR` env var, defaulting to
//! `~/.base-studio-code/personas/`.

use bsc_cli_util::CmdDoc;
use bsc_json_store::cli::CliSpec;

/// How long `use` waits for the app, and how it polls — the same numbers `bsc fleet` uses, so the two
/// verbs on this transport behave alike.
const DEFAULT_TIMEOUT_MS: i64 = 10_000;
const POLL_INTERVAL_MS: u64 = 50;
/// Requests older than this are swept before a new one is written, so a dead run cannot accumulate.
const STALE_MS: i64 = 60_000;

const TAGLINE: &str = "the user persona store — list/get/set/remove ~/.base-studio-code/personas (#2094)";

