        let body = serde_json::json!({ "id": id, "name": "X", "role": "designer", "builtin": builtin });
        s.set(id, &serde_json::to_string(&body).unwrap()).unwrap();
        s
    }

    fn scratch(tag: &str) -> std::path::PathBuf {
