        let denied = strings(&user["denied"]);
        assert_eq!(denied.first().map(String::as_str), Some("git push"), "user denies come first");
        assert!(
            session_denied_commands(&["git push".to_string()], None, &[], Some("auto-pr"), &[])
                .contains(&"git push".to_string()),
