    }

    #[test]
    fn spares_everything_at_the_old_three_day_cutoff() {
        // The no-op this default replaced.
        let entries =
            [hours_ago("s-aaa-1", 0.1), hours_ago("bsc_graph-2bbbbbbbbbbbb", 8.0), hours_ago("s-aaa-3", 30.0)];
