    fn unknown_command_is_refused_with_the_overview() {
        let e = run(vec!["frobnicate".into()], "bsc cve").unwrap_err();
        assert!(e.contains("unknown command 'frobnicate'"));
        assert!(e.contains("COMMANDS:"));
    }

