/// Recursively collect names+versions from a v1 `dependencies` tree.
fn walk_v1_deps(
    deps: &serde_json::Map<String, Value>,
    push: &mut impl FnMut(String, Option<String>, &mut Vec<Package>),
    out: &mut Vec<Package>,
) {
    for (name, entry) in deps {
