    }

    #[test]
    fn the_window_floor_excludes_older_rows() {
        let d = tmp("since");
        write(
            &d,
            "2026-09-01T12:00:00Z\tp\th\t200\t1\t10\t∅\t∅\t∅\n\
             2026-09-01T18:00:00Z\tp\th\t200\t9\t10\t∅\t∅\t∅\n",
