        assert!(sl.done);
        assert_eq!(sl.done_reason, "stop");
        assert_eq!(sl.usage["input_tokens"], 12);
        assert_eq!(sl.usage["output_tokens"], 7);
        // A non-JSON / partial line is skipped.
