        assert_eq!(pane_llm_config(&global, Some("llama3.1"), &tiers()).num_ctx, Some(65536), "rule 4");
        assert_eq!(pane_llm_config(&global, Some("opus-4.5"), &tiers()).num_ctx, Some(65536), "rule 2");
