implementations.code:
//! Design-graph health analyzer (#2678, epic #2677) — the PURE traversal behind `bsc ui doctor`.
//!
//! The component library is a per-kit composition graph: nodes are components (`role`, `used` =
//! cross-codebase reuse count, `composes` = the names it depends on), edges are `composes`
//! (composer → dependency, resolved by-name WITHIN a kit). This module finds the dead/duplicated
//! design a growing kit accumulates — especially as the designer LLM authors components via
//! `bsc ui` — so the session can discover and prune it in ONE call.
//!
//! Pure: input is the parsed component records, output is a ranked `Vec<Finding>`. No I/O, so it's
//! unit-tested directly and the same taxonomy can be mirrored frontend-side for graph badges (#2680).
//!
//! Findings (most-severe first): **cycle** (a `composes` loop — also breaks the layered layout) ·
//! **dangling-composes-reference** (a `composes` entry naming no component in the kit — the edge is
//! silently dropped, so the graph reads as complete while the reference names nothing, #89) ·
//! **dangling-branch** (an unused root that still pulls in dependencies) · **duplicate** (two
//! components wrapping the same intrinsic, or byte-identical source) · **no-implementation** (a
//! component the Design Studio preview can't build — a spec, not code) · **self-reference** (an
//! own-module component whose only rendered element is ITSELF, `<Name/>` — a self-referential stub
//! that passes the buildability + syntax gates yet produces no output, #3026) · **unresolvable-import** (a
//! module imports something the preview can't resolve — a bare npm package not in the import-map, #2934,
//! OR an internal `@/…`/relative import matching no kit component or runtime-closure module, #2954 —
//! throws "module not found" at preview time) · **reimplementation** (an own-source component that
//! DECLARES a symbol re-coding a node that already exists in the library — an inline `function fibonacci`
//! while `@bsc/algorithms/fibonacci` exists — instead of importing it; the "compose, don't recreate"
//! guardrail, #3118) · **orphan**
//! (an isolated, never-referenced primitive/composite) · **unwired-prop** (declares props its own source
//! never references — a declared interface that does nothing, #2924) · **props-metadata-mismatch** (the
//! record's `props[]` disagrees with the prop signature its own source declares — an EMPTY `props: []` on
//! a component with a real typed signature silently disables the preview's sample-data synthesizer, #88) ·
//! **skips-family-shell** (a member of a folder/name-suffix family that does NOT compose the shell
//! primitive nearly all its siblings do — a REPORT, not a rule, #87) · **phantom-compose** (a user
//! component declares `composes` children its own source never renders — a false graph edge that also
//! masks orphan detection, #3111) · **slot-shell** (INFORMATIONAL — a
//! composite whose composed children arrive via ReactNode content slots, so a standalone preview renders
//! a demo placeholder, #2921). "Unused" = orphan ∪ dangling-branch — a node with no composer AND
//! `used == 0`; a `page`/`layout` with `used > 0` is a legit entry point, never flagged.
//!
//! **Reporting a dead root is not the same as auto-DELETING one.** The findings above are a diagnosis;
//! [`prune_plan`] is what `bsc ui doctor --fix` may actually remove, and it filters the dead-root
//! candidates through three guards (#3087) — never a `page` (a page is a root by definition), never a
//! `builtin: true` packaged seed, and never anything at all while the `used` index is unpopulated
//! (`used == 0` store-wide means the usage signal is UNKNOWN, not that everything is unused). A guarded
//! candidate is still REPORTED; only its automatic removal is withheld.
//!
//! The **no-implementation** check is artifact-aware: a store record strips a built-in's `source`
//! (#2794), so both built-ins and user specs look source-less in the store — but a built-in still
//! builds because its real code lives in the packaged react-ui artifact. So a node is buildable iff
//! its `src` is in that artifact (with `source`), OR it carries its own non-empty `source`, OR its
//! `srcText` is a real module (`looks_buildable_module`) — the exact `componentPreviewFiles` logic
//! (#2824/#2828). A module's `@/…` imports resolve against the kit's own components, the packaged
//! platform-module registry, AND any record's `provides` (component OR algorithm-graph, #125/#83 — the
//! loader's first resolution path) — so a component composing a hook that has been lifted into the
//! algorithms graph builds exactly as the app mounts it. Only a node that is NONE of those is flagged
//! (mirrors `graphHealth.ts`).

use serde_json::{json, Value};
use std::collections::{BTreeMap, BTreeSet};

/// One health finding — LLM-consumable: what, where, why, and what to do about it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Finding {
    /// `cycle` | `dangling-composes-reference` (#89, sev-2) | `dangling-branch` | `duplicate` | `no-implementation` | `self-reference` |
    /// `unresolvable-import` | `stubbed-import` (#3696, sev-1) | `hardcoded-color` (#3704, sev-1) |
    /// `reimplementation` | `reimplemented-component` (#3892, sev-3) | `orphan` | `unwired-prop` |
    /// `props-metadata-mismatch` (#88, sev-2) | `skips-family-shell` (#87, sev-2) |
    /// `phantom-compose` | `no-empty-state` |
    /// `multi-component` (#doctor-flags…, sev-2) | `multi-export` (#a-record-holds-one-item…, sev-2 —
    /// its EXPORTED counterpart; see the loop for why both exist) |
    /// `no-loading-state` | `no-error-state` (#3555) | `no-analytics` (#3810) | `no-tests` (#3878) | `slot-shell` | `render-error` (#3540, CLI-only — see [`render_error_findings`]) |
    /// `unresolved-import-symbol` (bsc request #149, sev-4, CLI-only, behind `--imports` — see
    /// [`crate::import_symbols::unresolved_import_symbol_findings`]: the specifier resolves but does not
    /// export the imported name, even through an `export * from` barrel).
    pub category: &'static str,
    /// Higher = more severe; the report is sorted by this, descending.
    pub severity: u8,
    /// The kit the finding is scoped to.
    pub kit: String,
    /// The component id(s) involved (a cycle/duplicate/branch can span several).
    pub node_ids: Vec<String>,
    /// The component name(s), parallel to `node_ids` — the human/LLM-readable handle.
    pub node_names: Vec<String>,
    /// A one-line explanation of the finding.
    pub why: String,
    /// The concrete next step (e.g. which id to remove, or which to merge into which).
    pub suggested_action: String,
}

impl Finding {
    /// The finding as a JSON object (the `--json` report shape). Manual — the crate carries
    /// `serde_json` but not the `serde` derive.
    pub fn to_value(&self) -> Value {
        json!({
            "category": self.category,
            "severity": self.severity,
            "kit": self.kit,
            "nodeIds": self.node_ids,
            "nodeNames": self.node_names,
            "why": self.why,
            "suggestedAction": self.suggested_action,
        })
    }
}

/// Findings for components whose PREVIEW failed — a `build:` esbuild failure OR a `render:` runtime throw
/// (#3540/#3549) — the half doctor's static analyzer is blind to. Doctor cannot run esbuild or mount a
/// component, so a preview failure can only reach the report via the durable preview-error log
/// (`preview_errors::latest_error_by_id`), which the app's on-visit scan + live previews record with a
/// `build:`/`render:` kind prefix. Fed those `(id, message)` pairs, this emits one finding per errored
/// component STILL in `components` (a stale id for a removed component is dropped), with prose matched to
/// the kind (a build failure and a render throw need different fixes).
///
/// Deliberately NOT part of [`analyze_with`]: that function has a byte-parity TS twin (`graphHealth.ts`)
/// which is static-only, and the render error is a Rust/CLI-only signal fed from a log the frontend
/// doesn't read. `cmd_doctor` appends these like `analyze_motion`, so the twin stays untouched.
/// The sentence that keeps a REPLAY from reading as a fresh check.
///
/// `bsc ui doctor` cannot build or mount anything — it is a CLI with no esbuild and no DOM, which is the
/// whole reason [`crate::preview_errors`] exists. So every `render-error` is an observation the APP made
/// at some earlier moment, and re-running doctor re-reads the same line. Without this sentence the two
/// are indistinguishable, and the reader's natural loop — fix, re-run doctor, see the same error — reads
/// as "the fix did not take".
///
/// That is not hypothetical. Designer request #101: a session gave a record the `provides` its importer
/// needed, re-ran doctor six-plus times over several minutes against one 19:48:22Z line, and filed a bug
/// against the preview's dependency index. The fix had worked — forcing a real render posted a fresh
/// entry seconds later, and it was a RENDER throw, not the build failure. Nothing in the output could
/// have told it apart, including its own counter-evidence: the fixes that DID appear to clear were on
/// components it happened to have open in the Studio, so the app re-rendered those.
///
/// The stamp is the log line's own `at`, never a clock read here — so the report is deterministic and a
/// test over a fixture cannot flake. A line with no `at` degrades to the instruction alone rather than
/// printing an empty "observed".
fn replay_notice(kit: &str, id: &str, at: &str) -> String {
    let target = if kit.is_empty() { id.to_string() } else { format!("{kit} {id}") };
    let observed = if at.trim().is_empty() {
        String::from("This is a REPLAY of a recorded observation")
    } else {
        format!("This is a REPLAY of what the app observed at {}", at.trim())
    };
    format!(
        "{observed} — doctor never builds, so RE-RUNNING IT CANNOT REFRESH THIS. \
         `bsc navigate component {target}` makes the running app rebuild and render it, and the \
         fresh result lands in `bsc ui preview-errors`."
    )
}

pub fn render_error_findings(components: &[Value], errors: &[(String, String, String)]) -> Vec<Finding> {
    let by_id: BTreeMap<&str, &Value> = components
        .iter()
        // #3725: a suppression tombstone is not a component — drop its errors like a store-absent one.
        .filter(|c| c.get("suppressed").and_then(Value::as_bool) != Some(true))
        .filter_map(|c| c.get("id").and_then(Value::as_str).map(|id| (id, c)))
        .collect();
    errors
        .iter()
        .filter_map(|(id, message, at)| {
            let comp = by_id.get(id.as_str())?; // drop a stale error for a component no longer in the store
            // #3737: drop a render-error for a component whose current srcText is EMPTY — an empty spec
            // can't have a live render error (the preview shows no-implementation, not a throw), so a
            // persisted error there is stale by definition (the component was reduced to a spec since).
            // Conservative: a NON-empty srcText keeps its error (a real build/render failure is possible).
            if comp.get("srcText").and_then(Value::as_str).unwrap_or_default().trim().is_empty() {
                return None;
            }
            let name = comp.get("name").and_then(Value::as_str).unwrap_or(id.as_str()).to_string();
            let kit = comp.get("kitId").and_then(Value::as_str).unwrap_or_default().to_string();
            let kit_for_notice = kit.clone();
            // The scan records the failure with a `build:`/`render:` kind prefix (#3549). Strip it for
            // display and branch the prose — a BUILD failure (esbuild) and a RENDER throw (an exception
            // during mount) need different fixes. A raw message with no prefix is treated as a render throw.
            let is_build = message.starts_with("build:");
            let detail = message
                .strip_prefix("build:")
                .or_else(|| message.strip_prefix("render:"))
                .unwrap_or(message)
                .trim();
            // Collapse a multi-line stack trace to one line and cap it — the finding is a summary; the
            // full trace stays in `bsc ui preview-errors`.
            let one_line: String = detail.replace(['\n', '\t'], " ").chars().take(240).collect();
            Some(Finding {
                // Severity 5 — above every static finding (cycle is 4): a confirmed preview failure is the
                // most actionable, so it sorts to the top of the report.
                category: "render-error",
                severity: 5,
                kit,
                node_ids: vec![id.clone()],
                node_names: vec![name.clone()],
                why: if is_build {
                    format!("`{name}` failed to BUILD in the preview: {}", one_line.trim())
                } else {
                    format!("`{name}` threw when the preview rendered it: {}", one_line.trim())
                },
                suggested_action: if is_build {
                    format!(
                        "the preview's esbuild build failed — check the source + imports with \
                         `bsc ui get {id} --field srcText --raw` (a missing/mistyped import, an unresolved \
                         sibling, or TypeScript in a file loaded as plain JS shows up here). {}",
                        replay_notice(&kit_for_notice, id, at),
                    )
                } else {
                    format!(
                        "the preview likely passes `undefined` for a prop it reads — check `bsc ui preview-props {id}` \
                         and guard the access (or fix the sample-data shape). {}",
                        replay_notice(&kit_for_notice, id, at),
                    )
                },
            })
        })
        .collect()
}

/// A component record reduced to the fields the analyzer needs (parsed from the store JSON). Records
/// that don't parse to at least an id are skipped — the analyzer never crashes on an odd row.
struct Node {
    id: String,
    name: String,
    kit: String,
    role: String,
    used: i64,
    composes: Vec<String>,
    wraps: Option<String>,
    src_text: String,
    /// `src/`-relative source path — cross-referenced against the packaged artifact roster for the
    /// buildability check (a built-in's real code lives in the artifact even though the store strips it).
    src: String,
    /// The component's own implementation `source`, when it carries one (a user-authored module).
    /// The store strips a built-in's `source` (#2794), so this is empty for built-ins.
    source: String,
    /// The registered PLATFORM module specifier this graph-source component OVERRIDES (#3660), e.g.
    /// `@/shared/ui/typography/Text` — empty when it's an ordinary component. The runtime loader resolves a
    /// `@/…` import to the component that `provides` it; the buildability check mirrors that (#43).
    provides: String,
    /// `(name, type)` per prop — for the slot-shell check (a non-`children` ReactNode content slot).
    props: Vec<(String, String)>,
    /// The record's folder — one of the two groupings the `skips-family-shell` check treats as a FAMILY
    /// (#87). Read through `record_folder`, which also honours the legacy `group` key that most stored
    /// records still carry: reading `folder` alone leaves this empty on nearly the whole real library.
    folder: String,
    /// Whether this is a packaged built-in (its store record is a contract catalog: `source` stripped,
    /// `srcText` an illustrative snippet). The phantom-compose check (#3111) skips built-ins — scanning
    /// their illustrative snippet for composed children would false-positive.
    builtin: bool,
    /// How many analytics events the component's `analytics` manifest declares (#3810) — the per-node
    /// events contract (data, not code). 0 ⇒ uninstrumented, which the `no-analytics` check flags for an
    /// interactive component.
    analytics_events: usize,
    /// How many tests the component's `tests` manifest carries (#3878) — the per-node test contract, the
    /// same shape one field over from `analytics`. A node's tests travel WITH it, because once its source
    /// is a store record compiled at runtime, a test file in `src/**` is no longer beside what it tests.
    /// 0 ⇒ untested, which the `no-tests` check flags for an IMPLEMENTED own-module component.
    tests: usize,
    /// Has this node's usage actually been DETERMINED? (`usageAssessed`, slice 1 of #3888.)
    ///
    /// `used == 0` conflates two different facts — "we looked and found nothing" and "nothing looked" —
    /// and auto-pruning may only ever act on the first. Nothing writes this field yet, so today it is
    /// false everywhere and `--fix` prunes nothing, exactly as the store-wide guard already achieved.
    /// What it buys is that a detector can only make prunable the nodes it MEASURED: see [`prune_plan`].
    usage_assessed: bool,
}

fn s(v: &Value, key: &str) -> String {
    v.get(key).and_then(Value::as_str).unwrap_or_default().to_string()
}

fn parse_node(v: &Value) -> Option<Node> {
    let id = v.get("id").and_then(Value::as_str)?.to_string();
    if id.is_empty() {
        return None;
    }
    // #3725: a suppression tombstone (`{ id, suppressed: true }`) is not a component — it marks a
    // permanently-removed packaged builtin. Skip it here so EVERY graph-health consumer (analyze,
    // prunable, usage index) ignores it and it never shows a false `no-implementation` etc.
    if v.get("suppressed").and_then(Value::as_bool) == Some(true) {
        return None;
    }
    Some(Node {
        name: {
            let n = s(v, "name");
            if n.is_empty() { id.clone() } else { n }
        },
        id,
        kit: s(v, "kitId"),
        role: {
            let r = s(v, "role");
            if r.is_empty() { "primitive".to_string() } else { r }
        },
        used: v.get("used").and_then(Value::as_i64).unwrap_or(0),
        // `used > 0` IS an assessment — someone counted it. The explicit flag is for the other half: a
        // node a detector examined and found genuinely unused.
        usage_assessed: v.get("usageAssessed").and_then(Value::as_bool).unwrap_or(false)
            || v.get("used").and_then(Value::as_i64).unwrap_or(0) > 0,
        composes: v
            .get("composes")
            .and_then(Value::as_array)
            .map(|a| a.iter().filter_map(|x| x.as_str().map(str::to_string)).collect())
            .unwrap_or_default(),
        wraps: v.get("wraps").and_then(Value::as_str).filter(|w| !w.is_empty()).map(str::to_string),
        src_text: s(v, "srcText"),
        src: s(v, "src"),
        source: s(v, "source"),
        provides: s(v, "provides"),
        props: v
            .get("props")
            .and_then(Value::as_array)
            .map(|a| {
                a.iter()
                    .filter_map(|p| {
                        let name = p.get("name").and_then(Value::as_str)?.to_string();
                        let ty = p.get("type").and_then(Value::as_str).unwrap_or_default().to_string();
                        Some((name, ty))
                    })
                    .collect()
            })
            .unwrap_or_default(),
        folder: crate::cli::record_folder(v).unwrap_or_default().to_string(),
        builtin: v.get("builtin").and_then(Value::as_bool).unwrap_or(false),
        analytics_events: v.get("analytics").and_then(Value::as_array).map(Vec::len).unwrap_or(0),
        tests: v.get("tests").and_then(Value::as_array).map(Vec::len).unwrap_or(0),
    })
}

/// Is `(name, ty)` an ACTION prop — an event/callback the component fires (`onClick`, `onChange`,
/// `onSelect`, …: name starts with `on` + a function type)? Its presence marks the component as
/// INTERACTIVE, so the `no-analytics` check (#3810) expects an events manifest. Mirrors `isActionProp`
/// (graphHealth.ts).
fn is_action_prop(name: &str, ty: &str) -> bool {
    name.len() > 2 && name.to_lowercase().starts_with("on") && ty.contains("=>")
}

/// Is `(name, ty)` a CONTENT-SLOT prop — a non-`children` prop typed as a React node? Mirrors
/// `isNodeSlotProp` (graphHealth.ts) + how the preview samples props: a `reactnode`/`node`-typed prop is
/// filled with a placeholder standalone, so a component with one renders a demo (#2921).
fn is_node_slot_prop(name: &str, ty: &str) -> bool {
    if name == "children" {
        return false;
    }
    let t = ty.to_lowercase();
    t.contains("reactnode") || t.contains("node")
}

/// Is `ty` a COLLECTION/data prop — an array (`Row[]`, `array`)? A data component takes one; the preview's
/// empty/loading state switch (#3135) is expected of it. Mirrors `isCollectionProp` (componentPreview.ts).
fn is_collection_prop(ty: &str) -> bool {
    let t = ty.to_lowercase();
    t.contains("[]") || t.contains("array")
}

/// Is `(name, ty)` a LOADING-family boolean (`loading`/`busy`/`pending`/`isLoading`)? A data component with
/// one can preview its loading/skeleton render (#3135). Mirrors `isLoadingProp` (componentPreview.ts).
fn is_loading_prop(name: &str, ty: &str) -> bool {
    let t = ty.to_lowercase();
    (t == "boolean" || t.contains("boolean"))
        && matches!(name.to_lowercase().as_str(), "loading" | "busy" | "pending" | "isloading")
}

/// Is `(name, ty)` an ERROR-family prop (`error`/`err`/`isError`/`hasError`, and NOT a callback)? A data
/// component with one can preview its error render (#3555). Mirrors `isErrorProp` (componentPreview.ts).
fn is_error_prop(name: &str, ty: &str) -> bool {
    let t = ty.to_lowercase();
    let is_fn = t.contains("=>") || t.contains("function") || t.contains("void");
    !is_fn && matches!(name.to_lowercase().as_str(), "error" | "err" | "iserror" | "haserror")
}

/// The packaged `bsc/react-ui` kit artifact — the SAME `react-ui.json` the kit store + the vendored-
/// source emit read (`bsc_ui::kit::packaged_kit_json`). Read here too because this crate can't depend
/// on `bsc-ui` (that edge would cycle), so the buildability check can cross-reference a component's
/// `src` against the artifact roster — exactly like the frontend's raw
/// `@data/components/react-ui.json` import that `componentPreviewFiles` resolves a built-in against.
///
/// LOADED AT RUNTIME rather than `include_str!`'d (see [`bsc_util::packaged`]) — this was one of the
/// two crates a 5.3 MB record edit used to recompile.
fn packaged_kit_json() -> &'static str {
    static V: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    V.get_or_init(|| bsc_util::packaged::read_required("components/react-ui.json")).as_str()
}

/// The preview import-map (`src-tauri/data/ui/preview-importmap.json`) — the SAME json the frontend
/// `componentBundle` uses. Its KEYS are the specifiers the preview iframe can resolve; a bare import not
/// among them throws "Failed to resolve module specifier" at preview time (#2934). Embedded so the
/// static `unresolvable-import` check runs with no fs/network — the Rust twin of `graphHealth.ts`.
fn preview_importmap_json() -> &'static str {
    static CELL: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    CELL.get_or_init(|| bsc_util::packaged::read_required("ui/preview-importmap.json"))
}

/// The specifiers the runtime module REGISTRY resolves (#3897) — the SAME json `graphHealth.ts` imports,
/// generated from the real registry by `platformModules.gen.test.ts`.
///
/// Without it the buildability check resolved `@/…` against the packaged artifact and sibling node `src`
/// paths only, so a record honestly importing a registered platform module
/// (`@/shared/lib/security/consoleModel`) matched neither and read as `no-implementation` — while the app
/// mounted it fine. The finding then pressured the next author to STUB the import to silence it, which is
/// the corruption `reimplemented-component` exists to catch (#3892/#3895).
fn platform_modules_json() -> &'static str {
    static CELL: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    CELL.get_or_init(|| bsc_util::packaged::read_required("ui/platform-modules.json"))
}

/// Whether `spec` is a REGISTERED platform module — one the runtime module registry resolves, so a
/// record importing it mounts in the app without the import being vendored anywhere.
///
/// Public so the HARVESTER shares this one predicate instead of growing a second copy of the registry
/// (#4071). Harvest had exactly the blind spot #3897 fixed here: it resolved `@/…` against sibling `src`
/// paths only, so 116 of its 351 unbuildable candidates were blocked wholly or partly by specifiers the
/// runtime resolves fine. A false "unresolved import" is not merely noise — it is the pressure that makes
/// the next author hand-stub the import to silence it, which is the corruption `reimplemented-component`
/// exists to catch (#3892/#3895).
pub fn is_registered_platform_module(spec: &str) -> bool {
    platform_modules().contains(spec)
}

/// The specifiers records in the OPEN STORE `provides` — the loader's first resolution path (#3660).
///
/// Unlike the platform manifest this cannot be embedded at compile time: it depends on the store being
/// written to, which is chosen per invocation (`--dir` / `BSC_COMPONENT_DIR`). `open_component_store`
/// publishes it here on open. Empty until then, which makes the gate behave exactly as it did before —
/// a caller that never opens a store (the unit tests) is unaffected.
static PROVIDED: std::sync::RwLock<Option<std::collections::HashSet<String>>> = std::sync::RwLock::new(None);

/// Publish the open store's provides-set. Called once per invocation, from `open_component_store`.
pub(crate) fn set_provided_specifiers(specs: std::collections::HashSet<String>) {
    if let Ok(mut w) = PROVIDED.write() {
        *w = Some(specs);
    }
}

fn provided_specifiers() -> std::collections::HashSet<String> {
    PROVIDED.read().ok().and_then(|g| g.clone()).unwrap_or_default()
}

/// Does some RECORD `provides` this specifier? The loader's FIRST resolution path, so every tool that
/// judges whether an import resolves has to ask it — otherwise a dependency that has been MIGRATED still
/// reads as unresolvable, and promoting a keystone component unblocks nothing that imports it.
///
/// Empty until a caller publishes the set ([`set_provided_specifiers`], via `open_component_store` or
/// `publish_provided_specifiers`), so a tool that never opens a store behaves exactly as before.
pub fn is_provided_specifier(spec: &str) -> bool {
    PROVIDED.read().ok().and_then(|g| g.as_ref().map(|s| s.contains(spec))).unwrap_or(false)
}

/// The registered platform specifiers, matched LITERALLY (exactly as the loader's `isAppModule` does).
pub(crate) fn platform_modules() -> &'static BTreeSet<String> {
    static M: std::sync::OnceLock<BTreeSet<String>> = std::sync::OnceLock::new();
    M.get_or_init(|| {
        serde_json::from_str::<Vec<String>>(platform_modules_json()).unwrap_or_default().into_iter().collect()
    })
}

/// The DEFAULT sound kit seed (`src-tauri/data/sounds/signal.json`) — the kit an UNPINNED project resolves
/// `@bsc/sounds/<id>` against, the twin of the frontend's `SoundKitSelection::default` arm. A project whose
/// blueprint PINS a sound kit resolves against that kit instead ([`HealthOptions::sound_kit_json`], #3412).
/// Embedded so the SOUNDS arm of the third import class (#3117) is recognized with no fs/network: a
/// reference matching a real cue/voice resolves (the preview vendors a GENERATED player module — a sound has
/// no JS source) and is NEVER flagged; a `@bsc/sounds/<missing>` is. The Rust twin of `soundNodeLookup` /
/// `libraryModules.ts`. LOCKSTEP: if the default sound kit ever changes, update this embed — a test pins
/// `signal` on both sides.
fn sound_kit_json() -> &'static str {
    static CELL: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    CELL.get_or_init(|| bsc_util::packaged::read_required("sounds/signal.json"))
}

/// The set of specifiers the preview can resolve — the import-map's keys. Cached; a malformed map yields
/// an empty set (so the check flags nothing — fail safe, never a false alarm).
fn resolvable_specifiers() -> &'static BTreeSet<String> {
    static KEYS: std::sync::OnceLock<BTreeSet<String>> = std::sync::OnceLock::new();
    KEYS.get_or_init(|| {
        serde_json::from_str::<Value>(preview_importmap_json())
            .ok()
            .as_ref()
            .and_then(Value::as_object)
            .map(|m| m.keys().cloned().collect())
            .unwrap_or_default()
    })
}

/// Is `spec` a BARE package specifier — not a relative (`.`/`..`), absolute (`/`), first-party (`@/`),
/// or an absolute URL? Only bare specifiers resolve through the preview import-map. Mirrors
/// `isBareSpecifier` (TS).
fn is_bare_specifier(spec: &str) -> bool {
    !spec.starts_with('.') && !spec.starts_with('/') && !spec.starts_with("@/") && !is_url_specifier(spec)
}

/// Is `spec` a `@bsc/<segment>/<name>` LIBRARY reference (#3116) — the reserved cross-graph import root
/// (A's `LIBRARY_ROOT`)? Bare-shaped, but it resolves against a library store (the algorithms graph), NOT
/// the preview import-map — the THIRD import-resolution class. Mirrors `isLibrarySpec` (nodeUrn.ts).
fn is_library_specifier(spec: &str) -> bool {
    spec.starts_with("@bsc/")
}

/// The resolvable `@bsc/algorithms/…` reference NAMES — every TYPESCRIPT algorithm impl carrying real
/// `code`, keyed by BOTH its bare name (`fibonacci`) and its exact id (`fibonacci.ts`), since a React
/// component resolves against the TS algorithm kit and accepts either form (#3116).
///
/// Sourced from [`bsc_graph::implementations`] — the SAME live, writer-reconciled catalog
/// `bsc graph impl list`/`impl get` serve (the packaged seed reconciled with whatever the librarian has
/// curated into the on-disk store, `~/.base-studio-code/knowledge/algorithms.json` / `BSC_GRAPH_STORE`).
/// This crate already depends on `bsc-graph` and reads the same catalog elsewhere for the identical
/// reason (`cmd_component_test`'s records-only boundary) — resolving straight against the PACKAGED seed
/// here instead was a second, independent read path that could only ever fall BEHIND the librarian's
/// curation, never ahead of it: a `bsc graph impl set` that adds, renames, or removes an algorithm
/// changes what `bsc graph impl get`/`impl list` answer immediately, and this detector's verdict on every
/// component's `reimplementation`/`unresolvable-import` findings should agree with that answer by
/// construction rather than by keeping two catalogs in sync by hand (bsc request #118 — a session with
/// no data-source visibility beyond the doctor report and `bsc graph` itself has no way to tell "the
/// detector's source is stale" apart from "the detector's source is simply wrong"; reading the one true
/// catalog removes the question). Cached per-process; a store the graph crate cannot read falls back to
/// ITS OWN packaged seed ([`bsc_graph::seed`]), never to empty — so a `@bsc/algorithms/…` reference is
/// never falsely flagged for a data problem in a sibling crate.
fn algo_library_names() -> &'static BTreeSet<String> {
    static N: std::sync::OnceLock<BTreeSet<String>> = std::sync::OnceLock::new();
    N.get_or_init(|| algo_library_names_from(&bsc_graph::implementations()))
}

/// Is `im` a TYPESCRIPT `algorithm`-role implementation carrying non-empty `code` — the ONLY class of
/// record `@bsc/algorithms/<name>` resolves against (a primitive descriptor has no code → not
/// importable, and the SAME bare name can legitimately belong to another language's kit too, e.g. a
/// `rust` `fibonacci` alongside the `typescript` one — `is_ts_algorithm_impl` is what keeps a lookup
/// from answering with the wrong language's record when names collide across kits).
fn is_ts_algorithm_impl(im: &Value) -> bool {
    let tech = im.get("tech").and_then(Value::as_str).unwrap_or_default();
    let role = im.get("role").and_then(Value::as_str).unwrap_or_default();
    let has_code = im.get("code").and_then(Value::as_str).is_some_and(|c| !c.trim().is_empty());
    tech == "typescript" && role == "algorithm" && has_code
}

/// Pure over a list of implementation records (testable without touching the store): the bare names +
/// exact ids of every typescript algorithm impl that ships non-empty `code` (a primitive descriptor has
/// no code → not importable, so it's excluded).
fn algo_library_names_from(implementations: &[Value]) -> BTreeSet<String> {
    let mut out = BTreeSet::new();
    for im in implementations {
        if !is_ts_algorithm_impl(im) {
            continue;
        }
        if let Some(id) = im.get("id").and_then(Value::as_str) {
            out.insert(id.to_string());
        }
        if let Some(name) = im.get("name").and_then(Value::as_str) {
            out.insert(name.to_string());
        }
    }
    out
}

/// The resolvable `@bsc/sounds/…` reference NAMES (#3117) — every CUE id (the playable product) + every
/// VOICE id (a playable patch) in the DEFAULT sound kit. A PRIMITIVE is a raw source descriptor with no
/// player (not importable/vendorable), so it's excluded — mirroring an algorithm primitive. Cached; a
/// malformed seed yields an empty set, so every `@bsc/sounds/…` is then flagged — fail safe, never a false
/// "resolves". Mirrors the resolvable set behind `soundNodeLookup` (crossGraphAdapter.ts).
fn sound_library_names() -> &'static BTreeSet<String> {
    static N: std::sync::OnceLock<BTreeSet<String>> = std::sync::OnceLock::new();
    N.get_or_init(|| sound_library_names_from(sound_kit_json()))
}

/// Pure over the kit seed JSON text (testable without the embed): the ids of every cue + voice in the kit
/// (a primitive has no player → excluded). Malformed JSON → empty set.
fn sound_library_names_from(json: &str) -> BTreeSet<String> {
    let Ok(v) = serde_json::from_str::<Value>(json) else {
        return BTreeSet::new();
    };
    let mut out = BTreeSet::new();
    for key in ["cues", "voices"] {
        for item in v.get(key).and_then(Value::as_array).into_iter().flatten() {
            if let Some(id) = item.get("id").and_then(Value::as_str).filter(|s| !s.is_empty()) {
                out.insert(id.to_string());
            }
        }
    }
    out
}

/// Does a `@bsc/<segment>/<name>` LIBRARY reference resolve to a real, runnable library node (#3116/#3117)?
/// The `algorithms` segment resolves against the TS algorithm kit (`<name>` = bare name OR exact id of an
/// impl carrying code); the `sounds` segment resolves against the default sound kit (`<name>` = a cue or
/// voice id — the preview vendors a generated player module). Any other segment (`ui`) has no vendor path
/// here → false. A non-`@bsc/` spec returns false (gated by `is_library_specifier`). Mirrors
/// `libraryModuleResolver(spec) !== null` (graphHealth.ts / libraryModules.ts).
fn resolves_library(spec: &str, sounds: &BTreeSet<String>) -> bool {
    let Some(rest) = spec.strip_prefix("@bsc/") else {
        return false;
    };
    let Some((segment, name)) = rest.split_once('/') else {
        return false;
    };
    if name.is_empty() {
        return false;
    }
    match segment {
        "algorithms" => algo_library_names().contains(name),
        "sounds" => sounds.contains(name),
        _ => false,
    }
}

/// The outcome of [`resolve_algorithm_library_node`] — three answers, not two, because a bare NAME
/// (unlike an id) is not unique: `bsc graph impl get` already learned this the hard way (#118's own
/// history — `index` alone names 20+ unrelated modules in the real store) and refuses to guess rather
/// than silently hand back an arbitrary one of several candidates. This verb makes the same call for
/// the same reason: a designer trusting a wrong silent pick would misjudge a `doctor` finding exactly
/// as often as they would correctly verify one.
#[derive(Debug, Clone, PartialEq)]
pub enum LibraryLookup {
    /// Exactly one typescript algorithm matches — the unambiguous case.
    Found(Value),
    /// The bare NAME matches several typescript algorithms; here are their (unique) ids, so the
    /// caller can retry with the exact one it means.
    Ambiguous(Vec<String>),
    /// Nothing matches.
    NotFound,
}

/// Resolve a `@bsc/algorithms/<name>` reference to its full implementation record (`bsc ui library get`,
/// bsc request #118) — the SAME `algorithms` arm [`resolves_library`] judges a `doctor` finding by, so a
/// verified name here is guaranteed to be the reason a `reimplementation`/`unresolvable-import` finding
/// fired (or didn't). Exists so the Design Studio's designer session — confined to `bsc ui`/`bsc
/// component`, never `bsc graph` (the librarian's surface) — can check a doctor finding's claim from
/// inside its own permitted shell instead of having no way to verify the report at all. Accepts a bare
/// name/id (`fibonacci`) OR the full spec (`@bsc/algorithms/fibonacci`); a bare name is always read as
/// the `algorithms` segment, matching the exact wording doctor's guidance prints ("import
/// `@bsc/algorithms/<name>`"). [`LibraryLookup::NotFound`] also covers a `@bsc/sounds/…` or non-library
/// spec, which this verb does not judge (sounds have no importable source to hand back; `doctor`'s own
/// reimplementation guardrail is algorithms-only for the same reason, see [`reimpl_targets`]).
///
/// An EXACT id always wins outright (ids are unique by construction, so there is nothing to
/// disambiguate); only a bare-NAME match can come back [`LibraryLookup::Ambiguous`].
pub fn resolve_algorithm_library_node(name_or_spec: &str) -> LibraryLookup {
    let Some(name) = (match name_or_spec.strip_prefix("@bsc/") {
        Some(rest) => rest.strip_prefix("algorithms/"),
        None => Some(name_or_spec),
    }) else {
        return LibraryLookup::NotFound;
    };
    if name.is_empty() {
        return LibraryLookup::NotFound;
    }
    // Re-apply the SAME `is_ts_algorithm_impl` filter `algo_library_names()` indexed under — the id or
    // bare name can collide with another language's kit (e.g. a `rust` `fibonacci` alongside the
    // `typescript` one), and only the typescript record is what `@bsc/algorithms/<name>` resolves to.
    let impls = bsc_graph::implementations();
    let ts_impls: Vec<&Value> = impls.iter().filter(|im| is_ts_algorithm_impl(im)).collect();
    if let Some(by_id) = ts_impls.iter().find(|im| im.get("id").and_then(Value::as_str) == Some(name)) {
        return LibraryLookup::Found((*by_id).clone());
    }
    let by_name: Vec<&&Value> =
        ts_impls.iter().filter(|im| im.get("name").and_then(Value::as_str) == Some(name)).collect();
    match by_name.as_slice() {
        [] => LibraryLookup::NotFound,
        [only] => LibraryLookup::Found((**only).clone()),
        many => {
            let mut ids: Vec<String> =
                many.iter().filter_map(|im| im.get("id").and_then(Value::as_str).map(str::to_string)).collect();
            ids.sort();
            LibraryLookup::Ambiguous(ids)
        }
    }
}

/// Is `s` a single valid JS identifier (so it COULD be a declared symbol)? Excludes empty, a leading
/// digit, and any non-`[A-Za-z0-9_$]` char — so a library name that can never appear as `function <name>`
/// (an extension-bearing algo id like `fibonacci.ts`) is not a reimplementation candidate. Mirrors
/// `isJsIdentifier` (libraryModules.ts).
fn is_js_identifier(s: &str) -> bool {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) if c.is_ascii_alphabetic() || c == '_' || c == '$' => {}
        _ => return false,
    }
    chars.all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '$')
}

/// The library nodes a component could RE-CODE instead of importing (#3118) — the "compose, don't
/// recreate" guardrail's candidate set. `(name, segment)`: `name` is the exact identifier a
/// reimplementation would DECLARE (an algorithm's bare name); `segment` is the `@bsc/<segment>` import
/// root (always `algorithms`). Drawn from the SAME `algo_library_names()` set the #3116 resolvable check
/// uses (so a listed name is one `@bsc/algorithms/<name>` resolves), then filtered to identifiers — a
/// non-identifier library name (the extension-bearing algo id `fibonacci.ts`) can never be a declared
/// symbol, so it's no reimplementation candidate. Cached. Mirrors `libraryReimplTargets` (libraryModules.ts).
///
/// ALGORITHMS-ONLY BY DESIGN. Sounds are DELIBERATELY excluded even though `@bsc/sounds/<id>` resolves +
/// vendors (#3117 — that import path stays fully intact, `sound_library_names()` still backs it): a sound
/// cue/voice id (`click`, `toggle`, `error`, `success`, `pop`, `tick`, …) collides with extremely common
/// handler/function names, so a component that legitimately declares `function click()` would be wrongly
/// flagged — and you don't "re-code" a cue as a function anyway. Value asymmetric, false-positive cost
/// high, so the reimplementation detector matches algorithms only.
fn reimpl_targets() -> &'static [(String, &'static str)] {
    static T: std::sync::OnceLock<Vec<(String, &'static str)>> = std::sync::OnceLock::new();
    T.get_or_init(|| {
        algo_library_names()
            .iter()
            .filter(|name| is_js_identifier(name))
            .map(|name| (name.clone(), "algorithms"))
            .collect()
    })
}

/// Is `spec` an ABSOLUTE URL — a `scheme:` prefix (the first `:` sits before any `/`, e.g. `https:`,
/// `http:`, `data:`)? Such a specifier resolves DIRECTLY in the preview iframe (the import-map's own
/// values ARE esm.sh URLs), so it needs no import-map entry and must never be flagged as an unresolvable
/// bare import (#2963). Mirrors `isUrlSpecifier` (TS). (Protocol-relative `//` is already excluded by the
/// leading-`/` check in `is_bare_specifier`.)
fn is_url_specifier(spec: &str) -> bool {
    match (spec.find(':'), spec.find('/')) {
        (Some(colon), Some(slash)) => colon < slash, // a scheme (`https:`) before any path `/`
        (Some(_), None) => true,                     // `data:…` with no slash
        _ => false,
    }
}

/// Every module specifier imported/exported-from in `source` — `import … from "X"`, `export … from "X"`,
/// `import "X"`, `import("X")`. A hand scanner (no regex dep): track the last identifier and, when a
/// string literal opens in normal code, capture it iff the last word was `from` or `import`. String +
/// line/block-comment state is tracked so a quote inside a comment/string is never captured. Deliberately
/// loose — over-inclusion is harmless (the caller flags only BARE unresolved specifiers). Rust twin of
/// `importSpecifiers` (TS).
pub(crate) fn import_specifiers(source: &str) -> Vec<String> {
    scan_imports(source).into_iter().map(|(spec, _)| spec).collect()
}

/// Every module specifier in `source` paired with whether its statement is SYNTACTICALLY type-only
/// (#4076) — the shape [`import_specifiers`] and [`erased_specifiers`] are both built from.
///
/// Type-only-ness is tracked by remembering where the current `import`/`export` statement began and
/// handing the clause between it and the `from` keyword to [`clause_is_type_only`].
fn scan_imports(source: &str) -> Vec<(String, bool)> {
    let chars: Vec<char> = source.chars().collect();
    let n = chars.len();
    let mut i = 0;
    let mut out = Vec::new();
    let mut last_word = String::new();
    // Where the clause of the statement in flight starts (just past its `import`/`export` keyword), and
    // where the word being scanned began — together they bracket the clause when `from` is reached.
    let mut clause_at: Option<usize> = None;
    let mut word_at = 0usize;
    let is_id = |c: char| c.is_alphanumeric() || c == '_' || c == '$';
    while i < n {
        let c = chars[i];
        // `;` ends the statement — a clause must never leak across one into the next.
        if c == ';' {
            clause_at = None;
        }
        if c == '/' && i + 1 < n && chars[i + 1] == '/' {
            i += 2;
            while i < n && chars[i] != '\n' {
                i += 1;
            }
        } else if c == '/' && i + 1 < n && chars[i + 1] == '*' {
            i += 2;
            while i < n && !(chars[i] == '*' && i + 1 < n && chars[i + 1] == '/') {
                i += 1;
            }
            i += 2;
        } else if c == '"' || c == '\'' || c == '`' {
            let quote = c;
            i += 1;
            let start = i;
            while i < n && chars[i] != quote {
                if chars[i] == '\\' {
                    i += 1;
                }
                i += 1;
            }
            if last_word == "from" || last_word == "import" {
                // The clause is what sits between the statement keyword and this `from` — for a bare
                // `import "x"` there is none, and a side-effect import is never type-only.
                let type_only = match clause_at {
                    Some(at) if last_word == "from" && at <= word_at => {
                        clause_is_type_only(&chars[at..word_at].iter().collect::<String>())
                    }
                    _ => false,
                };
                out.push((chars[start..i.min(n)].iter().collect(), type_only));
                clause_at = None;
            }
            i += 1; // past the closing quote (or EOF)
            last_word.clear(); // a string is not an identifier
        } else if is_id(c) {
            let mut w = String::new();
            word_at = i;
            while i < n && is_id(chars[i]) {
                w.push(chars[i]);
                i += 1;
            }
            // A new `import`/`export` opens a statement; its clause runs from just past the keyword.
            if w == "import" || w == "export" {
                clause_at = Some(i);
            }
            last_word = w;
        } else {
            // A non-identifier char between a keyword and a string decides whether the string is a REAL
            // import target. A pending `from`/`import` survives ONLY across whitespace (`from "x"`,
            // `import "x"`); `import` additionally survives a single `(` (dynamic `import("x")`). Anything
            // else — a `:` (`{ from: "x" }` graph-edge demo data), a `(` after `from` (`Array.from("x")`),
            // a `.`, `,`, `{`, … — means the keyword was an object key or member, NOT an import clause, so
            // clear it. Without this a graph component's demo edge `{ from: "node-id" }` was misread as
            // importing "node-id" and flagged unresolvable-import (#3687: false positives on
            // RelationshipGraphView / TeamsCanvas, filed 5×). Mirrors the regex twins `\bfrom\s+["']`.
            let survives = last_word.is_empty()
                || c.is_whitespace()
                || (c == '(' && last_word == "import");
            if !survives {
                last_word.clear();
            }
            i += 1;
        }
    }
    out
}

/// Is `clause` — the text between an `import`/`export` keyword and its `from` — erased entirely by the
/// TypeScript loader? Two spellings qualify: the statement-level keyword (`import type { P } from …`,
/// `import type * as N from …`) and a named clause where EVERY binding carries the inline modifier
/// (`import { type P, type Q } from …`).
///
/// SYNTACTIC on purpose. A binding that merely happens to name a type (`import { P } from …`) is NOT
/// erasable — esbuild has no type information and keeps the import — so a mixed clause
/// (`{ run, type P }`) keeps the statement and stays a real dependency. Verified against the very
/// esbuild-wasm build the preview runs, not inferred from the docs. Twin of `clauseIsTypeOnly` (TS).
fn clause_is_type_only(clause: &str) -> bool {
    let t = clause.trim();
    // `type` must be its own word — `import { typeGuard }` is a value binding, not a type modifier.
    let type_prefixed = |s: &str| {
        s.strip_prefix("type")
            .is_some_and(|rest| rest.starts_with(|c: char| c.is_whitespace() || c == '{' || c == '*'))
    };
    if type_prefixed(t) {
        return true;
    }
    let Some(inner) = t.strip_prefix('{').and_then(|s| s.strip_suffix('}')) else {
        return false;
    };
    let mut entries = inner.split(',').map(str::trim).filter(|s| !s.is_empty()).peekable();
    // An empty clause (`import {} from "x"`) imports nothing but is NOT a type-erasure — the statement
    // survives as a side-effect import, so it must keep counting.
    entries.peek().is_some() && entries.all(type_prefixed)
}

/// The specifiers `source` imports ONLY under an erased (type-only) statement (#4076). A specifier
/// imported both ways — `import type { P } from "./x"` beside `import { run } from "./x"` — is absent:
/// the value import survives the loader, so the module is still a real dependency.
///
/// This is what keeps `doctor` from accusing a component the preview builds happily: harvest stopped
/// counting erased imports against buildability, so every resolution check here must agree, or the two
/// drift in exactly the direction the [`is_preview_buildable`] note warns about (#3486).
fn erased_specifiers(source: &str) -> BTreeSet<String> {
    let mut erased: BTreeSet<String> = BTreeSet::new();
    let mut kept: BTreeSet<String> = BTreeSet::new();
    for (spec, type_only) in scan_imports(source) {
        if type_only {
            erased.insert(spec);
        } else {
            kept.insert(spec);
        }
    }
    erased.retain(|s| !kept.contains(s));
    erased
}

/// The set of packaged-artifact component `src` paths that ship a real implementation `source` — the
/// "buildable roster" the Design Studio preview (`componentPreviewFiles`, #2824) resolves a built-in
/// against. Cached: parsed once from the embedded artifact.
fn buildable_srcs() -> &'static BTreeSet<String> {
    static ROSTER: std::sync::OnceLock<BTreeSet<String>> = std::sync::OnceLock::new();
    ROSTER.get_or_init(|| artifact_buildable_srcs(packaged_kit_json()))
}

/// Collect the `src` of every component in a kit-artifact JSON that carries a non-empty `source` (a
/// real implementation file) — mirrors the `comp.src === c.src && c.source` artifact match in
/// `componentPreviewFiles`. Pure over the JSON text (testable without the embed); a malformed artifact
/// yields an empty roster, so the check just falls back to own-source / srcText — fail safe.
fn artifact_buildable_srcs(artifact_json: &str) -> BTreeSet<String> {
    let Ok(v) = serde_json::from_str::<Value>(artifact_json) else {
        return BTreeSet::new();
    };
    v.get("components")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|c| {
            let src = c.get("src").and_then(Value::as_str).filter(|s| !s.is_empty())?;
            let has_source = c.get("source").and_then(Value::as_str).is_some_and(|s| !s.is_empty());
            has_source.then(|| src.to_string())
        })
        .collect()
}

/// The runtime-closure module paths a kit artifact vendors (#2798/#2954) — the KEYS of its `runtime`
/// object (support modules like `shared/ui/typography/type.ts` the preview resolves a built-in's `@/`
/// or RELATIVE import against). Pure over the JSON text (testable without the embed); a malformed
/// artifact yields an empty set, so the internal-import check just flags nothing — fail safe.
fn artifact_runtime_paths(artifact_json: &str) -> BTreeSet<String> {
    serde_json::from_str::<Value>(artifact_json)
        .ok()
        .as_ref()
        .and_then(|v| v.get("runtime"))
        .and_then(Value::as_object)
        .map(|m| m.keys().cloned().collect())
        .unwrap_or_default()
}

/// The set an INTERNAL import can resolve to at preview time (#2954): every packaged built-in that ships
/// a real `source` (a `composes` sibling the preview vendors) PLUS every runtime-closure support module.
/// Cached from the embedded artifact. The per-kit check unions in this kit's own component `src` paths so
/// composing a sibling in the SAME kit (built-in or user) also resolves.
fn internal_targets() -> &'static BTreeSet<String> {
    static T: std::sync::OnceLock<BTreeSet<String>> = std::sync::OnceLock::new();
    T.get_or_init(|| {
        let mut s = artifact_buildable_srcs(packaged_kit_json());
        s.extend(artifact_runtime_paths(packaged_kit_json()));
        s
    })
}

/// Is `spec` an INTERNAL first-party import — a `@/…` alias or a RELATIVE (`./`, `../`) path — as opposed
/// to a bare npm specifier or an absolute path? These resolve against the kit's components + runtime
/// closure, not the preview import-map. Mirrors `isInternalSpecifier` (TS).
pub fn is_internal_specifier(spec: &str) -> bool {
    spec.starts_with("@/") || spec.starts_with("./") || spec.starts_with("../")
}

/// Resolve an INTERNAL import `spec` — imported FROM module `from_rel` (a `src/`-relative path) — to its
/// `src/`-relative module BASE (no extension), or `None` when it isn't internal. `@/x` → `x`; a relative
/// path is joined onto the importer's directory and `.`/`..` segments collapsed. Mirrors the closure
/// walker's resolver (reactUiKit.gen.test.ts) and `resolveInternalBase` (TS).
pub fn resolve_internal_base(spec: &str, from_rel: &str) -> Option<String> {
    let segs: Vec<&str> = if let Some(rest) = spec.strip_prefix("@/") {
        rest.split('/').collect()
    } else if spec.starts_with("./") || spec.starts_with("../") {
        let from_dir = from_rel.rsplit_once('/').map(|(d, _)| d).unwrap_or("");
        from_dir.split('/').chain(spec.split('/')).collect()
    } else {
        return None;
    };
    let mut out: Vec<&str> = Vec::new();
    for seg in segs {
        match seg {
            "" | "." => {}
            ".." => {
                out.pop();
            }
            _ => out.push(seg),
        }
    }
    Some(out.join("/"))
}

/// Does an INTERNAL import `spec` (from module `from_rel`) resolve to a component or runtime module the
/// preview provides (`targets`)? Tries TS module-resolution order (`.ts`/`.tsx`/`/index.ts`/`/index.tsx`)
/// over the importer-relative base. A NON-internal spec returns `true` — it isn't this check's concern
/// (the bare-specifier check owns npm resolution). Mirrors `resolvesInternal` (TS).
fn resolves_internal(spec: &str, from_rel: &str, targets: &BTreeSet<String>) -> bool {
    let Some(base) = resolve_internal_base(spec, from_rel) else {
        return true;
    };
    [".ts", ".tsx", "/index.ts", "/index.tsx"]
        .iter()
        .any(|ext| targets.contains(&format!("{base}{ext}")))
}

/// Whether a component has a buildable implementation the Design Studio preview can render — the Rust
/// mirror of `componentPreviewFiles(comp, artifact) !== null` (componentPreview.ts, #2824/#2828).
/// Buildable iff: its `src` is a packaged-artifact component shipping a real `source` (a BUILT-IN — its
/// code lives in the artifact even though the store strips it, #2794), OR it carries its own non-empty
/// `source`, OR its `srcText` is a real module rather than a usage snippet (`looks_buildable_module`).
fn is_buildable(node: &Node, buildable: &BTreeSet<String>, kit_targets: &BTreeSet<String>) -> bool {
    (!node.src.is_empty() && buildable.contains(&node.src))
        || !node.source.trim().is_empty()
        || is_preview_buildable(&node.src_text, &node.src, kit_targets)
}

/// Sibling-aware buildability of a preview MODULE (#3112) — the Rust mirror of `isPreviewBuildable`
/// (componentPreview.ts). Like `looks_buildable_module`, but an internal (`@/`, `./`) import is ALLOWED
/// when it resolves to a sibling in `kit_targets` (the kit's component `src` paths); an internal import
/// that resolves to NOTHING still fails, as do a `…` placeholder and a missing `export`.
///
/// This predicate answers "will the preview build it?", so its `…` test must be whatever the TS
/// `isPreviewBuildable` does — `doctor` must never be more permissive than the thing it reports on, or it
/// calls a component healthy that the preview then refuses (a MISSED no-implementation finding). Until
/// #3486 that pinned it to the PLAIN substring test, because the TS side still used one. #3486 ported the
/// context-aware scanner to TS, so both moved to [`has_code_elision`] together — and they must keep
/// moving together. The two are also wrong in opposite directions if they drift: plain-here/aware-there
/// makes `doctor` report a no-implementation the preview happily renders, which is the false accusation
/// #3486 was filed for.
/// The bar for `multi-component`. See the loop for why it is 4 and what the distribution looked like.
const MULTI_COMPONENT_MIN: usize = 4;

/// A backtick-quoted, comma-joined name list for a finding's prose, truncated past three. `ui-charts`
/// carries FIFTEEN foreign exports and a finding that spells all fifteen into one sentence is a wall,
/// not a report — the full list is one `bsc ui exports <id>` away, and `why` already names them.
fn naming(names: &[String]) -> String {
    let shown: Vec<String> = names.iter().take(3).map(|n| format!("`{n}`")).collect();
    match names.len() {
        0..=3 => shown.join(", "),
        n => format!("{} and {} more", shown.join(", "), n - 3),
    }
}

// ── skips-family-shell (#87) — the four gates that make "which sibling skips the shared shell?" a
// SIGNAL rather than a list. Every one of them was set against the real library (585 records): at these
// values the whole store yields FOUR findings, including the case the request was filed for — 20 of the
// 21 `settings/cards` components compose `Card` and `AchievementsCard` does not. Loosening the share to
// 0.7 turns the same sweep into ~20 rows of five-and-six-member "outlier" sets, which is the report that
// made a human read a dozen srcTexts by hand in the first place.

/// A family must have this many members before "most of them do X" means anything. A cheap pre-filter:
/// [`FAMILY_SHELL_SHARE`] is the binding constraint, and it makes SEVEN the smallest family that can
/// actually fire (6 of 7 = 0.857 clears; 5 of 6 = 0.833 does not).
const FAMILY_MIN: usize = 6;
/// The share of a family that must compose a shell before the rest read as outliers rather than as a
/// second convention. At 0.85, `settings/cards` (20/21) fires and a 70/30 split does not.
const FAMILY_SHELL_SHARE: f64 = 0.85;
/// A finding names the MINORITY. Past this many non-composers it is not an outlier set, it is a split —
/// and a split is a design question, not a mechanical finding.
const FAMILY_MAX_OUTLIERS: usize = 3;
/// The shell must be widely composed IN ITS KIT, so an accident of two siblings sharing a helper cannot
/// become "the family shell".
const FAMILY_SHELL_COMPOSERS_MIN: usize = 10;

/// The trailing PascalCase word of `name` — the second grouping convention (`AchievementsCard` → `Card`),
/// alongside the record's folder. `None` for a single-segment name, which conveniently also keeps a shell
/// out of the family named after it (`Card` itself is not a `*Card`).
fn name_suffix(name: &str) -> Option<String> {
    let mut segments: Vec<String> = Vec::new();
    for c in name.chars() {
        if c.is_ascii_uppercase() || segments.is_empty() {
            segments.push(String::new());
        }
        segments.last_mut().expect("just pushed").push(c);
    }
    (segments.len() >= 2).then(|| segments.pop()).flatten().filter(|s| s.len() > 1)
}

/// The TOP-LEVEL component definitions in `src` — `function Foo(` / `const Foo = (` / `const Foo = … =>`,
/// with or without `export`, at column 0.
///
/// Column 0 is the whole conservatism: a nested arrow inside a component is not a sibling component, and
/// a helper indented inside a function body is not one either. PascalCase is required because that is the
/// only signal in the source that separates a component from an ordinary function. It will miss exotic
/// forms (a `React.memo(` wrapper assigned to a lowercase name); missing one is the right way to be wrong
/// here, since a false positive pushes someone to split a file that never needed splitting.
pub(crate) fn top_level_components(src: &str) -> Vec<String> {
    let mut out = Vec::new();
    for line in src.lines() {
        if line.starts_with(char::is_whitespace) {
            continue; // not top level
        }
        let rest = line.strip_prefix("export ").unwrap_or(line);
        let name = if let Some(r) = rest.strip_prefix("function ") {
            r.split(|c: char| !c.is_alphanumeric() && c != '_').next().unwrap_or("")
        } else if let Some(r) = rest.strip_prefix("const ") {
            let n = r.split(|c: char| !c.is_alphanumeric() && c != '_').next().unwrap_or("");
            // A const is only a component when it is actually assigned a function.
            let tail = &r[n.len()..];
            if !(tail.contains("=> ") || tail.contains("=>") || tail.contains("= (") || tail.contains("=(")) {
                continue;
            }
            n
        } else {
            continue;
        };
        if name.starts_with(|c: char| c.is_ascii_uppercase()) && !out.iter().any(|x| x == name) {
            out.push(name.to_string());
        }
    }
    out
}

/// `src` as a char vector with every COMMENT and every string/template-literal BODY blanked to spaces —
/// the substrate the prop-signature parser below scans. Char-count- and newline-preserving, so column-0
/// detection still works and every later scan is plain bracket-depth counting: a `,` inside a JSDoc block,
/// a trailing `// note`, or a default value like `{ sep = "," }` can no longer split a parameter list.
///
/// Two guards keep prose from eating real code, because over-blanking is the one way this could invent a
/// finding rather than miss one: a `'`/`"` is only a delimiter when it does NOT immediately follow a value
/// end (so the apostrophe in a JSX `don't` or `</b>'s` is not a string opener — the same adjacency rule,
/// and the same reasoning, as the write-time scanner in `syntax.rs`), and a `'`/`"` literal that reaches a
/// newline before its closer is prose rather than a string (only a template may span lines).
///
/// It is a second, smaller scanner than [`crate::syntax::check_module_syntax`] on purpose: that one
/// answers "is this lexically well-formed?" and returns a verdict, this one needs the BLANKED text back.
fn blank_code(src: &str) -> Vec<char> {
    let b: Vec<char> = src.chars().collect();
    let n = b.len();
    let mut out = b.clone();
    let mut i = 0;
    let blank = |out: &mut Vec<char>, from: usize, to: usize| {
        for c in out.iter_mut().take(to.min(n)).skip(from) {
            if *c != '\n' {
                *c = ' ';
            }
        }
    };
    while i < n {
        match b[i] {
            '/' if i + 1 < n && b[i + 1] == '/' => {
                let start = i;
                while i < n && b[i] != '\n' {
                    i += 1;
                }
                blank(&mut out, start, i);
            }
            '/' if i + 1 < n && b[i + 1] == '*' => {
                let start = i;
                i += 2;
                while i + 1 < n && !(b[i] == '*' && b[i + 1] == '/') {
                    i += 1;
                }
                i = (i + 2).min(n);
                blank(&mut out, start, i);
            }
            q @ ('"' | '\'' | '`') => {
                // Adjacency is the whole rule (see `syntax.rs`): a quote pressed against a value end is
                // prose, not a literal — `don't`, `</b>'s`. A BACKTICK is exempt: pressed against a name it
                // is a tagged template (`` css`…` ``), which really is a literal. `=>'x'` stays a string.
                let value_end = |c: char| c.is_alphanumeric() || c == '_' || c == '$' || c == ')' || c == ']' || c == '}';
                let prose = i > 0
                    && q != '`'
                    && (value_end(b[i - 1]) || (b[i - 1] == '>' && !(i > 1 && b[i - 2] == '=')));
                if prose {
                    i += 1;
                    continue;
                }
                let mut j = i + 1;
                let mut closed = false;
                while j < n {
                    if b[j] == '\\' {
                        j += 2;
                        continue;
                    }
                    // A `'`/`"` literal cannot span lines; hitting one means this was prose, not a string.
                    if b[j] == '\n' && q != '`' {
                        break;
                    }
                    if b[j] == q {
                        closed = true;
                        break;
                    }
                    j += 1;
                }
                if !closed {
                    i += 1;
                    continue;
                }
                blank(&mut out, i + 1, j);
                i = j + 1;
            }
            _ => i += 1,
        }
    }
    out
}

/// The index of the bracket closing the one at `open_at` (`(`, `[` or `{`), counting only that pair —
/// safe on the comment/string-blanked source, where no literal can contribute a stray bracket.
fn matching_bracket(b: &[char], open_at: usize) -> Option<usize> {
    let open = b[open_at];
    let close = match open {
        '(' => ')',
        '[' => ']',
        '{' => '}',
        _ => return None,
    };
    let mut depth = 0usize;
    for (i, &c) in b.iter().enumerate().skip(open_at) {
        if c == open {
            depth += 1;
        } else if c == close {
            depth -= 1;
            if depth == 0 {
                return Some(i);
            }
        }
    }
    None
}

/// `b[from..]`'s first non-whitespace index (or `b.len()`).
fn skip_ws(b: &[char], from: usize) -> usize {
    let mut i = from;
    while i < b.len() && b[i].is_whitespace() {
        i += 1;
    }
    i
}

/// The JS identifier starting at `from` (empty when there isn't one) and the index just past it.
fn ident_at(b: &[char], from: usize) -> (String, usize) {
    let is_start = |c: char| c.is_alphabetic() || c == '_' || c == '$';
    let is_rest = |c: char| c.is_alphanumeric() || c == '_' || c == '$';
    if from >= b.len() || !is_start(b[from]) {
        return (String::new(), from);
    }
    let mut i = from;
    while i < b.len() && is_rest(b[i]) {
        i += 1;
    }
    (b[from..i].iter().collect(), i)
}

/// Split `b` on `sep` at bracket depth 0 (`(`/`[`/`{` counted). The input is already blanked, so a
/// separator inside a literal or comment cannot reach here.
fn split_top_level(b: &[char], sep: char) -> Vec<Vec<char>> {
    let mut out = Vec::new();
    let mut depth = 0i32;
    let mut start = 0usize;
    for (i, &c) in b.iter().enumerate() {
        match c {
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth -= 1,
            _ if c == sep && depth == 0 => {
                out.push(b[start..i].to_vec());
                start = i + 1;
            }
            _ => {}
        }
    }
    out.push(b[start..].to_vec());
    out
}

/// The PARAMETER-LIST text of the top-level declaration of component `name` in the blanked source `b` —
/// the chars between its outer parens. `None` when there is no unambiguous column-0 `function name(` /
/// `const name = (` / `const name = function (` form (with or without `export`/`export default`/`async`
/// and a generic parameter list), which is the conservative outcome: an exotic wrapper like
/// `const X = memo((…) => …)` is left alone rather than guessed at.
fn decl_params(b: &[char], name: &str) -> Option<Vec<char>> {
    let n = b.len();
    let mut line_start = 0usize;
    while line_start < n {
        let next_line = b[line_start..].iter().position(|&c| c == '\n').map_or(n, |k| line_start + k + 1);
        // Column 0 only: an indented declaration is a nested helper, not the module's component.
        if b[line_start].is_whitespace() {
            line_start = next_line;
            continue;
        }
        let mut i = line_start;
        for kw in ["export ", "default ", "async "] {
            let k: Vec<char> = kw.chars().collect();
            if b[i..].starts_with(&k) {
                i = skip_ws(b, i + k.len());
            }
        }
        let is_fn = b[i..].starts_with(&['f', 'u', 'n', 'c', 't', 'i', 'o', 'n', ' ']);
        let binding = ["const ", "let ", "var "].iter().find(|kw| {
            let k: Vec<char> = kw.chars().collect();
            b[i..].starts_with(&k)
        });
        let Some(kw_len) = (if is_fn { Some("function".len()) } else { binding.map(|kw| kw.len() - 1) })
        else {
            line_start = next_line;
            continue;
        };
        i = skip_ws(b, i + kw_len);
        // `function* Gen(` — a generator is still a declaration of that name.
        if i < n && b[i] == '*' {
            i = skip_ws(b, i + 1);
        }
        let (found, after) = ident_at(b, i);
        if found != name {
            line_start = next_line;
            continue;
        }
        return if is_fn { fn_params(b, after) } else { binding_params(b, after) };
    }
    None
}

/// The parameter list of a `function name…` whose name ends at `after` — skipping a generic list.
fn fn_params(b: &[char], after: usize) -> Option<Vec<char>> {
    let mut i = skip_ws(b, after);
    if i < b.len() && b[i] == '<' {
        let mut depth = 0i32;
        while i < b.len() {
            match b[i] {
                '<' => depth += 1,
                '>' => {
                    depth -= 1;
                    if depth == 0 {
                        i += 1;
                        break;
                    }
                }
                _ => {}
            }
            i += 1;
        }
        i = skip_ws(b, i);
    }
    if i >= b.len() || b[i] != '(' {
        return None;
    }
    let close = matching_bracket(b, i)?;
    Some(b[i + 1..close].to_vec())
}

/// The parameter list of a `const name … = <fn>` binding whose name ends at `after`. Handles an arrow
/// (`= (…) =>`, `= async (…) =>`) and a function expression (`= function (…)`); anything else — a
/// `memo(`/`forwardRef(` wrapper, a non-function value — yields `None`.
fn binding_params(b: &[char], after: usize) -> Option<Vec<char>> {
    // The assignment `=` — the first one that is not part of a compound operator or the `=>` of an arrow
    // inside the type annotation (`: Record<string, () => void> =` reaches the initializer past two).
    let mut i = after;
    let compound = |c: char| matches!(c, '=' | '!' | '<' | '>' | '+' | '-' | '*' | '/' | '%' | '&' | '|' | '^');
    while i < b.len() {
        if b[i] == ';' {
            return None; // a declaration with no initializer — not a component
        }
        if b[i] == '='
            && b.get(i + 1) != Some(&'=')
            && b.get(i + 1) != Some(&'>')
            && (i == 0 || !compound(b[i - 1]))
        {
            break;
        }
        i += 1;
    }
    if i >= b.len() {
        return None;
    }
    i = skip_ws(b, i + 1);
    for kw in ["async ", "function"] {
        let k: Vec<char> = kw.chars().collect();
        if b[i..].starts_with(&k) {
            i = skip_ws(b, i + k.len());
            // `function Name(` — step past an optional expression name.
            let (_, past) = ident_at(b, i);
            i = skip_ws(b, past);
        }
    }
    if i >= b.len() || b[i] != '(' {
        return None;
    }
    let close = matching_bracket(b, i)?;
    Some(b[i + 1..close].to_vec())
}

/// The body of the column-0 `interface <name> { … }` / `type <name> = { … }` declaration in `b` — the
/// chars inside its braces. `None` when the type is imported, generic, or an intersection/union rather
/// than a plain object literal: in every one of those cases the member list is NOT knowable from this
/// source alone, and a guess would be a fabricated finding.
fn type_block(b: &[char], name: &str) -> Option<Vec<char>> {
    let n = b.len();
    let mut line_start = 0usize;
    while line_start < n {
        let next_line = b[line_start..].iter().position(|&c| c == '\n').map_or(n, |k| line_start + k + 1);
        if b[line_start].is_whitespace() {
            line_start = next_line;
            continue;
        }
        let mut i = line_start;
        let k: Vec<char> = "export ".chars().collect();
        if b[i..].starts_with(&k) {
            i = skip_ws(b, i + k.len());
        }
        let is_iface = b[i..].starts_with(&['i', 'n', 't', 'e', 'r', 'f', 'a', 'c', 'e', ' ']);
        let is_alias = b[i..].starts_with(&['t', 'y', 'p', 'e', ' ']);
        if !is_iface && !is_alias {
            line_start = next_line;
            continue;
        }
        i = skip_ws(b, i + if is_iface { "interface".len() } else { "type".len() });
        let (found, after) = ident_at(b, i);
        if found != name {
            line_start = next_line;
            continue;
        }
        let mut j = skip_ws(b, after);
        if is_alias {
            if j >= n || b[j] != '=' {
                return None; // a generic alias (`type P<T> = …`) — not resolvable here
            }
            j = skip_ws(b, j + 1);
        }
        if j >= n || b[j] != '{' {
            return None; // `interface P extends Q {` / `type P = A & B` — the members aren't all here
        }
        let close = matching_bracket(b, j)?;
        return Some(b[j + 1..close].to_vec());
    }
    None
}

/// The top-level member names of an object-type body (`{ a: string; b?: () => void }` → `a`, `b`). An
/// index signature (`[k: string]: V`) contributes nothing. A segment only counts when its leading
/// identifier is followed by `?`, `:` or `(` — the shape of a real member — so the debris left by
/// splitting a one-line `Map<string, number>` on its comma is discarded rather than read as a prop.
fn object_member_names(b: &[char]) -> Vec<String> {
    let mut out = Vec::new();
    for raw in split_top_level(b, ';').into_iter().flat_map(|s| split_top_level(&s, ',')) {
        for seg in split_top_level(&raw, '\n') {
            let start = skip_ws(&seg, 0);
            if start >= seg.len() || seg[start] == '[' {
                continue;
            }
            let mut i = start;
            let readonly: Vec<char> = "readonly ".chars().collect();
            if seg[i..].starts_with(&readonly) {
                i = skip_ws(&seg, i + readonly.len());
            }
            let (name, after) = ident_at(&seg, i);
            if name.is_empty() {
                continue;
            }
            let next = skip_ws(&seg, after);
            if matches!(seg.get(next), Some('?') | Some(':') | Some('(') | Some('<')) && !out.contains(&name) {
                out.push(name);
            }
        }
    }
    out
}

/// The top-level bindings of a destructuring pattern body (`{ a, b: alias, c = 1, ...rest }` → `a`, `b`,
/// `c`), plus whether a REST element is present. The key is what the prop is called, so `b: alias` reports
/// `b`; a rest element means the component can consume props this list does not name, which is why the
/// caller stops reporting EXTRA metadata once it sees one.
fn destructured_names(b: &[char]) -> (Vec<String>, bool) {
    let mut out = Vec::new();
    let mut has_rest = false;
    for part in split_top_level(b, ',') {
        let start = skip_ws(&part, 0);
        if start >= part.len() {
            continue;
        }
        if part[start..].starts_with(&['.', '.', '.']) {
            has_rest = true;
            continue;
        }
        let (name, _) = ident_at(&part, start);
        if !name.is_empty() && !out.contains(&name) {
            out.push(name);
        }
    }
    (out, has_rest)
}

/// The prop names a component's own source DECLARES, and whether its signature ends in a rest element.
#[derive(Debug, PartialEq, Eq)]
struct SignatureProps {
    names: BTreeSet<String>,
    has_rest: bool,
}

/// The prop signature of component `name` as parsed from its own module source — the oracle the
/// `props-metadata-mismatch` check (#88) diffs the record's `props[]` against.
///
/// Reads the FIRST parameter of the component's top-level declaration, by both routes an author writes:
/// a destructuring pattern (`({ a, b }: Props)`) and a named parameter with a type (`(props: Props)` /
/// `(props: { a: string })`). When a destructured parameter ALSO carries a resolvable annotation the two
/// are UNIONED — a member the interface declares but the body never destructures is part of the declared
/// contract (its absence from the body is `unwired-prop`'s finding, not this one), so counting it here
/// keeps the two checks from contradicting each other.
///
/// `None` means "not knowable from this source" — no column-0 declaration of that name, an untyped
/// `props` parameter, or an annotation naming a type that is imported rather than declared here. Every
/// such case is SILENT: the whole value of this check is that it fires only on a mechanical mismatch, so
/// anything requiring a guess yields nothing at all. `Some` with an empty set is the confident opposite —
/// the component genuinely takes no props.
fn signature_props(src: &str, name: &str) -> Option<SignatureProps> {
    let b = blank_code(src);
    let params = decl_params(&b, name)?;
    let first = split_top_level(&params, ',').into_iter().next().unwrap_or_default();
    let start = skip_ws(&first, 0);
    if start >= first.len() {
        // `function Foo()` — no parameter at all, so the component takes no props. Confident, not unknown.
        return Some(SignatureProps { names: BTreeSet::new(), has_rest: false });
    }
    let mut names: BTreeSet<String> = BTreeSet::new();
    let mut has_rest = false;
    let annotation_at = if first[start] == '{' {
        let close = matching_bracket(&first, start)?;
        let (destructured, rest) = destructured_names(&first[start + 1..close]);
        names.extend(destructured);
        has_rest = rest;
        skip_ws(&first, close + 1)
    } else {
        // A named parameter (`props`) — everything it declares comes from its annotation.
        let (ident, after) = ident_at(&first, start);
        if ident.is_empty() {
            return None;
        }
        skip_ws(&first, after)
    };
    let typed = first.get(annotation_at) == Some(&':');
    if !typed {
        // An untyped `props` parameter tells us nothing; an untyped destructure told us everything.
        return if names.is_empty() && !has_rest { None } else { Some(SignatureProps { names, has_rest }) };
    }
    let ty_start = skip_ws(&first, annotation_at + 1);
    let members = if first.get(ty_start) == Some(&'{') {
        let close = matching_bracket(&first, ty_start)?;
        Some(object_member_names(&first[ty_start + 1..close]))
    } else {
        let (ty_name, after) = ident_at(&first, ty_start);
        // A generic or qualified type (`Props<T>`, `NS.Props`) is not resolvable by name lookup alone.
        let plain = !ty_name.is_empty() && skip_ws(&first, after) >= first.len();
        plain.then(|| type_block(&b, &ty_name).map(|blk| object_member_names(&blk))).flatten()
    };
    match members {
        Some(m) => names.extend(m),
        // The annotation named a type this module doesn't declare (an imported contract). A destructure
        // still stands on its own; a bare `props: Imported` leaves us with nothing to say.
        None if names.is_empty() && !has_rest => return None,
        None => {}
    }
    Some(SignatureProps { names, has_rest })
}

/// Every `import { a, b, … } from "spec"` statement in `source`, paired as (spec, bound names) — the
/// evidence [`reimplemented-component`] (#130) uses to tell a genuine local re-declaration from a node
/// that legitimately AGGREGATES sibling declarations under its own registered `provides`: if some OTHER
/// component in the graph demonstrably imports the colliding name from THIS node's own `provides`, this
/// node is the graph's VERIFIED provider of that name, not a stub competing with the real thing —
/// exactly backwards from what the finding accuses it of.
///
/// `Foo as Bar` binds the EXPORTED name (`Foo`), not the local alias, since it's the exported identifier
/// a collision is keyed on. A default or `* as X` namespace import contributes nothing — only a named
/// (braced) clause can unambiguously name a single symbol.
///
/// Same statement-detection rule as [`imported_identifiers`] (line-initial `import `, then the first
/// ` from `) — deliberately loose in the same direction: a missed pairing only costs a name-only finding
/// staying as conservative as it always was, never a false suppression from thin air.
fn named_import_clauses(source: &str) -> Vec<(String, BTreeSet<String>)> {
    let mut out = Vec::new();
    for line_start in source.match_indices("import ").map(|(i, _)| i) {
        let before = source[..line_start].chars().rev().take_while(|c| !matches!(c, '\n')).all(char::is_whitespace);
        if !before {
            continue;
        }
        let rest = &source[line_start..];
        let Some(from_at) = rest.find(" from ") else { continue };
        let header = &rest[..from_at];
        let (Some(open), Some(close)) = (header.find('{'), header.rfind('}')) else {
            continue; // no named clause — a default/namespace-only import names nothing to compare
        };
        let names: BTreeSet<String> = header[open + 1..close]
            .split(',')
            .filter_map(|entry| {
                let entry = entry.trim().strip_prefix("type ").unwrap_or(entry.trim()).trim();
                entry.split_whitespace().next().map(str::to_string)
            })
            .filter(|s| !s.is_empty())
            .collect();
        if names.is_empty() {
            continue;
        }
        let after_from = &rest[from_at + " from ".len()..];
        let Some(quote) = after_from.chars().next().filter(|c| matches!(c, '"' | '\'')) else { continue };
        let Some(end) = after_from[1..].find(quote) else { continue };
        out.push((after_from[1..1 + end].to_string(), names));
    }
    out
}

/// The minimum prop-name Jaccard overlap for a name collision to read as the SAME component rather than
/// two different components that happen to share a generic English word (#130). Mirrors `near-duplicate`'s
/// own contract bar (`DUPLICATE_CONTRACT`, similarity.rs) at the same value: below it, two colliding
/// declarations disagree on their contract more than they agree, which reads as "different component,
/// coincidental name" rather than "the same thing, redeclared".
const REIMPL_CONTRACT_MIN: f64 = 0.5;

/// Prop-name Jaccard between the LOCAL redeclaration of `name` inside `src` and `target_props` (the
/// colliding node's own recorded signature) — the second dimension [`reimplemented-component`] (#130)
/// needs so a bare identifier match on a generic word (`Avatar`, `Field`, `Card`, …) doesn't fire just
/// because two UNRELATED components happen to share it: the chart/bot-glyph `Avatar({login,size,bot})`
/// and the GitHub-login `Avatar({login,size,palette,bordered,ml,fontScale})` share a name and little else
/// (2/7 ≈ 0.29, well under the bar).
///
/// `None` when either side carries no confident signal — an unparseable local declaration, a confidently
/// no-prop local stub, or a target with no recorded `props` (most composite/aggregate records don't carry
/// prop metadata at all) — so the caller falls back to the old name-only behavior rather than guess.
/// Conservative in the SAME direction as the rest of this check: a missing signal must never manufacture
/// a suppression, only a genuinely LOW-overlap comparison does.
fn contract_overlap(src: &str, name: &str, target_props: &[(String, String)]) -> Option<f64> {
    if target_props.is_empty() {
        return None;
    }
    let local = signature_props(src, name)?;
    if local.names.is_empty() {
        return None;
    }
    let target_names: BTreeSet<&str> = target_props.iter().map(|(n, _)| n.as_str()).collect();
    let local_names: BTreeSet<&str> = local.names.iter().map(String::as_str).collect();
    let inter = local_names.intersection(&target_names).count() as f64;
    let union = local_names.union(&target_names).count() as f64;
    Some(if union == 0.0 { 0.0 } else { inter / union })
}

fn is_preview_buildable(src_text: &str, from_rel: &str, kit_targets: &BTreeSet<String>) -> bool {
    let s = src_text.trim();
    if s.is_empty() || !contains_word(s, "export") || has_code_elision(s) {
        return false;
    }
    let erased = erased_specifiers(s);
    import_specifiers(s)
        .iter()
        // A REGISTERED platform module (#3897) resolves literally, like the loader's `isAppModule` — it is
        // neither an artifact path nor a sibling `src`, so without this it read as unbuildable.
        .all(|spec| {
            !is_internal_specifier(spec)
                // Erased before resolution (#4076) — the loader never asks for it.
                || erased.contains(spec)
                || platform_modules().contains(spec)
                // bsc request #125: an ALGORITHMS-graph (or component-store) record `provides` this
                // specifier — the loader's FIRST resolution path (#3660), already honoured by the write-time
                // gate (`unresolved_specifiers`, below) via `is_provided_specifier`. This read-time check had
                // drifted behind it (and behind the TS twin's `makeGraphProvidesResolver`, #83): a hook lifted
                // into the algorithms graph (`useCiWatcher`, `useFleetGithub`, `useFleetLive`,
                // `mcpCatalogView`, `useMcpInstallStatus`, …) resolves at runtime but was judged unbuildable
                // here, condemning a component the app mounts fine as `no-implementation`.
                || is_provided_specifier(spec)
                || resolves_internal(spec, from_rel, kit_targets)
        })
}

/// Every reason the preview CANNOT build `node` — the reason-first face of [`is_preview_buildable`],
/// in the same order that predicate tests them.
///
/// A `no-implementation` finding used to state only THAT a component was unbuildable, so the reader had
/// to re-derive the cause by hand — the gap `bsc request` #4 was filed for. The causes are already
/// computed to decide the predicate; this names them so `bsc ui doctor --json` is diagnosable on its own.
/// Mirrors `bsc_ui::harvest`'s `buildability`, which reports the same three defects at harvest time.
///
/// Returns EMPTY only when nothing is wrong, so a caller can treat non-empty as "unbuildable, and here
/// is why" — a node with no source of its own is a stated reason, not an empty list.
fn no_implementation_reasons(node: &Node, kit_targets: &BTreeSet<String>) -> Vec<String> {
    let s = node.src_text.trim();
    if s.is_empty() {
        return vec!["it carries no module source of its own (neither `source` nor `srcText`)".to_string()];
    }
    let mut why = Vec::new();
    if !contains_word(s, "export") {
        why.push("its source declares no `export`".to_string());
    }
    if has_code_elision(s) {
        why.push("its source contains a code-elision marker (`…`) — a sketch, not code".to_string());
    }
    let erased = erased_specifiers(s);
    let unresolved: BTreeSet<String> = import_specifiers(s)
        .into_iter()
        .filter(|spec| {
            is_internal_specifier(spec)
                // Erased by the loader before it resolves anything (#4076) — never a missing dependency.
                && !erased.contains(spec)
                && !platform_modules().contains(spec)
                // bsc request #125 — see the matching arm in `is_preview_buildable`.
                && !is_provided_specifier(spec)
                && !resolves_internal(spec, &node.src, kit_targets)
        })
        .collect();
    if !unresolved.is_empty() {
        why.push(format!(
            "it imports {} — resolving to no kit component, runtime file or registered platform module",
            unresolved.iter().map(|s| format!("`{s}`")).collect::<Vec<_>>().join(", ")
        ));
    }
    why
}

/// The component's OWN module source — its `source`, else a `srcText` that is a real module — or `None`
/// when neither (a built-in whose store `source` is stripped, #2794, or a usage-snippet spec). `kit_targets`
/// (the kit's component `src` paths) makes a `srcText` that imports SIBLINGS count as a real (composing)
/// module (#3112), so the health checks scan exactly the source the preview builds. Mirrors `ownModuleSource`
/// (graphHealth.ts).
fn own_module_source<'a>(node: &'a Node, kit_targets: &BTreeSet<String>) -> Option<&'a str> {
    if !node.source.trim().is_empty() {
        return Some(node.source.as_str());
    }
    if is_preview_buildable(&node.src_text, &node.src, kit_targets) {
        return Some(node.src_text.as_str());
    }
    None
}

/// Rust port of `looksBuildableModule` (componentPreview.ts, #2828): does `src_text` look like a
/// self-contained, buildable component MODULE rather than the usual usage snippet? Conservative — it
/// must declare an `export`, contain no `…` code-elision marker, and use no `@/` first-party import
/// (which has no dependency closure to resolve against IN THE PREVIEW SANDBOX). Crate-visible so the
/// write-time syntax gate (#2928) reuses the SAME "is this a module?" test to decide whether to
/// syntax-check a `srcText`.
///
/// This is the PREVIEW's oracle and must stay in lockstep with the TS `looksBuildableModule`. For "will
/// the runtime LOADER mount this?" — a different and far more permissive question — use
/// [`renders_at_runtime`] (#3849).
///
/// It is now the boolean face of [`module_defects`] — the reasons ARE the predicate, so the write-time
/// gate can NAME why it treated a `srcText` as a spec instead of silently skipping it (#3470).
pub(crate) fn looks_buildable_module(src_text: &str) -> bool {
    !src_text.trim().is_empty() && module_defects(src_text).is_empty()
}

/// Every reason `src_text` is NOT a self-contained, buildable component module — empty when it IS one
/// (so `defects.is_empty()` is exactly [`looks_buildable_module`] for a non-blank source). Reason-first
/// rather than bool-first because of #3470: `bsc ui set` used to SKIP its syntax gate whenever this
/// predicate was false, so the source least like a module — one that keeps its unresolved `@/…` imports —
/// got the LEAST validation and stored with no complaint at all, surfacing only much later as a
/// `no-implementation` finding in `bsc ui doctor`. Storing a spec-only record stays legitimate; it just
/// has to be a STATED outcome, which needs the reasons this returns. Mirrors `bsc_ui::harvest`'s
/// `buildability`, which reports the same three defects for a harvested candidate.
///
/// A blank source is NOT a defect here (it returns no reasons): "this record carries no `srcText`" is a
/// different, legitimate state, and every caller checks it first.
pub(crate) fn module_defects(src_text: &str) -> Vec<String> {
    let s = src_text.trim();
    let mut why = Vec::new();
    if s.is_empty() {
        return why;
    }
    if !contains_word(s, "export") {
        why.push("no `export` — the preview has nothing to import and mount".to_string());
    }
    if has_code_elision(s) {
        why.push("a `…` elision marker stands in for omitted code — a sketch, not compilable code".to_string());
    }
    // The PREVIEW's oracle, deliberately: any `@/` import is unresolvable in the preview sandbox, which
    // is an isolated iframe resolving bare specifiers from esm.sh and shipping no first-party closure.
    // This mirrors the TS `looksBuildableModule` exactly, and `looks_buildable_module_mirrors_the_ts_twin`
    // holds the two in lockstep. Do NOT relax it here: the runtime loader's far more permissive
    // resolution is a DIFFERENT question, answered by [`runtime_module_defects`].
    if s.contains("\"@/") || s.contains("'@/") {
        let named = unresolved_specifiers(s);
        let all: Vec<String> = if named.is_empty() { internal_specifiers(s) } else { named };
        let list = if all.is_empty() {
            String::new()
        } else {
            format!(" ({})", all.iter().map(|m| format!("`{m}`")).collect::<Vec<_>>().join(", "))
        };
        why.push(format!(
            "unresolved first-party `@/…` import(s){list} — there is no dependency closure to resolve them against"
        ));
    }
    why
}

/// Every reason `src_text` would not RENDER — the runtime loader's oracle, not the preview sandbox's.
///
/// #3849. [`module_defects`] answers "would the preview sandbox build this?", and for a `role: page`
/// that is the wrong question asked of the wrong runtime. A page is mounted by the LOADER, which
/// resolves a registered platform module (`isAppModule`) and an `@/components/<id>` sibling perfectly
/// well — so the preview oracle condemns every graph page over imports that work. Measured live:
/// restoring `fleetpage` from the recovery archive warned about sixteen specifiers, every one of which
/// the runtime resolves.
///
/// A false "unresolved import" is not merely noise — it is the pressure that makes the next author
/// hand-stub the import to silence it, which is the corruption `reimplemented-component` exists to catch
/// (#3892/#3895). Two band-aids had already grown over the mismatch: `bsc ui set` skips the advisory
/// entirely for any record carrying `provides` (#43), and `is_preview_buildable` grew its own
/// registry-aware path (#3897). This is the third caller getting the right oracle rather than a fourth
/// exception.
pub(crate) fn runtime_module_defects(src_text: &str) -> Vec<String> {
    let s = src_text.trim();
    let mut why = Vec::new();
    if s.is_empty() {
        return why;
    }
    if !contains_word(s, "export") {
        why.push("no `export` — the loader has nothing to mount".to_string());
    }
    if has_code_elision(s) {
        why.push("a `…` elision marker stands in for omitted code — a sketch, not compilable code".to_string());
    }
    let unresolved = unresolved_specifiers(s);
    if !unresolved.is_empty() {
        let list = unresolved.iter().map(|m| format!("`{m}`")).collect::<Vec<_>>().join(", ");
        why.push(format!(
            "unresolved first-party import(s) ({list}) — resolving to no registered platform module and no `@/components/<id>` sibling"
        ));
    }
    why
}

/// Is `src_text` a module the RUNTIME LOADER can mount? The boolean face of [`runtime_module_defects`].
pub(crate) fn renders_at_runtime(src_text: &str) -> bool {
    !src_text.trim().is_empty() && runtime_module_defects(src_text).is_empty()
}

/// The distinct `@/…` specifiers `src_text` imports, in source order and de-duplicated — used only to
/// NAME them in a [`module_defects`] reason when none of them is individually unresolvable (the preview
/// defect is decided by the coarser substring test, so the message must not contradict it).
fn internal_specifiers(src_text: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for spec in import_specifiers(src_text) {
        if spec.starts_with("@/") && !out.iter().any(|s| s == &spec) {
            out.push(spec);
        }
    }
    out
}

/// The `@/…` specifiers a bare `srcText` carries that would NOT resolve at runtime — the write-time
/// counterpart to [`no_implementation_reasons`]'s check, minus the parts that need a kit.
///
/// FOUR ways a first-party specifier resolves, exactly as the loader does it:
///   * a PROVIDING RECORD — some record's `provides` equals the specifier, which `resolveGraphSource`
///     matches FIRST, ahead of the registry (#3660, graph-first). This one was missing, and its absence
///     made the gate STRICTER than the runtime rather than looser: after the code-fallback cut removed
///     the registrations a record's `provides` had replaced, three page records the app renders fine
///     could no longer be WRITTEN. A gate that refuses what the loader mounts is as wrong as one that
///     accepts what it cannot.
///   * a REGISTERED PLATFORM MODULE — `isAppModule`, matched literally against the generated manifest;
///   * a SIBLING RECORD — `@/components/<id>`, which `resolveGraphSource` vendors from the store by id;
///   * ERASED before resolution (`import type`), which the loader never asks for at all (#4076).
///
/// A kit-relative `src`-path resolution (`resolves_internal`) is deliberately NOT attempted: at write
/// time there is no kit context, and guessing one would put this check back in the business of being
/// more permissive than the runtime, which is what #4188 removed from the frontend guard.
pub(crate) fn unresolved_specifiers(src_text: &str) -> Vec<String> {
    let erased = erased_specifiers(src_text);
    let provided = provided_specifiers();
    let mut out: Vec<String> = Vec::new();
    for spec in import_specifiers(src_text) {
        if !is_internal_specifier(&spec)
            || erased.contains(&spec)
            || provided.contains(&spec)
            || platform_modules().contains(&spec)
            || spec.starts_with("@/components/")
        {
            continue;
        }
        if !out.iter().any(|s| s == &spec) {
            out.push(spec);
        }
    }
    out
}

/// The specifiers `source` imports that SURVIVE the TypeScript loader — every specifier except the
/// type-only ones (#4076) — in source order, deduped. The shape a CLOSURE walk needs
/// ([`crate::closure`]): a type-only import is erased before resolution, so materializing a record for
/// it would be writing a file nothing ever asks for.
pub(crate) fn live_specifiers(source: &str) -> Vec<String> {
    let erased = erased_specifiers(source);
    let mut seen: BTreeSet<String> = BTreeSet::new();
    import_specifiers(source)
        .into_iter()
        .filter(|s| !erased.contains(s))
        .filter(|s| seen.insert(s.clone()))
        .collect()
}

/// Whether the code-elision marker at this position reads as PROSE rather than a stand-in for omitted
/// code (#125). `before` is every character preceding the marker. Beyond the original "directly after a
/// word character" case (#3897), two more shapes are prose:
///   * preceded (after skipping whitespace) by ordinary running-text punctuation (`/`, `;`, `,`, `.`,
///     `:`, `)`, `]`, `%`) — an HTML-entity-heavy path example ending `&lt;project&gt;/…` reads as `/`
///     immediately before the marker, not a word character (designer request #125, `WorkspaceCard`);
///   * preceded by the `>` that CLOSES a sibling JSX element — `</Text>\n…` (a message continuing after
///     an interpolated element, designer request #125, `ConnectGithubCard`) or a self-closing `<Icon />…`.
///     An `>` that OPENS an element (`<Card>…`) is deliberately excluded: that shape is the ellipsis
///     standing in as the element's ONLY content, which is the actual sketch case #3897 established —
///     see `looks_buildable_module_mirrors_the_ts_twin`'s `<Card>…</Card>` fixture.
fn ellipsis_reads_as_prose(before: &[char]) -> bool {
    let mut j = before.len();
    while j > 0 && before[j - 1].is_whitespace() {
        j -= 1;
    }
    let Some(&c) = before.get(j.wrapping_sub(1)) else {
        return false;
    };
    if c.is_alphanumeric() || matches!(c, '/' | ';' | ',' | '.' | ':' | ')' | ']' | '%') {
        return true;
    }
    if c != '>' {
        return false;
    }
    // Walk back to the tag's `<` — bounded, since a tag is short and this must never scan the whole file.
    let start = j.saturating_sub(500);
    let Some(rel) = before[start..j - 1].iter().rposition(|&ch| ch == '<') else {
        return false;
    };
    let lt = start + rel;
    let closing = before.get(lt + 1) == Some(&'/');
    let self_closing = j >= 2 && before[j - 2] == '/';
    closing || self_closing
}

/// Does `…` appear in real CODE — not inside a string/template literal or a comment? Only then is it an
/// elision marker standing in for omitted code. The plain substring test this replaced (#3470) is a
/// MEASURED false-positive generator, not a hypothetical one: `…` is ordinary UI copy
/// (`placeholder="Select…"`) and ordinary doc-comment prose, and over this repo's own `src/shared/ui` it
/// condemned 13 perfectly good components as sketches. Condemning a real component over the ellipsis in
/// its placeholder text is a false accusation someone then has to overrule, so both contexts are skipped.
///
/// Lives here, in the crate that owns the buildability predicates, so `bsc_ui::harvest` (which found the
/// false positives) and the write-time gate share ONE scanner rather than drifting copies.
pub fn has_code_elision(src: &str) -> bool {
    let b: Vec<char> = src.chars().collect();
    let (mut i, n) = (0usize, b.len());
    while i < n {
        match b[i] {
            '/' if i + 1 < n && b[i + 1] == '/' => {
                while i < n && b[i] != '\n' {
                    i += 1;
                }
            }
            '/' if i + 1 < n && b[i + 1] == '*' => {
                i += 2;
                while i + 1 < n && !(b[i] == '*' && b[i + 1] == '/') {
                    i += 1;
                }
                i = (i + 2).min(n);
            }
            quote @ ('"' | '\'' | '`') => {
                i += 1;
                while i < n && b[i] != quote {
                    // A backslash escapes the next char, so an escaped quote doesn't end the literal.
                    i += if b[i] == '\\' { 2 } else { 1 };
                }
                i += 1;
            }
            // An ellipsis in PROSE position, not code (#3897/#125) — see `ellipsis_reads_as_prose`.
            '…' if ellipsis_reads_as_prose(&b[..i]) => {
                i += 1;
            }
            '…' => return true,
            _ => i += 1,
        }
    }
    false
}

/// Whether `needle` appears in `haystack` as a whole word (the JS `\bword\b` the TS twin uses) —
/// bounded by a non-word char (`[^A-Za-z0-9_]`) or the string edge on each side.
fn contains_word(haystack: &str, needle: &str) -> bool {
    let is_word = |c: char| c.is_ascii_alphanumeric() || c == '_';
    let mut from = 0;
    while let Some(rel) = haystack[from..].find(needle) {
        let at = from + rel;
        let before_ok = haystack[..at].chars().next_back().is_none_or(|c| !is_word(c));
        let after = at + needle.len();
        let after_ok = haystack[after..].chars().next().is_none_or(|c| !is_word(c));
        if before_ok && after_ok {
            return true;
        }
        from = at + 1;
    }
    false
}

/// Whether `source` DECLARES the symbol `name` — a `function`/`const`/`let`/`var`/`class` binding of it
/// (`export function Foo` / `const Foo =` / …), not a mere reference. Distinguishes a module that DEFINES
/// the component from a bare usage snippet that only calls it. Mirrors `declaresSymbol` (graphHealth.ts).
/// The identifiers an `import` statement BINDS in `source` — the names inside `{ … }`, a default binding,
/// and a `* as X` namespace. Used by `reimplemented-component` (#3892) to skip a node that legitimately
/// imports the name it also mentions, so only a genuine local RE-DECLARATION is flagged.
///
/// Deliberately loose: it scans the header text of each `import … from` and takes every identifier that is
/// not a keyword. Over-collecting only ever SUPPRESSES a finding, which is the safe direction for a check
/// whose false positives are worse than its misses.
fn imported_identifiers(source: &str) -> BTreeSet<String> {
    let mut out = BTreeSet::new();
    for line_start in source.match_indices("import ").map(|(i, _)| i) {
        // Only a real statement start (line-initial, bar whitespace) — not `.import` or a string body.
        let before = source[..line_start].chars().rev().take_while(|c| !matches!(c, '\n')).all(char::is_whitespace);
        if !before {
            continue;
        }
        let rest = &source[line_start..];
        let Some(from_at) = rest.find(" from ") else { continue };
        let header = &rest[..from_at];
        let mut ident = String::new();
        for c in header.chars() {
            if c.is_alphanumeric() || c == '_' || c == '$' {
                ident.push(c);
            } else {
                if !ident.is_empty() && !matches!(ident.as_str(), "import" | "type" | "as") {
                    out.insert(std::mem::take(&mut ident));
                } else {
                    ident.clear();
                }
            }
        }
        if !ident.is_empty() && !matches!(ident.as_str(), "import" | "type" | "as") {
            out.insert(ident);
        }
    }
    out
}

/// Every symbol the source DECLARES — the INVERSE of [`declares_symbol`], derived in ONE pass.
///
/// Both `reimplementation` and `reimplemented-component` ask "does this source declare X?" for a large
/// candidate set: every library ALGORITHM (~670) and every component NODE (~409) respectively, for each of
/// ~409 components. That is ~440k whole-source scans, and MEASURED it was 2.19s + 1.26s of `bsc ui
/// doctor`'s ~5s CPU — far and away its cost. Deriving the declared set once per component answers every
/// candidate with a hash lookup.
///
/// EXACTLY EQUIVALENT to `declares_symbol`, including its quirks: the keyword needs no word boundary
/// BEFORE it (so `myfunction foo` declares `foo` to both), and a keyword followed by anything that is not
/// an identifier start yields no name (`const {a}` declares nothing, `const  x` declares nothing because
/// the literal `"const x"` is absent). Pinned by
/// `declared_symbols_agrees_with_declares_symbol_case_for_case`.
///
/// ONE INPUT DIFFERS, and it is not a real candidate: the EMPTY name. `declares_symbol(src, "")` searches
/// for the bare keyword and so reports almost every source as declaring it, while a derived set holds no
/// empty entry. Algorithm targets pass `is_js_identifier`, and a node whose name is empty firing this
/// guardrail against every source containing `const ` would be a bug rather than a finding — so the
/// caller below skips it explicitly instead of the set imitating the quirk.
fn declared_symbols(source: &str) -> std::collections::HashSet<&str> {
    let mut out = std::collections::HashSet::new();
    for kw in ["function ", "const ", "let ", "var ", "class "] {
        let mut from = 0;
        while let Some(rel) = source[from..].find(kw) {
            let at = from + rel + kw.len();
            let end = source[at..]
                .find(|c: char| !(c.is_ascii_alphanumeric() || c == '_'))
                .map_or(source.len(), |o| at + o);
            if end > at {
                out.insert(&source[at..end]);
            }
            from = from + rel + 1;
        }
    }
    out
}

fn declares_symbol(source: &str, name: &str) -> bool {
    ["function ", "const ", "let ", "var ", "class "].iter().any(|kw| {
        let needle = format!("{kw}{name}");
        let mut from = 0;
        while let Some(rel) = source[from..].find(&needle) {
            let at = from + rel;
            let after = at + needle.len();
            let after_ok =
                source[after..].chars().next().is_none_or(|c| !(c.is_ascii_alphanumeric() || c == '_'));
            if after_ok {
                return true;
            }
            from = at + 1;
        }
        false
    })
}

/// The set of JSX element/component tag names OPENED in `source` — every `<Ident` that is not a closing
/// `</…` tag. (A TS generic like `<Number>` lands here too, which only makes the self-reference check
/// MORE conservative — a stub carrying a generic simply isn't flagged.) Mirrors `jsxTagNames` (graphHealth.ts).
fn jsx_tag_names(source: &str) -> BTreeSet<String> {
    let bytes = source.as_bytes();
    let mut set = BTreeSet::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'<' && i + 1 < bytes.len() && (bytes[i + 1] as char).is_ascii_alphabetic() {
            let start = i + 1;
            let mut k = start;
            while k < bytes.len() && ((bytes[k] as char).is_ascii_alphanumeric() || bytes[k] == b'_') {
                k += 1;
            }
            set.insert(source[start..k].to_string());
            i = k;
            continue;
        }
        i += 1;
    }
    set
}

/// Whether `node` is a SELF-REFERENTIAL STUB — an own-module component that declares its own name yet the
/// ONLY element it renders is itself (`<Name/>`). It passes `looks_buildable_module` (it has an `export`)
/// so `no-implementation` is blind to it, and it's syntactically valid so the write-time gate accepts it —
/// but it produces no real output and recurses forever. Mirrors `isSelfReferentialStub` (graphHealth.ts).
fn is_self_referential_stub(node: &Node, kit_targets: &BTreeSet<String>) -> bool {
    // The component's OWN module source (sibling-aware, #3112). A non-module usage snippet is already
    // `no-implementation`; a built-in's stripped source isn't ours.
    let Some(src) = own_module_source(node, kit_targets) else {
        return false;
    };
    if node.name.is_empty() || !declares_symbol(src, &node.name) {
        return false;
    }
    let tags = jsx_tag_names(src);
    tags.len() == 1 && tags.contains(&node.name)
}

/// Analyze the component records for graph-health findings, grouped and scoped PER KIT (edges only
/// resolve within a kit). Returns a ranked list, most-severe first (stable tiebreak: kit, then the
/// first node name), so the same input always yields the same ordering.
/// How to run [`analyze_with`] — the injected state the packaged seeds can't supply (#3412).
#[derive(Debug, Default, Clone, Copy)]
pub struct HealthOptions<'a> {
    /// The PINNED sound kit's artifact JSON — the kit a `@bsc/sounds/<id>` reference resolves against for
    /// this project, mirroring the frontend's `SoundKitSelection`. `None` = no pin ⇒ the packaged default
    /// kit (the documented default, byte-identical to pre-#3412 behavior).
    ///
    /// FAIL LOUDLY, never a silent degrade: a caller holding a pin it could not resolve must NOT pass
    /// `None` (that would quietly report against the starter kit, and the user cannot hear the
    /// difference) — it should refuse to run. `bsc ui doctor --sound-kit` does exactly that.
    /// A malformed artifact yields an empty name set, so every `@bsc/sounds/…` is flagged — fail safe.
    pub sound_kit_json: Option<&'a str>,
}

/// The hardcoded COLOR literals in `text` (#3704, the theme-adherence check) — the leak candidates a theme
/// change can NOT reach (a `var(--token)` carries none): a 6- or 8-digit hex (`#rrggbb` / `#rrggbbaa`) or an
/// `rgb(` / `rgba(` / `hsl(` / `hsla(` / `oklch(` / `oklab(` function. Deliberately conservative — a 3-digit
/// `#219` (an issue ref) is skipped and named colors aren't caught.
///
/// CODE POSITION ONLY (#87): a `//` or `/* … */` comment is skipped, because a hex written there styles
/// nothing — the swatch in `// palette: #171717` is documentation, and reporting it as a theme leak sends
/// the reader to fix a line that has no effect. A literal inside a STRING is still caught, since that is
/// exactly where a real one lives (`color: "#171717"`). Mirrors `colorLiterals` (TS) + `bsc ui`'s
/// `count_color_literals` (reimplemented here — this crate can't depend on `bsc-ui`).
fn color_literals(text: &str) -> Vec<String> {
    let b: Vec<char> = text.chars().collect();
    let n = b.len();
    let mut out = Vec::new();
    let mut i = 0;
    while i < n {
        match b[i] {
            '/' if i + 1 < n && b[i + 1] == '/' => {
                while i < n && b[i] != '\n' {
                    i += 1;
                }
            }
            '/' if i + 1 < n && b[i + 1] == '*' => {
                i += 2;
                while i + 1 < n && !(b[i] == '*' && b[i + 1] == '/') {
                    i += 1;
                }
                i = (i + 2).min(n);
            }
            '#' => {
                let mut j = i + 1;
                while j < n && b[j].is_ascii_hexdigit() {
                    j += 1;
                }
                if j - i - 1 == 6 || j - i - 1 == 8 {
                    out.push(b[i..j].iter().collect::<String>());
                }
                i = j.max(i + 1);
            }
            c if c.is_ascii_alphabetic() => {
                // A colour FUNCTION — matched on a whole-word boundary so `to_rgb(` isn't one.
                let start = i;
                while i < n && (b[i].is_ascii_alphanumeric() || b[i] == '_') {
                    i += 1;
                }
                let word: String = b[start..i].iter().collect::<String>().to_ascii_lowercase();
                let boundary_ok = start == 0 || !(b[start - 1].is_ascii_alphanumeric() || b[start - 1] == '_');
                if boundary_ok
                    && b.get(i) == Some(&'(')
                    && matches!(word.as_str(), "rgb" | "rgba" | "hsl" | "hsla" | "oklch" | "oklab")
                {
                    out.push(word);
                }
            }
            _ => i += 1,
        }
    }
    out
}

/// Does `text` reference a THEME TOKEN — a `var(--…)` design-token consumer? A component that does is
/// considered wired to the theme (it re-themes with the active palette); one that hardcodes colors and has
/// NONE is the `hardcoded-color` finding (#3704). Mirrors `usesThemeToken` (TS).
fn uses_theme_token(text: &str) -> bool {
    text.contains("var(--")
}

/// The JS unicode/hex escapes in `src` that sit in CODE position — OUTSIDE any string literal, template,
/// or comment (#3709). A `\uXXXX` / `\u{H+}` / `\xHH` here is almost always a JSX-**text** leak: JSX
/// children text is not a JS string literal, so the escape is never interpreted — the browser renders the
/// literal 6 characters `backslash-u-0-0-b-7`, not the `·` glyph. It passes the syntax check (valid JS)
/// and stores clean, so only a screenshot catches it. String/comment-aware (mirrors `has_code_elision`'s
/// scanner), so the CORRECT forms — a real `·` UTF-8 char, or the JSX `{"·"}` — are NOT flagged (the
/// escape lives inside a string there, or there is no escape at all). Conservative: a lone `\u` in a regex
/// literal is a rare false
/// positive, tolerable for an advisory. Mirrors `jsxTextEscapeLeaks` (there is no TS twin — this is a
/// write-time advisory, Rust-only).
pub fn jsx_text_escape_leaks(src: &str) -> Vec<String> {
    let b: Vec<char> = src.chars().collect();
    let (mut i, n) = (0usize, b.len());
    let mut out = Vec::new();
    while i < n {
        match b[i] {
            '/' if i + 1 < n && b[i + 1] == '/' => {
                while i < n && b[i] != '\n' {
                    i += 1;
                }
            }
            '/' if i + 1 < n && b[i + 1] == '*' => {
                i += 2;
                while i + 1 < n && !(b[i] == '*' && b[i + 1] == '/') {
                    i += 1;
                }
                i = (i + 2).min(n);
            }
            quote @ ('"' | '\'' | '`') => {
                i += 1;
                while i < n && b[i] != quote {
                    // A backslash escapes the next char — an escaped quote does not end the literal,
                    // and a `·` INSIDE the string (the correct form) is consumed here, never flagged.
                    i += if b[i] == '\\' { 2 } else { 1 };
                }
                i += 1;
            }
            '\\' if i + 1 < n && (b[i + 1] == 'u' || b[i + 1] == 'x') => {
                let is_u = b[i + 1] == 'u';
                let start = i;
                let mut j = i + 2;
                if is_u && j < n && b[j] == '{' {
                    // `\u{H+}` — code-point escape.
                    j += 1;
                    while j < n && b[j].is_ascii_hexdigit() {
                        j += 1;
                    }
                    if j < n && b[j] == '}' {
                        j += 1;
                    } else {
                        // Malformed (no closing `}`) — not an escape, step past the backslash only.
                        i += 1;
                        continue;
                    }
                } else {
                    // `\uHHHH` (4 hex) or `\xHH` (2 hex). Only a leak if the hex digits are actually there;
                    // a bare `\u` with no digits is a syntax error the write gate rejects separately.
                    let want = if is_u { 4 } else { 2 };
                    let mut got = 0;
                    while got < want && j < n && b[j].is_ascii_hexdigit() {
                        j += 1;
                        got += 1;
                    }
                    if got < want {
                        i += 1;
                        continue;
                    }
                }
                out.push(b[start..j].iter().collect::<String>());
                i = j;
            }
            _ => i += 1,
        }
    }
    out
}

/// [`analyze_with`] against the packaged seeds — the unpinned default (see [`HealthOptions`]).
pub fn analyze(components: &[Value]) -> Vec<Finding> {
    analyze_with(components, &HealthOptions::default())
}

/// The graph-health analyzer, run against a specific library context (#3412) — the Rust twin of
/// `analyzeGraphHealth(comps, libResolver)`. Both sides take the SAME pinned sound kit, so a reference
/// that resolves in the Design Studio resolves here too.
pub fn analyze_with(components: &[Value], opts: &HealthOptions) -> Vec<Finding> {
    // The pinned kit's importable names when a pin is supplied, else the packaged default kit's.
    let sounds = match opts.sound_kit_json {
        Some(json) => sound_library_names_from(json),
        None => sound_library_names().clone(),
    };
    let nodes: Vec<Node> = components.iter().filter_map(parse_node).collect();
    let mut by_kit: BTreeMap<&str, Vec<&Node>> = BTreeMap::new();
    for n in &nodes {
        by_kit.entry(n.kit.as_str()).or_default().push(n);
    }
    // Handle (name or id) → the kits that carry it, ACROSS the whole library. `composes` resolves within a
    // kit, so an entry naming a component that exists only in another kit still draws no edge — but it is a
    // different defect from one naming nothing at all, and telling the author to "write the canonical
    // record" for a `Box` that already exists would be exactly the impossible advice #89 is about.
    let mut kits_holding: BTreeMap<&str, BTreeSet<&str>> = BTreeMap::new();
    for n in &nodes {
        for handle in [n.name.as_str(), n.id.as_str()] {
            kits_holding.entry(handle).or_default().insert(n.kit.as_str());
        }
    }
    let buildable = buildable_srcs();
    let mut out = Vec::new();
    for (kit, kit_nodes) in by_kit {
        analyze_kit(kit, &kit_nodes, buildable, &sounds, &kits_holding, &mut out);
    }
    out.sort_by(|a, b| {
        b.severity
            .cmp(&a.severity)
            .then_with(|| a.kit.cmp(&b.kit))
            .then_with(|| a.node_names.first().cmp(&b.node_names.first()))
    });
    out
}

/// A component safe to prune (#2679) — a finding root the confirm-gated `--fix` may remove.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Prunable {
    pub id: String,
    pub name: String,
    pub reason: String,
}

/// A dead-root finding the auto-prune plan deliberately WITHHELD (#3087). It is still REPORTED by
/// `bsc ui doctor` — the read-only diagnosis stays complete — but `--fix` will never remove it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PruneSkip {
    pub id: String,
    pub name: String,
    /// Which guard held it back, in prose (printed by `--fix` so the withholding is never silent).
    pub guard: String,
}

/// The auto-prune plan: what `--fix` MAY remove, and what a guard held back (#3087).
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct PrunePlan {
    pub prune: Vec<Prunable>,
    pub skipped: Vec<PruneSkip>,
}

/// Is the `used` reuse-count index POPULATED for this component set — does ANY node carry `used > 0`?
///
/// `used` is a cross-codebase reuse count that no writer currently maintains: the packaged kit artifact
/// ships every component at `used: 0` and nothing increments it, so on a real install the whole store
/// reads zero. A store where NOTHING is used is therefore not a store full of dead components — it is a
/// store with **no usage signal at all**, and `used == 0` there means UNKNOWN, not unused (#3087).
/// Judged over the components HANDED IN, so a `--kit`-scoped call can only ever prune LESS.
///
/// **No longer what gates pruning** (#3888 slice 1) — [`prune_plan`] asks per NODE whether that node's
/// usage was determined, because a store-wide answer turns one measured node into a licence to delete
/// every unmeasured one. Kept as the honest READ of whether any usage signal exists at all, which is
/// what the `--fix` report says out loud and what a detector's own progress is measured against.
pub fn usage_index_populated(components: &[Value]) -> bool {
    components.iter().filter_map(parse_node).any(|n| n.used > 0)
}

/// The safe-to-remove set (#2679): the ROOT of every orphan / dangling-branch finding — a node with
/// no composer and `used == 0`. Deliberately NOT the branch DESCENDANTS (one might be shared by a live
/// component): removing the roots and re-running `doctor` surfaces any newly-orphaned children on the
/// next pass. Cycles, duplicates, and no-implementation findings are never auto-pruned (they need a
/// human's merge/break/author call). By construction a `used > 0` node can never appear here.
///
/// See [`prune_plan`] for the three safety guards this set is filtered through.
pub fn prunable(components: &[Value]) -> Vec<Prunable> {
    prune_plan(components).prune
}

/// The guarded auto-prune plan (#3087). Every orphan / dangling-branch ROOT is a *candidate*; three
/// guards decide whether it may actually be removed, because the dead-root heuristic (`in-degree 0 AND
/// used == 0`) has three known FALSE-POSITIVE classes — and epic #3087 wires a curator to run `--fix`
/// automatically, which turns each of them into unattended data loss:
///
/// 1. **A `page` is a root BY DEFINITION** — nothing composes a page; that is what makes it a page. The
///    heuristic condemns the whole pages tier (#2505) on principle. (The orphan arm already refuses to
///    flag an isolated page/layout as "entry point by role"; the dangling-branch arm did not, so a page
///    that composes anything at all — i.e. every real page — landed in the prune plan.)
/// 2. **A packaged `builtin: true` seed is not garbage** — the viz kits' demo components (#3194/#3242)
///    are isolated ON PURPOSE, to demo their kit's motion. Removing one only invites the seed reconcile
///    to re-add it on the next launch, so the "optimization" is a no-op that churns the store.
/// 3. **Usage that was never DETERMINED is UNKNOWN, not unused** — `used == 0` conflates "we looked and
///    found nothing" with "nothing looked", and only the first may condemn a node. A node qualifies when
///    `used > 0` (someone counted it) or it carries `usageAssessed: true` (a detector examined it against
///    a declared corpus and found none).
/// 4. **A record that CLAIMS a specifier is never auto-pruned** — its usage lives outside the composes
///    graph by definition: an importer resolves `@/x`, and no implemented source measures that.
///
/// ## Why guard 3 is PER NODE, and why that is the whole point (#3888 slice 1)
///
/// It used to be store-wide — *nothing* in scope has `used > 0`, therefore prune nothing — and that is
/// the only reason `--fix` has been safe. It also evaporates for EVERY node the moment a detector
/// populates `used` for ONE. The test pinning it said so as intended behaviour: *"one real usage count
/// anywhere restores the signal — and the same nodes prune again."* #3888 slice 2 populates `used` for
/// the 8 host-mounted pages; on that commit, 545 nodes no detector had ever examined would have become
/// prunable at once, unattended, because #3087 wires a curator to run `--fix` on its own.
///
/// Per-node, a detector can only ever make prunable the nodes it actually MEASURED. Nothing writes
/// `usageAssessed` yet, so today's behaviour is unchanged — `--fix` prunes nothing, exactly as before —
/// and every later source is additive. The cliff cannot exist by construction rather than by nobody
/// having stepped off it yet.
///
/// Guard 4 exists because a PARTIAL detector is the dangerous case, not a missing one: the moment
/// `usageAssessed` starts landing, the records that answer a specifier are the ones whose usage the
/// implemented sources still cannot see. That is the class 34 records went dark from on 2026-08-24.
///
/// A guarded candidate moves to `skipped` rather than vanishing: `doctor` still REPORTS the finding
/// (the diagnosis is useful), only the automatic removal is withheld.
pub fn prune_plan(components: &[Value]) -> PrunePlan {
    prune_plan_with(components, components)
}

/// Same as [`prune_plan`], except the `usage_index_populated` GUARD is judged against
/// `usage_reference` instead of `components` — so a caller can hand `analyze` a `components` list
/// whose `used` has been ENRICHED with an ephemeral, per-run usage signal (#3888's host-mount +
/// `provides` reachability, `usage_sources::enrich_used`) to suppress false-positive orphan/
/// dangling-branch findings, WITHOUT that same enrichment also widening what `--fix --yes` is willing
/// to auto-delete. That is the ordering hazard #3888 names explicitly: the moment `usage_known` flips
/// true, EVERY other candidate loses the "unpopulated" guard — safe when it flips because something
/// really did persist a `used` count, not safe when it flips because one run's necessarily-incomplete
/// reachability walk happened to reach one thing. `usage_reference` stays the STORE's real, persisted
/// `used` field (pass the un-enriched `components`) so this hazard can only ever be closed by
/// something that actually writes usage to disk — never by this report's own ephemeral read.
pub fn prune_plan_with(components: &[Value], usage_reference: &[Value]) -> PrunePlan {
    let nodes: Vec<Node> = components.iter().filter_map(parse_node).collect();
    let by_id: BTreeMap<&str, &Node> = nodes.iter().map(|n| (n.id.as_str(), n)).collect();
    // THE USAGE FACTS COME FROM `usage_reference`, NOT `components`. This is the whole reason the
    // `_with` variant exists (#3888): a caller may hand `components` a `used` field ENRICHED by one
    // run's reachability walk to suppress false-positive findings, and that enrichment must never
    // widen what `--fix --yes` will delete. Judging the usage guard against the un-enriched reference
    // keeps the two decisions separate. `prune_plan` passes the same list for both, which is the
    // honest default when there is no enrichment.
    let reference_nodes: Vec<Node> = usage_reference.iter().filter_map(parse_node).collect();
    let usage_by_id: BTreeMap<&str, &Node> =
        reference_nodes.iter().map(|n| (n.id.as_str(), n)).collect();

    let mut plan = PrunePlan::default();
    for f in analyze(components) {
        if !matches!(f.category, "orphan" | "dangling-branch") {
            continue;
        }
        let Some(id) = f.node_ids.into_iter().next() else { continue };
        let name = f.node_names.into_iter().next().unwrap_or_default();
        let node = by_id.get(id.as_str());
        // The usage guard reads the REFERENCE node (see above); every other guard below is a property
        // of the record itself and reads the node as given.
        let usage_node = usage_by_id.get(id.as_str()).copied().or(node.copied());
        let guard = if usage_node.is_some_and(|n| !n.usage_assessed) {
            Some(
                "this node's usage was never DETERMINED — `used = 0` with no `usageAssessed` means \
                 nothing looked, not that nothing uses it",
            )
        } else if node.is_some_and(|n| !n.provides.trim().is_empty()) {
            Some(
                "it CLAIMS a specifier — an importer resolves that name, and no implemented usage source \
                 measures it, so in-degree cannot condemn it",
            )
        } else if node.is_some_and(|n| n.role == "page") {
            Some("a `page` is a root BY DEFINITION — nothing composes a page; that is what makes it a page")
        } else if node.is_some_and(|n| n.builtin) {
            Some("a packaged built-in seed — it is shipped on purpose and the seed reconcile re-adds it")
        } else {
            None
        };
        match guard {
            Some(guard) => plan.skipped.push(PruneSkip { id, name, guard: guard.to_string() }),
            None => plan.prune.push(Prunable { id, name, reason: f.why }),
        }
    }
    plan
}

/// A byte-identical MERGE group (#3089, epic #3087) — the OPTIMIZE analog of a [`Prunable`]: the safe,
/// mechanical dedup the curator's optimize command applies. Components in a kit sharing byte-identical
/// non-empty `srcText` ARE the same component (e.g. two projects harvested the same Button), so the group
/// folds into ONE canonical — the most-`used` (tie-broken by smallest id, deterministic) — and the rest
/// are removed. Only byte-identical is auto-merged: a same-`wraps` "duplicate" finding is a WEAKER signal
/// (two DIFFERENT implementations of one intrinsic) that needs the curator's semantic judgment, so it is
/// NOT merged here.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MergeGroup {
    pub kit: String,
    pub canonical_id: String,
    pub canonical_name: String,
    /// The merged-away duplicates (removed from the store), each `(id, name)`.
    pub removed: Vec<(String, String)>,
}

/// The full byte-identical merge plan (#3089): the groups to fold + every composer record whose
/// `composes` must be repointed from a removed dup's NAME to the canonical's NAME. `repoints` carries the
/// FULL rewritten record (all fields preserved, only `composes` edited) so the caller writes it verbatim.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct MergePlan {
    pub groups: Vec<MergeGroup>,
    pub repoints: Vec<(String, Value)>,
}

/// Plan the safe, MECHANICAL merge of byte-identical duplicate components (#3089) — the curator's
/// optimize step, so 'keep the graph minimal' is a COMMAND, not hand-organization. Per kit: group nodes
/// by non-empty `srcText`; a group of 2+ folds into the most-`used` canonical (tie-break smallest id),
/// removing the rest and repointing every composer's `composes` from a removed NAME → the canonical NAME
/// (deduped; a resulting self-reference is dropped). Pure — APPLYING the plan (store writes) is the
/// caller's. Deterministic ordering (kit+source sort). Never touches a cycle / same-`wraps` dup.
pub fn merge_plan(components: &[Value]) -> MergePlan {
    let nodes: Vec<Node> = components.iter().filter_map(parse_node).collect();
    let raw_by_id: BTreeMap<&str, &Value> = components
        .iter()
        .filter_map(|v| v.get("id").and_then(Value::as_str).map(|id| (id, v)))
        .collect();

    // Group by (kit, srcText) — byte-identical source within a kit (edges never cross kits).
    let mut by_src: BTreeMap<(&str, &str), Vec<&Node>> = BTreeMap::new();
    for n in &nodes {
        if !n.src_text.trim().is_empty() {
            by_src.entry((n.kit.as_str(), n.src_text.as_str())).or_default().push(n);
        }
    }

    let mut groups: Vec<MergeGroup> = Vec::new();
    let mut remap: BTreeMap<(String, String), String> = BTreeMap::new(); // (kit, removedName) → canonicalName
    let mut removed_ids: BTreeSet<String> = BTreeSet::new();
    for ((kit, _src), group) in &by_src {
        if group.len() < 2 {
            continue;
        }
        // Canonical = most-used; tie-break the SMALLEST id (so the pick is deterministic + stable).
        let canonical = group
            .iter()
            .max_by(|a, b| a.used.cmp(&b.used).then_with(|| b.id.cmp(&a.id)))
            .unwrap();
        let mut removed: Vec<(String, String)> = Vec::new();
        for n in group {
            if n.id != canonical.id {
                removed.push((n.id.clone(), n.name.clone()));
                removed_ids.insert(n.id.clone());
                remap.insert(((*kit).to_string(), n.name.clone()), canonical.name.clone());
            }
        }
        if !removed.is_empty() {
            groups.push(MergeGroup {
                kit: (*kit).to_string(),
                canonical_id: canonical.id.clone(),
                canonical_name: canonical.name.clone(),
                removed,
            });
        }
    }

    // Repoint composers: any SURVIVING node whose `composes` references a removed NAME (same kit) → the
    // canonical NAME, deduped; an edge the remap turns into a self-reference is dropped.
    let mut repoints: Vec<(String, Value)> = Vec::new();
    for n in &nodes {
        if removed_ids.contains(&n.id) {
            continue;
        }
        let mut changed = false;
        let mut new_composes: Vec<String> = Vec::new();
        for dep in &n.composes {
            let mapped = remap.get(&(n.kit.clone(), dep.clone())).cloned().unwrap_or_else(|| dep.clone());
            if &mapped != dep {
                changed = true;
            }
            if mapped == n.name || new_composes.contains(&mapped) {
                changed = true; // dropped a self-reference or a duplicate edge produced by the remap
            } else {
                new_composes.push(mapped);
            }
        }
        if changed {
            if let Some(raw) = raw_by_id.get(n.id.as_str()) {
                let mut v = (*raw).clone();
                v["composes"] = Value::Array(new_composes.into_iter().map(Value::String).collect());
                repoints.push((n.id.clone(), v));
            }
        }
    }

    MergePlan { groups, repoints }
}

fn analyze_kit(
    kit: &str,
    nodes: &[&Node],
    buildable: &BTreeSet<String>,
    // The importable `@bsc/sounds/…` names for THIS run — the pinned kit's, else the packaged default's.
    sounds: &BTreeSet<String>,
    // Handle (name or id) → the kits carrying it, library-wide. Lets the dangling-composes check say
    // whether an unresolved name exists NOWHERE or merely in another kit — two defects with opposite fixes.
    kits_holding: &BTreeMap<&str, BTreeSet<&str>>,
    out: &mut Vec<Finding>,
) {
    // Name → ids (in-kit). A name is NOT guaranteed unique — a fossil left behind by a promotion/rename
    // can carry the same `name` as its live replacement (#request-115: `ConsolePageCard` existed as both
    // the live `settings-consolepagecard` and a stale built-in `consolepagecard`). Crediting only ONE id
    // for a shared name (keep-first, or any other arbitrary pick) silently starves every OTHER same-named
    // node of the edge a real composer declares — which is exactly what turned six live settings-page
    // cards into false `orphan`/`dangling-branch` findings: `GeneralPage.composes` names `ConsolePageCard`
    // once, but the store held two ids for that name, and only the arbitrarily-chosen one received the
    // in-degree. `bsc ui used-by` resolves by name too and was never wrong — it credits every id sharing
    // the queried name — so this collects every id per name and credits ALL of them, agreeing with it.
    let mut ids_by_name: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
    for n in nodes {
        ids_by_name.entry(n.name.as_str()).or_default().push(n.id.as_str());
    }
    // Resolved edges (composer id → dependency id) + in/out degree by id.
    let mut out_ids: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
    let mut in_deg: BTreeMap<&str, usize> = BTreeMap::new();
    for n in nodes {
        in_deg.entry(n.id.as_str()).or_insert(0);
    }
    // Every id in the kit — so a `composes` entry is judged DANGLING only when it matches neither a name
    // nor an id (#89). An entry naming an id draws no edge (resolution is by name, as the TS
    // `buildComposesEdges` twin does) but it is not a fabricated reference, so it is deliberately not
    // reported here — a real but lesser gap, left visible in this comment rather than silently conflated.
    let ids_in_kit: BTreeSet<&str> = nodes.iter().map(|n| n.id.as_str()).collect();
    // `composes` entry that resolves to nothing → the composers that declare it.
    let mut dangling: BTreeMap<&str, Vec<&&Node>> = BTreeMap::new();
    for n in nodes {
        for dep_name in &n.composes {
            if let Some(dep_ids) = ids_by_name.get(dep_name.as_str()) {
                for &dep_id in dep_ids {
                    out_ids.entry(n.id.as_str()).or_default().push(dep_id);
                    *in_deg.entry(dep_id).or_insert(0) += 1;
                }
            } else if !dep_name.trim().is_empty() && !ids_in_kit.contains(dep_name.as_str()) {
                dangling.entry(dep_name.as_str()).or_default().push(n);
            }
        }
    }

    // ── dangling-composes-reference (severity 2): a `composes` entry naming NO component in the kit — by
    // name OR by id (#89). Both edge builders DROP an unresolved name, so the graph draws no edge and looks
    // complete while the record claims a composition of something that exists nowhere. It is the standard
    // the designer doc has always stated ("every `composes` entry names a real component in the kit") and
    // the one thing nothing checked.
    //
    // It gets its own category because the finding it used to surface as was actively misleading: two
    // components sharing a forward reference score as a fuzzy near-DUPLICATE pair (their prop shapes align
    // around the child they both intend to extract), and that finding's "merge X into Y" is not merely less
    // useful — it is impossible, because the preview sandbox forbids the first-party import a literal merge
    // would need. The right fix in every instance of the pattern is the opposite of a merge: AUTHOR the
    // canonical record the reference already names, which is what the suggested action says. Grouped by the
    // MISSING name (one finding per absent component, listing every composer) rather than per composer,
    // because the fix is one record, not one per site. Mirrors `graphHealth.ts`.
    for (missing, composers) in &dangling {
        let names: Vec<String> = composers.iter().map(|n| n.name.clone()).collect();
        let one = composers.len() == 1;
        // Does the name exist at all, just in another kit? The defect is the same dropped edge either way,
        // but the fixes are opposites: author the missing record vs. reach the one that already exists.
        let elsewhere: Vec<&str> = kits_holding
            .get(missing)
            .map(|kits| kits.iter().copied().filter(|k| *k != kit).collect())
            .unwrap_or_default();
        let (tail, action) = if elsewhere.is_empty() {
            (
                "no component ANYWHERE in the library carries that name or id — the reference names something that does not exist".to_string(),
                format!(
                    "author the canonical `{missing}` record the reference already names (`bsc ui set {}`), so {} compose{} the real node — or drop `{missing}` from {} `composes`. Do NOT merge the composers into each other: what they share is a forward reference, not an implementation",
                    missing.to_lowercase(),
                    if one { "it" } else { "they" },
                    if one { "s" } else { "" },
                    if one { "its" } else { "their" },
                ),
            )
        } else {
            (
                format!(
                    "no component in THIS kit carries that name or id — it exists in {} ({}), and `composes` only ever resolves within one kit",
                    if elsewhere.len() == 1 { "another kit" } else { "other kits" },
                    elsewhere.join(", "),
                ),
                format!(
                    "add `{missing}` to the `{kit}` kit (or move the composer{} to the kit that already has it) — do NOT author a second copy, and do NOT merge the composers: the record exists, this kit just cannot reach it",
                    if one { "" } else { "s" },
                ),
            )
        };
        out.push(Finding {
            category: "dangling-composes-reference",
            severity: 2,
            kit: kit.to_string(),
            node_ids: composers.iter().map(|n| n.id.clone()).collect(),
            node_names: names.clone(),
            why: format!(
                "{} component{} ({}) declare{} they compose `{missing}`, but {tail} — the edge resolves to nothing and is silently dropped, so the graph reads as complete",
                composers.len(),
                if one { "" } else { "s" },
                names.join(", "),
                if one { "s" } else { "" },
            ),
            suggested_action: action,
        });
    }

    let node_by_id: BTreeMap<&str, &&Node> = nodes.iter().map(|n| (n.id.as_str(), n)).collect();
    let name_of = |id: &str| node_by_id.get(id).map(|n| n.name.clone()).unwrap_or_default();

    // What a component's internal (`@/`, `./`) import resolves to when the preview BUILDS it — the Rust
    // mirror of `componentPreviewFiles`'s resolution (#43/#3660): this kit's component `src` paths, the
    // packaged artifact's built-in sources + runtime closure (the app's real modules), AND every graph
    // component's `provides` specifier (a graph-source primitive importing a sibling resolves exactly as the
    // runtime loader does). So a graph-source component composing siblings + app utilities builds — and is
    // scanned as the module it is — instead of being falsely flagged no-implementation (#3112).
    let kit_targets: BTreeSet<String> = {
        let mut t = internal_targets().clone();
        t.extend(nodes.iter().map(|n| n.src.clone()).filter(|s| !s.is_empty()));
        for n in nodes {
            if let Some(base) = resolve_internal_base(&n.provides, "") {
                t.insert(format!("{base}.tsx"));
            }
            // #3897: `@/components/<node-id>` is the loader's SIBLING-BY-ID form — how a migrated page
            // pulls in its panels (`@/components/security-profiles`). It is neither a `src` path nor a
            // registered module, so the Security page (now `logspage`) read as no-implementation while
            // the app mounted it.
            // Injected as a synthetic target so the ordinary resolver finds it.
            t.insert(format!("components/{}.tsx", n.id));
        }
        t
    };

    // ── cycles (severity 4) — a `composes` loop; report each SCC of size > 1 (or a self-loop).
    for scc in strongly_connected(nodes, &out_ids) {
        let is_cycle = scc.len() > 1 || out_ids.get(scc[0]).is_some_and(|d| d.contains(&scc[0]));
        if !is_cycle {
            continue;
        }
        let names: Vec<String> = scc.iter().map(|id| name_of(id)).collect();
        out.push(Finding {
            category: "cycle",
            severity: 4,
            kit: kit.to_string(),
            node_ids: scc.iter().map(|s| s.to_string()).collect(),
            node_names: names.clone(),
            why: format!("these components form a `composes` cycle: {}", names.join(" → ")),
            suggested_action: "break the loop — a composition graph must be acyclic (it also breaks the layered layout)".to_string(),
        });
    }

    // ── no-implementation (severity 3): a component the Design Studio preview can't build
    // (componentPreviewFiles → null) — it's a spec, not code. The store strips a built-in's artifact
    // `source` (#2794), so a BUILT-IN looks source-less yet builds from the packaged artifact; only a
    // node in NEITHER the artifact roster NOR carrying its own module/`source` is flagged (a user-
    // authored spec, e.g. a `page` like GraphExplorerPage). Independent of used/role/degree — an
    // unrenderable node is always flagged. Mirrors the frontend `analyzeGraphHealth` (graphHealth.ts).
    for n in nodes {
        if is_buildable(n, buildable, &kit_targets) {
            continue;
        }
        out.push(Finding {
            category: "no-implementation",
            severity: 3,
            kit: kit.to_string(),
            node_ids: vec![n.id.clone()],
            node_names: vec![n.name.clone()],
            why: format!(
                "`{}` has no buildable implementation — the preview can't render it (a spec, not code): {}",
                n.name,
                no_implementation_reasons(n, &kit_targets).join("; ")
            ),
            suggested_action: format!(
                "author a self-contained module for `{}` (its own `source`/`srcText`) or compose it from built-in kit components",
                n.name
            ),
        });
    }

    // ── hardcoded-color (severity 1, #3704): a component NOT wired to the theme — its own source hardcodes
    // color literals (hex / rgb / hsl / oklch) and references NO `var(--…)` design token, so it won't follow
    // the active theme/preset (the contract is "components reference ONLY semantic tokens, never raw
    // colors"). Built-ins are skipped (their store record is a curated snippet, not the real source). Uses
    // the node's own source (`source` else `srcText`) — independent of buildability, so an unthemed mobile
    // component is flagged whether or not its imports resolve standalone. Mirrors `analyzeGraphHealth` (TS).
    for n in nodes {
        if n.builtin {
            continue;
        }
        let src = if !n.source.trim().is_empty() { n.source.as_str() } else { n.src_text.as_str() };
        if src.trim().is_empty() || uses_theme_token(src) {
            continue;
        }
        let colors = color_literals(src);
        if colors.is_empty() {
            continue;
        }
        let sample = colors.iter().take(4).map(|c| format!("`{c}`")).collect::<Vec<_>>().join(", ");
        let more = if colors.len() > 4 { format!(", +{}", colors.len() - 4) } else { String::new() };
        out.push(Finding {
            category: "hardcoded-color",
            severity: 1,
            kit: kit.to_string(),
            node_ids: vec![n.id.clone()],
            node_names: vec![n.name.clone()],
            why: format!(
                "`{}` hardcodes {} color literal{} ({sample}{more}) and references no theme token — it won't follow the active theme/preset",
                n.name,
                colors.len(),
                if colors.len() == 1 { "" } else { "s" },
            ),
            suggested_action:
                "replace the raw colors with `var(--…)` design tokens (e.g. `var(--fg)`, `var(--bg-panel)`, `var(--accent)`; see `bsc ui tokens`) so it re-themes with the palette".to_string(),
        });
    }

    // ── self-reference (severity 3): an own-module component whose only rendered element is ITSELF
    // (`<Name/>`). It passes the buildability check (it has an `export`, so no-implementation is blind to
    // it) and the write-time syntax gate (it's valid), yet it produces no output and recurses forever —
    // the class the designer hit authoring D3 components as self-calls (#3026).
    for n in nodes {
        if !is_self_referential_stub(n, &kit_targets) {
            continue;
        }
        out.push(Finding {
            category: "self-reference",
            severity: 3,
            kit: kit.to_string(),
            node_ids: vec![n.id.clone()],
            node_names: vec![n.name.clone()],
            why: format!(
                "`{}` only renders itself (`<{}/>`) — a self-referential stub, not a real implementation (it produces no output and recurses forever)",
                n.name, n.name
            ),
            suggested_action: format!(
                "replace `{}`'s source with its REAL body — the elements/state/effects that produce its output — never a call to `<{}>`",
                n.name, n.name
            ),
        });
    }

    // ── dead roots: in-degree 0 AND used == 0, excluding a page/layout entry point kept alive by use.
    for n in nodes {
        let indeg = *in_deg.get(n.id.as_str()).unwrap_or(&0);
        let outdeg = out_ids.get(n.id.as_str()).map(Vec::len).unwrap_or(0);
        if indeg != 0 || n.used != 0 {
            continue;
        }
        if outdeg == 0 {
            // ── orphan (severity 2) — an isolated primitive/composite nobody composes or uses.
            if n.role == "primitive" || n.role == "composite" {
                out.push(Finding {
                    category: "orphan",
                    severity: 2,
                    kit: kit.to_string(),
                    node_ids: vec![n.id.clone()],
                    node_names: vec![n.name.clone()],
                    why: format!("`{}` is isolated (nothing composes it) and unused (used = 0)", n.name),
                    suggested_action: format!("prune it — `bsc ui remove {}` (confirm-gated)", n.id),
                });
            }
            // A dead isolated page/layout is unusual (a stray screen); leave it for the human — it's
            // an entry point by role, so we don't auto-flag it as prunable.
        } else {
            // ── dangling-branch (severity 3) — an unused root that still pulls in dependencies.
            let mut reachable = BTreeSet::new();
            collect_reachable(n.id.as_str(), &out_ids, &mut reachable);
            reachable.remove(n.id.as_str());
            // A `page` is a root BY DEFINITION — nothing composes a page; that is what makes it a page
            // (`prune_plan` guard 1 already says so for auto-prune, #3087). The finding still surfaces so a
            // human auditing the graph sees a page with no explicit mount-composer, but its `node_ids`
            // deliberately name ONLY the root, never the reachable set: those are the page's ordinary,
            // often widely-shared content (#110 — `SettingsWorkspace` alone reaches 73 real components
            // including `DeployToggle`, which `bsc ui used-by` shows composed by 8 others elsewhere).
            // Spreading the category onto every one of them badged real, live components as "unused"
            // purely because ONE unrelated page happens to reach them. A dead LAYOUT keeps the full
            // branch below — unlike a page it is not guaranteed to be a real entry point, so dragging its
            // subtree down with it is a genuine, worth-reporting risk (`flags_an_unused_root_with_deps_as_a_dangling_branch`).
            let (ids, names) = if n.role == "page" {
                (vec![n.id.clone()], vec![n.name.clone()])
            } else {
                let mut ids = vec![n.id.clone()];
                let mut names = vec![n.name.clone()];
                for id in &reachable {
                    ids.push(id.to_string());
                    names.push(name_of(id));
                }
                (ids, names)
            };
            out.push(Finding {
                category: "dangling-branch",
                severity: 3,
                kit: kit.to_string(),
                node_ids: ids,
                node_names: names,
                why: format!(
                    "`{}` is an unused root (nothing composes it, used = 0) that pulls in {} dependenc{}",
                    n.name,
                    reachable.len(),
                    if reachable.len() == 1 { "y" } else { "ies" }
                ),
                suggested_action: if n.role == "page" {
                    "a page is a root by definition — nothing composes it; it is never auto-pruned (see \
                     `bsc ui doctor --fix`'s guard), reported here only so a human notices it has no \
                     explicit mount-composer"
                        .to_string()
                } else {
                    format!(
                        "prune the branch from its root `{}` — check each dependency isn't shared before removing",
                        n.name
                    )
                },
            });
        }
    }

    // ── duplicates (severity 3): two components wrapping the SAME intrinsic, or byte-identical source.
    let mut by_wraps: BTreeMap<&str, Vec<&&Node>> = BTreeMap::new();
    for n in nodes {
        if let Some(w) = &n.wraps {
            by_wraps.entry(w.as_str()).or_default().push(n);
        }
    }
    for (intrinsic, group) in by_wraps {
        if group.len() < 2 {
            continue;
        }
        let names: Vec<String> = group.iter().map(|n| n.name.clone()).collect();
        // Suggest keeping the most-used one as the merge target.
        let target = group.iter().max_by_key(|n| n.used).map(|n| n.name.clone()).unwrap_or_default();
        out.push(Finding {
            category: "duplicate",
            severity: 3,
            kit: kit.to_string(),
            node_ids: group.iter().map(|n| n.id.clone()).collect(),
            node_names: names.clone(),
            why: format!("{} components all wrap the raw `<{}>`: {}", group.len(), intrinsic, names.join(", ")),
            suggested_action: format!("merge into `{target}` (the most-used) and repoint the others"),
        });
    }
    // Byte-identical source (a stronger duplicate signal than `wraps`).
    let mut by_src: BTreeMap<&str, Vec<&&Node>> = BTreeMap::new();
    for n in nodes {
        if !n.src_text.trim().is_empty() {
            by_src.entry(n.src_text.as_str()).or_default().push(n);
        }
    }
    for (_src, group) in by_src {
        if group.len() < 2 {
            continue;
        }
        let names: Vec<String> = group.iter().map(|n| n.name.clone()).collect();
        let target = group.iter().max_by_key(|n| n.used).map(|n| n.name.clone()).unwrap_or_default();
        out.push(Finding {
            category: "duplicate",
            severity: 3,
            kit: kit.to_string(),
            node_ids: group.iter().map(|n| n.id.clone()).collect(),
            node_names: names.clone(),
            why: format!("{} components have byte-identical source: {}", group.len(), names.join(", ")),
            suggested_action: format!("merge into `{target}` (the most-used) and repoint the others"),
        });
    }

    // ── unresolvable-import (severity 3): a component whose module imports something the preview CAN'T
    // resolve — the class `bsc ui doctor` was blind to (the static graph looked clean while the component
    // was broken). Kinds (#2934 bare, #2954 internal, #3116 library):
    //   • BARE npm (#3696) — a package not among the curated preview externals no longer FAILS: the preview
    //     bundles a local shim/stub for it, so it renders APPROXIMATELY. Emitted as a severity-1
    //     `stubbed-import` NOTE (not the old sev-3 error) so the designer knows the preview isn't the real
    //     package. Only INTERNAL/LIBRARY below are genuine (sev-3 `unresolvable-import`) — they have no stub.
    //   • INTERNAL — a `@/…` or RELATIVE import resolving to NEITHER a kit component NOR a runtime-closure
    //     module → "module not found" (exactly the `Code`→`../typography/type` / `Skeleton`→`./shimmer`
    //     failure #2954 fixed in the packaged closure; this catches any future/user-authored recurrence).
    //   • LIBRARY (#3116) — a `@bsc/<segment>/<name>` cross-graph reference (the THIRD class, neither npm
    //     nor first-party) naming NO real library node. A `@bsc/algorithms/<name>` matching a real algorithm
    //     is a NEW resolvable class (the preview vendors its code), NEVER flagged; only a missing one is.
    // Scanned on own-source components (a built-in's `source`, or a `looks_buildable_module` srcText) — the
    // source the preview actually builds. Resolution uses `kit_targets` (the full build set: artifact +
    // node srcs + `provides`, #43), so a graph-source import resolves here exactly as the build does.
    // Mirrors `graphHealth.ts`.
    for n in nodes {
        let Some(src) = own_module_source(n, &kit_targets) else {
            continue;
        };
        let resolvable = resolvable_specifiers();
        // Every classification below asks "can the preview provide this module?". A SYNTACTICALLY
        // type-only import (#4076) is erased by the loader before it resolves anything, so it needs no
        // kit component, no runtime file, no library node and no npm stub — drop it up front rather than
        // exempting it three times. Harvest applies the same rule, and the two must not drift (#3486).
        let erased = erased_specifiers(src);
        let specs: Vec<String> = import_specifiers(src).into_iter().filter(|s| !erased.contains(s)).collect();
        // A `@bsc/…` LIBRARY reference (#3116) is bare-shaped but resolves against the algorithms store, NOT
        // the import-map — so it's excluded from `stubbed` and judged by `resolves_library` (a match ⇒ the
        // preview vendors its code ⇒ clean; a `@bsc/algorithms/<missing>` ⇒ flagged here).
        let mut library: Vec<String> =
            specs.iter().filter(|s| is_library_specifier(s) && !resolves_library(s, sounds)).cloned().collect();
        // A BARE npm specifier that isn't a curated preview external (#3696): it no longer FAILS — the
        // preview bundles a local shim/stub for any such import (react-native → real layout, react-native-svg
        // → real SVG, else a universal passthrough), so nothing throws "Failed to resolve module specifier".
        // It renders APPROXIMATELY (a stub, not the real package) → a severity-1 note, not the old sev-3 error.
        let mut stubbed: Vec<String> = specs
            .iter()
            .filter(|s| is_bare_specifier(s) && !is_library_specifier(s) && !resolvable.contains(*s))
            .cloned()
            .collect();
        let mut internal: Vec<String> = specs
            .iter()
            .filter(|s| {
                is_internal_specifier(s)
                    && !platform_modules().contains(*s)
                    // bsc request #125: a record (component OR algorithm-graph) `provides` this specifier —
                    // the same gap fixed in `is_preview_buildable`/`no_implementation_reasons` above. Without
                    // it a component that PASSES the (now-fixed) no-implementation check over a graph-provided
                    // import still fell into this second, independent resolution check and was re-flagged
                    // here as `unresolvable-import` instead — the same false report under a different label.
                    && !is_provided_specifier(s)
                    && !resolves_internal(s, &n.src, &kit_targets)
            })
            .cloned()
            .collect();
        for v in [&mut stubbed, &mut library, &mut internal] {
            v.sort();
            v.dedup();
        }
        let fmt = |v: &[String]| v.iter().map(|s| format!("`{s}`")).collect::<Vec<_>>().join(", ");
        // GENUINELY unresolvable (severity 3): a first-party `@/…`/relative module mapping to no kit
        // component or runtime file, or a `@bsc/…` library reference naming no real node. Unlike a bare npm
        // import, these have NO stub fallback — the preview really can't build them.
        if !library.is_empty() || !internal.is_empty() {
            let mut reasons = Vec::new();
            let mut actions = Vec::new();
            if !library.is_empty() {
                reasons.push(format!("{} (no matching node in the library)", fmt(&library)));
                actions.push(format!(
                    "reference an EXISTING library node for {} (e.g. `@bsc/algorithms/fibonacci`), or author it in the library",
                    fmt(&library)
                ));
            }
            if !internal.is_empty() {
                reasons.push(format!("{} (no such module in the kit or its runtime closure)", fmt(&internal)));
                actions.push(format!("fix or add the module for {} (it resolves to no kit component or runtime file)", fmt(&internal)));
            }
            out.push(Finding {
                category: "unresolvable-import",
                severity: 3,
                kit: kit.to_string(),
                node_ids: vec![n.id.clone()],
                node_names: vec![n.name.clone()],
                why: format!(
                    "`{}` imports {} — the preview can't resolve it, so it throws \"module not found\" when rendered",
                    n.name,
                    reasons.join("; ")
                ),
                suggested_action: actions.join("; "),
            });
        }
        // STUBBED npm imports (severity 1): the component renders, but the package is a local shim/stub, not
        // the real thing — informational so the designer knows the preview is approximate (#3696).
        if !stubbed.is_empty() {
            out.push(Finding {
                category: "stubbed-import",
                severity: 1,
                kit: kit.to_string(),
                node_ids: vec![n.id.clone()],
                node_names: vec![n.name.clone()],
                why: format!(
                    "`{}` imports {} — not a curated preview external, so the preview renders it via a bundled-in local shim/stub (approximate, not the real package)",
                    n.name,
                    fmt(&stubbed)
                ),
                suggested_action: format!(
                    "acceptable for most native/app packages; if {} needs its REAL behaviour in the preview, add it to the curated externals (src-tauri/data/ui/preview-importmap.json)",
                    fmt(&stubbed)
                ),
            });
        }
    }

    // ── reimplemented-component (severity 3, #3892): the SAME "compose, don't recreate" guardrail as
    // `reimplementation` below, one dimension over — an own-source component that DECLARES a name which is
    // already a COMPONENT NODE in this graph. The algorithm version has existed since #3118; the component
    // version did not, which is how 36 of 74 harvested records came to carry a local `function Box` while a
    // `Box` node sat in the same kit. They render — as a STUB Box, not the kit's — so the page looks right
    // and every later revision iterates on the reduced copy (the #3833 failure mode).
    //
    // The provenance is promotion, not harvest: `bsc ui harvest` reports such a candidate as
    // `buildable: false` with the exact unresolved specifiers and never stubs them. This catches the hand
    // "resolution" that satisfies buildability by faking the import.
    //
    // Conservative, matching its sibling: EXACT whole-identifier declaration, on the source the preview
    // builds, never self, and SKIPPED when the source already imports that identifier (a component may
    // legitimately re-export or alias). Mirrors graphHealth.ts.
    //
    // NAME ALONE IS TOO WEAK A SIGNAL (#130, filed by the react designer after investigating all 6 live
    // findings in depth): 5 of 6 were a name COINCIDENCE, not a re-declaration. Two further guards, each
    // independently sufficient to clear a candidate:
    //   • VERIFIED PROVIDER — some OTHER node in the graph demonstrably imports the exact colliding name
    //     from `n`'s own `provides`. That's the ConsoleStates/Charts shape: a multi-export module
    //     concatenates (or aggregates) sibling declarations that are ALSO catalogued as their own separate
    //     nodes, and `PaneAt`/`fleetpage`/etc. genuinely import `DisabledConsole`/`Avatar`/`ItemBars`/…
    //     from the aggregate's own specifier — so the aggregate IS the real, resolved provider, not a stub
    //     competing with one.
    //   • CONTRACT MISMATCH — the local declaration's own prop signature and the colliding node's recorded
    //     `props` disagree more than they agree (`contract_overlap` < [`REIMPL_CONTRACT_MIN`]), the
    //     RangeToggle/SoundsInspector shape: a chart's bot-glyph `Avatar` and a key-value row's `Field` are
    //     different components that happen to share a generic English word with an unrelated sibling.
    {
        // Real-import evidence, computed ONCE across the whole graph rather than re-scanned per
        // candidate: every named binding `{ a, b } from "spec"` any node's own source carries.
        let mut named_imports_by_spec: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
        for t in nodes {
            for (spec, names) in named_import_clauses(&t.src_text) {
                named_imports_by_spec.entry(spec).or_default().extend(names);
            }
        }
        for n in nodes {
            let Some(src) = own_module_source(n, &kit_targets) else {
                continue;
            };
            let imported = imported_identifiers(src);
            // ONE pass, for the same reason — this filters over EVERY node in the kit.
            let declared = declared_symbols(src);
            let verified_provider = |name: &str| {
                !n.provides.is_empty()
                    && named_imports_by_spec.get(&n.provides).is_some_and(|names| names.contains(name))
            };
            // SAME-FILE siblings are not stubs (#3895). Several nodes are routinely extracted from ONE
            // module — `AgentFace` and `TeamsCanvas` both come from TeamsCanvas.tsx — so that module's
            // closure legitimately CONTAINS both declarations. Flagging them would demand an import of the
            // file from itself. Only a target from a DIFFERENT source is a re-declaration.
            let mut recoded: Vec<&str> = nodes
                .iter()
                .filter(|t| t.name != n.name && (n.src.is_empty() || t.src != n.src))
                // `!t.name.is_empty()`: see `declared_symbols` — the empty name is the one input where
                // the derived set and the predicate differ, and firing on it would be a bug.
                .filter(|t| !t.name.is_empty())
                .filter(|t| declared.contains(t.name.as_str()) && !imported.contains(t.name.as_str()))
                .filter(|t| !verified_provider(&t.name))
                .filter(|t| contract_overlap(src, &t.name, &t.props).is_none_or(|o| o >= REIMPL_CONTRACT_MIN))
                .map(|t| t.name.as_str())
                .collect();
            if recoded.is_empty() {
                continue;
            }
            recoded.sort_unstable();
            recoded.dedup();
            let list = recoded.iter().map(|x| format!("`{x}`")).collect::<Vec<_>>().join(", ");
            let one = recoded.len() == 1;
            out.push(Finding {
                category: "reimplemented-component",
                severity: 3,
                kit: kit.to_string(),
                node_ids: vec![n.id.clone()],
                node_names: vec![n.name.clone()],
                why: format!(
                    "`{}` declares {} locally, but {} already {} in this graph — the preview renders the LOCAL copy, so this node looks correct while composing a stub instead of the real component",
                    n.name,
                    list,
                    if one { "that name is" } else { "those names are" },
                    if one { "a node" } else { "nodes" },
                ),
                suggested_action: format!(
                    "import the real {} instead of re-declaring {} — if the import could not be resolved at promotion, register it as a platform module rather than stubbing it (`bsc ui harvest` flags an unclosable candidate as buildable:false for exactly this reason)",
                    if one { "component" } else { "components" },
                    if one { "it" } else { "them" },
                ),
            });
        }
    }

    // ── reimplementation (severity 3): the "compose, don't recreate" guardrail (#3118, epic #3114). An
    // own-source component that DECLARES a symbol whose name EXACTLY matches an existing LIBRARY ALGORITHM
    // is RE-CODING what it could import via `@bsc/algorithms/…` — an inline `function fibonacci` while
    // `@bsc/algorithms/fibonacci` already exists. #3116 made those references resolvable + vendorable (the
    // preview runs the library impl); this steers the designer to compose the ONE canonical node instead of
    // forking it. ALGORITHMS-ONLY (see `reimpl_targets`): sounds are excluded — a cue id like `click`
    // collides with common handler names. Conservative (false positives are worse than a miss): EXACT
    // whole-identifier match (`declares_symbol`), on the source the preview builds (`own_module_source`),
    // and SKIPPED when the component already imports that `@bsc/<segment>/<name>` node. Mirrors graphHealth.ts.
    for n in nodes {
        let Some(src) = own_module_source(n, &kit_targets) else {
            continue;
        };
        let specs: BTreeSet<String> = import_specifiers(src).into_iter().collect();
        // ONE pass over the source, not one per target — see `declared_symbols`.
        let declared = declared_symbols(src);
        let mut recoded: Vec<(String, String)> = Vec::new(); // (name, importSpec)
        for (name, segment) in reimpl_targets() {
            let import_spec = format!("@bsc/{segment}/{name}");
            if declared.contains(name.as_str()) && !specs.contains(&import_spec) {
                recoded.push((name.clone(), import_spec));
            }
        }
        if recoded.is_empty() {
            continue;
        }
        recoded.sort();
        recoded.dedup();
        let one = recoded.len() == 1;
        let list = recoded
            .iter()
            .map(|(name, spec)| format!("`{name}` (import `{spec}`)"))
            .collect::<Vec<_>>()
            .join(", ");
        let names = recoded.iter().map(|(name, _)| format!("`{name}`")).collect::<Vec<_>>().join(", ");
        let imports = recoded.iter().map(|(_, spec)| format!("`{spec}`")).collect::<Vec<_>>().join(", ");
        out.push(Finding {
            category: "reimplementation",
            severity: 3,
            kit: kit.to_string(),
            node_ids: vec![n.id.clone()],
            node_names: vec![n.name.clone()],
            why: format!(
                "`{}` re-codes {}: {} — compose {} from the library instead of re-coding (compose, don't recreate)",
                n.name,
                if one { "a library node that already exists" } else { "library nodes that already exist" },
                list,
                if one { "it" } else { "them" }
            ),
            suggested_action: format!(
                "import {} instead of re-declaring {} inline in `{}`",
                imports, names, n.name
            ),
        });
    }

    // ── unwired-prop (severity 2): a component that declares props its OWN module source never references
    // — a declared interface that does nothing (#2924). Only for a node whose own source is present (a
    // user-authored module: its `source`, or a buildable `srcText`); a built-in (source in the artifact)
    // or a spec (no buildable module) is skipped. Guard: require ≥1 prop REFERENCED (so it uses NAMED
    // props — not a `{...props}` spreader) before flagging the unreferenced ones. Mirrors `graphHealth.ts`.
    for n in nodes {
        let Some(src) = own_module_source(n, &kit_targets) else {
            continue;
        };
        if n.props.is_empty() || !n.props.iter().any(|p| contains_word(src, &p.0)) {
            continue; // no props, or none referenced (a spreader) → conservative skip
        }
        let unwired: Vec<&str> =
            n.props.iter().filter(|p| !contains_word(src, &p.0)).map(|p| p.0.as_str()).collect();
        if unwired.is_empty() {
            continue;
        }
        out.push(Finding {
            category: "unwired-prop",
            severity: 2,
            kit: kit.to_string(),
            node_ids: vec![n.id.clone()],
            node_names: vec![n.name.clone()],
            why: format!(
                "`{}` declares prop{} its source never uses: {} — a declared interface that does nothing",
                n.name,
                if unwired.len() == 1 { "" } else { "s" },
                unwired.join(", ")
            ),
            suggested_action: format!(
                "wire {} into `{}`'s implementation, or drop {} from its props",
                unwired.join(", "),
                n.name,
                if unwired.len() == 1 { "it" } else { "them" }
            ),
        });
    }

    // ── props-metadata-mismatch (severity 2): the record's `props[]` metadata disagrees with the prop
    // signature its OWN source declares (#88). The mismatch is purely mechanical — the metadata simply
    // does not reflect what the module destructures or types — but the preview's sample-data synthesizer
    // reads ONLY the metadata, so an EMPTY `props: []` on a component with a real typed signature silently
    // gives it nothing to synthesize and the component crashes on its first unguarded prop read. Four such
    // records were found ONE AT A TIME chasing individual render errors, because nothing could ask the
    // question in bulk; asked over the whole kit it partitions the render-error backlog into "fixable by
    // populating metadata" and "needs the infra fix".
    //
    // The conservatism is the check: [`signature_props`] returns `None` for anything it cannot read off
    // this source alone, so an imported props type, an untyped `props` parameter or a `memo(…)` wrapper
    // produces NOTHING rather than a guess. Built-ins are skipped (their `srcText` is an illustrative
    // snippet, not the module, #2794) as they are for phantom-compose. A rest element (`...rest`) means the
    // component can take props the signature does not name, so EXTRA metadata stops being reported for it —
    // only MISSING, which a rest element cannot explain away. Mirrors `graphHealth.ts`.
    for n in nodes {
        if n.builtin {
            continue;
        }
        let Some(src) = own_module_source(n, &kit_targets) else {
            continue; // built-in or spec-only — no module of ours to read the signature off
        };
        let Some(sig) = signature_props(src, &n.name) else {
            continue; // not knowable from this source — say nothing
        };
        let declared: BTreeSet<&str> = n.props.iter().map(|p| p.0.as_str()).collect();
        let missing: Vec<&str> =
            sig.names.iter().map(String::as_str).filter(|s| !declared.contains(s)).collect();
        let extra: Vec<&str> = if sig.has_rest {
            Vec::new()
        } else {
            declared.iter().copied().filter(|d| !sig.names.contains(*d)).collect()
        };
        if missing.is_empty() && extra.is_empty() {
            continue;
        }
        // `unwired-prop` (#2924) ALREADY owns the case where the only disagreement is metadata naming props
        // the source never uses at all — same evidence, same fix ("drop it from `props`"), so saying it a
        // second time would only double the noise. This check speaks when the signature itself is out of
        // sync: something is MISSING from the metadata, or an extra name IS referenced by the source (a
        // parse/metadata disagreement rather than a dead declaration).
        if missing.is_empty() && !extra.iter().any(|e| contains_word(src, e)) {
            continue;
        }
        // The load-bearing case gets its own prose: an empty `props` is not "a bit out of date", it is the
        // one state that disables the sampler outright.
        let (why, suggested_action) = if declared.is_empty() {
            (
                format!(
                    "`{}` carries NO props metadata while its own signature declares {}: {} — the preview's sample-data synthesizer reads `props`, so it has nothing to synthesize and the component renders with every prop undefined",
                    n.name,
                    missing.len(),
                    missing.join(", ")
                ),
                format!(
                    "populate `{}`'s `props` from its signature ({}) so the preview can sample it",
                    n.id,
                    missing.join(", ")
                ),
            )
        } else {
            let mut parts = Vec::new();
            if !missing.is_empty() {
                parts.push(format!(
                    "missing {} (in the signature, absent from `props`)",
                    missing.join(", ")
                ));
            }
            if !extra.is_empty() {
                parts.push(format!("extra {} (in `props`, absent from the signature)", extra.join(", ")));
            }
            let mut fixes = Vec::new();
            if !missing.is_empty() {
                fixes.push(format!("add {}", missing.join(", ")));
            }
            if !extra.is_empty() {
                fixes.push(format!("drop {}", extra.join(", ")));
            }
            (
                format!(
                    "`{}`'s props metadata disagrees with the signature its own source declares: {}",
                    n.name,
                    parts.join("; ")
                ),
                format!(
                    "{} in `{}`'s `props` so the metadata matches its signature — the preview samples from `props`, not from the source",
                    fixes.join(" and "),
                    n.id
                ),
            )
        };
        out.push(Finding {
            category: "props-metadata-mismatch",
            severity: 2,
            kit: kit.to_string(),
            node_ids: vec![n.id.clone()],
            node_names: vec![n.name.clone()],
            why,
            suggested_action,
        });
    }

    // ── skips-family-shell (severity 2, a REPORT not a rule): the members of a family that do NOT compose
    // the shell the rest of it does (#87). A family is a folder or a trailing-PascalCase-word group; a
    // shell is any component the family composes at or above [`FAMILY_SHELL_SHARE`] and that its kit
    // composes widely.
    //
    // This is the question `dupes`/`similar` structurally CANNOT answer, and the cost of answering it by
    // hand is measured: a ~480k-token fork reading a dozen srcTexts. Fuzzy name + prop-contract distance
    // never sees "shares a shell primitive", because the two components' props are unrelated — a toggle
    // card has `enabled`/`onToggle` and an info card has `value`/`label`, so none of the 51 card-suffixed
    // ids ever appeared together in a dupes report. What answered it in ONE call was `bsc ui used-by
    // ui-card`: the healthy majority separated from the single real outlier. This is that call, run for
    // every family at once. Mirrors `graphHealth.ts`.
    let mut families: BTreeMap<(&str, String), Vec<&&Node>> = BTreeMap::new();
    for n in nodes {
        if !n.folder.trim().is_empty() {
            families.entry(("folder", n.folder.trim().to_string())).or_default().push(n);
        }
        if let Some(suffix) = name_suffix(&n.name) {
            families.entry(("name suffix", suffix)).or_default().push(n);
        }
    }
    // How many DISTINCT in-kit components compose each name — the `used-by` count this check is built on.
    let mut composers_in_kit: BTreeMap<&str, usize> = BTreeMap::new();
    for n in nodes {
        for dep in n.composes.iter().collect::<BTreeSet<_>>() {
            *composers_in_kit.entry(dep.as_str()).or_insert(0) += 1;
        }
    }
    // A component's folder family and its name-suffix family usually overlap, so both groupings can reach
    // the SAME (shell, outliers) verdict. That is one fact, and it is reported once — keyed here and, since
    // `families` is ordered and "folder" sorts before "name suffix", attributed to the more specific
    // grouping. Without this the flagship case reports twice, which is the noise the check exists to end.
    let mut already: BTreeSet<(String, Vec<String>)> = BTreeSet::new();
    for ((grouping, key), members) in &families {
        if members.len() < FAMILY_MIN {
            continue;
        }
        let mut within: BTreeMap<&str, usize> = BTreeMap::new();
        for m in members {
            for dep in m.composes.iter().collect::<BTreeSet<_>>() {
                *within.entry(dep.as_str()).or_insert(0) += 1;
            }
        }
        for (shell, composed_by) in &within {
            if composers_in_kit.get(shell).copied().unwrap_or(0) < FAMILY_SHELL_COMPOSERS_MIN {
                continue; // not a widely-composed primitive — an accident of two siblings sharing a helper
            }
            if (*composed_by as f64) < FAMILY_SHELL_SHARE * members.len() as f64 {
                continue; // not the family's shell; a minority convention is not a standard to hold others to
            }
            // The shell is never an outlier in its own family — it cannot compose itself.
            let outliers: Vec<&&Node> =
                members.iter().filter(|m| m.name != **shell && !m.composes.iter().any(|c| c == shell)).copied().collect();
            if outliers.is_empty() || outliers.len() > FAMILY_MAX_OUTLIERS {
                continue;
            }
            let ids: Vec<String> = outliers.iter().map(|n| n.id.clone()).collect();
            if !already.insert(((*shell).to_string(), ids)) {
                continue; // the other grouping already said this
            }
            let names: Vec<String> = outliers.iter().map(|n| n.name.clone()).collect();
            let one = outliers.len() == 1;
            out.push(Finding {
                category: "skips-family-shell",
                severity: 2,
                kit: kit.to_string(),
                node_ids: outliers.iter().map(|n| n.id.clone()).collect(),
                node_names: names.clone(),
                why: format!(
                    "{} of the {} components in the `{key}` {grouping} family compose `{shell}`; {} do{} not — the outlier{} of an otherwise consistent family",
                    composed_by,
                    members.len(),
                    names.join(", "),
                    if one { "es" } else { "" },
                    if one { "" } else { "s" },
                ),
                suggested_action: format!(
                    "read {} against a sibling that composes `{shell}` — {} likely hand-rolls the same shell instead of composing it. Either compose `{shell}` (the family's convention) or, if the difference is deliberate, leave it: this is a REPORT, not a rule",
                    names.join(", "),
                    if one { "it" } else { "they" },
                ),
            });
        }
    }

    // ── phantom-compose (severity 2): a component that DECLARES `composes` children its own source never
    // renders. The graph draws edges straight from `composes`, so a phantom edge claims a composition that
    // doesn't happen AND masks orphan detection (the phantom in-edge makes the child look used). Only
    // USER-authored components with own-module source: a built-in's store record is a contract catalog
    // (`source` stripped #2794, `srcText` an illustrative snippet), so scanning it would false-positive. A
    // SLOT-SHELL is exempt — its children legitimately arrive via a content slot. Mirrors graphHealth.ts (#3111).
    for n in nodes {
        if n.builtin || n.composes.is_empty() {
            continue;
        }
        let Some(src) = own_module_source(n, &kit_targets) else {
            continue; // no scannable module (a spec) → no-implementation owns it
        };
        if n.props.iter().any(|p| is_node_slot_prop(&p.0, &p.1)) {
            continue; // slot-shell: composes may arrive via a slot
        }
        let rendered = jsx_tag_names(src);
        if rendered.is_empty() {
            continue; // renders no JSX at all → a stub, not a phantom composition
        }
        let phantom: Vec<&str> =
            n.composes.iter().filter(|c| !rendered.contains(c.as_str())).map(String::as_str).collect();
        if phantom.is_empty() {
            continue;
        }
        let it = if phantom.len() == 1 { "it" } else { "them" };
        out.push(Finding {
            category: "phantom-compose",
            severity: 2,
            kit: kit.to_string(),
            node_ids: vec![n.id.clone()],
            node_names: vec![n.name.clone()],
            why: format!(
                "`{}` declares it composes {} but its source never renders {it} — a phantom composition edge (the graph draws a composition that doesn't happen, and the false edge hides the child from orphan detection)",
                n.name,
                phantom.join(", ")
            ),
            suggested_action: format!(
                "render {} in `{}`'s source, or drop {} from its `composes`",
                phantom.join(", "),
                n.name,
                if phantom.len() == 1 { "it" } else { "them" }
            ),
        });
    }

    // ── no-empty-state / no-loading-state / no-error-state (severity 1, INFORMATIONAL, #3135/#3555): the
    // preview's data-state switcher can only SHOW a state a component SUPPORTS. A DATA component (has a
    // collection/array prop), scanned from its own module source, is flagged when it lacks: (a) an EMPTY
    // render — no `EmptyState` and no `Array.isArray`/`.length` empty-guard; (b) a `loading`-family prop;
    // or (c) an `error`-family prop. Guides the designer session to add the missing state. Mirrors
    // `analyzeGraphHealth` (graphHealth.ts).
    for n in nodes {
        let Some(src) = own_module_source(n, &kit_targets) else {
            continue;
        };
        let collections: Vec<&str> =
            n.props.iter().filter(|p| is_collection_prop(&p.1)).map(|p| p.0.as_str()).collect();
        if collections.is_empty() {
            continue;
        }
        if !src.contains("EmptyState") && !src.contains("Array.isArray") && !src.contains(".length") {
            out.push(Finding {
                category: "no-empty-state",
                severity: 1,
                kit: kit.to_string(),
                node_ids: vec![n.id.clone()],
                node_names: vec![n.name.clone()],
                why: format!(
                    "`{}` takes data ({}) but renders no distinct EMPTY state (no EmptyState, no empty-data branch) — its empty preview shows the same as loaded",
                    n.name,
                    collections.join(", ")
                ),
                suggested_action: format!(
                    "add an EmptyState / empty-data render to `{}` so its empty state is viewable",
                    n.name
                ),
            });
        }
        if !n.props.iter().any(|p| is_loading_prop(&p.0, &p.1)) {
            out.push(Finding {
                category: "no-loading-state",
                severity: 1,
                kit: kit.to_string(),
                node_ids: vec![n.id.clone()],
                node_names: vec![n.name.clone()],
                why: format!(
                    "`{}` takes data ({}) but exposes no `loading` prop — the preview can't show its LOADING state",
                    n.name,
                    collections.join(", ")
                ),
                suggested_action: format!("add a boolean `loading` prop to `{}` that renders a skeleton", n.name),
            });
        }
        if !n.props.iter().any(|p| is_error_prop(&p.0, &p.1)) {
            out.push(Finding {
                category: "no-error-state",
                severity: 1,
                kit: kit.to_string(),
                node_ids: vec![n.id.clone()],
                node_names: vec![n.name.clone()],
                why: format!(
                    "`{}` takes data ({}) but exposes no `error` prop — the preview can't show its ERROR state",
                    n.name,
                    collections.join(", ")
                ),
                suggested_action: format!(
                    "add an `error` prop to `{}` (a message string or boolean) that renders an error state",
                    n.name
                ),
            });
        }
    }

    // ── no-analytics (severity 1, INFORMATIONAL, #3810): an INTERACTIVE component (exposes an action/event
    // prop the user can trigger) that declares NO analytics events. Instrumentation is a per-node data
    // CONTRACT — like the behavior/motion a node already carries — so every interactive node should
    // declare what it emits, and any app composed from these nodes is instrumented by construction.
    // Own-module (user-authored) only; built-ins are skipped (packaged separately). Mirrors the frontend
    // `analyzeGraphHealth` (graphHealth.ts).
    for n in nodes {
        if own_module_source(n, &kit_targets).is_none() {
            continue; // built-in / no user source — not the designer's to instrument in-session
        }
        if n.analytics_events > 0 {
            continue; // already declares events
        }
        let actions: Vec<&str> =
            n.props.iter().filter(|p| is_action_prop(&p.0, &p.1)).map(|p| p.0.as_str()).collect();
        if actions.is_empty() {
            continue; // not interactive — nothing to instrument
        }
        out.push(Finding {
            category: "no-analytics",
            severity: 1,
            kit: kit.to_string(),
            node_ids: vec![n.id.clone()],
            node_names: vec![n.name.clone()],
            why: format!(
                "`{}` is interactive ({}) but declares no analytics events — an app composed from it captures nothing when the user acts",
                n.name,
                actions.join(", ")
            ),
            suggested_action: format!(
                "add an `analytics` manifest to `{}` declaring the events it emits (e.g. a `click` event for its action) — data, not code",
                n.name
            ),
        });
    }

    // ── multi-component (severity 2, #doctor-flags-a-record-holding-more-than-one-component): a record
    // whose source defines SEVERAL top-level components. One record = one component is assumed by the id,
    // the preview, the `composes` graph, `rename`, `merge`, `similar` and this file's own reachability —
    // so every extra definition is invisible: no id, never previewed, never an edge, and carried off
    // silently by a merge. `settings-general` holds TWENTY-TWO; twenty-one of them cannot be reached.
    //
    // THE BAR IS 4, AND IT IS MEASURED, NOT GUESSED. Across the 568 records that carry source: 411 hold
    // exactly one, 69 hold two, 34 hold three — that shoulder is a component plus an ordinary local
    // helper, and flagging it would fire on a QUARTER of the store, which is noise wearing a finding's
    // clothes. From four upward there are 39 records (7%), and the tail is unambiguous: 22, 20, 18, 16.
    // If the bar ever moves, re-measure first — the number is only defensible against the distribution.
    for n in nodes {
        let Some(src) = own_module_source(n, &kit_targets) else {
            continue; // built-in or spec-only — no source of ours to read
        };
        let found = top_level_components(src);
        if found.len() < MULTI_COMPONENT_MIN {
            continue;
        }
        let extras: Vec<String> = found.iter().filter(|f| **f != n.name).cloned().collect();
        out.push(Finding {
            category: "multi-component",
            severity: 2,
            kit: kit.to_string(),
            node_ids: vec![n.id.clone()],
            node_names: vec![n.name.clone()],
            why: format!(
                "`{}` defines {} components in one record — {} beyond itself ({}{}). Only `{}` has an id, so the others never preview, never appear as a composes edge, and a merge would take them along invisibly",
                n.name,
                found.len(),
                extras.len(),
                extras.iter().take(4).cloned().collect::<Vec<_>>().join(", "),
                if extras.len() > 4 { format!(", +{} more", extras.len() - 4) } else { String::new() },
                n.name,
            ),
            suggested_action: format!(
                "split the extra components out of `{}` into their own records so the graph can see them — or, if they are genuinely private helpers, leave it: this is a REPORT, not a rule",
                n.name
            ),
        });
    }

    // ── multi-export (severity 2, #a-record-holds-one-item-not-a-module-of-them): a record whose module
    // EXPORTS a component other than itself. The library's rule is one record, one item — a `Card` record
    // exports `Card` and the things that decorate it (`CardProps`, `useCard`), not `ListItemCard`.
    //
    // It is a DIFFERENT question from `multi-component` above, which counts component DEFINITIONS whether
    // or not they are exported, and the two disagree in both directions:
    //   · `ttscard` DEFINES four components and exports one — `multi-component` fires, this does not, and
    //     this is right: `ToggleRow` is private, so no consumer can reach it. That is a composition
    //     observation (should the file be split?), not an API one.
    //   · `teams-canvas` defines ONE component and exports five items — `multi-component` cannot see it.
    //   · `projectsworkspace` exports 34 names (four `register*Platform` registrars, a manifest validator,
    //     a payload builder) and `hooksview` 22, and the definition count reports nothing on either.
    // They want opposite fixes — inline the helper versus extract the record — so they stay separate.
    //
    // NO MEASURED BAR HERE, because the sharpening is qualitative rather than numeric. Over the 505
    // records that carry source, 185 (37%) export more than one NAME and 99 (20%) more than one ITEM —
    // far too many to be a severity-2 finding, and most of that shoulder is a component plus one domain
    // type it genuinely owns (`Stepper` + `Stage`, `LogView` + `Commit`). Restricting the finding to a
    // foreign exported COMPONENT cuts it to 35 records (7%) with no arbitrary threshold, and every one of
    // them is a real case: `ui-field` ships `TextField`/`TextArea`/`SelectField`, and `textfield`,
    // `textarea` and `ui-field` each export a `Field`, which is how three records come to claim one name.
    // The wider item count is not lost — `bsc ui exports --all` ranks the whole store by it, unbounded.
    for n in nodes {
        let Some(src) = own_module_source(n, &kit_targets) else {
            continue; // built-in or spec-only — no source of ours to read
        };
        let defined: BTreeSet<String> = top_level_components(src).into_iter().collect();
        let surface = crate::exports::surface(src, &n.name, &defined);
        let foreign: Vec<String> = surface.foreign_components().iter().map(|e| e.name.clone()).collect();
        if foreign.is_empty() {
            continue;
        }
        out.push(Finding {
            category: "multi-export",
            severity: 2,
            kit: kit.to_string(),
            node_ids: vec![n.id.clone()],
            node_names: vec![n.name.clone()],
            why: format!(
                "`{}` exports {} component{} beyond itself ({}) — {} item{} in a record whose id names one. An exported sibling is reachable by import but invisible to everything keyed on the id: it has no record, never previews on its own, and is never a `composes` edge — even though the id-only mount now self-corrects, matching the export to the record's own name (#121-pickComponent-mounts-wrong-export) rather than picking whichever comes first in source order",
                n.name,
                foreign.len(),
                if foreign.len() == 1 { "" } else { "s" },
                foreign.join(", "),
                surface.items.len(),
                if surface.items.len() == 1 { "" } else { "s" },
            ),
            suggested_action: format!(
                "give {} {} own record{} and have `{}` reference {} — check `bsc ui similar` first, since a name this record exports may already exist elsewhere in the library",
                naming(&foreign),
                if foreign.len() == 1 { "its" } else { "each their" },
                if foreign.len() == 1 { "" } else { "s" },
                n.name,
                if foreign.len() == 1 { "it" } else { "them" },
            ),
        });
    }

    // ── no-tests (severity 1, INFORMATIONAL, #3878): an IMPLEMENTED own-module component that carries no
    // tests. Tests are a per-node data contract — the same shape as the analytics manifest one field over —
    // because once a component's source is a store record compiled at runtime, a test file under `src/**` is
    // no longer beside the thing it tests. #3833 is the cost of that drift: the Skills record ran on a
    // preview-grade transcription for days because the page still LOOKED right and git no longer held what
    // shipped.
    //
    // Deliberately narrow, so this stays a useful suggestion rather than a finding on every node:
    //   · built-ins are skipped — packaged separately, not the designer's to test in-session (as no-analytics);
    //   · a SPEC-ONLY node is skipped — it already earns `no-implementation`, and nagging for tests over code
    //     that does not exist would be a second finding for one cause;
    //   · only INTERACTIVE nodes are flagged, the same line `no-analytics` draws. A component you can ACT on
    //     is one whose behaviour can regress; a pure display primitive is covered by the render/preview
    //     checks instead. Scoping it this way was not the first instinct — flagging every implemented node
    //     lit up essentially the whole graph, which the test suite caught immediately. Widening later (pages
    //     first) is a one-line change if the noise proves worth it.
    for n in nodes {
        if own_module_source(n, &kit_targets).is_none() {
            continue; // built-in, or spec-only — no implementation of ours to cover
        }
        if n.tests > 0 {
            continue; // already carries its tests
        }
        if !n.props.iter().any(|p| is_action_prop(&p.0, &p.1)) {
            continue; // not interactive — nothing actable to regress
        }
        out.push(Finding {
            category: "no-tests",
            severity: 1,
            kit: kit.to_string(),
            node_ids: vec![n.id.clone()],
            node_names: vec![n.name.clone()],
            why: format!(
                "`{}` is interactive and implemented but carries no tests — its source lives in the graph while anything covering it does not, so the node can be revised with nothing to catch a regression",
                n.name
            ),
            suggested_action: format!(
                "add a `tests` manifest to `{}` — an array of `{{ name, src }}`, data alongside the node like its analytics events",
                n.name
            ),
        });
    }

    // ── slot-shell (severity 1, INFORMATIONAL): a composite whose composed children arrive via ReactNode
    // CONTENT SLOTS. Standalone (no slots passed) it renders a demo/placeholder fallback, not its
    // assembled function — so a preview looks non-functional even though it isn't (#2921). Explains e.g.
    // GraphExplorerPage / AnalyticsPage. Detect: it `composes` ≥1 child AND exposes ≥1 non-`children`
    // ReactNode slot prop. Mirrors the frontend `analyzeGraphHealth` (graphHealth.ts).
    for n in nodes {
        if n.composes.is_empty() {
            continue;
        }
        let slots: Vec<&str> =
            n.props.iter().filter(|p| is_node_slot_prop(&p.0, &p.1)).map(|p| p.0.as_str()).collect();
        if slots.is_empty() {
            continue;
        }
        out.push(Finding {
            category: "slot-shell",
            severity: 1,
            kit: kit.to_string(),
            node_ids: vec![n.id.clone()],
            node_names: vec![n.name.clone()],
            why: format!(
                "`{}` is a slot-driven composite — its composed children ({}) arrive via content slots ({}), so a standalone preview renders a demo placeholder, not its assembled function",
                n.name,
                n.composes.join(", "),
                slots.join(", ")
            ),
            suggested_action: format!(
                "to preview `{}`'s real function, fill its slots ({}) with instances of the components it composes ({})",
                n.name,
                slots.join(", "),
                n.composes.join(", ")
            ),
        });
    }
}

/// Collect every id reachable from `start` along `out_ids` (DFS, cycle-safe via the visited set).
fn collect_reachable<'a>(
    start: &'a str,
    out_ids: &BTreeMap<&'a str, Vec<&'a str>>,
    visited: &mut BTreeSet<&'a str>,
) {
    if !visited.insert(start) {
        return;
    }
    if let Some(deps) = out_ids.get(start) {
        for &d in deps {
            collect_reachable(d, out_ids, visited);
        }
    }
}

/// Tarjan's strongly-connected components over the resolved `composes` edges — the SCCs of size > 1
/// (and self-loops) are the cycles. Deterministic: nodes are visited in the input order.
fn strongly_connected<'a>(nodes: &[&'a Node], out_ids: &BTreeMap<&'a str, Vec<&'a str>>) -> Vec<Vec<&'a str>> {
    struct T<'a> {
        idx: BTreeMap<&'a str, usize>,
        low: BTreeMap<&'a str, usize>,
        on_stack: BTreeSet<&'a str>,
        stack: Vec<&'a str>,
        counter: usize,
        sccs: Vec<Vec<&'a str>>,
    }
    fn strong<'a>(v: &'a str, out_ids: &BTreeMap<&'a str, Vec<&'a str>>, t: &mut T<'a>) {
        t.idx.insert(v, t.counter);
        t.low.insert(v, t.counter);
        t.counter += 1;
        t.stack.push(v);
        t.on_stack.insert(v);
        if let Some(deps) = out_ids.get(v) {
            for &w in deps {
                if !t.idx.contains_key(w) {
                    strong(w, out_ids, t);
                    let lw = t.low[w];
                    let e = t.low.get_mut(v).unwrap();
                    *e = (*e).min(lw);
                } else if t.on_stack.contains(w) {
                    let iw = t.idx[w];
                    let e = t.low.get_mut(v).unwrap();
                    *e = (*e).min(iw);
                }
            }
        }
        if t.low[v] == t.idx[v] {
            let mut comp = Vec::new();
            while let Some(w) = t.stack.pop() {
                t.on_stack.remove(w);
                comp.push(w);
                if w == v {
                    break;
                }
            }
            t.sccs.push(comp);
        }
    }
    let mut t = T {
        idx: BTreeMap::new(),
        low: BTreeMap::new(),
        on_stack: BTreeSet::new(),
        stack: Vec::new(),
        counter: 0,
        sccs: Vec::new(),
    };
    for n in nodes {
        if !t.idx.contains_key(n.id.as_str()) {
            strong(n.id.as_str(), out_ids, &mut t);
        }
    }
    t.sccs
}

// ── motion checks (#3163, `bsc ui doctor --motion`) ──────────────────────────────────────────────────
// Four MECHANICAL faults an author used to hand-diagnose from a broken preview, surfaced from the data.
// They scan a component's INLINE animation defs (the object entries of `animations`; a name-ref string
// points at the shared kit library, which the doctor doesn't resolve, so it's skipped) against its
// rendered markup (`source` + `srcText`). The TS twin is `analyzeMotion` (graphHealth.ts) — keep both in
// lockstep (categories, severities, rules, the collision pass). Reported through the SAME `Finding` shape
// as the topology checks, so the CLI merges them under `--motion`.

/// The INLINE animation defs on a component's `animations` array — the object entries with a string
/// `name` (a name-ref string is skipped). Mirrors TS `inlineAnimations`.
fn inline_animations(v: &Value) -> Vec<&Value> {
    v.get("animations")
        .and_then(Value::as_array)
        .map(|a| {
            a.iter()
                .filter(|e| e.is_object() && e.get("name").and_then(Value::as_str).is_some())
                .collect()
        })
        .unwrap_or_default()
}

/// The class HOOK tokens a `selector` targets — every `.<ident>` (`ident` = `[A-Za-z0-9_-]+`). Mirrors
/// the TS `selectorClasses` regex `/\.([A-Za-z0-9_-]+)/g`. #3163 check (a).
fn selector_classes(selector: &str) -> Vec<String> {
    let bytes = selector.as_bytes();
    let is_tok = |c: u8| (c as char).is_ascii_alphanumeric() || c == b'-' || c == b'_';
    let mut out = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'.' {
            let start = i + 1;
            let mut k = start;
            while k < bytes.len() && is_tok(bytes[k]) {
                k += 1;
            }
            if k > start {
                out.push(selector[start..k].to_string());
            }
            i = k.max(start); // past the token (or the lone `.`)
        } else {
            i += 1;
        }
    }
    out
}

/// The set of CSS declaration PROPERTIES an animation's keyframes touch. Mirrors TS `keyframeProps`.
fn keyframe_props(anim: &Value) -> BTreeSet<String> {
    let mut props = BTreeSet::new();
    if let Some(kf) = anim.get("keyframes").and_then(Value::as_object) {
        for decls in kf.values() {
            if let Some(obj) = decls.as_object() {
                for p in obj.keys() {
                    props.insert(p.clone());
                }
            }
        }
    }
    props
}

/// Whether `markup` contains an SVG `transform=` ATTRIBUTE — the literal `transform`, optional
/// whitespace, then `=` (mirrors the TS `/transform\s*=/`, substring, no word boundary). Distinct from a
/// CSS `transform:` declaration. #3163 check (c).
fn has_transform_attr(markup: &str) -> bool {
    let bytes = markup.as_bytes();
    let needle = b"transform";
    let mut i = 0;
    while i + needle.len() <= bytes.len() {
        if &bytes[i..i + needle.len()] == needle {
            let mut j = i + needle.len();
            while j < bytes.len() && (bytes[j] as char).is_whitespace() {
                j += 1;
            }
            if j < bytes.len() && bytes[j] == b'=' {
                return true;
            }
        }
        i += 1;
    }
    false
}

/// Analyze components for MOTION-graph faults (#3163) — the `bsc ui doctor --motion` checks, the Rust
/// twin of `analyzeMotion` (graphHealth.ts). Ranked most-severe first (stable name tiebreak). Pure.
/// Four checks: (a) `motion-dead-selector` (an animation `selector` whose class hook the source never
/// renders) · (b) `motion-dash-no-pathlength` (a stroke-dash keyframe on a component with no `pathLength`)
/// · (c) `motion-transform-attr` (a CSS `transform` keyframe on a component using an SVG `transform=`
/// attribute) · (d) `motion-name-collision` (an inline animation NAME declared by 2+ components in a kit).
/// **name-collision** (#a-composes-target-can-name-two-records) — two or more records in ONE kit answer
/// to the same name, so a `composes` entry naming it is AMBIGUOUS.
///
/// # Why this needs its own detector
///
/// Nothing else can see it. `composes` resolution is a MEMBERSHIP test, not a lookup: `handles_by_kit`
/// builds a per-kit set of `{lowercased name} ∪ {lowercased id}` and `dangling_composes` only asks
/// whether a handle EXISTS, while [`analyze_with`]'s `dangling-composes-reference` flags a target that
/// "matches neither a name nor an id". A name owned by TWO records answers "yes, that resolves" to both
/// — and no caller ever learns there were two answers.
///
/// Where something must pick, the tie-break is arbitrary: `closure::Index::new` keeps the FIRST match,
/// matching the `components.find(…)` the runtime resolver runs over the same store order. So the winner
/// is whichever record store order happens to yield, which is not a decision anyone made.
///
/// And `duplicate`/`near-duplicate` cannot substitute, which is the trap worth naming: those detect
/// CONTENT similarity, while a name collision is dangerous precisely when the two records DIFFER.
/// Measured on the live library 2026-08-25 — 39 colliding names, of which `bsc ui dupes` reported 6.
///
/// # Scope
///
/// Per KIT, because `composes` only ever resolves within one kit — the same rule
/// `dangling-composes-reference` applies. Two kits may each carry a `Card`; that is not a collision.
///
/// SUPPRESSION TOMBSTONES ARE EXCLUDED. A `{id, suppressed: true}` row occupies an id so the seed
/// reconcile stops re-adding it; it is not a component and can never be the target of a `composes`
/// edge, so counting it would invent collisions that cannot be acted on.
///
/// Propose-only, and deliberately never fed to `--fix`: resolving a pair is curation (merge one into
/// the other, rename one, or keep both under distinct names) and needs judgement per pair.
pub fn analyze_name_collisions(components: &[Value]) -> Vec<Finding> {
    // (kit, lowercased name) -> the records answering to it, in store order.
    let mut by_handle: BTreeMap<(String, String), Vec<(String, String)>> = BTreeMap::new();
    for c in components {
        if c.get("suppressed").and_then(Value::as_bool).unwrap_or(false) {
            continue;
        }
        let Some(name) = c.get("name").and_then(Value::as_str).filter(|s| !s.trim().is_empty()) else {
            continue;
        };
        let Some(id) = c.get("id").and_then(Value::as_str).filter(|s| !s.trim().is_empty()) else {
            continue;
        };
        let kit = c.get("kitId").and_then(Value::as_str).unwrap_or_default().to_string();
        by_handle
            .entry((kit, name.to_lowercase()))
            .or_default()
            .push((id.to_string(), name.to_string()));
    }

    let mut out = Vec::new();
    for ((kit, _lc), members) in by_handle {
        if members.len() < 2 {
            continue;
        }
        let ids: Vec<String> = members.iter().map(|(i, _)| i.clone()).collect();
        let names: Vec<String> = members.iter().map(|(_, n)| n.clone()).collect();
        // The winner TODAY, stated rather than left to be discovered: first in store order.
        let winner = ids[0].clone();
        let display = names.first().cloned().unwrap_or_default();
        out.push(Finding {
            category: "name-collision",
            // Sev 3: it silently mis-resolves an edge rather than failing, so it outranks the
            // report-only findings and sits with the correctness class.
            severity: 3,
            kit: kit.clone(),
            node_ids: ids.clone(),
            node_names: names,
            why: format!(
                "{} records in kit '{}' answer to the name '{}' ({}), so a `composes` entry naming it is \
                 AMBIGUOUS — it resolves, but to whichever record comes first in store order ('{}'), which \
                 is not a decision anyone made. `dupes` cannot see this: it detects CONTENT similarity, and \
                 a name collision is most dangerous when the records DIFFER.",
                ids.len(), kit, display, ids.join(", "), winner
            ),
            suggested_action: format!(
                "decide which record owns the name '{display}': `bsc ui merge <from> <into>` if they are \
                 one component, `bsc ui rename <id> <NewName>` if they are two — then re-run to confirm \
                 zero. Inspect with `bsc ui similar {}`.",
                ids[0]
            ),
        });
    }
    out
}

pub fn analyze_motion(components: &[Value]) -> Vec<Finding> {
    let mut out: Vec<Finding> = Vec::new();
    // (d) per-kit collision groups: (kit, animName) → owners [(id, name)], deduped by id, insertion order.
    let mut collisions: BTreeMap<(String, String), Vec<(String, String)>> = BTreeMap::new();

    for v in components {
        let id = match v.get("id").and_then(Value::as_str) {
            Some(s) if !s.is_empty() => s.to_string(),
            _ => continue,
        };
        let name = {
            let n = s(v, "name");
            if n.is_empty() {
                id.clone()
            } else {
                n
            }
        };
        let kit = s(v, "kitId");
        let markup = format!("{}\n{}", s(v, "source"), s(v, "srcText"));
        let anims = inline_animations(v);
        if anims.is_empty() {
            continue;
        }
        for anim in &anims {
            let anim_name = s(anim, "name");
            let props = keyframe_props(anim);

            // (a) dead selector hook — the animation targets a class the source never renders.
            if let Some(selector) =
                anim.get("selector").and_then(Value::as_str).filter(|s| !s.is_empty())
            {
                let dead: Vec<String> = selector_classes(selector)
                    .into_iter()
                    .filter(|cls| !markup.contains(cls.as_str()))
                    .collect();
                if !dead.is_empty() {
                    let list = dead.iter().map(|d| format!("`.{d}`")).collect::<Vec<_>>().join(", ");
                    out.push(Finding {
                        category: "motion-dead-selector",
                        severity: 2,
                        kit: kit.clone(),
                        node_ids: vec![id.clone()],
                        node_names: vec![name.clone()],
                        why: format!(
                            "`{name}`'s animation `{anim_name}` targets {list} but its source renders no such element — the animation matches nothing (a dead selector hook)"
                        ),
                        suggested_action: format!(
                            "render the element `{anim_name}` targets in `{name}`'s source, or fix the animation's `selector`"
                        ),
                    });
                }
            }

            // (b) stroke-dash keyframe with no pathLength — a draw-in needs a known geometry length.
            let dash: Vec<&str> = props
                .iter()
                .filter(|p| p.as_str() == "stroke-dashoffset" || p.as_str() == "stroke-dasharray")
                .map(String::as_str)
                .collect();
            if !dash.is_empty() && !markup.to_ascii_lowercase().contains("pathlength") {
                let list = dash.iter().map(|d| format!("`{d}`")).collect::<Vec<_>>().join(", ");
                out.push(Finding {
                    category: "motion-dash-no-pathlength",
                    severity: 1,
                    kit: kit.clone(),
                    node_ids: vec![id.clone()],
                    node_names: vec![name.clone()],
                    why: format!(
                        "`{name}`'s animation `{anim_name}` animates {list} but its source sets no `pathLength` — a stroke-dash draw needs a known path length to animate predictably"
                    ),
                    suggested_action: format!(
                        "set `pathLength` on the animated path in `{name}` so its stroke-dash draw has a stable length"
                    ),
                });
            }

            // (c) CSS transform keyframe on a transform-ATTRIBUTED SVG element — the two don't compose.
            if props.contains("transform") && has_transform_attr(&markup) {
                out.push(Finding {
                    category: "motion-transform-attr",
                    severity: 1,
                    kit: kit.clone(),
                    node_ids: vec![id.clone()],
                    node_names: vec![name.clone()],
                    why: format!(
                        "`{name}`'s animation `{anim_name}` sets a CSS `transform` keyframe, but its source uses an SVG `transform=` ATTRIBUTE — CSS transforms and the SVG transform attribute don't compose (animate the attribute, or drop the attribute and transform via CSS)"
                    ),
                    suggested_action: format!(
                        "move the transform in `{name}` to CSS (drop the SVG `transform=` attribute), or animate the attribute instead of a CSS `transform` keyframe"
                    ),
                });
            }

            // (d) collect this inline name for the cross-component collision pass.
            if !anim_name.is_empty() {
                let owners = collisions.entry((kit.clone(), anim_name.clone())).or_default();
                if !owners.iter().any(|(oid, _)| oid == &id) {
                    owners.push((id.clone(), name.clone()));
                }
            }
        }
    }

    // (d) an inline animation NAME declared by 2+ components in a kit — a cross-component collision.
    for ((kit, anim_name), owners) in &collisions {
        if owners.len() < 2 {
            continue;
        }
        let mut sorted = owners.clone();
        sorted.sort_by(|a, b| a.1.cmp(&b.1));
        let names: Vec<String> = sorted.iter().map(|(_, n)| n.clone()).collect();
        out.push(Finding {
            category: "motion-name-collision",
            severity: 2,
            kit: kit.clone(),
            node_ids: sorted.iter().map(|(i, _)| i.clone()).collect(),
            node_names: names.clone(),
            why: format!(
                "inline animation `{anim_name}` is declared by {} components ({}) — same-named keyframes across components collide; namespace them (#3163) or lift the shared one into the kit's animation library",
                owners.len(),
                names.join(", ")
            ),
            suggested_action: format!(
                "namespace the per-component animations (#3163), or lift `{anim_name}` into the kit's shared animation library and reference it by name from each component"
            ),
        });
    }

    out.sort_by(|a, b| {
        b.severity.cmp(&a.severity).then_with(|| a.node_names.first().cmp(&b.node_names.first()))
    });
    out
}

#[cfg(test)]
mod provides_resolution_tests {
    use super::*;

    /// A specifier no record provides and nothing registers — the control. If this ever resolves, the
    /// gate has stopped gating and every test below is vacuous.
    const UNKNOWN: &str = "@/features/nowhere/DoesNotExist";
    const PROVIDED_SPEC: &str = "@/features/planner/fleet/WorkerDetail";

    fn page_importing(spec: &str) -> String {
        format!("import {{ X }} from \"{spec}\";\nexport function P() {{ return <X />; }}\n")
    }

    // These share one process-global, so they run as a single test rather than racing each other.
    #[test]
    fn a_specifier_some_record_provides_resolves_like_it_does_at_runtime() {
        // BEFORE the store is opened: nothing is published, so the gate behaves exactly as it always did.
        set_provided_specifiers(std::collections::HashSet::new());
        assert_eq!(
            unresolved_specifiers(&page_importing(PROVIDED_SPEC)),
            vec![PROVIDED_SPEC.to_string()],
            "with no provides published this must still be unresolved",
        );

        // AFTER: the record that provides it makes it resolve — the #3660 graph-first path the loader
        // tries FIRST, and the one whose absence refused FleetPage/ProjectsPage/Planning post-cut.
        set_provided_specifiers(std::collections::HashSet::from([PROVIDED_SPEC.to_string()]));
        assert!(
            unresolved_specifiers(&page_importing(PROVIDED_SPEC)).is_empty(),
            "a provided specifier must resolve",
        );
        assert!(renders_at_runtime(&page_importing(PROVIDED_SPEC)));

        // …AND THE GATE DID NOT MERELY GET WEAKER. A specifier that resolves NOWHERE is still refused,
        // even with a populated provides-set — otherwise this fix would have turned a false rejection
        // into a silent acceptance, which is the worse trade for a write gate.
        assert_eq!(
            unresolved_specifiers(&page_importing(UNKNOWN)),
            vec![UNKNOWN.to_string()],
            "an unprovided, unregistered specifier must STILL be refused",
        );
        assert!(!renders_at_runtime(&page_importing(UNKNOWN)));

        // The same answer through the accessor `bsc ui harvest` asks, so a candidate whose dependency
        // has already been MIGRATED is reported buildable. Without it, promoting a keystone component
        // unblocks nothing that imports it and the migration cannot cascade.
        assert!(is_provided_specifier(PROVIDED_SPEC), "harvest must see what the loader resolves first");
        assert!(!is_provided_specifier(UNKNOWN));

        set_provided_specifiers(std::collections::HashSet::new());
        assert!(
            !is_provided_specifier(PROVIDED_SPEC),
            "and with nothing published it reports nothing — a tool that never opens a store is unaffected",
        );
    }

    /// bsc request #125: `doctor`'s no-implementation check (`is_preview_buildable` /
    /// `no_implementation_reasons`) had drifted behind the write-time gate above — it never consulted
    /// `is_provided_specifier`, so a component composing a hook the ALGORITHMS graph provides (exactly the
    /// shape `useCiWatcher`/`useFleetGithub`/`mcpCatalogView` take after being lifted out of `src/`) was
    /// condemned `no-implementation` even though the runtime loader resolves it and the app mounts it fine.
    /// Mirrors the TS twin's #83 fix (`componentBuildable`'s `graphResolver`/`makeGraphProvidesResolver`).
    #[test]
    fn a_provided_specifier_makes_the_composing_component_buildable_not_no_implementation() {
        let kit_targets = BTreeSet::new();
        let src = page_importing(PROVIDED_SPEC);

        set_provided_specifiers(std::collections::HashSet::new());
        assert!(
            !is_preview_buildable(&src, "src/features/x/X.tsx", &kit_targets),
            "control: unprovided, the import is genuinely unresolved"
        );
        let comps = [json!({
            "id":"x", "name":"X", "kitId":"react-ui", "role":"composite", "used":2,
            "src":"src/features/x/X.tsx", "srcText": src,
        })];
        let fs = analyze(&comps);
        assert!(
            fs.iter().any(|f| f.category == "no-implementation"),
            "control: flagged before the specifier is published: {fs:?}"
        );

        set_provided_specifiers(std::collections::HashSet::from([PROVIDED_SPEC.to_string()]));
        assert!(
            is_preview_buildable(&src, "src/features/x/X.tsx", &kit_targets),
            "a record-provided specifier makes the composing module buildable"
        );
        let fs = analyze(&comps);
        assert!(
            !fs.iter().any(|f| f.category == "no-implementation"),
            "must not be flagged once the algorithms graph provides the import: {fs:?}"
        );
        assert!(!fs.iter().any(|f| f.category == "unresolvable-import"), "resolvable: {fs:?}");

        set_provided_specifiers(std::collections::HashSet::new());
    }
}

#[cfg(test)]
mod tests {

    /// `declared_symbols` REPLACED `declares_symbol` in the two hot sweeps, so it has to answer the same
    /// question — including the predicate's quirks, which are what a hand-written set would get wrong.
    #[test]
    fn declared_symbols_agrees_with_declares_symbol_case_for_case() {
        let corpus = [
            "export function Box(props) { return null; }",
            "const Card = () => null;\nlet x = 1;\nvar y = 2;\nclass Thing {}",
            // No word boundary is required BEFORE the keyword — the predicate finds `function foo`
            // inside `myfunction foo`, so the set must too.
            "myfunction foo() {}",
            // A keyword followed by a non-identifier declares NOTHING to the predicate.
            "const { a, b } = obj;",
            "const  spaced = 1;",
            "",
            "function fibonacci(n) { return n; }\nconst fibonacci2 = 1;",
        ];
        // Every NON-EMPTY name: the empty one is the documented exception (see `declared_symbols`).
        let names = [
            "Box", "Card", "x", "y", "Thing", "foo", "a", "b", "obj", "spaced", "fibonacci",
            "fibonacci2", "nope", "unction",
        ];
        for src in corpus {
            let set = declared_symbols(src);
            // The documented exception, asserted so it is a KNOWN difference rather than an unexamined one.
            assert!(!set.contains(""), "a derived set never holds the empty name");
            for n in names {
                assert_eq!(
                    set.contains(n),
                    declares_symbol(src, n),
                    "disagreement on {n:?} in {src:?} — set={:?}",
                    {
                        let mut v: Vec<&str> = set.iter().copied().collect();
                        v.sort();
                        v
                    }
                );
            }
        }
    }

    /// ...and against the REAL library, which is the corpus that actually matters: a quirk the cases above
    /// miss would still have to survive 409 components of hand-written TSX.
    #[test]
    fn declared_symbols_agrees_with_declares_symbol_on_the_packaged_kit() {
        let artifact: Value =
            serde_json::from_str(packaged_kit_json()).expect("the packaged kit is valid JSON");
        let comps = artifact.get("components").and_then(Value::as_array).expect("components[]");
        let mut checked = 0usize;
        for c in comps.iter().take(120) {
            let Some(src) = c.get("source").and_then(Value::as_str).filter(|s| !s.is_empty()) else {
                continue;
            };
            let set = declared_symbols(src);
            // Every name the SET claims must satisfy the predicate...
            for n in &set {
                assert!(declares_symbol(src, n), "set claims {n:?} which the predicate denies");
                checked += 1;
            }
            // ...and a name the set lacks must be denied by it too, sampled over the other components'
            // names so the check is not vacuous on its own declarations.
            for other in comps.iter().take(40) {
                if let Some(name) = other.get("name").and_then(Value::as_str) {
                    if !set.contains(name) {
                        assert!(
                            !declares_symbol(src, name),
                            "predicate finds {name:?} which the set missed"
                        );
                        checked += 1;
                    }
                }
            }
        }
        assert!(checked > 500, "the corpus check was nearly vacuous: {checked} comparisons");
    }
    /// The scanner is the whole finding, so its CONSERVATISM is what is under test: it must see real
    /// siblings and must NOT see nested arrows, indented helpers, or non-function consts. A false
    /// positive here pushes someone to split a file that never needed splitting.
    #[test]
    fn top_level_components_counts_siblings_and_ignores_the_rest() {
        let src = r#"
import { x } from "y";
const TITLE = "not a component";
const rows = items.map((r) => <Row key={r.id} />);
function SettingsSection({ title }: { title: string }) {
  const Inner = () => <div />;
  return <div>{title}</div>;
}
export function GeneralPage() {
  return <SettingsSection title="x" />;
}
const ToggleRow = ({ on }: { on: boolean }) => <input checked={on} />;
export const StatusRow = (props: P) => <span {...props} />;
"#;
        let found = top_level_components(src);
        assert_eq!(found, vec!["SettingsSection", "GeneralPage", "ToggleRow", "StatusRow"],
                   "four siblings; `Inner` is indented, `TITLE`/`rows` are not components");
    }

    /// The bar is 4 because 2 and 3 are a component plus ordinary helpers — 25% of the store — and a
    /// finding that fires on a quarter of everything is noise. Pin the boundary so it cannot drift.
    #[test]
    fn the_multi_component_bar_sits_above_the_helper_shoulder() {
        assert_eq!(MULTI_COMPONENT_MIN, 4);
        let three = "function A() {}
function B() {}
function C() {}
";
        assert!(top_level_components(three).len() < MULTI_COMPONENT_MIN, "three does not fire");
        let four = format!("{three}function D() {{}}
");
        assert!(top_level_components(&four).len() >= MULTI_COMPONENT_MIN, "four does");
    }

    use super::*;
