    fn the_embedded_packaged_roster_is_populated() {
        // The buildability check reads the SAME react-ui.json the kit store + emit embed. If the include
        // path or the artifact shape drifts, the roster empties and every built-in would be falsely
        // flagged — so guard that it stays non-empty.
        assert!(!buildable_srcs().is_empty(), "the embedded react-ui artifact roster must not be empty");
    }

    // ── motion checks (#3163) — the Rust twin of `analyzeMotion` (graphHealth.ts) ────────────────────

    fn motion_cats(fs: &[Finding]) -> Vec<&str> {
        fs.iter().map(|f| f.category).collect()
    }

    #[test]
    fn motion_helpers_mirror_the_ts_twin() {
        assert_eq!(selector_classes(".bar .cell rect"), vec!["bar".to_string(), "cell".to_string()]);
        assert_eq!(selector_classes(".foo.bar"), vec!["foo".to_string(), "bar".to_string()]);
        assert!(selector_classes("rect").is_empty(), "a bare tag selector has no class hook");
        // `transform=` (attribute) is detected; a CSS `transform:` declaration is NOT.
        assert!(has_transform_attr("<g transform=\"translate(1,2)\">"));
        assert!(has_transform_attr("<g transform = \"x\">")); // optional whitespace like /transform\\s*=/
        assert!(!has_transform_attr("style={{ transform: 'rotate(1deg)' }}"));
    }

    #[test]
    fn flags_a_dead_animation_selector_hook_but_not_a_rendered_one() {
        // (a) `spin` targets `.bar`, but the source renders no such class → dead selector.
        let dead = json!({ "id": "chart", "name": "Chart", "kitId": "k",
            "source": "export function Chart(){ return <svg><rect/></svg>; }", "srcText": "",
            "animations": [{ "name": "spin", "selector": ".bar", "keyframes": { "from": { "transform": "scale(1)" } } }] });
        let fs = analyze_motion(std::slice::from_ref(&dead));
        assert!(motion_cats(&fs).contains(&"motion-dead-selector"), "flags a dead selector: {fs:?}");
        let f = fs.iter().find(|f| f.category == "motion-dead-selector").unwrap();
        assert_eq!(f.severity, 2);
        assert!(f.why.contains("`.bar`"), "names the dead class hook: {}", f.why);
        // A component that DOES render the `.bar` hook is not flagged.
        let live = json!({ "id": "chart2", "name": "Chart2", "kitId": "k",
            "source": "export function Chart2(){ return <svg><rect className=\"bar\"/></svg>; }", "srcText": "",
            "animations": [{ "name": "spin", "selector": ".bar", "keyframes": { "from": { "transform": "scale(1)" } } }] });
        assert!(!motion_cats(&analyze_motion(std::slice::from_ref(&live))).contains(&"motion-dead-selector"));
    }

    #[test]
    fn flags_a_stroke_dash_keyframe_without_pathlength() {
        // (b) a draw-in animating stroke-dashoffset, but the source sets no pathLength.
        let draw = json!({ "id": "p", "name": "Path", "kitId": "k",
            "source": "export function Path(){ return <svg><path d=\"M0 0\"/></svg>; }", "srcText": "",
            "animations": [{ "name": "draw", "keyframes": { "from": { "stroke-dashoffset": "100" }, "to": { "stroke-dashoffset": "0" } } }] });
        assert!(motion_cats(&analyze_motion(std::slice::from_ref(&draw))).contains(&"motion-dash-no-pathlength"));
        let f = analyze_motion(std::slice::from_ref(&draw));
        assert_eq!(f.iter().find(|f| f.category == "motion-dash-no-pathlength").unwrap().severity, 1);
        // With pathLength set, it is fine.
        let ok = json!({ "id": "p2", "name": "Path2", "kitId": "k",
            "source": "export function Path2(){ return <svg><path pathLength={1} d=\"M0 0\"/></svg>; }", "srcText": "",
            "animations": [{ "name": "draw", "keyframes": { "from": { "stroke-dashoffset": "100" } } }] });
        assert!(!motion_cats(&analyze_motion(std::slice::from_ref(&ok))).contains(&"motion-dash-no-pathlength"));
    }

    #[test]
    fn flags_a_css_transform_keyframe_fighting_an_svg_transform_attribute() {
        // (c) a CSS transform keyframe on a component that uses an SVG transform= ATTRIBUTE.
        let clash = json!({ "id": "g", "name": "Group", "kitId": "k",
            "source": "export function Group(){ return <svg><g transform=\"translate(4,4)\"><rect/></g></svg>; }", "srcText": "",
            "animations": [{ "name": "rot", "keyframes": { "from": { "transform": "rotate(0)" }, "to": { "transform": "rotate(90deg)" } } }] });
        assert!(motion_cats(&analyze_motion(std::slice::from_ref(&clash))).contains(&"motion-transform-attr"));
        // A CSS-only transform (no SVG transform attribute) is fine.
        let css_only = json!({ "id": "b", "name": "Box", "kitId": "k",
            "source": "export function Box(){ return <div className=\"box\"/>; }", "srcText": "",
            "animations": [{ "name": "rot", "keyframes": { "from": { "transform": "rotate(0)" } } }] });
        assert!(!motion_cats(&analyze_motion(std::slice::from_ref(&css_only))).contains(&"motion-transform-attr"));
    }

    #[test]
    fn flags_a_cross_component_inline_name_collision_but_not_a_shared_name_ref() {
        // (d) two components in one kit each declare an INLINE `draw` → a cross-component collision.
        let a = json!({ "id": "bar", "name": "Bar", "kitId": "k",
            "animations": [{ "name": "draw", "keyframes": { "from": { "opacity": "0" }, "to": { "opacity": "1" } } }] });
        let b = json!({ "id": "line", "name": "Line", "kitId": "k",
            "animations": [{ "name": "draw", "keyframes": { "from": { "opacity": "0" }, "to": { "opacity": "1" } } }] });
        let fs = analyze_motion(&[a, b]);
        let c = fs.iter().find(|f| f.category == "motion-name-collision").expect("collision flagged");
        assert_eq!(c.severity, 2);
        assert_eq!(c.node_names, vec!["Bar", "Line"]);
        assert_eq!(c.node_ids, vec!["bar", "line"]);
        assert!(c.why.contains("`draw`"), "names the colliding animation: {}", c.why);
        // Two components that NAME-REF the same kit animation (strings) are SHARING, not colliding.
        let x = json!({ "id": "x", "name": "X", "kitId": "k", "animations": ["draw"] });
        let y = json!({ "id": "y", "name": "Y", "kitId": "k", "animations": ["draw"] });
        assert!(!motion_cats(&analyze_motion(&[x, y])).contains(&"motion-name-collision"));
        // …and the collision is per-KIT — the same inline name in two DIFFERENT kits does not collide.
        let k1 = json!({ "id": "k1", "name": "K1", "kitId": "kit1", "animations": [{ "name": "draw", "keyframes": { "from": { "opacity": "0" } } }] });
        let k2 = json!({ "id": "k2", "name": "K2", "kitId": "kit2", "animations": [{ "name": "draw", "keyframes": { "from": { "opacity": "0" } } }] });
        assert!(!motion_cats(&analyze_motion(&[k1, k2])).contains(&"motion-name-collision"));
    }

    #[test]
    fn analyze_motion_is_empty_for_name_refs_or_no_animations() {
        let none = json!({ "id": "x", "name": "X", "kitId": "k", "source": "export default () => null;" });
        assert!(analyze_motion(std::slice::from_ref(&none)).is_empty());
        let refs = json!({ "id": "y", "name": "Y", "kitId": "k", "animations": ["fade-in", "pulse"] });
        assert!(analyze_motion(std::slice::from_ref(&refs)).is_empty(), "name-refs alone raise no motion finding");
    }

    #[test]
    fn render_error_findings_reports_each_errored_component_and_skips_the_unknown() {
        let comps = vec![
            json!({ "id": "bsc-keyvaluelist", "name": "BscKeyValueList", "kitId": "harvested",
                    "srcText": "export const BscKeyValueList = () => null;" }),
            json!({ "id": "bsc-dropdown", "name": "BscDropdown", "kitId": "harvested",
                    "srcText": "export const BscDropdown = () => null;" }),
        ];
        let errors = vec![
            ("bsc-keyvaluelist".to_string(), "Cannot read properties of undefined (reading 'map')".to_string(), "2026-08-24T19:48:22Z".to_string()),
            ("bsc-dropdown".to_string(), "trace line 1\n  at foo\n  at bar".to_string(), "2026-08-24T19:48:23Z".to_string()),
            ("ghost".to_string(), "not in the store — must be dropped".to_string(), "2026-08-24T19:48:24Z".to_string()),
        ];
        let f = render_error_findings(&comps, &errors);
        assert_eq!(f.len(), 2, "the stale `ghost` error is dropped");
        for x in &f {
            assert_eq!(x.category, "render-error");
            assert_eq!(x.severity, 5, "sorts above every static finding");
            assert_eq!(x.kit, "harvested");
        }
        let kvl = f.iter().find(|x| x.node_ids == ["bsc-keyvaluelist"]).unwrap();
        assert!(kvl.why.contains("reading 'map'"), "carries the real throw message");
        assert!(kvl.suggested_action.contains("bsc ui preview-props bsc-keyvaluelist"));
        // A multi-line stack trace is collapsed to one line in the summary.
        let dd = f.iter().find(|x| x.node_ids == ["bsc-dropdown"]).unwrap();
        assert!(!dd.why.contains('\n'), "the trace is flattened for the one-line finding");
    }

    #[test]
    fn render_error_findings_drops_a_stale_error_for_an_empty_srctext_component() {
        // #3737: a component reduced to an empty spec can't have a LIVE render error (the preview shows
        // no-implementation, not a throw), so a persisted error there is stale by definition. A non-empty
        // component keeps its recorded error.
        let comps = vec![
            json!({ "id": "empty", "name": "Empty", "kitId": "k", "srcText": "   " }),
            json!({ "id": "real", "name": "Real", "kitId": "k", "srcText": "export const Real = () => null;" }),
        ];
        let errors = vec![
            ("empty".to_string(), "no export Empty in @/x".to_string(), String::new()),
            ("real".to_string(), "threw at render".to_string(), String::new()),
        ];
        let f = render_error_findings(&comps, &errors);
        let ids: Vec<&str> = f.iter().flat_map(|x| x.node_ids.iter().map(String::as_str)).collect();
        assert!(!ids.contains(&"empty"), "the empty-srcText render-error is dropped as stale: {ids:?}");
        assert!(ids.contains(&"real"), "the non-empty component keeps its error: {ids:?}");
    }

    /// Designer request #101: six-plus doctor re-runs against ONE recorded line, read as "the fix did not
    /// take". The finding must say it is a replay, when it was observed, and what actually refreshes it.
    #[test]
    fn a_render_error_says_it_is_a_replay_and_names_what_refreshes_it() {
        let comps = vec![json!({
            "id": "console-pane-shell", "name": "PaneShell", "kitId": "base-studio-code",
            "role": "composite", "srcText": "export const PaneShell = () => null;",
        })];

        // A BUILD failure — the exact shape that cost #101 its afternoon.
        let errors = vec![(
            "console-pane-shell".to_string(),
            "build: preview: module not found: components/console-pane-menu".to_string(),
            "2026-08-24T19:48:22Z".to_string(),
        )];
        let f = render_error_findings(&comps, &errors);
        assert_eq!(f.len(), 1);
        let a = &f[0].suggested_action;
        assert!(a.contains("REPLAY"), "the finding must admit it is not a fresh check: {a}");
        assert!(a.contains("2026-08-24T19:48:22Z"), "and name WHEN it was observed: {a}");
        assert!(
            a.contains("RE-RUNNING IT CANNOT REFRESH THIS"),
            "the loop the reader will otherwise try must be ruled out explicitly: {a}",
        );
        assert!(
            a.contains("bsc navigate component base-studio-code console-pane-shell"),
            "and the verb that DOES refresh it must be spelled out, kit and id: {a}",
        );

        // The stamp is the LOG LINE's, never a clock read here — so the report is deterministic. Pinned by
        // asserting a second, different stamp round-trips rather than by asserting "some timestamp".
        let older = vec![(
            "console-pane-shell".to_string(),
            "render: TypeError: null is not an object".to_string(),
            "2026-01-02T03:04:05Z".to_string(),
        )];
        let g = render_error_findings(&comps, &older);
        assert!(g[0].suggested_action.contains("2026-01-02T03:04:05Z"), "{}", g[0].suggested_action);
        // ... and a RENDER throw keeps its own prose alongside the notice — the notice is additive.
        assert!(g[0].suggested_action.contains("bsc ui preview-props"), "{}", g[0].suggested_action);

        // A line with no `at` DEGRADES to the instruction alone. It must never print an empty "observed
        // at", and must never cost the finding — a preview failure with a malformed stamp is still a
        // preview failure.
        let undated = vec![(
            "console-pane-shell".to_string(),
            "build: boom".to_string(),
            String::new(),
        )];
        let h = render_error_findings(&comps, &undated);
        assert_eq!(h.len(), 1, "a blank `at` must not drop the finding");
        assert!(h[0].suggested_action.contains("REPLAY of a recorded observation"), "{}", h[0].suggested_action);
        assert!(!h[0].suggested_action.contains("observed at "), "no empty stamp: {}", h[0].suggested_action);
        assert!(h[0].suggested_action.contains("bsc navigate component base-studio-code console-pane-shell"));

        // A kit-less record still gets an actionable command — the id alone, not "` <id>`" with a hole.
        let kitless = vec![json!({
            "id": "loose", "name": "Loose", "role": "composite", "srcText": "export const Loose = () => null;",
        })];
        let k = render_error_findings(&kitless, &[("loose".to_string(), "build: x".to_string(), String::new())]);
        assert!(k[0].suggested_action.contains("bsc navigate component loose"), "{}", k[0].suggested_action);
        assert!(!k[0].suggested_action.contains("component  loose"), "no double space from an empty kit");

        // No RUN of spaces anywhere in the prose. This is not fussiness: the first cut of this notice
        // shipped with ten spaces mid-sentence, because a line-continuation collapsed wrong, and every
        // assertion above still passed — each one matches a fragment on ONE side of the gap. A finding is
        // read by a person and by an LLM; mangled whitespace in the middle of the actionable sentence is
        // the kind of defect that survives precisely because nothing asserts the shape of the whole.
        for f in [&f[0], &g[0], &h[0], &k[0]] {
            assert!(
                !f.suggested_action.contains("  "),
                "collapsed line-continuation left a space run: {:?}",
                f.suggested_action,
            );
        }
    }

    #[test]
    fn render_error_findings_is_empty_with_no_errors() {
        let comps = vec![json!({ "id": "a", "name": "A", "kitId": "k", "srcText": "export const A = () => null;" })];
        assert!(render_error_findings(&comps, &[]).is_empty());
    }

    #[test]
    fn render_error_findings_distinguishes_a_build_failure_from_a_render_throw() {
        let comps = vec![
            // Both carry a NON-EMPTY srcText on purpose: #3737 drops a persisted preview-error for a
            // component whose current srcText is empty (an empty spec can't have a live render error), so
            // a spec-only fixture here would be filtered as stale and this test would never reach the
            // build-vs-render prose it exists to pin.
            json!({ "id": "workspaceshellpage", "name": "WorkspaceShellPage", "kitId": "harvested",
                    "srcText": "export const WorkspaceShellPage = () => null;" }),
            json!({ "id": "bsc-dropdown", "name": "BscDropdown", "kitId": "harvested",
                    "srcText": "export const BscDropdown = () => null;" }),
        ];
        let errors = vec![
            // A `build:`-prefixed message (#3549) — the scan records esbuild failures too now.
            (
                "workspaceshellpage".to_string(),
                "build: Build failed with 1 error: mem:src/shared/ui/layouts:2:12: ERROR: Expected \"from\" but found \"{\"".to_string(),
                "2026-08-24T19:48:45Z".to_string(),
            ),
            ("bsc-dropdown".to_string(), "render: Cannot read properties of undefined".to_string(), String::new()),
        ];
        let f = render_error_findings(&comps, &errors);
        let ws = f.iter().find(|x| x.node_ids == ["workspaceshellpage"]).unwrap();
        assert!(ws.why.contains("failed to BUILD"), "build failures read as a build error, not a render throw");
        assert!(!ws.why.contains("build:"), "the kind prefix is stripped from the display message");
        assert!(ws.why.contains("Expected"), "carries the real esbuild message");
        assert!(ws.suggested_action.contains("--field srcText"), "build suggestion points at the source, not props");
        // The `render:`-prefixed one keeps the runtime prose + prop suggestion, prefix stripped.
        let dd = f.iter().find(|x| x.node_ids == ["bsc-dropdown"]).unwrap();
        assert!(dd.why.contains("threw when the preview rendered it"));
        assert!(!dd.why.contains("render:"), "the kind prefix is stripped");
        assert!(dd.suggested_action.contains("bsc ui preview-props"));
    }
}

#[cfg(test)]
mod name_collision_tests {
    use super::*;
    use serde_json::json;

    fn c(id: &str, name: &str, kit: &str) -> Value {
        json!({ "id": id, "name": name, "kitId": kit })
    }
    fn cats(fs: &[Finding]) -> Vec<&str> {
        fs.iter().map(|f| f.category).collect()
    }

    #[test]
    fn flags_two_records_in_one_kit_answering_to_one_name() {
        // The live shape this exists for: `accentcolorcard` and `settings-accentcolorcard`, both named
        // AccentColorCard, both in base-studio-code, and NOT duplicates (2469 vs 1816 bytes).
        let fs = analyze_name_collisions(&[
            c("accentcolorcard", "AccentColorCard", "base-studio-code"),
            c("settings-accentcolorcard", "AccentColorCard", "base-studio-code"),
            c("unrelated", "Sparkline", "base-studio-code"),
        ]);
        assert_eq!(cats(&fs), vec!["name-collision"], "exactly one finding: {fs:?}");
        assert_eq!(fs[0].node_ids, vec!["accentcolorcard", "settings-accentcolorcard"]);
        assert_eq!(fs[0].kit, "base-studio-code");
        assert!(fs[0].why.contains("first in store order"), "names the arbitrary winner: {}", fs[0].why);
    }

    #[test]
    fn one_name_per_kit_is_not_a_collision() {
        // `composes` only ever resolves within one kit, so two kits each carrying a `Card` is fine —
        // the same scoping rule `dangling-composes-reference` applies.
        let fs = analyze_name_collisions(&[
            c("card", "Card", "base-studio-code"),
            c("m-card", "Card", "mobile-studio-code"),
        ]);
        assert!(fs.is_empty(), "cross-kit same-name is not ambiguous: {fs:?}");
    }

    #[test]
    fn a_suppression_tombstone_never_creates_a_collision() {
        // A `{id, suppressed: true}` row occupies an id so the seed reconcile stops re-adding it. It is
        // not a component and can never be a `composes` target, so counting it would invent a collision
        // nobody can act on. The live store holds 12 such rows.
        let fs = analyze_name_collisions(&[
            c("card", "Card", "base-studio-code"),
            json!({ "id": "old-card", "name": "Card", "kitId": "base-studio-code", "suppressed": true }),
        ]);
        assert!(fs.is_empty(), "a tombstone is not a second answer: {fs:?}");
    }

    #[test]
    fn the_match_is_case_insensitive_because_composes_entries_arrive_lowercased() {
        // `handles_by_kit` folds both sides to lowercase (composes entries arrive lowercased via
        // `str_array`), so a collision that differs only in case is still a collision at resolve time.
        let fs = analyze_name_collisions(&[
            c("a", "SettingsRow", "k"),
            c("b", "settingsrow", "k"),
        ]);
        assert_eq!(cats(&fs), vec!["name-collision"], "case-folded: {fs:?}");
    }

    #[test]
    fn three_records_report_as_one_finding_naming_every_member() {
        let fs = analyze_name_collisions(&[c("a", "Row", "k"), c("b", "Row", "k"), c("c", "Row", "k")]);
        assert_eq!(fs.len(), 1, "N colliding records are ONE finding, not N-1 pairs");
        assert_eq!(fs[0].node_ids.len(), 3, "and it names every member: {:?}", fs[0].node_ids);
    }

    #[test]
    fn a_record_missing_a_name_or_id_is_skipped_rather_than_grouped_under_empty() {
        let fs = analyze_name_collisions(&[
            json!({ "id": "a", "kitId": "k" }),
            json!({ "id": "b", "kitId": "k" }),
            json!({ "name": "NoId", "kitId": "k" }),
            json!({ "name": "NoId2", "kitId": "k" }),
        ]);
        assert!(fs.is_empty(), "absent handles must not collide with each other: {fs:?}");
    }

    #[test]
    fn a_clean_library_reports_nothing() {
        let fs = analyze_name_collisions(&[c("a", "Alpha", "k"), c("b", "Beta", "k")]);
        assert!(fs.is_empty());
    }
}

implementations.code:
//! The motion COMPILER (#3163) — the Rust port of `compileAnimationsCss` (`src/shared/ui/kit/animations.ts`),
//! so `bsc ui kit emit-motion-css` can print the SAME compiled CSS an author's motion renders as: the
//! `@keyframes` blocks + the `prefers-reduced-motion`-guarded applying rules (+ delays + the per-element
//! stagger ramp) — the black box made inspectable.
//!
//! Like the frontend compiler this turns LLM-authored data into live CSS, so it carries the SAME closed
//! safety grammar (a kit/name must be a safe ident, a stop must be `from`/`to`/`N%`, a property must be
//! `[a-z-]+`, no value may inject CSS, a child `selector` must be selector-safe) and SKIPS anything that
//! fails — never emitting it. It also mirrors the #3163 component NAMESPACING: a def carrying a
//! `component` compiles to `bsc-<kit>-<component>-<name>` / `.<kit>-<component>-anim-<name>` so two
//! components' same-named animations don't collide. Kept in lockstep with animations.ts.

use serde_json::{Map, Value};

const DUR_DEFAULT: &str = "var(--dur-base)";
const EASE_DEFAULT: &str = "var(--ease-standard)";
/// Cap on the stagger nth-child ramp (mirrors animations.ts `STAGGER_MAX`).
const STAGGER_MAX: usize = 32;

/// A safe CSS identifier — `^[a-z][a-z0-9-]*$` (mirrors animations.ts `SAFE_IDENT`).
fn is_safe_ident(s: &str) -> bool {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) if c.is_ascii_lowercase() => {}
        _ => return false,
    }
    chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
}

/// A keyframe stop selector — `from`, `to`, or a 1–3 digit percentage (mirrors `SAFE_STOP`).
fn is_safe_stop(s: &str) -> bool {
    if s == "from" || s == "to" {
        return true;
    }
    match s.strip_suffix('%') {
        Some(num) => (1..=3).contains(&num.len()) && num.chars().all(|c| c.is_ascii_digit()),
        None => false,
    }
}

/// A CSS declaration property — `^[a-z-]+$`, non-empty (mirrors `SAFE_PROP`).
fn is_safe_prop(s: &str) -> bool {
    !s.is_empty() && s.chars().all(|c| c.is_ascii_lowercase() || c == '-')
}

/// A non-empty CHILD selector using ONLY selector-safe characters (mirrors `SAFE_SELECTOR`).
fn is_safe_selector(s: &str) -> bool {
    !s.is_empty()
        && s.chars().all(|c| {
            c.is_ascii_alphanumeric()
                || matches!(
                    c,
                    ' ' | '.' | '_' | '#' | '>' | '[' | ']' | '=' | '"' | '\'' | '-' | ':' | '(' | ')'
                        | ',' | '*' | '+' | '~'
                )
        })
}

/// A declaration/duration/easing VALUE that cannot end the declaration or inject CSS (mirrors `safeValue`).
fn is_safe_value(v: &str) -> bool {
    if v.is_empty() {
        return false;
    }
    if v.chars().any(|c| matches!(c, ';' | '{' | '}' | '<' | '>' | '\\')) {
        return false;
    }
    let lower = v.to_ascii_lowercase();
    !(lower.contains("url(") || lower.contains("expression(") || lower.contains("@import") || lower.contains("/*"))
}

/// Sanitize a component name into a safe CSS-identifier SEGMENT for keyframe/class namespacing (#3163) —
/// the exact mirror of animations.ts `identSegment`: lowercased, each maximal run of non-`[a-z0-9-]`
/// chars collapsed to a single `-`, leading/trailing `-` stripped; "" if the result isn't a safe ident.
fn ident_segment(s: &str) -> String {
    let lower = s.to_ascii_lowercase();
    let mut out = String::with_capacity(lower.len());
    let mut in_bad_run = false;
    for c in lower.chars() {
        if c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-' {
            out.push(c);
            in_bad_run = false;
        } else if !in_bad_run {
            out.push('-');
            in_bad_run = true;
        }
    }
    let slug = out.trim_matches('-');
    if is_safe_ident(slug) {
        slug.to_string()
    } else {
        String::new()
    }
}

fn get_str<'a>(v: &'a Value, key: &str) -> Option<&'a str> {
    v.get(key).and_then(Value::as_str)
}

/// The `@keyframes` NAME for a def — namespaced by `component` when one resolves (#3163).
fn keyframe_name(component: &str, kit: &str, name: &str) -> String {
    let seg = ident_segment(component);
    if seg.is_empty() {
        format!("bsc-{kit}-{name}")
    } else {
        format!("bsc-{kit}-{seg}-{name}")
    }
}

/// The applying CLASS hook for a def — the component-namespaced twin of {@link keyframe_name} (#3163).
fn class_name(component: &str, kit: &str, name: &str) -> String {
    let seg = ident_segment(component);
    if seg.is_empty() {
        format!("{kit}-anim-{name}")
    } else {
        format!("{kit}-{seg}-anim-{name}")
    }
}

/// Compile one animation's `@keyframes` block, or "" when no stop/declaration passes the guards.
fn keyframes_css(d: &Value, anim: &str) -> String {
    let mut stops: Vec<String> = Vec::new();
    if let Some(kf) = d.get("keyframes").and_then(Value::as_object) {
        for (stop, decls) in kf {
            if !is_safe_stop(stop) {
                continue;
            }
            let mut lines: Vec<String> = Vec::new();
            if let Some(obj) = decls.as_object() {
                for (prop, value) in obj {
                    if is_safe_prop(prop) {
                        if let Some(vs) = value.as_str() {
                            if is_safe_value(vs) {
                                lines.push(format!("    {prop}: {vs};"));
                            }
                        }
                    }
                }
            }
            if !lines.is_empty() {
                stops.push(format!("  {stop} {{\n{}\n  }}", lines.join("\n")));
            }
        }
    }
    if stops.is_empty() {
        String::new()
    } else {
        format!("@keyframes {anim} {{\n{}\n}}", stops.join("\n"))
    }
}

/// STATIC declarations (`set`) applied on the rule body — each guarded like a keyframe declaration.
fn set_css(d: &Value) -> String {
    let mut parts: Vec<String> = Vec::new();
    if let Some(set) = d.get("set").and_then(Value::as_object) {
        for (prop, value) in set {
            if is_safe_prop(prop) {
                if let Some(vs) = value.as_str() {
                    if is_safe_value(vs) {
                        parts.push(format!("{prop}: {vs};"));
                    }
                }
            }
        }
    }
    parts.join(" ")
}

/// Compile flat animation definitions (each a JSON object carrying `kit`, an optional `component`, and the
/// `KitAnimation` fields) into CSS — the Rust twin of `compileAnimationsCss`. Empty string when nothing is
/// renderable. Pure + guarded (skips any def failing the safety grammar).
pub fn compile_animations_css(defs: &[Value]) -> String {
    let mut blocks: Vec<String> = Vec::new();
    for d in defs {
        let kit = get_str(d, "kit").unwrap_or_default();
        let name = get_str(d, "name").unwrap_or_default();
        if !is_safe_ident(kit) || !is_safe_ident(name) {
            continue;
        }
        let component = get_str(d, "component").unwrap_or_default();
        let anim = keyframe_name(component, kit, name);
        let frames = keyframes_css(d, &anim);
        if frames.is_empty() {
            continue;
        }
        let dur = match get_str(d, "duration") {
            Some(s) if is_safe_value(s) => s,
            _ => DUR_DEFAULT,
        };
        let ease = match get_str(d, "easing") {
            Some(s) if is_safe_value(s) => s,
            _ => EASE_DEFAULT,
        };
        let delay = match get_str(d, "delay") {
            Some(s) if is_safe_value(s) => format!(" {s}"),
            _ => String::new(),
        };
        let cls = format!(".{}", class_name(component, kit, name));

        let selector = get_str(d, "selector").unwrap_or_default();
        let selector_ok = is_safe_selector(selector);
        let scoped = if selector_ok { format!("{cls} {}", selector.trim()) } else { cls };

        let trigger = get_str(d, "trigger").unwrap_or("mount");
        let rule = match trigger {
            "hover" => format!("{scoped}:hover"),
            "exit" => format!("{scoped}[data-bsc-exit]"),
            _ => scoped,
        };
        let iter = if trigger == "always" { "infinite" } else { "1" };

        let set = set_css(d);
        let prefix = if set.is_empty() { String::new() } else { format!("{set} ") };
        let body = format!("{prefix}animation: {anim} {dur} {ease}{delay} {iter} both;");

        // #3055 per-element stagger ramp: with a safe selector AND a safe stagger STEP, cascade the matched
        // elements by a bounded nth-child(2..STAGGER_MAX) animation-delay ramp after the base rule.
        let mut stagger_ramp = String::new();
        if selector_ok {
            let stagger = match get_str(d, "stagger") {
                Some(s) if is_safe_value(s) => Some(s),
                _ => None,
            };
            if let Some(step) = stagger {
                let base_term = match get_str(d, "delay") {
                    Some(s) if is_safe_value(s) => format!("{s} + "),
                    _ => String::new(),
                };
                let mut steps: Vec<String> = Vec::new();
                for k in 2..=STAGGER_MAX {
                    steps.push(format!(
                        "  {rule}:nth-child({k}) {{ animation-delay: calc({base_term}{} * {step}); }}",
                        k - 1
                    ));
                }
                stagger_ramp = format!("\n{}", steps.join("\n"));
            }
        }

        blocks.push(format!(
            "{frames}\n@media (prefers-reduced-motion: no-preference) {{\n  {rule} {{ {body} }}{stagger_ramp}\n}}"
        ));
    }
    blocks.join("\n\n")
}

/// Stamp `kit` (and optional owning `component`, #3163) onto an animation object, producing the flat
/// AnimationDef {@link compile_animations_css} consumes. A non-object anim yields `None` (skipped).
pub fn anim_def(anim: &Value, kit: &str, component: Option<&str>) -> Option<Value> {
    let obj = anim.as_object()?;
    let mut m: Map<String, Value> = obj.clone();
    m.insert("kit".to_string(), Value::String(kit.to_string()));
    if let Some(c) = component {
        m.insert("component".to_string(), Value::String(c.to_string()));
    }
    Some(Value::Object(m))
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn compiles_a_basic_animation_like_the_ts_twin() {
        let defs = [json!({ "kit": "react-ui", "name": "fade-in",
            "keyframes": { "from": { "opacity": "0" }, "to": { "opacity": "1" } } })];
        let css = compile_animations_css(&defs);
        assert!(css.contains("@keyframes bsc-react-ui-fade-in {"));
        assert!(css.contains("@media (prefers-reduced-motion: no-preference) {"));
        assert!(css.contains(
            ".react-ui-anim-fade-in { animation: bsc-react-ui-fade-in var(--dur-base) var(--ease-standard) 1 both; }"
        ));
    }

    #[test]
    fn namespaces_by_component_so_two_components_dont_collide() {
        let defs = [
            json!({ "kit": "react-ui", "name": "draw-in", "component": "BarChart", "keyframes": { "from": { "opacity": "0" } } }),
            json!({ "kit": "react-ui", "name": "draw-in", "component": "Sparkline", "keyframes": { "from": { "opacity": "1" } } }),
        ];
        let css = compile_animations_css(&defs);
        assert!(css.contains("@keyframes bsc-react-ui-barchart-draw-in {"));
        assert!(css.contains("@keyframes bsc-react-ui-sparkline-draw-in {"));
        assert!(css.contains(".react-ui-barchart-anim-draw-in { animation: bsc-react-ui-barchart-draw-in"));
        assert!(!css.contains("@keyframes bsc-react-ui-draw-in {"), "never the colliding un-namespaced form");
    }

    #[test]
    fn ident_segment_mirrors_the_ts_sanitizer() {
        assert_eq!(ident_segment("Sparkline"), "sparkline");
        assert_eq!(ident_segment("Bar Chart"), "bar-chart");
        assert_eq!(ident_segment("BarChart"), "barchart");
        assert_eq!(ident_segment(""), "");
        assert_eq!(ident_segment("***"), "", "an all-unsafe name falls back to the un-namespaced form");
    }

    #[test]
    fn honors_trigger_selector_set_delay_and_stagger() {
        let hover = compile_animations_css(&[json!({ "kit": "react-ui", "name": "pulse", "trigger": "hover",
            "duration": "120ms", "easing": "var(--ease-emphasized)", "keyframes": { "from": { "opacity": "0" } } })]);
        assert!(hover.contains(".react-ui-anim-pulse:hover { animation: bsc-react-ui-pulse 120ms var(--ease-emphasized) 1 both; }"));

        let child = compile_animations_css(&[json!({ "kit": "react-ui", "name": "spin", "selector": ".icon",
            "set": { "transform-origin": "center" }, "keyframes": { "from": { "opacity": "0" } } })]);
        assert!(child.contains(".react-ui-anim-spin .icon { transform-origin: center; animation:"));

        let always = compile_animations_css(&[json!({ "kit": "react-ui", "name": "loop", "trigger": "always",
            "keyframes": { "from": { "opacity": "0" } } })]);
        assert!(always.contains("infinite both; }"));

        let wave = compile_animations_css(&[json!({ "kit": "react-ui", "name": "wave", "selector": ".cell",
            "stagger": "14ms", "keyframes": { "from": { "opacity": "0" } } })]);
        assert!(wave.contains(".react-ui-anim-wave .cell:nth-child(2) { animation-delay: calc(1 * 14ms); }"));
        assert!(wave.contains(".react-ui-anim-wave .cell:nth-child(32) { animation-delay: calc(31 * 14ms); }"));
        assert!(!wave.contains(":nth-child(33)"));
    }

    #[test]
    fn skips_unsafe_defs() {
        assert_eq!(
            compile_animations_css(&[json!({ "kit": "React-UI", "name": "x", "keyframes": { "from": { "opacity": "0" } } })]),
            ""
        );
        assert_eq!(
            compile_animations_css(&[json!({ "kit": "react-ui", "name": "x", "keyframes": { "from": { "opacity": "1; } a{" } } })]),
            ""
        );
        assert_eq!(compile_animations_css(&[]), "");
    }

    #[test]
    fn anim_def_stamps_kit_and_component() {
        let a = json!({ "name": "draw", "keyframes": { "from": { "opacity": "0" } } });
        let kit_def = anim_def(&a, "react-ui", None).unwrap();
        assert_eq!(kit_def.get("kit").and_then(Value::as_str), Some("react-ui"));
        assert!(kit_def.get("component").is_none());
        let comp_def = anim_def(&a, "react-ui", Some("BarChart")).unwrap();
        assert_eq!(comp_def.get("component").and_then(Value::as_str), Some("BarChart"));
        assert!(anim_def(&json!("a-name-ref"), "react-ui", None).is_none(), "a name-ref string yields no def");
    }
}

