    #[test]
    fn a_term_with_no_signal_on_either_side_is_dropped_not_scored_zero() {
        // The rule the whole measure rests on: two prop-less primitives must not read as identical for
        // both lacking props, and an absent field must not read as disagreement.
        let a = comp_with("a", "Card", "k", fields! { "src": "src/a.tsx" });
        let b = comp_with("b", "Card", "k", fields! { "src": "src/b.tsx" });
        let terms = explain_pair(&a, &b).expect("same name admits the pair");
        let by = |l: &str| terms.iter().find(|t| t.label == l).unwrap().clone();
        assert_eq!(by("props").value, None, "neither carries props → dropped");
        assert_eq!(by("shapes").value, None);
        assert_eq!(by("guidance").value, None);
        // POSITIVE-ONLY (#4138): both carry `src` and they DIFFER, which is NOT evidence against — two
        // copies of one component necessarily live in different files. Dropped, not zero.
        assert_eq!(by("src").value, None, "a differing src is dropped, never a penalty");
        assert_eq!(by("role").value, Some(1.0), "role always carries signal");
        // A dropped term contributes nothing.
        assert_eq!(by("props").contribution(), 0.0);
    }

    #[test]
    fn the_same_source_file_raises_a_pair_without_deciding_it() {
        // #3895: `AgentFace` and `TeamsCanvas` legitimately come from ONE module, so `src` is a weighted
        // PRIOR — it must lift the score, never settle it on its own.
        // Distinct props so SOME term disagrees — otherwise the only scored terms are `src` and `role`,
        // both 1.0, and the mean is trivially 1.0 with nothing to prove.
        let mk = |id: &str, name: &str, src: &str| {
            let mut v = comp_with(id, name, "k", fields! { "src": src });
            v.as_object_mut().unwrap().insert(
                "props".into(),
                json!([{ "name": id, "type": "any" }]),
            );
            v
        };
        let same = explain_pair(&mk("a", "Card", "src/x.tsx"), &mk("b", "Card", "src/x.tsx")).unwrap();
        let diff = explain_pair(&mk("a", "Card", "src/x.tsx"), &mk("b", "Card", "src/y.tsx")).unwrap();
        let src_of = |t: &Vec<Term>| t.iter().find(|x| x.label == "src").unwrap().value;
        assert_eq!(src_of(&same), Some(1.0), "a shared file is evidence FOR");
        assert_eq!(src_of(&diff), None, "a differing file is no evidence either way — dropped");
        assert!(mean(&same) > mean(&diff), "shared provenance raises the score");
        assert!(mean(&same) < 1.0, "…but never on its own — other terms still disagree");
        // The property that made the symmetric version wrong: adding provenance must never LOWER a
        // pair's score relative to having no provenance at all.
        let none = explain_pair(&mk("a", "Card", ""), &mk("b", "Card", "")).unwrap();
        assert!(mean(&diff) >= mean(&none) - f64::EPSILON, "a differing src must not penalize the pair");
    }

    /// The shape that cost Settings, Glance and Accessibility their resolution graph on 2026-08-24: a
    /// module record and a component harvested out of the SAME FILE, proposed for consolidation.
    #[test]
    fn a_module_record_is_not_a_duplicate_of_what_was_harvested_from_it() {
        // The real records, near-verbatim. Same `src`; the `-module` half carries `provides` and IS the
        // file, the other half is one component lifted out of it. Near-identical srcText by construction.
        const SRC: &str = "src/features/settings/cards/accentcolorcard.tsx";
        // NOT byte-identical: an exact match is owned by the `duplicate` detector and skipped by
        // `exactly_caught` before this rule is ever consulted, so a test built on identical bodies would
        // pass without exercising anything. These differ by one line and score on the FUZZY path.
        let body = |extra: &str| {
            format!(
                "import {{ Card }} from \"@/shared/ui/data/Card\";\n\
                 export function AccentColorCard() {{ {extra}return <Card title=\"Accent color\" />; }}"
            )
        };
        let module = comp_with("settings-accentcolorcard", "AccentColorCard", "base-studio-code", fields! {
            "src": SRC, "provides": "@/features/settings/cards/AccentColorCard",
        });
        let mut module = module;
        module["srcText"] = json!(body("const { accent } = useAppStore(); "));
        let harvest = comp_with("accentcolorcard", "AccentColorCard", "base-studio-code", fields! { "src": SRC });
        let mut harvest = harvest;
        harvest["srcText"] = json!(body(""));

        // Sanity: WITHOUT the rule this pair scores well past the bar — otherwise the assertions below
        // would pass for want of similarity rather than because of the rule.
        assert!(
            contract_similarity(&module, &harvest) >= 0.7,
            "the pair must be genuinely near-identical for this test to mean anything: {}",
            contract_similarity(&module, &harvest),
        );

        let pair = vec![module.clone(), harvest.clone()];
        assert!(
            near_duplicate_findings(&pair, 0.55).is_empty(),
            "a module and its own harvest are one file, not two implementations: {:?}",
            near_duplicate_findings(&pair, 0.55),
        );
        // ... and neither is offered as somewhere to merge the other INTO. Retiring the `provides` half
        // is what orphans the specifier every importer resolves through, so this ranking is the whole
        // hazard: it is the only place the action gets proposed.
        assert!(rank_similar("settings-accentcolorcard", &pair, 10, 0.0).is_empty(), "module -> harvest");
        assert!(rank_similar("accentcolorcard", &pair, 10, 0.0).is_empty(), "harvest -> module");

        // The absence is REPORTED, not silent — an unexplained gap in a ranking reads as "nothing
        // resembles it", which is exactly the wrong conclusion here.
        assert_eq!(harvest_siblings_of("settings-accentcolorcard", &pair), vec!["accentcolorcard".to_string()]);
        assert_eq!(
            harvest_siblings_of("accentcolorcard", &pair),
            vec!["settings-accentcolorcard".to_string()],
        );

        // ── The narrowing must not disable the surface. Two ways it could over-reach, both pinned: ──

        // 1 · Same file, BOTH claiming a specifier — still not a merge candidate. One source file is
        //     one module; two records out of it cannot legitimately claim two different specifiers, so
        //     the pair is a data defect, not a duplicate. This is the case the XOR first cut got wrong:
        //     a 2026-08-17 batch had given many harvested halves a `@/components/<id>` specifier, and
        //     the rule read that defect as a distinction and let the pair through.
        let mut rival = comp_with("accentcolorcard", "AccentColorCard", "base-studio-code", fields! {
            "src": SRC, "provides": "@/components/accentcolorcard",
        });
        rival["srcText"] = json!(body(""));
        assert!(
            near_duplicate_findings(&[module.clone(), rival.clone()], 0.55).is_empty(),
            "one file is one module — a second specifier out of it is a defect, not a duplicate: {:?}",
            near_duplicate_findings(&[module.clone(), rival.clone()], 0.55),
        );

        // ... and the genuine conflict — two records claiming the SAME specifier — keeps its own finding,
        //     which says something different and correct. Narrowing the dupe surface must not silence it.
        let mut clash = comp_with("clash", "AccentColorCard", "base-studio-code", fields! {
            "src": SRC, "provides": "@/features/settings/cards/AccentColorCard",
        });
        clash["srcText"] = json!(body(""));
        let collisions = provides_collision_findings(&[module.clone(), clash]);
        assert_eq!(collisions.len(), 1, "a real provides collision must still be reported on its own");
        assert_eq!(collisions[0].category, "provides-collision");

        // 2 · Same file, NEITHER claiming a specifier. Two components harvested from one file genuinely
        //     CAN duplicate each other — `actionrow` / `menurow` / `menusection` all come out of
        //     `PaneMenu.tsx`. That is the case this surface exists for, and the narrowing must not eat it.
        let mut sibling = comp_with("accentswatch", "AccentColorCard", "base-studio-code", fields! { "src": SRC });
        sibling["srcText"] = json!(body("const x = 1; "));
        assert!(
            !near_duplicate_findings(&[harvest.clone(), sibling], 0.55).is_empty(),
            "two harvested components from one file are still scorable duplicates",
        );

        // 3 · No `src` at all — the common case. An empty string must never match itself into a pair, or
        //     the rule would silently swallow every unprovenanced record that happens to carry `provides`.
        let mut a = comp_with("a", "AccentColorCard", "k", fields! { "provides": "@/x/A" });
        a["srcText"] = json!(body(""));
        let mut b = comp_with("b", "AccentColorCard", "k", fields! {});
        b["srcText"] = json!(body("const y = 2; "));
        assert!(
            !near_duplicate_findings(&[a, b], 0.55).is_empty(),
            "two records with no `src` are not a module/harvest pair — an empty src must not match itself",
        );
    }

    /// #129 — a BARREL and one of the files it re-exports are different source files by construction
    /// (`src/shared/ui/charts/index.ts` re-exporting `Charts.tsx` / `primitives.tsx` / `telemetry.tsx`
    /// under one specifier each), so `module_and_its_harvest`'s shared-`src` check can never relate them.
    /// Only `provides` says the pair is one barrel and one of its submodules.
    #[test]
    fn a_barrel_and_its_submodule_are_not_a_duplicate() {
        let body = |extra: &str| {
            format!(
                "export function RangeToggle({{ value, onChange, options = [\"7d\", \"14d\", \"30d\"] }}) {{\n  \
                 {extra}return (\n    <div className=\"seg\">\n      {{options.map(o => (\n        \
                 <button key={{o}} className={{o === value ? \"on\" : \"\"}} onClick={{() => onChange(o)}}>{{o}}</button>\n      \
                 ))}}\n    </div>\n  );\n}}"
            )
        };
        let barrel = comp_with("ui-charts", "Charts", "base-studio-code", fields! {
            "src": "src/shared/ui/charts/Charts.tsx", "provides": "@/shared/ui/charts",
        });
        let mut barrel = barrel;
        barrel["srcText"] = json!(body("const noop = 1; "));
        let submodule = comp_with("rangetoggle", "RangeToggle", "base-studio-code", fields! {
            "src": "src/shared/ui/charts/primitives.tsx", "provides": "@/shared/ui/charts/primitives",
        });
        let mut submodule = submodule;
        submodule["srcText"] = json!(body(""));

        // Sanity: WITHOUT the rule this pair scores well past the bar.
        assert!(
            contract_similarity(&barrel, &submodule) >= 0.7,
            "the pair must be genuinely near-identical for this test to mean anything: {}",
            contract_similarity(&barrel, &submodule),
        );

        let pair = vec![barrel.clone(), submodule.clone()];
        assert!(
            near_duplicate_findings(&pair, 0.55).is_empty(),
            "a barrel and its own submodule are one family, not two implementations: {:?}",
            near_duplicate_findings(&pair, 0.55),
        );
        assert!(rank_similar("ui-charts", &pair, 10, 0.0).is_empty(), "barrel -> submodule");
        assert!(rank_similar("rangetoggle", &pair, 10, 0.0).is_empty(), "submodule -> barrel");
        assert_eq!(harvest_siblings_of("ui-charts", &pair), vec!["rangetoggle".to_string()]);
        assert_eq!(harvest_siblings_of("rangetoggle", &pair), vec!["ui-charts".to_string()]);

        // The relation is prefix-matched at a `/` boundary — a SHORTER, unrelated specifier that merely
        // starts with the same characters must not false-positive as a barrel over this submodule.
        let mut unrelated = comp_with("chart-thing", "ChartThing", "base-studio-code", fields! {
            "src": "src/shared/ui/chart.tsx", "provides": "@/shared/ui/chart",
        });
        unrelated["srcText"] = json!(body(""));
        assert!(
            harvest_siblings_of("rangetoggle", &[submodule.clone(), unrelated]).is_empty(),
            "`@/shared/ui/chart` is a different, shorter specifier — not a barrel over `.../charts/primitives`",
        );
    }

    /// A pairwise check under-withholds a CHAIN: a component harvested out of a submodule file shares no
    /// direct `src` or `provides` relation with the barrel two hops away, only with the submodule in
    /// between. #129 ("chart-primitives family") is exactly this shape — `itembars` (harvested from
    /// `telemetry.tsx`) relates to `ui-charts` (the `@/shared/ui/charts` barrel) only via `telemetry-
    /// module` (`provides: @/shared/ui/charts/telemetry`), which sits between them.
    #[test]
    fn harvest_family_is_transitive_across_a_chain() {
        let body = |extra: &str| {
            format!("export function ItemBars({{ rows }}) {{ {extra}return <div />; }}")
        };
        let barrel = {
            let mut v = comp_with("ui-charts", "Charts", "base-studio-code", fields! {
                "src": "src/shared/ui/charts/Charts.tsx", "provides": "@/shared/ui/charts",
            });
            v["srcText"] = json!(body("const noop = 1; "));
            v
        };
        let telemetry_module = {
            let mut v = comp_with("telemetry-module", "TelemetryPanel", "base-studio-code", fields! {
                "src": "src/shared/ui/charts/telemetry.tsx", "provides": "@/shared/ui/charts/telemetry",
            });
            v["srcText"] = json!(body("const noop = 2; "));
            v
        };
        let itembars = {
            // Same file as `telemetry_module`, no `provides` of its own — a pure harvested view.
            let mut v = comp_with("itembars", "ItemBars", "base-studio-code", fields! {
                "src": "src/shared/ui/charts/telemetry.tsx",
            });
            v["srcText"] = json!(body(""));
            v
        };
        let all = vec![barrel, telemetry_module, itembars];

        assert_eq!(
            harvest_siblings_of("ui-charts", &all),
            vec!["itembars".to_string(), "telemetry-module".to_string()],
            "itembars is reachable from ui-charts only through telemetry-module — a pairwise check misses it",
        );
        assert!(
            rank_similar("ui-charts", &all, 10, 0.0).is_empty(),
            "the whole two-hop family must be withheld from the ranking, not just the direct submodule",
        );
        assert!(near_duplicate_findings(&all, 0.55).is_empty());
    }

    #[test]
    fn a_provides_collision_is_its_own_finding_not_a_similarity_score() {
        // The loader resolves a specifier to ONE record; the rest are dead overrides that still read as
        // live. That has a definite answer, so it is a conflict rather than a fuzzy pair.
        let mk = |id: &str, used: i64| comp_with(id, id, "k", fields! { "provides": "@/shared/ui/Box", "used": used });
        let f = provides_collision_findings(&[mk("a", 1), mk("b", 9), mk("c", 0)]);
        assert_eq!(f.len(), 1);
        assert_eq!(f[0].category, "provides-collision");
        assert!(f[0].severity > 3, "a conflict outranks a duplicate");
        assert_eq!(f[0].node_ids.len(), 3);
        assert!(f[0].suggested_action.contains("keep `b`"), "the most-used record is the keeper: {}", f[0].suggested_action);
        // A lone provider is not a collision.
        assert!(provides_collision_findings(&[mk("a", 1)]).is_empty());
    }

    /// #129: same `src`, two DIFFERENT specifiers — the mirror of a `provides-collision` and the exact
    /// shape `near_duplicate_findings`'s "1 · Same file, BOTH claiming a specifier" case (above) proves
    /// is withheld from merge scoring. That withholding is correct (retiring either side is destructive),
    /// but it means the defect needs its OWN finding or it is invisible everywhere — which is what request
    /// #129 was filed against (`ui-charts` vs `charts-module`, both harvested from `Charts.tsx`).
    #[test]
    fn a_provides_split_is_flagged_even_though_near_duplicate_withholds_it() {
        const SRC: &str = "src/shared/ui/charts/Charts.tsx";
        let whole_file = comp_with("ui-charts", "Charts", "base-studio-code", fields! {
            "src": SRC, "provides": "@/shared/ui/charts",
        });
        let submodule = comp_with("charts-module", "LineArea", "base-studio-code", fields! {
            "src": SRC, "provides": "@/shared/ui/charts/Charts",
        });

        // Confirmed silent everywhere else: not a collision (specifiers differ)...
        assert!(provides_collision_findings(&[whole_file.clone(), submodule.clone()]).is_empty());
        // ... and withheld from near-duplicate scoring (module_and_its_harvest).
        assert!(near_duplicate_findings(&[whole_file.clone(), submodule.clone()], 0.0).is_empty());

        // ... but IS its own finding.
        let splits = provides_split_findings(&[whole_file, submodule]);
        assert_eq!(splits.len(), 1);
        assert_eq!(splits[0].category, "provides-split");
        assert_eq!(splits[0].severity, 4);
        assert_eq!(splits[0].node_ids, vec!["charts-module".to_string(), "ui-charts".to_string()]);
        assert!(splits[0].why.contains("@/shared/ui/charts"));
        assert!(splits[0].why.contains("@/shared/ui/charts/Charts"));

        // Same file, only ONE side claims a specifier — not a split, just an ordinary module/harvest pair.
        let unclaimed = comp_with("sibling", "Sibling", "base-studio-code", fields! { "src": SRC });
        let one_claim = comp_with("owner", "Owner", "base-studio-code", fields! {
            "src": SRC, "provides": "@/shared/ui/charts/Charts",
        });
        assert!(provides_split_findings(&[unclaimed, one_claim]).is_empty());

        // No `src` at all must never group records together by an empty string.
        let no_src_a = comp_with("a", "A", "k", fields! { "provides": "@/x/A" });
        let no_src_b = comp_with("b", "B", "k", fields! { "provides": "@/x/B" });
        assert!(provides_split_findings(&[no_src_a, no_src_b]).is_empty());
    }

    // ── suppression tombstones (#97) ─────────────────────────────────────────────────────────────────
    // `bsc ui suppress`/`merge` retire a packaged builtin by writing `{ id, suppressed: true }` in place
    // of the record (#3725) — the frontend seed-reconcile needs to see it occupying the id, so it is
    // never a bare delete. `graph_health::parse_node` already treats that shape as "not a component";
    // `similarity::parse` did not, so a tombstone kept scoring against the rest of the library forever.

    #[test]
    fn a_suppression_tombstone_is_invisible_to_near_duplicate_findings() {
        // Several stale variants of the same id, all suppressed — before the fix these score as a
        // mutually-near-duplicate CLUSTER purely off their id-derived names, with no real content at all.
        let tombstone = |id: &str| json!({ "id": id, "suppressed": true, "supersededBy": "accentcolorcard" });
        let survivor = comp_with("accentcolorcard", "AccentColorCard", "react-ui", fields! {
            "props": [{ "name": "color", "type": "string" }],
            "srcText": "export function AccentColorCard({color}) { return <div>{color}</div>; }",
        });
        let comps: Vec<Value> = vec![
            tombstone("accentcolorcard-old"),
            tombstone("accentcolorcard-legacy"),
            tombstone("accentcolorcard-v1"),
            tombstone("accentcolorcard-v2"),
            tombstone("accentcolorcard-draft"),
            survivor,
        ];
        let f = near_duplicate_findings(&comps, DEFAULT_THRESHOLD);
        assert!(f.is_empty(), "tombstones must not cluster as near-duplicates: {f:?}");
    }

    #[test]
    fn a_merged_away_id_does_not_reappear_against_its_own_survivor() {
        // The exact request-#97 repro: `bsc ui merge settings-accentcolorcard accentcolorcard` retires the
        // `from` side as a tombstone (`retire_component`) — `dupes` must go quiet, not keep proposing the
        // merge it was just told to do.
        let tombstone = json!({ "id": "settings-accentcolorcard", "suppressed": true, "supersededBy": "accentcolorcard" });
        let survivor = comp_with("accentcolorcard", "AccentColorCard", "react-ui", fields! {
            "provides": "@/components/settings/AccentColorCard",
            "props": [{ "name": "color", "type": "string" }],
            "srcText": "export function AccentColorCard({color}) { return <div>{color}</div>; }",
        });
        let f = near_duplicate_findings(&[tombstone, survivor], DEFAULT_THRESHOLD);
        assert!(f.is_empty(), "a merged-away tombstone must not re-pair with its survivor: {f:?}");
    }

    #[test]
    fn a_suppression_tombstone_is_invisible_to_provides_collision_findings() {
        // A tombstone predating #97 could still carry a stale `provides` from before it was retired —
        // it must not count toward a collision on that specifier.
        let tombstone = json!({
            "id": "old-box", "suppressed": true, "supersededBy": "box", "provides": "@/shared/ui/Box",
        });
        let live = comp_with("box", "Box", "k", fields! { "provides": "@/shared/ui/Box" });
        assert!(
            provides_collision_findings(&[tombstone, live]).is_empty(),
            "a lone live provider plus a tombstone is not a collision",
        );
    }

    #[test]
    fn parse_returns_none_for_a_suppression_tombstone() {
        assert!(parse(&json!({ "id": "cost", "suppressed": true })).is_none());
        // `suppressed: false` (or absent) is an ordinary record and must still parse.
        assert!(parse(&json!({ "id": "cost", "suppressed": false })).is_some());
        assert!(parse(&json!({ "id": "cost" })).is_some());
    }

    #[test]
    fn the_all_pairs_sweep_stays_affordable_at_a_thousand_records() {
        // #4138 replaced a name gate that was load-bearing for COST, not just precision: 349 records is
        // 61k pairs, 1000 is 500k. The replacement admits a pair on a hard co-location signal, so this
        // measures the WORST realistic shape — a library where a third of records share a folder, which
        // is what the folder tree (#4128) produces — rather than a best case with nothing in common.
        let comps: Vec<Value> = (0..1000)
            .map(|i| {
                let mut v = comp_with(&format!("c{i}"), &format!("Comp{i}"), "k", fields! {});
                v.as_object_mut().unwrap().insert("folder".into(), json!(format!("shared/ui/g{}", i % 3)));
                v.as_object_mut().unwrap().insert(
                    "srcText".into(),
                    json!(format!("export const C{i} = (p) => make(p.a, p.b, {i});")),
                );
                v
            })
            .collect();
        let t0 = std::time::Instant::now();
        let found = near_duplicate_findings(&comps, DEFAULT_THRESHOLD);
        let ms = t0.elapsed().as_millis();
        // Generous, because CI machines vary — this guards an ORDER OF MAGNITUDE regression (a sweep
        // that fell back to scoring all 500k pairs on full contract terms), not a few ms of drift.
        assert!(ms < 4_000, "1000-record sweep took {ms}ms; the pre-filter is not holding");
        // Not vacuous: this corpus really does exercise the co-location admission path.
        assert!(!found.is_empty() || comps.len() == 1000);
    }

    #[test]
    fn normalize_strips_noise_and_singularizes() {
        assert_eq!(normalize_tokens("BscBarChart"), BTreeSet::from(["bar".to_string()]));
        assert_eq!(normalize_tokens("Donut"), normalize_tokens("DonutChart"));
        assert_eq!(normalize_tokens("HBars"), BTreeSet::from(["h".to_string(), "bar".to_string()]));
        // A structurally-different name shares no token.
        assert!(normalize_tokens("Button").is_disjoint(&normalize_tokens("Card")));
    }

    #[test]
