            max_magnitude: u16::from_be_bytes([b[8], b[9]]),
            max_index: b[10],
            tsf: u64::from_be_bytes(b[12..20].try_into().expect("8 bytes")),
            bins,
        });
        off += HT20_RECORD;
    }
    (out, None)
}

/// One channel's energy over a window, small enough for the wire.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ChannelSpectrum {
    pub freq_mhz: u16,
    /// How many sweeps were folded in. A spectrum from two sweeps and one from
    /// two thousand are different claims and must not render alike.
    pub sweeps: u32,
    pub noise_dbm: i8,
    /// Peak bin magnitude across the window — where interference shows.
    pub peak_magnitude: u16,
    /// Bin index of that peak, so a renderer can mark the offending frequency.
    pub peak_bin: u8,
    /// Per-bin maximum across the window. The max, not the mean: a brief
    /// microwave burst is exactly what this tier exists to catch, and averaging
    /// it against quiet sweeps is how it gets hidden.
    pub bin_max: [u8; HT20_BINS],
}

/// Fold many sweeps into one per-channel spectrum.
///
/// The reduction that makes Tier 3 fit a 20/s wire: ~666 samples per second in,
/// one record per channel per window out.
pub fn aggregate(samples: &[Sample]) -> Vec<ChannelSpectrum> {
    let mut by_freq: BTreeMap<u16, ChannelSpectrum> = BTreeMap::new();

    for s in samples {
        let e = by_freq.entry(s.freq_mhz).or_insert_with(|| ChannelSpectrum {
            freq_mhz: s.freq_mhz,
            sweeps: 0,
            noise_dbm: s.noise_dbm,
            peak_magnitude: 0,
            peak_bin: 0,
            bin_max: [0u8; HT20_BINS],
        });
        e.sweeps += 1;
        if s.max_magnitude > e.peak_magnitude {
            e.peak_magnitude = s.max_magnitude;
            e.peak_bin = s.max_index;
        }
        for (slot, v) in e.bin_max.iter_mut().zip(s.bins.iter()) {
            *slot = (*slot).max(*v);
        }
    }
    by_freq.into_values().collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn ht20(freq: u16, bins: [u8; HT20_BINS], max_mag: u16, max_idx: u8) -> Vec<u8> {
        let mut v = Vec::with_capacity(HT20_RECORD);
        v.push(TLV_HT20);
        v.extend_from_slice(&((HT20_RECORD - 3) as u16).to_be_bytes());
        v.push(1); // max_exp
        v.extend_from_slice(&freq.to_be_bytes());
        v.push(23u8); // rssi
        v.push((-95i8) as u8); // noise
        v.extend_from_slice(&max_mag.to_be_bytes());
        v.push(max_idx);
        v.push(0); // bitmap_weight
        v.extend_from_slice(&7u64.to_be_bytes());
        v.extend_from_slice(&bins);
        v
    }

    #[test]
    fn a_well_formed_record_decodes_every_field() {
        let mut bins = [0u8; HT20_BINS];
        bins[11] = 194;
        let (s, err) = decode(&ht20(2437, bins, 194, 11));
        assert!(err.is_none());
        assert_eq!(s.len(), 1);
        assert_eq!(s[0].freq_mhz, 2437);
        assert_eq!(s[0].noise_dbm, -95);
        assert_eq!(s[0].rssi, 23);
        assert_eq!(s[0].max_magnitude, 194);
        assert_eq!(s[0].max_index, 11);
        assert_eq!(s[0].bins[11], 194);
    }

    #[test]
    fn a_truncated_record_is_an_error_and_the_good_samples_survive() {
        let mut raw = ht20(2437, [1u8; HT20_BINS], 10, 0);
        raw.extend_from_slice(&ht20(2437, [2u8; HT20_BINS], 10, 0)[..40]); // cut short
        let (s, err) = decode(&raw);
        assert_eq!(s.len(), 1, "the intact record must still be returned");
        assert!(matches!(err, Some(SpectralError::Truncated { .. })), "{err:?}");
    }

    #[test]
    fn an_unknown_tlv_type_is_refused_rather_than_guessed_at() {
        // No resynchronisation marker exists in this stream, so guessing a
        // layout desynchronises everything after it.
        let mut raw = ht20(2437, [0u8; HT20_BINS], 1, 0);
        raw[0] = 9;
        let (s, err) = decode(&raw);
        assert!(s.is_empty());
        assert!(matches!(err, Some(SpectralError::UnknownType { kind: 9, .. })), "{err:?}");
    }

    #[test]
    fn a_bad_length_is_refused_rather_than_desynchronising_the_stream() {
        let mut raw = ht20(2437, [0u8; HT20_BINS], 1, 0);
        raw[1] = 0xff;
        raw[2] = 0xff;
        let (_, err) = decode(&raw);
        assert!(matches!(err, Some(SpectralError::LengthMismatch { .. })), "{err:?}");
    }

    #[test]
    fn aggregation_keeps_the_peak_not_the_mean() {
        // A brief microwave burst is exactly what this tier exists to catch,
        // and averaging it against quiet sweeps is how it gets hidden.
        let quiet = [5u8; HT20_BINS];
        let mut burst = [5u8; HT20_BINS];
        burst[30] = 250;
        let mut raw = Vec::new();
        for _ in 0..50 {
            raw.extend_from_slice(&ht20(2437, quiet, 10, 0));
        }
        raw.extend_from_slice(&ht20(2437, burst, 1514, 30));

        let (s, err) = decode(&raw);
        assert!(err.is_none());
        let agg = aggregate(&s);
        assert_eq!(agg.len(), 1);
        assert_eq!(agg[0].sweeps, 51, "the evidence count must travel with the spectrum");
        assert_eq!(agg[0].bin_max[30], 250, "one burst in fifty quiet sweeps must survive");
        assert_eq!(agg[0].peak_magnitude, 1514);
        assert_eq!(agg[0].peak_bin, 30, "a renderer must be able to mark the offending frequency");
    }

    #[test]
    fn separate_channels_aggregate_separately() {
        let mut raw = ht20(2437, [1u8; HT20_BINS], 10, 0);
        raw.extend_from_slice(&ht20(2412, [2u8; HT20_BINS], 20, 1));
        let (s, _) = decode(&raw);
        let agg = aggregate(&s);
        assert_eq!(agg.len(), 2);
        assert_eq!(agg[0].freq_mhz, 2412, "sorted by frequency for a stable render order");
        assert_eq!(agg[1].freq_mhz, 2437);
    }

    #[test]
    fn an_empty_read_yields_nothing_and_no_error() {
        let (s, err) = decode(&[]);
        assert!(s.is_empty());
        assert!(err.is_none(), "an empty read is not a malformed one");
        assert!(aggregate(&s).is_empty());
    }
}

//! The spectral decoder against a REAL capture from the rebuilt driver.
//!
//! `fixtures/ath9k-ht20-channel6.bin` is the first 200 records of a 252,928-byte
//! read from `spectral_scan0` on the monitor Pi's ALFA AR9271, channel 6
//! (2437 MHz), 2026-09-04 — taken minutes after `ath9k_htc` and `ath9k_common`
//! were rebuilt with `CONFIG_ATH9K_HTC_DEBUGFS` and `CONFIG_ATH9K_COMMON_SPECTRAL`,
//! on a kernel that shipped with both unset.
//!
//! Every other test of this decoder uses records I constructed, which proves
//! the decoder does what I intended. This one proves I understood the format
//! the hardware actually emits — and it is the only test that could have
//! caught a wrong field offset, since a wrong offset still produces
//! plausible-looking numbers.

use bsc_rf::spectral::{aggregate, decode, HT20_BINS, HT20_RECORD};

fn capture() -> Vec<u8> {
    std::fs::read(
        std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/ath9k-ht20-channel6.bin"),
    )
    .expect("the real capture fixture is readable")
}

#[test]
fn the_real_capture_decodes_completely_with_nothing_left_over() {
    let raw = capture();
    assert_eq!(raw.len() % HT20_RECORD, 0, "the capture is not a whole number of records");

    let (samples, err) = decode(&raw);
    assert!(err.is_none(), "real hardware output failed to decode: {err:?}");
    assert_eq!(
        samples.len(),
        raw.len() / HT20_RECORD,
        "decoded a different number of records than the byte length implies"
    );
    assert!(samples.len() >= 100, "only {} samples — too few to conclude anything", samples.len());
}

/// A wrong field offset still yields plausible numbers, so the values are
/// checked against what the radio was actually doing.
#[test]
fn the_decoded_fields_match_the_radios_real_state() {
    let (samples, _) = decode(&capture());

    // The radio was pinned to channel 6 before the capture.
    assert!(
        samples.iter().all(|s| s.freq_mhz == 2437),
        "every sample should report 2437 MHz; saw {:?}",
        samples.iter().map(|s| s.freq_mhz).collect::<std::collections::BTreeSet<_>>()
    );

    // A 2.4 GHz noise floor is around -90 to -100 dBm. A wrong offset here
    // would read some other byte and land far outside that.
    for s in &samples {
        assert!(
            (-110..=-70).contains(&(s.noise_dbm as i32)),
            "noise floor {} dBm is not physically plausible — likely a field offset error",
            s.noise_dbm
        );
    }

    // max_index must address a real bin.
    assert!(
        samples.iter().all(|s| (s.max_index as usize) < HT20_BINS),
        "max_index out of range for a 56-bin sample"
    );
}

/// The data must actually vary. A decoder reading a constant byte would give
/// identical samples and pass every structural check above.
#[test]
fn the_capture_carries_real_variation_and_not_a_constant() {
    let (samples, _) = decode(&capture());
    let mags: std::collections::BTreeSet<u16> = samples.iter().map(|s| s.max_magnitude).collect();
    assert!(
        mags.len() > 10,
        "only {} distinct max_magnitude values across {} samples — this looks like a \
         constant field being read, not real spectrum",
        mags.len(),
        samples.len()
    );
    let bins_vary = samples.iter().any(|s| {
        let first = s.bins[0];
        s.bins.iter().any(|b| *b != first)
    });
    assert!(bins_vary, "no sample has any variation across its 56 bins");
}

#[test]
fn aggregating_the_real_capture_produces_one_channel_and_keeps_the_peak() {
    let (samples, _) = decode(&capture());
    let agg = aggregate(&samples);

    assert_eq!(agg.len(), 1, "the capture was single-channel; got {} channels", agg.len());
    let c = &agg[0];
    assert_eq!(c.freq_mhz, 2437);
    assert_eq!(c.sweeps as usize, samples.len(), "every sweep must be counted as evidence");

    // The aggregate peak must equal the real maximum, not an average of it.
    let true_peak = samples.iter().map(|s| s.max_magnitude).max().unwrap();
    assert_eq!(c.peak_magnitude, true_peak, "aggregation lost the peak");

    // And per-bin maxima must dominate every individual sweep.
    for s in &samples {
        for (i, b) in s.bins.iter().enumerate() {
            assert!(c.bin_max[i] >= *b, "bin {i}: aggregate {} < sample {}", c.bin_max[i], b);
        }
    }
}

/// The reduction that makes Tier 3 fit the wire, measured on real data.
#[test]
fn aggregation_reduces_the_real_capture_by_orders_of_magnitude() {
    let (samples, _) = decode(&capture());
    let agg = aggregate(&samples);
    assert!(
        samples.len() / agg.len() > 100,
        "aggregation only reduced {} samples to {} records — the full capture runs at \
         ~666 samples/sec against a 20/s wire, so the reduction has to be large",
        samples.len(),
        agg.len()
    );
}

