//! Tree-sitter COMPONENT harvest (#3471, epic #3087) — the component half of `bsc graph harvest`
//! (`bsc-graph/src/extract.rs`). Parse a repo's real `.tsx`/`.ts` source and lift each React component
//! into a CANDIDATE component record, so a project that gets built FILLS the component graph instead of
//! the library being hand-authored one `bsc ui set` at a time. Deterministic + zero egress: tree-sitter
//! parses locally, no network, and the walk is order-stable (sorted traversal). It EMITS candidates
//! only — storing them is the curation gate, never here.
//!
//! ── WHY THIS IS NOT A COPY OF THE ALGORITHMS HARVEST ─────────────────────────────────────────────────
//! `graph harvest` lifts a function's node text verbatim, which is fine for a self-contained algorithm.
//! A React component is NOT self-contained: its module has imports, type declarations and sibling
//! helpers, and its stored `srcText` must be a module the preview can actually COMPILE. So this
//! extractor computes a CLOSURE — the component, plus the same-file declarations it transitively
//! references, plus exactly the imports those need — rather than a node slice.
//!
//! And it says so when it fails. A `srcText` that keeps unresolved `@/…` imports USED to be stored with
//! no complaint at all (#3470: `looks_buildable_module` returned false, which made the syntax gate SKIP),
//! surfacing much later as an unbuildable component; `bsc ui set` now warns with these same reasons. So every candidate carries an honest `buildable`
//! flag with reasons; a candidate that could not be closed is emitted flagged, never quietly degraded.
//!
//! ── SIBLING IMPORTS ARE COMPOSITION, NOT DAMAGE ──────────────────────────────────────────────────────
//! A harvest is a SET, and the preview knows it: `componentPreviewFiles` (componentPreview.ts, #3112 —
//! mirrored by `graph_health::is_preview_buildable`) vendors the transitive closure of the SIBLINGS a
//! component imports into its build, so an internal import that lands on a sibling of the same kit is
//! resolvable. Judging each candidate alone therefore under-reports, measurably: harvesting this repo's
//! own `src/shared/ui` produced 93 candidates of which 51 were `buildable: false` purely for `@/…`
//! imports — and 129 of the 150 `@/…` specifiers in that harvest pointed at OTHER components in it. So
//! buildability is decided against the in-set candidates: an `@/…` import that lands on a harvested
//! sibling MODULE is a `composes` edge, not a defect. Anything else — app state, a store, a feature's
//! logic, a shared hook — still makes the candidate unbuildable, with its reason naming the specifier.
//! Same harvest after: 76 of 93 buildable, and every one of the 17 remaining is held back by a genuine
//! non-component module (`@/shared/hooks/useDragResize`, `@/shared/lib/core/format`, …).

use std::collections::{BTreeSet, HashSet};
use std::path::{Path, PathBuf};
use tree_sitter::{Language, Node, Parser};

/// A candidate component harvested from real source (#3471) — the store's component-record shape, so
/// the curation gate can review it straight into the library via `bsc ui set`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Candidate {
    /// Candidate id — the store's convention is the lowercased name with separators dropped
    /// (`AnalyticsPage` → `analyticspage`), matching the records already in the library.
    pub id: String,
    /// The component's source name, verbatim (`Button`, `BarChart`).
    pub name: String,
    /// The kit this candidate would join (`--kit`, else [`DEFAULT_KIT`]).
    pub kit_id: String,
    /// `"primitive"` | `"composite"` | `"page"` — the #2863 role tier, by heuristic.
    pub role: &'static str,
    /// NAMES of the other harvested components this one renders. The component graph composes by
    /// NAME, not by id (`graph_health::parse_node`) — deliberately unlike `graph harvest`'s id form.
    pub composes: Vec<String>,
    /// The component's source CLOSURE — a module, not a node slice (see the module docs).
    pub src_text: String,
    /// Repo-relative path the component was harvested from.
    pub src: String,
    /// Is `src_text` a module the preview could compile? Honest, and never silently assumed (#3470).
    pub buildable: bool,
    /// Why `buildable` is false — empty when it is true.
    pub unbuildable_reasons: Vec<String>,
    /// The reusability classification — library-worthy vs. project glue, with reasons.
    pub classification: Classification,
}

/// The kit a harvest lands in when `--kit` is not given. Deliberately NOT an existing kit: harvested
/// candidates are unreviewed, and defaulting them into `react-ui` would contaminate a curated kit.
pub const DEFAULT_KIT: &str = "harvested";

/// Path segments we never descend into — vendored deps, build output, VCS/tooling dirs.
const SKIP_DIRS: &[&str] = &["node_modules", "target", ".git", ".claude", "dist", "build"];

/// The reusability classification of a harvested candidate — mirrors the algorithms classifier's shape
/// (`bsc_graph::extract::Classification`) so the two pillars behave alike.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Classification {
    /// The candidate cleared the worthiness threshold (a net-positive score).
    pub worthy: bool,
    /// The weighted signal score.
    pub score: i32,
    /// One human-readable reason per signal that fired.
    pub reasons: Vec<String>,
}

/// Test/story files carry no production component. Extension-agnostic (#3571): the same `.test` / `.spec`
/// / `.stories` marker excludes a `.js`/`.jsx` test as well as a `.ts`/`.tsx` one. Checks the stem before
/// the final extension so `Foo.test.tsx` matches while `latest.tsx` (no dot before `test`) does not.
fn is_test_file(name: &str) -> bool {
    let stem = name.rsplit_once('.').map_or(name, |(s, _)| s);
    stem.ends_with(".test") || stem.ends_with(".spec") || stem.ends_with(".stories")
}

/// The store's component id for a source name — lowercased, non-alphanumerics dropped
/// (`AnalyticsPage` → `analyticspage`), matching the records already in the library.
fn component_id(name: &str) -> String {
    name.chars().filter(|c| c.is_ascii_alphanumeric()).collect::<String>().to_ascii_lowercase()
}

/// Is this a React COMPONENT name? React requires a capitalized identifier — a lowercase name is
/// treated as an intrinsic tag and can never be a component, so this is a real signal, not a style rule.
fn is_component_name(name: &str) -> bool {
    name.chars().next().is_some_and(|c| c.is_ascii_uppercase())
}

/// App-glue component names that aren't reusable library pieces.
const GLUE_NAMES: &[&str] = &["App", "Root", "Main", "Index", "Wrapper", "Provider", "Layout"];

fn is_glue_name(name: &str) -> bool {
    GLUE_NAMES.contains(&name) || name.ends_with("Provider") || name.ends_with("Context")
}

/// Does the closure render nothing but a single element with no logic? Nothing worth storing.
fn is_trivial(src_text: &str) -> bool {
    src_text.lines().filter(|l| {
        let t = l.trim();
        !t.is_empty() && !t.starts_with("//") && !t.starts_with("import ") && t != "}" && t != "{"
    }).count() <= 2
}

/// Classify a candidate's reusability: a weighted score over cheap, tree-sitter-derivable signals.
/// `worthy` when the score is net-positive (the curation gate reviews only these).
pub fn classify(c: &Candidate) -> Classification {
    let mut score = 0;
    let mut reasons = Vec::new();
    if !c.composes.is_empty() {
        score += 1;
        reasons.push(format!("composes {} component(s)", c.composes.len()));
    }
    if c.buildable {
        score += 1;
        reasons.push("self-contained module — compiles on its own".to_string());
    } else {
        score -= 1;
        reasons.push("not a self-contained module".to_string());
    }
    if is_glue_name(&c.name) {
        score -= 2;
        reasons.push("app-glue / provider name".to_string());
    }
    if is_trivial(&c.src_text) {
        score -= 2;
        reasons.push("trivial body — nothing to store".to_string());
    }
    Classification { worthy: score >= 1, score, reasons }
}

/// Resolve a source file to its tree-sitter language, or `None` for a file we don't parse.
fn language_for(path: &Path) -> Option<Language> {
    let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
    if is_test_file(name) {
        return None;
    }
    match path.extension().and_then(|e| e.to_str()).unwrap_or("") {
        // All four parse with the TSX grammar — a strict superset of JS+JSX+TS, so a `.ts`/`.js` file
        // that contains no JSX is parsed harmlessly and JS/JSX components are lifted just like TS ones.
        // Without `.jsx`/`.js` a JavaScript React project harvested to ZERO candidates (#3571).
        "ts" | "tsx" | "jsx" | "js" | "mjs" | "cjs" => Some(tree_sitter_typescript::LANGUAGE_TSX.into()),
        _ => None,
    }
}

/// Read + tree-sitter-parse `path`. `None` on an unparsable/unknown file or any read/parse error.
fn parse(path: &Path) -> Option<(Vec<u8>, tree_sitter::Tree)> {
    let language = language_for(path)?;
    let src = std::fs::read(path).ok()?;
    let mut parser = Parser::new();
    parser.set_language(&language).ok()?;
    let tree = parser.parse(&src, None)?;
    Some((src, tree))
}

/// Harvest `dir` into candidate components (#3471): every React component becomes a `Candidate`
/// carrying its source CLOSURE, a heuristic role, an honest `buildable` verdict, and the NAMES of the
/// other harvested components it renders (`composes`). Order-stable; skips vendored/build/VCS dirs and
/// test files. Storing candidates is the curation gate's job, not this function's.
pub fn harvest(dir: &Path, kit_id: &str) -> Vec<Candidate> {
    let mut found: Vec<Found> = Vec::new();
    walk(dir, dir, &mut found);
    build_candidates(found, kit_id)
}

/// Harvest a SINGLE file (#3722) — parse just `file` and lift its components, `composes` resolved within
/// the file. For targeting ONE component's module instead of a whole tree (and pairing with `--out` so a
/// large candidate's `srcText` is recoverable). A non-parseable path (a test/story file, a non-source
/// extension) yields no candidates, exactly as the dir walk skips it. The recorded `src` is the file's
/// own name — a single-file harvest has no root to make the path relative to.
pub fn harvest_file(file: &Path, kit_id: &str) -> Vec<Candidate> {
    let mut found: Vec<Found> = Vec::new();
    if let Some((src, tree)) = parse(file) {
        // The file's PATH, not its basename. Two things depended on this and both were broken by the
        // bare name: every stored record carries a full `src/…` path (it is what `bsc ui backing`,
        // `doctor` and `folder_from_src` key off, and a basename derives no folder and matches no file),
        // and a RELATIVE import has nothing to resolve against without the directory it was written in.
        let rel = file.to_string_lossy().replace('\\', "/");
        let rel = rel.strip_prefix("./").unwrap_or(&rel).to_string();
        collect_file(tree.root_node(), &src, &rel, &mut found);
    }
    build_candidates(found, kit_id)
}

/// Resolve `composes` edges + buildability across a harvested `Found` set and render each into a
/// `Candidate`. Shared by the directory [`harvest`] and the single-file [`harvest_file`], so both apply
/// the same in-set sibling resolution (a single file's siblings are simply the components defined beside
/// it in that one module).
fn build_candidates(found: Vec<Found>, kit_id: &str) -> Vec<Candidate> {
    // Which component NAMES were harvested, and from which MODULE — `composes` only links in-set
    // candidates, and a sibling import must agree on BOTH (see `SiblingIndex`).
    let mut in_set = SiblingIndex::default();
    for f in &found {
        in_set.0.entry(f.name.clone()).or_default().push(module_base(&f.src));
    }
    found
        .into_iter()
        .map(|f| {
            let imports = internal_imports(&f.src_text);
            // Rendered tags that are themselves harvested components, minus self-recursion.
            let mut composes: Vec<String> = Vec::new();
            for tag in &f.tags {
                if tag != &f.name && in_set.has(tag) && !composes.contains(tag) {
                    composes.push(tag.clone());
                }
            }
            // …plus the harvested siblings it IMPORTS. Usually the same set (you import what you render),
            // but a sibling handed on as a prop (`icon={Icon}`) or rendered through an alias is a real
            // composition edge that no JSX tag records — and the whole point of resolving sibling imports
            // is that they become edges rather than dangling.
            for name in imports.iter().flat_map(|i| &i.names) {
                if name != &f.name && in_set.has(name) && !composes.contains(name) {
                    composes.push(name.clone());
                }
            }
            let role = if f.name.ends_with("Page") {
                "page"
            } else if composes.is_empty() {
                "primitive"
            } else {
                "composite"
            };
            let (buildable, unbuildable_reasons) = buildability(&f.src_text, &imports, &in_set, &f.src);
            let mut c = Candidate {
                id: component_id(&f.name),
                name: f.name,
                kit_id: kit_id.to_string(),
                role,
                composes,
                src_text: f.src_text,
                src: f.src,
                buildable,
                unbuildable_reasons,
                classification: Classification::default(),
            };
            c.classification = classify(&c);
            c
        })
        .collect()
}

/// The names of TOP-LEVEL functional/algorithmic definitions under `path` that are NOT React components
/// (#3740) — named functions, and arrow-const utils/hooks. A component harvest lifts only PascalCase JSX
/// components, so these plain function/hook/util modules fall through silently; but they belong in the
/// ALGORITHMS graph (`bsc graph harvest`, which lifts exactly this shape). So `bsc ui harvest` surfaces
/// them (and points at `bsc graph harvest`) rather than dropping them between the two harvests. A
/// PascalCase name that renders JSX is a component (excluded); a data const (`export const x = {…}`) and a
/// component-internal local are correctly not listed (only top-level function-shaped defs). Handles a
/// single FILE or a DIR (#3722), order-stable + deduped, same dir/test-file skips as the component walk.
pub fn functional_module_names(path: &Path) -> Vec<String> {
    let mut out = Vec::new();
    if path.is_file() {
        if let Some((src, tree)) = parse(path) {
            collect_functional_defs(tree.root_node(), &src, &mut out);
        }
    } else {
        functional_walk(path, &mut out);
    }
    out.sort();
    out.dedup();
    out
}

fn functional_walk(dir: &Path, out: &mut Vec<String>) {
    let Ok(entries) = std::fs::read_dir(dir) else { return };
    let mut paths: Vec<PathBuf> = entries.filter_map(|e| e.ok()).map(|e| e.path()).collect();
    paths.sort();
    for path in paths {
        let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
        if path.is_dir() {
            if !SKIP_DIRS.contains(&name) && !is_nested_git_root(&path) {
                functional_walk(&path, out);
            }
        } else if let Some((src, tree)) = parse(&path) {
            collect_functional_defs(tree.root_node(), &src, out);
        }
    }
}

/// Collect the file's TOP-LEVEL (module-level) function/arrow-const definition names that are not
/// components — the reusable functional units. Only direct children of the module (optionally wrapped in
/// `export …`), never nested helpers, so the list is the module's public functional surface.
fn collect_functional_defs(root: Node, src: &[u8], out: &mut Vec<String>) {
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        let inner = if child.kind() == "export_statement" {
            child.named_child(0).unwrap_or(child)
        } else {
            child
        };
        match inner.kind() {
            "function_declaration" => {
                if let Some(name) = field_text(inner, "name", src) {
                    push_functional(name, inner, out);
                }
            }
            "lexical_declaration" | "variable_declaration" => {
                let mut c = inner.walk();
                for d in inner.children(&mut c) {
                    if d.kind() != "variable_declarator" {
                        continue;
                    }
                    // Only a def bound to a FUNCTION/ARROW is a functional module — a data const
                    // (`= {…}` / a value / a `call()` result) is not, and is correctly skipped.
                    let is_fn = d
                        .child_by_field_name("value")
                        .is_some_and(|v| matches!(v.kind(), "arrow_function" | "function" | "function_expression"));
                    if is_fn {
                        if let Some(name) = field_text(d, "name", src) {
                            push_functional(name, d, out);
                        }
                    }
                }
            }
            _ => {}
        }
    }
}

/// Push `name` as a functional module unless it is a React component (PascalCase + renders JSX — the
/// component harvest's job) or already collected. `node` is the def whose JSX is checked.
fn push_functional(name: String, node: Node, out: &mut Vec<String>) {
    let is_component = is_component_name(&name) && contains_jsx(node);
    if !(is_component || out.contains(&name)) {
        out.push(name);
    }
}

/// Is the closure a module the preview could compile, and if not, exactly why? The predicate mirrors
/// `bsc_component::graph_health::is_preview_buildable` (export present · no elision marker · no internal
/// import that resolves to nothing) but REPORTS its reasons instead of collapsing to a bool — the whole
/// point of #3470 is that "not buildable" must be a stated outcome, never a silent one.
///
/// `siblings` is what this harvest produced. An `@/…` import that lands on a sibling MODULE is NOT
/// counted against buildability — the preview vendors the closure of the siblings a component imports,
/// so that import resolves once the set is curated into one kit.
///
/// ── THE IMPORT IS KEPT IN `src_text`, NOT DROPPED ────────────────────────────────────────────────────
/// The other option was to elide a resolved sibling import from the emitted closure and lean on kit
/// resolution to supply the binding. It would be wrong, because that is not how the preview resolves a
/// sibling: `componentPreviewFiles` walks the source's OWN import specifiers (`importSpecs` → BFS),
/// resolves each against the sibling `src` paths (`resolveInternalBase`: `@/x` → `x`), and vendors the
/// modules it lands on. The import statement is therefore load-bearing TWICE — it is the only record of
/// which sibling to vendor, and it is what binds the identifier the JSX then renders. Drop it and esbuild
/// still bundles the module happily (a free identifier is just a global reference), so the candidate
/// would report `buildable: true` and then throw `ReferenceError: Button is not defined` at render —
/// trading an honest flag for a silent runtime failure, which is exactly the degradation this harvester
/// exists to prevent. Keeping the import also keeps the closure a faithful copy of the real source.
fn buildability(
    src_text: &str,
    imports: &[InternalImport],
    siblings: &SiblingIndex,
    from_rel: &str,
) -> (bool, Vec<String>) {
    let mut why = Vec::new();
    if !src_text.contains("export ") {
        why.push("no `export` — nothing for the preview to mount".to_string());
    }
    // The context-aware scanner now lives in the crate that owns the buildability predicates, so the
    // write-time gate and this harvest share ONE implementation rather than drifting copies (#3470).
    if bsc_component::graph_health::has_code_elision(src_text) {
        why.push("contains an elision marker (`…`) — a sketch, not code".to_string());
    }
    // A REGISTERED platform module is NOT unresolved (#4071). The runtime module registry resolves these
    // specifiers literally — the app mounts a record importing `@/store` or `@/shared/lib/core/format`
    // without complaint — so counting them against buildability flagged 116 of 351 candidates for
    // something that is not wrong. Same blind spot #3897 fixed in the doctor, one tool over, and the same
    // predicate is reused rather than a second copy of the registry.
    //
    // The import STAYS in `src_text`, exactly as it does for a resolved sibling: it is the binding the JSX
    // renders against, and the registry supplies it at load time. Nothing is vendored or stubbed — this
    // changes only whether the candidate is REPORTED buildable.
    let unresolved: BTreeSet<&str> = imports
        .iter()
        // A SYNTACTICALLY type-only import is erased by the tsx loader before anything resolves (#4076),
        // so the module it names need not be in the closure for the closure to compile. Counting it was
        // simply wrong — 45 of this repo's 289 unbuildable candidates were blocked by nothing else.
        .filter(|i| !i.type_only)
        .filter(|i| !i.is_sibling(siblings, from_rel))
        .filter(|i| !resolves_outside_the_set(&i.spec, from_rel))
        .map(|i| i.spec.as_str())
        .collect();
    if !unresolved.is_empty() {
        let list = unresolved.iter().map(|m| format!("`{m}`")).collect::<Vec<_>>().join(", ");
        why.push(format!("unresolved internal import(s): {list} — resolve or vendor them"));
    }
    (why.is_empty(), why)
}

/// Does `spec`, imported from `from_rel`, resolve to something OUTSIDE the harvested set — a record, or
/// a module the platform registry declares?
///
/// This is the runtime resolver's own chain, and harvest has to run it or the two disagree: a candidate
/// certified `buildable: true` here then reporting `no-implementation` in `doctor`, with nothing to say
/// why. A RECORD comes first, exactly as `resolveGraphSource` puts it first — a dependency that has
/// already been migrated is resolvable by definition, and that is what lets a migration CASCADE (promote
/// a keystone component, and everything importing it becomes buildable).
///
/// A RELATIVE specifier is normalized to its `@/` form before any of that. Testing it raw against a
/// registry that only ever holds `@/…` entries could never match, which is why 41 of this repo's 59
/// remaining components reported unresolved imports that were mostly `./log`-shaped.
///
/// Matching is deliberately EXACT — the normalized base, then the base minus a leading `src/` (the
/// harvest root is often the repo rather than the alias root). No suffix scan: harvest's honesty is the
/// property that matters, and a too-eager match manufactures the promotion trap `buildable` exists to
/// prevent (#3470).
fn resolves_outside_the_set(spec: &str, from_rel: &str) -> bool {
    let Some(base) = bsc_component::graph_health::resolve_internal_base(spec, from_rel) else {
        // Not an internal specifier at all — a bare package, which the bundler resolves.
        return true;
    };
    let known = |b: &str| {
        let s = format!("@/{b}");
        bsc_component::graph_health::is_registered_platform_module(&s)
            || bsc_component::graph_health::is_provided_specifier(&s)
    };
    known(&base) || base.strip_prefix("src/").is_some_and(known)
}

/// One INTERNAL (`@/…` alias OR relative `./`/`../`) import in a closure: the specifier and the names it
/// imports. `names` holds the IMPORTED names (`import { Button as Btn }` imports `Button`) — the identity
/// that matches a harvested component — and is EMPTY for a form whose bindings can't be attributed to
/// named exports (`import * as X`, a bare side-effect import), which therefore never counts as a sibling
/// import.
pub(crate) struct InternalImport {
    pub(crate) spec: String,
    names: Vec<String>,
    /// Syntactically type-only (#4076) — erased before the bundler resolves anything, so it never blocks.
    pub(crate) type_only: bool,
}

/// The harvested set indexed for import resolution: component NAME → the module BASE(s) it was
/// harvested from (its `src` minus the extension). Both halves are needed. A name alone would forgive
/// `import { Button, useAppStore } from "@/store"` merely because some `Button` exists elsewhere; a path
/// alone can't be compared across roots. Together they answer the only question that matters — does this
/// specifier name a module this harvest produced?
#[derive(Default)]
struct SiblingIndex(std::collections::HashMap<String, Vec<String>>);

impl SiblingIndex {
    /// Was a component of this name harvested? (The `composes` membership test — by NAME, the component
    /// graph's key.)
    fn has(&self, name: &str) -> bool {
        self.0.contains_key(name)
    }

    /// Does an import of `names` from module base `spec_base` land on a harvested sibling module?
    fn resolves(&self, spec_base: &str, names: &[String]) -> bool {
        names.iter().any(|n| {
            self.0.get(n).is_some_and(|bases| bases.iter().any(|b| same_module(spec_base, b)))
        })
    }
}

/// A module's import base — its harvested `src` minus the TS/TSX extension, which is what an import
/// specifier resolves to (`resolve_internal_base`: `@/x` → `x`).
fn module_base(src: &str) -> String {
    src.trim_end_matches(".tsx").trim_end_matches(".ts").to_string()
}

/// Do two module bases name the same module? Equal, or one a SEGMENT-ALIGNED suffix of the other — the
/// harvest root is rarely the alias root, so a candidate harvested from `src/shared/ui` carries
/// `controls/Button` while the specifier says `@/shared/ui/controls/Button`. Comparing the shared tail
/// is what makes the two roots commensurable; requiring a `/` boundary keeps `…/IconButton` from
/// matching `…/Button`.
fn same_module(a: &str, b: &str) -> bool {
    a == b || a.ends_with(&format!("/{b}")) || b.ends_with(&format!("/{a}"))
}

impl InternalImport {
    /// Does this import land on a harvested sibling module? True when ANY imported binding is a
    /// harvested component AND the specifier names that component's module — at which point the WHOLE
    /// import resolves, because the preview vendors the module wholesale: the other bindings on the same
    /// specifier (`import { KeyValueList, type KeyValueItem } from "@/shared/ui/data/KeyValueList"`, a
    /// real and common shape here) come from that same vendored file. An `import * as X` is opaque
    /// (`names` empty) and never resolves, and nor does a specifier no harvested module answers to.
    ///
    /// `from_rel` is the IMPORTING candidate's own harvested `src` — needed to resolve a RELATIVE
    /// (`./`, `../`) specifier against the importer's directory (an `@/…` alias needs no such anchor).
    /// Shares `bsc_component::graph_health::resolve_internal_base` — the exact join/collapse rule
    /// `doctor` judges the same specifier by later, so harvest's `buildable` verdict can never disagree
    /// with `doctor`'s over how a `./…` import resolves (the #4 gap: a promoted component that harvest
    /// certified `buildable: true` reporting `no-implementation` in `doctor` with no way to tell why).
    fn is_sibling(&self, siblings: &SiblingIndex, from_rel: &str) -> bool {
        let Some(base) = bsc_component::graph_health::resolve_internal_base(&self.spec, from_rel) else {
            return false;
        };
        siblings.resolves(&base, &self.names)
    }
}

/// The internal (`@/…` alias OR relative `./`/`../`) imports of a module, with the names each binds.
///
/// A PROJECTION of [`crate::import_scan::scan_imports_all`], not a scanner of its own. It used to walk
/// the root's `import_statement` children directly, which made every re-export invisible:
///
/// ```text
/// export { ProjectRow } from "./published/ProjectRow";   -> []
/// export * from "./a";                                   -> []
/// export function load() { return import("./page"); }    -> []
/// ```
///
/// esbuild compiles a re-export to the same `require()` an import produces, so a component whose closure
/// needed a re-exported sibling was certified `buildable: true` and then could not load — the gap the
/// TypeScript names as having shipped `projectspage` broken (#3874). A dynamic import was invisible for a
/// second reason: it is an ordinary expression and can sit anywhere, so a walk that stops at the root's
/// children cannot see one.
///
/// This is the same class of bug harvest already fixed once. Relative imports used to be skipped entirely
/// on the assumption that "the closure is built from ONE file, so it never emits one" — false in practice,
/// and it silently exempted real sibling imports from the buildability check (#4). The re-export case is
/// that bug again through a different hole, and pointing at the one canonical scanner is what closes the
/// class rather than the instance.
///
/// Type-only imports are kept and FLAGGED rather than dropped. Erasure is a buildability judgement only:
/// a type-only import of a harvested sibling is still a composition edge, because the graph's edges
/// describe the source and buildability describes the bundle (#4076).
pub(crate) fn internal_imports(src_text: &str) -> Vec<InternalImport> {
    crate::import_scan::scan_imports_all(src_text)
        .into_iter()
        .filter(|i| bsc_component::graph_health::is_internal_specifier(&i.specifier))
        .map(|i| InternalImport { spec: i.specifier, names: i.locals, type_only: i.type_only })
        .collect()
}

/// One component located in one file, before cross-file `composes` resolution.
struct Found {
    name: String,
    src_text: String,
    src: String,
    /// PascalCase JSX tags rendered anywhere in the component.
    tags: Vec<String>,
}

/// Is `dir` the root of a NESTED git tree — a worktree, submodule, or vendored clone (#3571)? A git
/// worktree/submodule marks its root with a `.git` FILE (a `gitdir:` pointer), a standalone clone with a
/// `.git` DIRECTORY; either presence means a separate git root whose sources duplicate the primary tree.
fn is_nested_git_root(dir: &Path) -> bool {
    dir.join(".git").exists()
}

fn walk(root: &Path, dir: &Path, out: &mut Vec<Found>) {
    let Ok(entries) = std::fs::read_dir(dir) else { return };
    let mut paths: Vec<PathBuf> = entries.filter_map(|e| e.ok()).map(|e| e.path()).collect();
    paths.sort();
    for path in paths {
        let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
        if path.is_dir() {
            // Never descend a vendored/build/VCS dir, NOR a NESTED git root (#3571): a subdir carrying its
            // own `.git` is a worktree or submodule — its `src/` is a duplicate copy of components already
            // harvested from the primary tree, so walking it double-counts every one. base-studio-code
            // keeps its issue worktrees (`wt3568/`, …) right beside `src/`, so harvesting the repo root was
            // reporting each component once per live worktree. (`.git` itself is in SKIP_DIRS, so this only
            // affects the CHILD dir that contains one — the root's own `.git` is never in play here.)
            if !SKIP_DIRS.contains(&name) && !is_nested_git_root(&path) {
                walk(root, &path, out);
            }
        } else if let Some((src, tree)) = parse(&path) {
            let rel = path.strip_prefix(root).unwrap_or(&path).to_string_lossy().replace('\\', "/");
            collect_file(tree.root_node(), &src, &rel, out);
        }
    }
}

/// Lift every React component defined at any depth in one parsed file.
fn collect_file(root: Node, src: &[u8], rel: &str, out: &mut Vec<Found>) {
    let imports = import_lines(root, src);
    let decls = top_level_decls(root, src);
    let mut defs: Vec<(String, Node)> = Vec::new();
    collect_component_defs(root, src, &mut defs);
    for (name, node) in defs {
        let own = exported_text(node, src);
        let src_text = close_over(&own, &imports, &decls, &name);
        out.push(Found {
            name,
            tags: jsx_tags(node, src),
            src_text,
            src: rel.to_string(),
        });
    }
}

/// Every React component definition under `node`: a PascalCase-named function that renders JSX.
fn collect_component_defs<'a>(node: Node<'a>, src: &[u8], out: &mut Vec<(String, Node<'a>)>) {
    if let Some(name) = fn_def_name(node, src) {
        if is_component_name(&name) && contains_jsx(node) {
            out.push((name, node));
            // A component's inner closures are part of IT, never separate candidates.
            return;
        }
    }
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        collect_component_defs(child, src, out);
    }
}

/// The source name of the function `node` DEFINES, or `None` if it isn't a function definition.
fn fn_def_name(node: Node, src: &[u8]) -> Option<String> {
    match node.kind() {
        "function_declaration" | "function_item" | "method_definition" => field_text(node, "name", src),
        "variable_declarator" => {
            // A component bound to a variable: either DIRECTLY (`const X = () => …`) or WRAPPED in a
            // higher-order call (`const X = memo(…)` / `forwardRef(…)` / `observer(…)`) — a
            // `call_expression` value (#3571). The wrapped form was invisible before: the name still names
            // a component, and the JSX gate in `collect_component_defs` (`contains_jsx`) keeps a non-render
            // call like `const X = loadConfig()` out, since its subtree has no JSX. A bare JSX-element value
            // (`const X = <div/>`) is deliberately NOT matched — that is an element constant, not a
            // component the preview can mount.
            let bound_to_component = node
                .child_by_field_name("value")
                .map(|v| matches!(v.kind(), "arrow_function" | "function" | "function_expression" | "call_expression"))
                .unwrap_or(false);
            bound_to_component.then(|| field_text(node, "name", src)).flatten()
        }
        _ => None,
    }
}

fn field_text(node: Node, field: &str, src: &[u8]) -> Option<String> {
    node.child_by_field_name(field).and_then(|n| n.utf8_text(src).ok()).map(str::to_string)
}

/// Does this subtree render JSX? The other half of the component test — a capitalized function that
/// returns no JSX is a factory/hook/class, not a component.
fn contains_jsx(node: Node) -> bool {
    if matches!(node.kind(), "jsx_element" | "jsx_self_closing_element" | "jsx_fragment") {
        return true;
    }
    let mut cursor = node.walk();
    let found = node.children(&mut cursor).any(contains_jsx);
    found
}

/// The PascalCase JSX tag names rendered under `node`, in first-appearance order. Lowercase tags are
/// intrinsics (`div`, `span`) and are never components.
fn jsx_tags(node: Node, src: &[u8]) -> Vec<String> {
    let mut out = Vec::new();
    collect_tags(node, src, &mut out);
    out
}

fn collect_tags(node: Node, src: &[u8], out: &mut Vec<String>) {
    if matches!(node.kind(), "jsx_opening_element" | "jsx_self_closing_element") {
        if let Some(name) = field_text(node, "name", src) {
            if is_component_name(&name) && !out.contains(&name) {
                out.push(name);
            }
        }
    }
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        collect_tags(child, src, out);
    }
}

/// The node's text INCLUDING a wrapping `export` (tree-sitter puts `export` in a parent
/// `export_statement`, so the bare node text would silently drop it and the module would export nothing).
fn exported_text(node: Node, src: &[u8]) -> String {
    let mut top = node;
    // Climb out of `variable_declarator` → `lexical_declaration` → `export_statement`.
    while let Some(parent) = top.parent() {
        if matches!(parent.kind(), "lexical_declaration" | "variable_declaration" | "export_statement") {
            top = parent;
        } else {
            break;
        }
    }
    let text = top.utf8_text(src).unwrap_or("").to_string();
    if text.trim_start().starts_with("export ") { text } else { format!("export {text}") }
}

/// One top-level declaration in a file: the names it binds and its full source text.
struct Decl {
    names: Vec<String>,
    text: String,
}

/// Top-level type/const/function declarations, so a component's local helpers can be pulled into its
/// closure. (Component declarations are included too — a sibling component used by this one is a
/// `composes` edge AND may need its source when it isn't separately harvested.)
fn top_level_decls(root: Node, src: &[u8]) -> Vec<Decl> {
    let mut out = Vec::new();
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        let inner = if child.kind() == "export_statement" {
            child.named_child(0).unwrap_or(child)
        } else {
            child
        };
        let names = match inner.kind() {
            "function_declaration" | "class_declaration" | "type_alias_declaration"
            | "interface_declaration" | "enum_declaration" => {
                field_text(inner, "name", src).into_iter().collect()
            }
            "lexical_declaration" | "variable_declaration" => {
                let mut n = Vec::new();
                let mut c = inner.walk();
                for d in inner.children(&mut c) {
                    if d.kind() == "variable_declarator" {
                        if let Some(name) = field_text(d, "name", src) {
                            n.push(name);
                        }
                    }
                }
                n
            }
            _ => Vec::new(),
        };
        if !names.is_empty() {
            if let Ok(text) = child.utf8_text(src) {
                out.push(Decl { names, text: text.to_string() });
            }
        }
    }
    out
}

/// The file's import statements, each with the identifiers it binds.
fn import_lines(root: Node, src: &[u8]) -> Vec<Decl> {
    let mut out = Vec::new();
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        if child.kind() != "import_statement" {
            continue;
        }
        let Ok(text) = child.utf8_text(src) else { continue };
        let mut names = Vec::new();
        collect_idents(child, src, &mut names);
        out.push(Decl { names, text: text.to_string() });
    }
    out
}

/// Every identifier token under `node` (used both for import bindings and for reference scanning).
fn collect_idents(node: Node, src: &[u8], out: &mut Vec<String>) {
    if matches!(node.kind(), "identifier" | "type_identifier" | "shorthand_property_identifier_pattern") {
        if let Ok(t) = node.utf8_text(src) {
            let t = t.to_string();
            if !out.contains(&t) {
                out.push(t);
            }
        }
    }
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        collect_idents(child, src, out);
    }
}

/// Build the component's module CLOSURE: the imports it actually uses + the same-file declarations it
/// transitively references + the component itself. Only what is REFERENCED is pulled in, so a harvested
/// component doesn't drag its whole file along — but nothing it needs is left behind either, which is
/// the failure the algorithms extractor's node-slice strategy would produce here.
fn close_over(own: &str, imports: &[Decl], decls: &[Decl], self_name: &str) -> String {
    let mut wanted: HashSet<String> = idents_in(own);
    // Transitively pull in local declarations, re-scanning each one for further references.
    let mut taken: Vec<usize> = Vec::new();
    loop {
        let mut grew = false;
        for (i, d) in decls.iter().enumerate() {
            if taken.contains(&i) || d.names.iter().any(|n| n == self_name) {
                continue;
            }
            if d.names.iter().any(|n| wanted.contains(n)) {
                for id in idents_in(&d.text) {
                    wanted.insert(id);
                }
                taken.push(i);
                grew = true;
            }
        }
        if !grew {
            break;
        }
    }
    taken.sort_unstable();
    let mut parts: Vec<String> = Vec::new();
    for imp in imports.iter().filter(|i| i.names.iter().any(|n| wanted.contains(n))) {
        parts.push(imp.text.clone());
    }
    if !parts.is_empty() {
        parts.push(String::new()); // blank line between imports and body
    }
    for i in taken {
        parts.push(decls[i].text.clone());
    }
    parts.push(own.to_string());
    parts.join("\n")
}

/// The identifier-ish words in a chunk of source — a cheap scanner used to decide what a closure needs.
/// Deliberately over-inclusive: pulling in one unused local declaration is harmless, whereas MISSING one
/// produces an uncompilable component, which is the failure mode that matters.
fn idents_in(text: &str) -> HashSet<String> {
    let mut out = HashSet::new();
    let mut cur = String::new();
    for ch in text.chars() {
        if ch.is_ascii_alphanumeric() || ch == '_' || ch == '$' {
            cur.push(ch);
        } else {
            if !cur.is_empty() && !cur.chars().next().unwrap().is_ascii_digit() {
                out.insert(std::mem::take(&mut cur));
            }
            cur.clear();
        }
    }
    if !cur.is_empty() {
        out.insert(cur);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn fixtures() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests").join("fixtures").join("harvest")
    }

    fn run() -> Vec<Candidate> {
        harvest(&fixtures(), DEFAULT_KIT)
    }

    fn by_name(name: &str) -> Candidate {
        run().into_iter().find(|c| c.name == name).unwrap_or_else(|| panic!("{name} not harvested"))
    }

    /// Buildability of a standalone module — no harvest around it, so it has no siblings to resolve
    /// against (the pre-#3471 single-module judgement). `from_rel` is a placeholder path (its own
    /// existing tests only exercise `@/…` specifiers, which resolve independently of it).
    fn buildability_of(src: &str) -> (bool, Vec<String>) {
        buildability(src, &internal_imports(src), &SiblingIndex::default(), "user/Standalone.tsx")
    }

    /// Buildability of a module harvested alongside `siblings`, each given as `(name, src)`, as if this
    /// module itself lived at `from_rel` — needed to resolve any RELATIVE (`./`, `../`) import in `src`.
    fn buildability_with_at(src: &str, siblings: &[(&str, &str)], from_rel: &str) -> (bool, Vec<String>) {
        let mut idx = SiblingIndex::default();
        for (name, at) in siblings {
            idx.0.entry((*name).to_string()).or_default().push(module_base(at));
        }
        buildability(src, &internal_imports(src), &idx, from_rel)
    }

    /// [`buildability_with_at`] for the common case — the module's own path doesn't matter because `src`
    /// only imports by `@/…` alias (unaffected by `from_rel`).
    fn buildability_with(src: &str, siblings: &[(&str, &str)]) -> (bool, Vec<String>) {
        buildability_with_at(src, siblings, "user/Standalone.tsx")
    }

    #[test]
    fn lifts_react_components_and_nothing_else() {
        let names: Vec<String> = run().into_iter().map(|c| c.name).collect();
        assert!(names.contains(&"Button".to_string()));
        assert!(names.contains(&"Card".to_string()));
        assert!(names.contains(&"DashboardPage".to_string()));
        // `formatDate` renders no JSX and isn't PascalCase — not a component.
        assert!(!names.iter().any(|n| n == "formatDate"), "a plain util is not a component: {names:?}");
        // A test file defines a component too — it must be skipped as a FILE, not rescued by name.
        assert!(!names.iter().any(|n| n == "NeverHarvested"), "test files are skipped: {names:?}");
    }

    #[test]
    fn the_closure_pulls_in_the_imports_types_and_helpers_the_component_uses() {
        // THE core difference from the algorithms harvest: a node slice would lose all of these and the
        // stored component would not compile.
        let b = by_name("Button");
        assert!(b.src_text.contains(r#"import { cx } from "clsx";"#), "keeps the used import:\n{}", b.src_text);
        assert!(b.src_text.contains("type ButtonProps"), "keeps the referenced type:\n{}", b.src_text);
        assert!(b.src_text.contains("function toneClass"), "keeps the referenced helper:\n{}", b.src_text);
        assert!(b.src_text.contains("export function Button"), "keeps the component itself:\n{}", b.src_text);
        // …and only what is referenced: an unrelated sibling declaration stays behind.
        assert!(!b.src_text.contains("UNUSED_ELSEWHERE"), "unreferenced decls are not dragged along:\n{}", b.src_text);
    }

    #[test]
    fn an_arrow_component_is_lifted_and_stays_exported() {
        // tree-sitter puts `export` in a PARENT node, so the bare declarator text would export nothing.
        let c = by_name("Card");
        assert!(c.src_text.contains("export const Card"), "arrow component keeps its export:\n{}", c.src_text);
    }

    #[test]
    fn composes_lists_sibling_component_names_not_ids() {
        // The component graph composes by NAME (`graph_health::parse_node`), deliberately unlike the
        // algorithms harvest's id-based edges.
        let c = by_name("Card");
        assert_eq!(c.composes, vec!["Button".to_string()]);
        assert_eq!(c.role, "composite", "a component that renders another is composite");
    }

    #[test]
    fn an_unresolved_internal_import_is_flagged_never_silently_accepted() {
        // #3470: such a srcText USED to store with NO complaint (looks_buildable_module was false, so
        // the syntax gate skipped entirely). Both the harvest and `bsc ui set` state it now. `Gauge`
        // imports a specifier that is neither a harvested sibling nor a registered platform module — so
        // nothing resolves it, and it is a real dangling import.
        //
        // (This used to assert on `Panel`/`@/store`. #4071 reclassified that one: `@/store` IS in the
        // runtime registry, so it resolves — see the test below. The honesty guarantee needed a fixture
        // that is genuinely unresolvable, not one that merely looked it.)
        let c = by_name("Gauge");
        assert!(!c.buildable, "a component with a truly unresolved @/ import is not buildable");
        let why = c.unbuildable_reasons.join(" ");
        assert!(why.contains("`@/features/nowhere/lib/missing`"), "the reason NAMES the import: {why}");
    }

    /// #4071 — the blind spot: the runtime module registry resolves these specifiers literally, so a
    /// candidate importing one mounts fine in the app. Counting them against buildability flagged 116 of
    /// 351 candidates in the app's own tree for something that is not wrong — and a false "unresolved
    /// import" is what pressures the next author to hand-stub the import, the corruption
    /// `reimplemented-component` exists to catch (#3892/#3895).
    #[test]
    fn a_registered_platform_module_resolves_like_a_sibling() {
        // `Panel` imports a harvested sibling (`@/shared/ui/controls/Button`) AND `@/store`, a REGISTERED
        // platform module. Both resolve, so it is buildable.
        let c = by_name("Panel");
        assert!(c.buildable, "registered platform module resolves: {:?}", c.unbuildable_reasons);
        assert!(c.unbuildable_reasons.is_empty());
        // The import STAYS in the closure — the registry supplies the binding at load time; nothing is
        // vendored or stubbed. Dropping it would leave the JSX referencing a free identifier.
        assert!(c.src_text.contains("@/store"), "the import is kept, not elided:\n{}", c.src_text);
    }

    #[test]
    fn buildability_pins_each_import_class_independently() {
        // Registered platform module ONLY ⇒ buildable.
        let (ok, _) = buildability_of("import { useAppStore } from \"@/store\";\nexport function A() { return <i/>; }");
        assert!(ok, "a registered platform module alone does not block");
        // An UNREGISTERED alias ⇒ still blocked, and named.
        let (bad, why) = buildability_of("import { x } from \"@/features/nowhere/lib/missing\";\nexport function B() { return <i/>; }");
        assert!(!bad);
        assert!(why.join(" ").contains("`@/features/nowhere/lib/missing`"));
        // A RELATIVE sibling that is not in the set ⇒ still blocked (the 111-candidate class, untouched).
        let (rel, relwhy) = buildability_of("import { s } from \"./bodyStyles\";\nexport function C() { return <i/>; }");
        assert!(!rel, "a relative sibling outside the set still blocks");
        assert!(relwhy.join(" ").contains("`./bodyStyles`"));
        // MIXED — a registered module plus an unresolvable sibling ⇒ blocked, naming ONLY the real one.
        let (mixed, mwhy) = buildability_of(
            "import { useAppStore } from \"@/store\";\nimport { s } from \"./bodyStyles\";\nexport function D() { return <i/>; }",
        );
        assert!(!mixed);
        let joined = mwhy.join(" ");
        assert!(joined.contains("`./bodyStyles`"), "names the real blocker: {joined}");
        assert!(!joined.contains("@/store"), "does not condemn the resolved one: {joined}");
    }

    #[test]
    fn a_sibling_import_is_a_composes_edge_not_a_dangling_import() {
        // #3471 AC. `Card` imports `@/shared/ui/controls/Button`, and `Button` IS in this harvest — the
        // preview vendors the siblings a component imports (#3112), so judging `Card` alone was
        // pessimistic. MEASURED: 51 of 93 candidates harvested from this repo's own src/shared/ui were
        // unbuildable purely for `@/` imports, most of them pointing at other components in the set.
        let c = by_name("Card");
        assert!(c.buildable, "a harvested sibling import resolves: {:?}", c.unbuildable_reasons);
        assert!(c.unbuildable_reasons.is_empty());
        assert_eq!(c.composes, vec!["Button".to_string()], "it is an edge instead");
        // The import STAYS in the closure: it is what the preview's vendoring walk resolves and what
        // binds the identifier the JSX renders. Dropping it would build and then throw at render.
        assert!(
            c.src_text.contains(r#"import { Button } from "@/shared/ui/controls/Button";"#),
            "the sibling import is kept, not elided:\n{}",
            c.src_text
        );
    }

    #[test]
    fn an_imported_sibling_is_a_composes_edge_even_when_no_jsx_tag_renders_it() {
        // `Toolbar` hands `Button` to a render prop rather than rendering `<Button/>`, so the tag scan
        // sees nothing. The import is still a composition edge.
        let c = by_name("Toolbar");
        assert_eq!(c.composes, vec!["Button".to_string()]);
        assert_eq!(c.role, "composite");
    }

    #[test]
    fn only_imports_that_land_on_a_harvested_module_are_forgiven() {
        // NB (#4071): these specifiers are deliberately NOT real app modules. This test is about SIBLING
        // resolution, and a registered platform module now resolves by a different route — using a real
        // one (it used `@/shared/ui/controls/Button` and `@/store`) would pass for the wrong reason and
        // stop testing what it means to.
        let harvest = [("Button", "controls/Button.tsx")];
        let render = "\nexport const A = () => <Button />;";
        // The specifier names the harvested module (across roots — `controls/Button` is the tail of
        // `@/features/nowhere/controls/Button`).
        assert!(buildability_with(&format!("import {{ Button }} from \"@/features/nowhere/controls/Button\";{render}"), &harvest).0);
        // Nothing of that name was harvested.
        assert!(!buildability_with(&format!("import {{ Button }} from \"@/features/nowhere/controls/Button\";{render}"), &[("Card", "data/Card.tsx")]).0);
        // The name matches but the MODULE doesn't — a state module is not the harvested `Button` module,
        // so this must stay a defect (a name-only rule would forgive it).
        let (ok, why) = buildability_with(&format!("import {{ Button, useThing }} from \"@/features/nowhere/state\";{render}"), &harvest);
        assert!(!ok, "a name match on the wrong module is not a sibling import");
        assert!(why.iter().any(|r| r.contains("`@/features/nowhere/state`")), "{why:?}");
        // A near-miss path must not match on a bare substring.
        assert!(!buildability_with(&format!("import {{ Button }} from \"@/ui/IconButton\";{render}"), &harvest).0);
        // A namespace import can't be attributed to named exports, so it is never assumed to be a sibling.
        // (Unregistered specifier for the #4071 reason above — a registered one would resolve regardless.)
        assert!(!buildability_with(&format!("import * as Button from \"@/features/nowhere/controls/Button\";{render}"), &harvest).0);
        // A type imported ALONGSIDE a harvested component resolves with it: the preview vendors the
        // module whole, so every binding on that specifier comes from the same file. (Real and common —
        // `import { KeyValueList, type KeyValueItem } from "@/shared/ui/data/KeyValueList"` accounts for
        // several of this repo's own pages.)
        assert!(buildability_with(&format!("import {{ Button, type ButtonProps }} from \"@/shared/ui/controls/Button\";{render}"), &harvest).0);
    }

    #[test]
    fn a_syntactically_type_only_import_does_not_block_the_closure() {
        // #4076: the tsx loader ERASES `import type …` before it resolves anything, so the module it
        // names need never be in the closure. Both spellings — the statement-level `type` keyword and
        // the per-binding inline modifier — are erased whole.
        let render = "\nexport const A = () => <b />;";
        for src in [
            format!("import type {{ Plan }} from \"@/features/nowhere/state\";{render}"),
            format!("import {{ type Plan, type Stage }} from \"@/features/nowhere/state\";{render}"),
            format!("import type * as N from \"@/features/nowhere/state\";{render}"),
        ] {
            let (ok, why) = buildability_of(&src);
            assert!(ok, "an erased import is not a missing dependency: {why:?}\n{src}");
        }
    }

    #[test]
    fn a_value_import_of_the_same_module_still_blocks() {
        // The rule is SYNTACTIC, never inferred from the target: harvest has no type information, and
        // neither does esbuild. `import { Plan } from …` is kept by the loader even when `Plan` happens
        // to be a type, so it must keep counting — otherwise the closure ships an unresolvable specifier.
        let render = "\nexport const A = () => <b />;";
        let (ok, why) = buildability_of(&format!("import {{ Plan }} from \"@/features/nowhere/state\";{render}"));
        assert!(!ok, "a plain named import is not erasable");
        assert!(why.iter().any(|r| r.contains("`@/features/nowhere/state`")), "{why:?}");
        // A default or namespace binding is a runtime value by construction, and a MIXED clause keeps
        // the statement — the erasable half doesn't excuse the half that survives.
        for src in [
            format!("import Plan from \"@/features/nowhere/state\";{render}"),
            format!("import * as N from \"@/features/nowhere/state\";{render}"),
            format!("import {{ run, type Plan }} from \"@/features/nowhere/state\";{render}"),
        ] {
            assert!(!buildability_of(&src).0, "still a runtime import:\n{src}");
        }
    }

    #[test]
    fn an_erased_import_is_still_a_composition_edge() {
        // Erasure is a BUILDABILITY judgement only. A type-only import of a harvested sibling must not
        // stop being reported as `composes` — the graph's edges describe the source, not the bundle.
        let harvest = [("Button", "controls/Button.tsx")];
        let src = "import type { ButtonProps } from \"@/features/nowhere/controls/Button\";\nexport const A = () => <b />;";
        let (ok, why) = buildability_with(src, &harvest);
        assert!(ok, "{why:?}");
        assert!(
            internal_imports(src).iter().any(|i| i.spec.ends_with("controls/Button")),
            "the import is still SEEN — it is only exempt from blocking",
        );
    }

    #[test]
    fn a_relative_import_to_no_harvested_sibling_is_flagged_not_silently_forgiven() {
        // #4: this is the exact class harvest used to be blind to — `internal_imports` only scanned
        // `@/…` specifiers, so a component keeping a genuine RELATIVE import to a module that was never
        // harvested (a real, common shape: `src/shared/ui/layout/Box.tsx` importing the sibling constants
        // module `./space`) was certified `buildable: true` regardless. `doctor`'s stricter, sibling-aware
        // check then correctly flagged it `no-implementation` once promoted — with harvest's own verdict
        // giving no hint why. Scanning `./`/`../` here closes that gap.
        // The specifier must name something the platform does NOT declare and no record provides —
        // `./space` was the original example and stopped serving as one the moment
        // `@/shared/ui/layout/space` was registered and then migrated to a record, which is precisely
        // the resolution this test must not be fooled by.
        let src = "import { q } from \"./quiddity\";\nexport function Box() { return q; }";
        let (ok, why) = buildability_with_at(src, &[], "src/shared/ui/layout/Box.tsx");
        assert!(!ok, "an unresolved relative import is not buildable: {why:?}");
        assert!(why.iter().any(|r| r.contains("`./quiddity`")), "the reason NAMES the import: {why:?}");
    }

    /// The other half of the same rule: a relative import IS resolvable when it normalizes onto something
    /// the platform declares. Testing the raw `./space` against a registry that only ever holds `@/…`
    /// entries could never match, which is why 41 of this repo's 59 remaining components were reported
    /// unreachable over imports that were mostly `./log`-shaped.
    #[test]
    fn a_relative_import_that_normalizes_onto_a_declared_module_resolves() {
        let src = "import { space } from \"./space\";\nexport function Box() { return space; }";
        let (ok, why) = buildability_with_at(src, &[], "src/shared/ui/layout/Box.tsx");
        assert!(ok, "`./space` from src/shared/ui/layout IS @/shared/ui/layout/space: {why:?}");
    }

    /// The harvest root is often the REPO rather than the alias root, so the normalized base keeps a
    /// leading `src/` the registry's `@/…` entries do not have. Both spellings must resolve — and only
    /// those two, never a suffix scan, because a false `buildable: true` is the promotion trap.
    #[test]
    fn a_leading_src_segment_is_tolerated_but_matching_stays_exact() {
        assert!(
            resolves_outside_the_set("@/src/shared/ui/layout/space", "anywhere.tsx"),
            "a repo-rooted base resolves once the leading `src/` is dropped",
        );
        assert!(
            !resolves_outside_the_set("@/layout/space", "anywhere.tsx"),
            "a TAIL of a declared specifier must NOT resolve — that would manufacture a false buildable",
        );
    }

    #[test]
    fn a_relative_import_landing_on_a_harvested_sibling_resolves() {
        // The same import, but `space` WAS harvested (from the same directory) — a real composing sibling,
        // resolved with the SAME join/collapse rule `doctor` uses (`graph_health::resolve_internal_base`),
        // so harvest and doctor can never disagree over whether `./space` resolves.
        let src = "import { space } from \"./space\";\nexport function Box() { return space; }";
        let siblings = [("space", "src/shared/ui/layout/space.ts")];
        let (ok, why) = buildability_with_at(src, &siblings, "src/shared/ui/layout/Box.tsx");
        assert!(ok, "a harvested relative sibling resolves: {why:?}");
        assert!(why.is_empty());
    }

    #[test]
    fn a_parent_relative_import_resolves_against_the_importers_directory() {
        // `../typography/Text` from `src/shared/ui/layout/Eyebrow.tsx` must resolve against
        // `src/shared/ui/typography/Text.tsx` — exercising the `..` segment collapse, not just `./`.
        let src = "import { Text } from \"../typography/Text\";\nexport function Eyebrow() { return <Text/>; }";
        let siblings = [("Text", "src/shared/ui/typography/Text.tsx")];
        let (ok, why) = buildability_with_at(src, &siblings, "src/shared/ui/layout/Eyebrow.tsx");
        assert!(ok, "a `../` import resolves against the importer's own directory: {why:?}");
    }

    #[test]
    fn a_multiline_import_is_seen() {
        // The line scanner this replaced only looked at lines STARTING with `import `, so a wrapped
        // import statement carried its specifier on an invisible line and the closure was silently
        // called buildable.
        // The specifier is deliberately unregistered (#4071) — this test is about the SCANNER seeing a
        // wrapped statement, not about which specifiers resolve.
        let (ok, why) = buildability_of("import {\n  useThing,\n} from \"@/features/nowhere/state\";\nexport const A = () => <b />;");
        assert!(!ok, "a wrapped import is still an import");
        assert!(why.iter().any(|r| r.contains("`@/features/nowhere/state`")), "{why:?}");
    }

    #[test]
    fn a_self_contained_component_is_reported_buildable() {
        let b = by_name("Button");
        assert!(b.buildable, "reasons: {:?}", b.unbuildable_reasons);
        assert!(b.unbuildable_reasons.is_empty());
    }

    #[test]
    fn role_and_id_follow_the_stores_conventions() {
        let p = by_name("DashboardPage");
        assert_eq!(p.role, "page");
        // The live store keys components as the lowercased name with separators dropped.
        assert_eq!(p.id, "dashboardpage");
        assert_eq!(by_name("Button").id, "button");
        assert_eq!(by_name("Button").role, "primitive", "renders no sibling component");
    }

    #[test]
    fn every_candidate_carries_its_source_path_and_kit() {
        for c in run() {
            assert!(
                [".tsx", ".ts", ".jsx", ".js"].iter().any(|e| c.src.ends_with(e)),
                "{} -> {}", c.name, c.src,
            );
            assert_eq!(c.kit_id, DEFAULT_KIT);
            assert!(!c.src_text.is_empty());
        }
    }

    #[test]
    fn a_higher_order_wrapped_component_is_lifted() {
        // #3571: `export const Badge = memo(({text}) => <span/>)` — the value is a `call_expression`, so
        // the harvester skipped it before. The name still names a component and the closure renders JSX.
        let names: Vec<String> = run().into_iter().map(|c| c.name).collect();
        assert!(names.contains(&"Badge".to_string()), "a memo()-wrapped component is harvested: {names:?}");
        let b = by_name("Badge");
        assert!(b.src_text.contains("export const Badge = memo("), "keeps the wrapping call:\n{}", b.src_text);
    }

    #[test]
    fn a_plain_javascript_jsx_component_is_lifted() {
        // #3571: a `.jsx` file — a JS-React project harvested to ZERO candidates before .jsx/.js parsed.
        let c = by_name("LegacyChip");
        assert!(c.src.ends_with(".jsx"), "harvested from the .jsx source: {}", c.src);
        assert!(c.buildable, "a self-contained JS component is buildable: {:?}", c.unbuildable_reasons);
    }

    #[test]
    fn a_nested_git_worktree_is_not_walked() {
        // #3571: a subdir carrying its own `.git` is a worktree/submodule whose src is a DUPLICATE of the
        // primary tree — walking it double-counts every component. base-studio-code keeps `wt####/` beside
        // `src/`, so harvesting the repo root reported each component once per live worktree.
        let base = std::env::temp_dir().join(format!("bsc-harvest-nested-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&base);
        // Primary tree: one real component.
        std::fs::create_dir_all(base.join("src")).unwrap();
        std::fs::write(base.join("src").join("Real.tsx"), "export const Real = () => <div/>;").unwrap();
        // A nested worktree with a `.git` marker (a file, as a real git worktree uses) and a duplicate.
        let wt = base.join("wt1234");
        std::fs::create_dir_all(wt.join("src")).unwrap();
        std::fs::write(wt.join(".git"), "gitdir: ../.git/worktrees/wt1234").unwrap();
        std::fs::write(wt.join("src").join("Real.tsx"), "export const Real = () => <div/>;").unwrap();

        let names: Vec<String> = harvest(&base, DEFAULT_KIT).into_iter().map(|c| c.name).collect();
        assert_eq!(names, vec!["Real".to_string()], "the worktree copy is skipped — no duplicate: {names:?}");
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn harvest_file_lifts_components_from_a_single_module() {
        // #3722: scope a harvest to ONE file. Two components in one module; `composes` resolves within it.
        let base = std::env::temp_dir().join(format!("bsc-harvest-file-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&base);
        std::fs::create_dir_all(&base).unwrap();
        let file = base.join("Widgets.tsx");
        std::fs::write(&file, "export const Chip = () => <span/>;\nexport const Bar = () => <Chip/>;").unwrap();

        let cands = harvest_file(&file, DEFAULT_KIT);
        let names: Vec<&str> = cands.iter().map(|c| c.name.as_str()).collect();
        assert!(names.contains(&"Chip") && names.contains(&"Bar"), "both components lifted: {names:?}");
        let bar = cands.iter().find(|c| c.name == "Bar").unwrap();
        assert_eq!(bar.composes, vec!["Chip".to_string()], "a sibling in the same file is a composes edge");
        // The PATH, not the basename. Every stored record carries a full `src/…` path — it is what
        // `bsc ui backing`, `doctor` and `folder_from_src` key off — and it is also the only anchor a
        // RELATIVE import can be resolved against. A bare name derived no folder and matched no file.
        assert!(bar.src.ends_with("/Widgets.tsx"), "src carries the file's path: {}", bar.src);
        assert!(bar.src.contains("bsc-harvest-file-"), "including the directory it came from: {}", bar.src);
        assert!(!bar.src.contains('\\'), "forward-slashed like every stored src: {}", bar.src);

        // A non-parseable single file (a test file) yields nothing — same skip the dir walk applies.
        let test = base.join("Widgets.test.tsx");
        std::fs::write(&test, "export const T = () => <span/>;").unwrap();
        assert!(harvest_file(&test, DEFAULT_KIT).is_empty(), "a test file yields no candidates");
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn functional_module_names_lists_functions_and_hooks_not_components_or_data() {
        // #3740: the functional/algorithmic surface a COMPONENT harvest skips — routed to the algorithms
        // graph. Functions + arrow utils + hooks are listed; a component and a data const are not.
        let base = std::env::temp_dir().join(format!("bsc-functional-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&base);
        std::fs::create_dir_all(&base).unwrap();
        std::fs::write(
            base.join("mix.tsx"),
            concat!(
                "export function Card() { return <div/>; }\n",                   // a component — excluded
                "export function formatDate(d: number) { return String(d); }\n", // a util fn — listed
                "export const clamp = (x: number) => Math.max(0, x);\n",         // an arrow util — listed
                "export function useThing() { return 1; }\n",                    // a hook — listed
                "export const SPACING = { sm: 4, md: 8 };\n",                    // a data const — excluded
            ),
        )
        .unwrap();

        let names = functional_module_names(&base);
        assert!(names.contains(&"formatDate".to_string()), "a util fn is listed: {names:?}");
        assert!(names.contains(&"clamp".to_string()), "an arrow util is listed: {names:?}");
        assert!(names.contains(&"useThing".to_string()), "a hook is listed: {names:?}");
        assert!(!names.contains(&"Card".to_string()), "a component is NOT listed (the component graph's job): {names:?}");
        assert!(!names.contains(&"SPACING".to_string()), "a data const is NOT a functional module: {names:?}");
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn the_walk_is_order_stable() {
        // Sorted traversal — a harvest diffed against a previous run must not churn on directory order.
        assert_eq!(run(), run());
    }

    #[test]
    fn the_default_kit_is_not_an_existing_curated_kit() {
        // Unreviewed candidates must not contaminate react-ui (or any curated kit) by default.
        assert_ne!(DEFAULT_KIT, "react-ui");
        assert_ne!(DEFAULT_KIT, "base");
    }

    #[test]
    fn classify_scores_composition_and_buildability_up_glue_down() {
        let card = by_name("Card");
        assert!(card.classification.reasons.iter().any(|r| r.contains("composes")));
        // A glue-named, unbuildable, trivial candidate must not be worthy.
        let glue = Candidate {
            id: "provider".into(), name: "Provider".into(), kit_id: DEFAULT_KIT.into(),
            role: "primitive", composes: vec![], src_text: "export const Provider = () => <div />;".into(),
            src: "Provider.tsx".into(), buildable: true, unbuildable_reasons: vec![],
            classification: Classification::default(),
        };
        assert!(!classify(&glue).worthy, "app-glue is not library-worthy: {:?}", classify(&glue));
    }

    #[test]
    fn an_ellipsis_in_copy_or_a_comment_is_not_an_elision_marker() {
        // A MEASURED false positive, not a hypothetical: harvesting this repo's own src/shared/ui
        // condemned 13 real components as "a sketch" because `…` is ordinary UI copy and ordinary prose
        // in a doc comment. A plain substring test is wrong here — `looks_buildable_module` shared the
        // same flaw until #3470 moved this scanner down into bsc-component for both to use.
        assert!(buildability_of(r#"export const A = () => <input placeholder="Select…" />;"#).0, "UI copy");
        assert!(buildability_of("// mentions …
export function A() { return null; }").0, "line comment");
        assert!(buildability_of("/* block … */
export function A() { return null; }").0, "block comment");
        assert!(buildability_of("export const A = () => <b>{`tpl …`}</b>;").0, "template literal");
        // …but a real elision standing in for omitted CODE still fails.
        assert!(!buildability_of("export function A() { … }").0, "a genuine code elision");
    }

    #[test]
    fn buildability_names_each_distinct_failure() {
        let (ok, why) = buildability_of("export function A() { return null; }");
        assert!(ok, "{why:?}");
        let (no_export, why) = buildability_of("function A() { return null; }");
        assert!(!no_export);
        assert!(why.iter().any(|r| r.contains("export")), "{why:?}");
        let (elided, why) = buildability_of("export function A() { … }");
        assert!(!elided);
        assert!(why.iter().any(|r| r.contains('…')), "{why:?}");
    }
}

implementations.code:
//! The ONE import scan — what a record's source actually `require()`s once the bundler is done with it.
//!
//! # Why this exists
//!
//! This repo was running THREE import scanners and they disagreed on 7 of the 11 cases first measured,
//! with no one of them right on all:
//!
//! | case              | TS `parseImports`  | [`crate::emit`] `import_specifiers` | [`crate::harvest`] `internal_imports` |
//! |-------------------|--------------------|-------------------------------------|---------------------------------------|
//! | `export … from`   | seen               | seen                                | **MISS**                              |
//! | `export *`        | seen               | seen                                | **MISS**                              |
//! | type-only         | erased             | **FALSE POSITIVE**                   | flagged                               |
//! | dynamic `import()`| **MISS**           | seen                                | **MISS**                              |
//! | `from` in comment | ignored            | **FALSE POSITIVE**                   | ignored                               |
//! | `from` in string  | ignored            | **FALSE POSITIVE**                   | ignored                               |
//!
//! `import_specifiers` WAS a raw keyword-SUBSTRING scan, so prose and string literals read as imports and
//! type-only imports the bundler erases were counted. `internal_imports` WAS tree-sitter and clean but
//! walked only `import_statement`, so every re-export was invisible — the exact gap the TypeScript names
//! as having shipped `projectspage` broken (#3874).
//!
//! BOTH COLUMNS ARE NOW HISTORY. Slice 2 deleted `import_specifiers` and pointed emit's closure walk
//! here; slice 3 made `internal_imports` a projection of [`scan_imports_all`]. Neither was fixed in
//! place, because two implementations of one question is what let them disagree for as long as they did.
//!
//! # What "right" means here, precisely
//!
//! An import counts when the COMPILED module will `require()` it. That is a syntactic question with an
//! exact answer, which is why this is a parser and not a regex:
//!
//! * A re-export IS an import. esbuild compiles `export { X } from "./y"` to the same `require("./y")`,
//!   so a scanner blind to it certifies a closure that cannot load.
//! * A syntactically type-only import is NOT one. `import type { T } from "./t"` and a clause whose every
//!   binding carries the inline `type` modifier are both erased before anything resolves, so the module
//!   need not exist. SYNTACTIC on purpose, never inferred from the target: `import { X } from "./y"` where
//!   `X` happens to be a type is NOT erasable, because esbuild has no type information and keeps it.
//! * A dynamic `import()` IS one, and is the thing the anchored regex cannot see.
//! * A `from` inside a comment or a string is not anything. This is not hypothetical — records in this
//!   tree carry provenance headers that name a specifier in prose.
//!
//! # Its relationship to the TypeScript
//!
//! `importScan.fixtures.json` is generated from the live `parseImports` and this scanner is proved
//! against it case by case, so "right" gets an independent second opinion rather than resting on the
//! author's reading. Two cases diverge DELIBERATELY, and the fixture records the TypeScript's own answer
//! for both so the divergence lives in the artifact instead of in a Rust-only expectation: the dynamic
//! import (the regex cannot see it) and the ordering of a bare import (the TypeScript runs its two
//! regexes in sequence, so a leading side-effect import is reported last). Both are the TypeScript being
//! wrong, and both are pinned so a future edit cannot quietly change which side moved.

use tree_sitter::{Language, Node, Parser};

/// One module specifier a source imports, and the symbols it takes from it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ImportRef {
    pub specifier: String,
    /// Imported names as written on the MODULE's side (`{ a as b }` → `a`). A namespace import is `*`,
    /// a default import is `default`, and a bare side-effect import has none. This is the field the
    /// generated fixture binds, so it means exactly what the TypeScript's `parseImports` means.
    pub symbols: Vec<String>,
    /// The names a consumer should match against a set of KNOWN COMPONENTS — [`symbols`], except that a
    /// default import contributes the LOCAL binding (`import Button from "./Button"` → `Button`, not
    /// `default`) and a namespace import contributes nothing.
    ///
    /// It exists because "which module does this require" and "which component does this reference" are
    /// different questions off the same parse, and harvest asks the second to build its `composes` edges.
    /// Without it a default-imported sibling would silently stop being an edge, since `default` matches no
    /// component name — a regression invisible to the buildability count this slice is measured by.
    /// Namespace imports contribute nothing because harvest has always treated `import * as N` as opaque:
    /// `N.Thing` is a member expression, not a binding it can resolve.
    pub locals: Vec<String>,
    /// Syntactically type-only (`import type …`, or a clause whose every binding carries the inline
    /// `type` modifier), and therefore ERASED before anything resolves.
    ///
    /// [`scan_imports`] never returns one. [`scan_imports_all`] returns it flagged, for the caller that
    /// must still SEE it — harvest reports a type-only import of a sibling as a composition edge while
    /// exempting it from blocking the closure, because the graph's edges describe the source and
    /// buildability describes the bundle (#4076).
    pub type_only: bool,
}

/// Every module specifier `source` will `require()` at runtime, in SOURCE order.
///
/// Returns an empty vec when the source cannot be parsed at all — a scan is a report, and a caller
/// sweeping hundreds of records must not stop at one bad file. (Note that tree-sitter is
/// error-tolerant, so this is close to unreachable in practice: a syntactically broken file still
/// yields a tree, and the imports it *can* see are still reported.)
pub fn scan_imports(source: &str) -> Vec<ImportRef> {
    scan_imports_all(source).into_iter().filter(|i| !i.type_only).collect()
}

/// Every module specifier `source` NAMES, including the syntactically type-only ones the bundler erases,
/// each flagged by [`ImportRef::type_only`].
///
/// [`scan_imports`] is this filtered, and is what a caller asking "what does the compiled module
/// require" wants. This form is for the caller that must also see what the SOURCE says — harvest, whose
/// `composes` edges describe the source while its buildability verdict describes the bundle.
pub fn scan_imports_all(source: &str) -> Vec<ImportRef> {
    let mut parser = Parser::new();
    let language: Language = tree_sitter_typescript::LANGUAGE_TSX.into();
    if parser.set_language(&language).is_err() {
        return Vec::new();
    }
    let Some(tree) = parser.parse(source, None) else { return Vec::new() };
    let src = source.as_bytes();
    let mut out = Vec::new();
    walk(tree.root_node(), src, &mut out);
    out
}

/// Depth-first over the whole tree. `import`/`export` statements are top-level in ESM, but a dynamic
/// `import()` is an ordinary expression and can be anywhere, so the walk cannot stop at the root's
/// children — which is one of the two things `internal_imports` gets wrong.
fn walk(node: Node, src: &[u8], out: &mut Vec<ImportRef>) {
    match node.kind() {
        "import_statement" => {
            if let Some(r) = import_statement(node, src) {
                out.push(r);
            }
            return; // nothing inside an import statement is another import
        }
        "export_statement" => {
            // Only a re-export — one with a `source` — is an import. A plain `export function f() {}`
            // has no source and is not.
            if node.child_by_field_name("source").is_some() {
                if let Some(r) = export_statement(node, src) {
                    out.push(r);
                }
                return;
            }
            // `export function f() { await import("./x") }` — fall through and keep walking.
        }
        "call_expression" => {
            if let Some(r) = dynamic_import(node, src) {
                out.push(r);
                // Keep walking: the ARGUMENT may itself contain another call.
            }
        }
        _ => {}
    }
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        walk(child, src, out);
    }
}

/// `import … from "x"` / `import "x"`. A syntactically type-only import is returned FLAGGED, not
/// dropped — [`scan_imports`] filters it out, so its contract is unchanged.
fn import_statement(node: Node, src: &[u8]) -> Option<ImportRef> {
    let specifier = source_text(node, src)?;
    let type_only = is_type_only(node, src);
    let (mut symbols, mut locals) = (Vec::new(), Vec::new());
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        if child.kind() == "import_clause" {
            clause_symbols(child, src, &mut symbols, &mut locals);
        }
    }
    Some(ImportRef { specifier, symbols, locals, type_only })
}

/// `export { X } from "y"` / `export * from "y"` / `export * as ns from "y"`. `None` when type-only.
fn export_statement(node: Node, src: &[u8]) -> Option<ImportRef> {
    let specifier = source_text(node, src)?;
    let type_only = is_type_only(node, src);
    let mut symbols = Vec::new();
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        match child.kind() {
            // `export * from` — the star is a bare token; `export * as ns from` is a namespace_export.
            // Both take everything, so both are `*`, matching the TypeScript's head-starts-with-`*` rule.
            "*" | "namespace_export" => symbols.push("*".to_string()),
            "export_clause" => named_symbols(child, src, &mut symbols),
            _ => {}
        }
    }
    // A re-export binds nothing locally, so the module-side names ARE the reference set: `export { Row }
    // from "./Row"` references `Row` exactly as an import of it would.
    let locals = symbols.iter().filter(|s| *s != "*").cloned().collect();
    Some(ImportRef { specifier, symbols, locals, type_only })
}

/// `import("x")` with a literal specifier. A computed one (`import(name)`) is unknowable statically and
/// is reported as nothing rather than guessed — the honest answer, and the same one every bundler gives.
fn dynamic_import(node: Node, src: &[u8]) -> Option<ImportRef> {
    let func = node.child_by_field_name("function")?;
    if func.kind() != "import" {
        return None;
    }
    let args = node.child_by_field_name("arguments")?;
    let mut cursor = args.walk();
    for child in args.children(&mut cursor) {
        if child.kind() == "string" {
            return Some(ImportRef {
                specifier: unquote(child.utf8_text(src).ok()?),
                symbols: Vec::new(),
                locals: Vec::new(),
                type_only: false,
            });
        }
    }
    None
}

/// The statement's quoted module specifier, unquoted.
fn source_text(node: Node, src: &[u8]) -> Option<String> {
    Some(unquote(node.child_by_field_name("source")?.utf8_text(src).ok()?))
}

fn unquote(s: &str) -> String {
    s.trim_matches(|c| c == '"' || c == '\'').to_string()
}

/// Is this statement SYNTACTICALLY type-only — `import type { T } from …` / `export type { T } from …`,
/// or a named clause whose every binding carries the inline `type` modifier?
///
/// A clause with a default or namespace binding is never type-only, and an EMPTY named clause is not
/// either: `import {} from "./x"` still emits a require.
fn is_type_only(node: Node, src: &[u8]) -> bool {
    let mut cursor = node.walk();
    let mut named: Option<Node> = None;
    for child in node.children(&mut cursor) {
        match child.kind() {
            // The statement-level `type` keyword, before any clause.
            _ if child.utf8_text(src).map(str::trim) == Ok("type") && child.kind() == "type" => return true,
            "import_clause" => {
                let mut cc = child.walk();
                for g in child.children(&mut cc) {
                    match g.kind() {
                        "named_imports" => named = Some(g),
                        "identifier" | "namespace_import" => return false,
                        _ => {}
                    }
                }
            }
            "export_clause" => named = Some(child),
            "namespace_export" | "*" => return false,
            _ => {}
        }
    }
    let Some(named) = named else { return false };
    let mut any = false;
    let mut nc = named.walk();
    for spec in named.children(&mut nc) {
        if !matches!(spec.kind(), "import_specifier" | "export_specifier") {
            continue;
        }
        any = true;
        if !spec.utf8_text(src).unwrap_or_default().trim_start().starts_with("type ") {
            return false;
        }
    }
    any
}

/// The names an `import_clause` binds, on both sides at once: `out` takes the MODULE-side name (a
/// default import contributes `default`, a namespace import `*`, a named list each binding's exported
/// name), and `locals` takes what a consumer should match against known component names (the default
/// import's LOCAL identifier, nothing for a namespace, and the same exported names for a named list).
///
/// One walk for both, because they are the same parse answering two questions — see [`ImportRef::locals`].
fn clause_symbols(clause: Node, src: &[u8], out: &mut Vec<String>, locals: &mut Vec<String>) {
    let mut cursor = clause.walk();
    for child in clause.children(&mut cursor) {
        match child.kind() {
            "identifier" => {
                out.push("default".to_string());
                if let Ok(t) = child.utf8_text(src) {
                    locals.push(t.trim().to_string());
                }
            }
            "namespace_import" => out.push("*".to_string()),
            "named_imports" => {
                let before = out.len();
                named_symbols(child, src, out);
                locals.extend(out[before..].iter().cloned());
            }
            _ => {}
        }
    }
}

/// Each specifier's module-side name, with an inline `type ` modifier stripped — matching the
/// TypeScript, which keeps a mixed clause and reports its value bindings under their bare names.
fn named_symbols(list: Node, src: &[u8], out: &mut Vec<String>) {
    let mut cursor = list.walk();
    for spec in list.children(&mut cursor) {
        if !matches!(spec.kind(), "import_specifier" | "export_specifier") {
            continue;
        }
        let Some(name) = spec.child_by_field_name("name") else { continue };
        if let Ok(text) = name.utf8_text(src) {
            out.push(text.trim().to_string());
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The fixture is GENERATED from the live TypeScript (`importScan.fixtures.gen.test.ts`), so this
    /// proves Rust equals what the renderer actually does today — not what its author believed it did.
    /// Located by filename under `src/`, the convention the tunnel and planner contracts already use, so
    /// moving a feature slice does not break this test but RENAMING the fixture does (deliberately).
    fn fixture() -> serde_json::Value {
        fn find(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
            let Ok(rd) = std::fs::read_dir(dir) else { return };
            for e in rd.flatten() {
                let p = e.path();
                if p.is_dir() {
                    find(&p, out);
                } else if p.file_name().and_then(|n| n.to_str()) == Some("importScan.fixtures.json") {
                    out.push(p);
                }
            }
        }
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../src");
        let mut found = Vec::new();
        find(&root, &mut found);
        assert_eq!(found.len(), 1, "expected one importScan.fixtures.json, got {found:?}");
        serde_json::from_str(&std::fs::read_to_string(&found[0]).unwrap()).unwrap()
    }

    /// The two labels whose TypeScript answer this scanner deliberately does NOT reproduce, because on
    /// both the TypeScript is wrong. Named by their fixture label so the exemption cannot silently widen
    /// to a case it was never argued for — adding a third requires editing this list and saying why.
    const INTENDED_DIVERGENCES: &[(&str, &str)] = &[
        (
            "a dynamic import — the regex cannot see it",
            "the anchored regex cannot see `import(\"x\")`; a dynamic import IS a require and this scanner reports it",
        ),
        (
            "a bare import BEFORE a named one",
            "the TypeScript runs its two regexes in sequence, so a leading side-effect import is reported LAST; this scanner reports source order",
        ),
    ];

    /// The TypeScript's answer for one case, as `(specifier, symbols)` pairs.
    ///
    /// PROJECTED, because those are the only two things `parseImports` reports and therefore the only two
    /// the generated fixture can bind. `locals` and `type_only` are this scanner's own additions — asked
    /// of the same parse for consumers the TypeScript never had — and are pinned by their own tests
    /// below. Comparing whole `ImportRef`s would require inventing fixture values for fields the
    /// TypeScript has no opinion about, which is how a parity test starts asserting its own assumptions.
    fn parsed(case: &serde_json::Value) -> Vec<(String, Vec<String>)> {
        case["imports"]
            .as_array()
            .expect("imports")
            .iter()
            .map(|i| {
                (
                    i["specifier"].as_str().unwrap().to_string(),
                    i["symbols"].as_array().unwrap().iter().map(|s| s.as_str().unwrap().to_string()).collect(),
                )
            })
            .collect()
    }

    /// The same projection, taken off this scanner.
    fn scanned(source: &str) -> Vec<(String, Vec<String>)> {
        scan_imports(source).into_iter().map(|i| (i.specifier, i.symbols)).collect()
    }

    /// An expected `ImportRef` for the shapes asserted directly below: `locals` mirrors the module-side
    /// symbols minus a namespace `*`, which is exactly what a named import and a re-export produce. A
    /// DEFAULT import is the one shape this cannot express — its local binding is not `default` — and it
    /// has its own test rather than a special case here.
    fn iref(specifier: &str, symbols: &[&str]) -> ImportRef {
        ImportRef {
            specifier: specifier.to_string(),
            symbols: symbols.iter().map(|s| (*s).to_string()).collect(),
            locals: symbols.iter().filter(|s| **s != "*").map(|s| (*s).to_string()).collect(),
            type_only: false,
        }
    }

    /// Reports EVERY mismatch at once rather than dying on the first — when a port is wrong it is
    /// usually wrong in a PATTERN, and one failing assertion hides the shape of it.
    #[test]
    fn the_scanner_matches_the_typescript_case_for_case() {
        let doc = fixture();
        let cases = doc["cases"].as_array().expect("cases");
        assert!(cases.len() >= 25, "fixture shrank to {} cases — regenerate it", cases.len());

        let mut mismatches = Vec::new();
        let mut checked = 0usize;
        for case in cases {
            let label = case["label"].as_str().unwrap();
            if INTENDED_DIVERGENCES.iter().any(|(l, _)| *l == label) {
                continue;
            }
            checked += 1;
            let want = parsed(case);
            let got = scanned(case["source"].as_str().unwrap());
            if got != want {
                mismatches.push(format!("  {label}\n    ts   {want:?}\n    rust {got:?}"));
            }
        }
        assert!(
            checked >= 25,
            "only {checked} cases were actually compared — an exemption list that swallowed the suite \
             would make this test vacuous"
        );
        assert!(
            mismatches.is_empty(),
            "the Rust scanner disagrees with the live TypeScript on {} of {checked} cases:\n{}",
            mismatches.len(),
            mismatches.join("\n")
        );
    }

    /// The exempted cases must ACTUALLY diverge. Without this, an exemption is a place a real regression
    /// can hide: if the scanner were "fixed" to reproduce the TypeScript's bug, the parity test above
    /// would skip it and stay green.
    #[test]
    fn every_intended_divergence_actually_diverges() {
        let doc = fixture();
        let cases = doc["cases"].as_array().expect("cases");
        for (label, why) in INTENDED_DIVERGENCES {
            let case = cases
                .iter()
                .find(|c| c["label"].as_str() == Some(label))
                .unwrap_or_else(|| panic!("no fixture case labelled {label:?} — the exemption is stale"));
            let ts = parsed(case);
            let rust = scanned(case["source"].as_str().unwrap());
            assert_ne!(rust, ts, "{label}: expected to diverge ({why}) but the two now agree");
        }
    }

    /// Each intended divergence, pinned to the value this scanner gives — an inequality alone would let
    /// the answer be anything at all as long as it was not the TypeScript's.
    #[test]
    fn the_divergences_give_the_right_answer_not_merely_a_different_one() {
        let dynamic = scan_imports("const m = await import(\"./lazy\");\n");
        assert_eq!(dynamic, vec![iref("./lazy", &[])]);

        let ordered = scan_imports("import \"./a.css\";\nimport { B } from \"./b\";\n");
        assert_eq!(
            ordered.iter().map(|i| i.specifier.as_str()).collect::<Vec<_>>(),
            vec!["./a.css", "./b"],
            "source order, not regex-pass order"
        );
    }

    /// The three cases the OTHER two Rust scanners get wrong, asserted directly. The parity test covers
    /// them through the fixture, but naming them here is what a reader of slices 2 and 3 comes looking
    /// for — this is the behaviour those flips are buying.
    #[test]
    fn it_fixes_what_the_other_two_rust_scanners_get_wrong() {
        // harvest::internal_imports walks only `import_statement`, so both of these are invisible to it.
        assert_eq!(
            scan_imports("export { ProjectRow } from \"./published/ProjectRow\";\n"),
            vec![iref("./published/ProjectRow", &["ProjectRow"])],
            "a re-export compiles to the same require an import does (#3874)"
        );
        assert_eq!(
            scan_imports("export * from \"./a\";\n"),
            vec![iref("./a", &["*"])]
        );

        // All three of these were false positives in emit's old substring scan.
        assert!(
            scan_imports("// see the note from \"./ghost\" for why\n").is_empty(),
            "prose is not an import — records in this tree carry provenance headers"
        );
        assert!(scan_imports("const s = 'from \"./strghost\"';\n").is_empty(), "a string literal is not an import");
        assert!(
            scan_imports("import type { T } from \"./t\";\n").is_empty(),
            "a type-only import is erased before anything resolves"
        );
    }

    /// Type-only detection is SYNTACTIC, never inferred from the target — esbuild has no type
    /// information, so an import of something that happens to be a type still emits a require.
    #[test]
    fn type_only_is_syntactic_and_a_mixed_clause_survives() {
        assert!(scan_imports("import { type A, type B } from \"./ab\";\n").is_empty());
        assert_eq!(
            scan_imports("import { type A, b } from \"./ab\";\n"),
            vec![iref("./ab", &["A", "b"])],
            "one value binding keeps the whole import"
        );
        assert_eq!(
            scan_imports("import { T } from \"./t\";\n").len(),
            1,
            "a value-syntax import of a type is NOT erasable"
        );
        assert!(scan_imports("export type { T } from \"./t\";\n").is_empty());
        assert_eq!(
            scan_imports("import {} from \"./x\";\n").len(),
            1,
            "an EMPTY clause is not type-only — it still emits a require"
        );
    }

    /// `locals` is what a consumer matches against KNOWN COMPONENT NAMES, and it differs from `symbols`
    /// in exactly two shapes. Both matter to harvest's `composes` edges, and getting either wrong is
    /// invisible to a buildability count — which is the number slice 3 is measured by.
    #[test]
    fn locals_report_the_binding_a_consumer_can_match_not_the_module_side_name() {
        let one = |src: &str| scan_imports(src).into_iter().next().expect("one import");

        // A DEFAULT import: the module-side name is `default`, which matches no component. The local
        // binding is the name the JSX actually renders.
        let d = one("import Button from \"./Button\";\n");
        assert_eq!(d.symbols, vec!["default"], "module side is unchanged — the fixture binds this");
        assert_eq!(d.locals, vec!["Button"], "consumer side is the local binding");

        // A NAMESPACE import is opaque: `N.Thing` is a member expression, not a resolvable binding.
        let n = one("import * as N from \"./mod\";\n");
        assert_eq!(n.symbols, vec!["*"]);
        assert!(n.locals.is_empty(), "a namespace binding names no component");

        // Everywhere else the two agree, including through an alias, where BOTH are the exported name.
        let a = one("import { Row as R } from \"./Row\";\n");
        assert_eq!(a.symbols, vec!["Row"]);
        assert_eq!(a.locals, vec!["Row"]);

        // A re-export binds nothing locally, so its module-side names are the reference set.
        let e = one("export { Row } from \"./Row\";\n");
        assert_eq!(e.locals, vec!["Row"], "a re-export references Row as surely as an import of it does");
    }

    /// `scan_imports_all` is the superset, and `scan_imports` is it filtered — asserted together so the
    /// filtered form's contract cannot drift from the flagged one.
    #[test]
    fn scan_imports_all_reports_the_erased_imports_flagged_and_scan_imports_drops_them() {
        let src = "import type { T } from \"./t\";\nimport { type A, type B } from \"./ab\";\nimport { X } from \"./x\";\n";
        let all = scan_imports_all(src);
        assert_eq!(
            all.iter().map(|i| (i.specifier.as_str(), i.type_only)).collect::<Vec<_>>(),
            vec![("./t", true), ("./ab", true), ("./x", false)],
            "both erased spellings are SEEN and flagged — harvest reports them as composition edges (#4076)"
        );
        assert_eq!(
            scan_imports(src).into_iter().map(|i| i.specifier).collect::<Vec<_>>(),
            vec!["./x"],
            "the filtered form is unchanged: only what the compiled module requires"
        );
        assert!(scan_imports_all("export type { T } from \"./t\";\n")[0].type_only, "a type-only re-export too");
    }

    /// A dynamic import nested inside a function body — the reason the walk cannot stop at the root's
    /// children, and a shape a lazy-loaded page actually has.
    #[test]
    fn a_nested_dynamic_import_is_found_and_a_computed_one_is_not_guessed() {
        let nested = scan_imports("export function load() {\n  return import(\"./page\");\n}\n");
        assert_eq!(nested, vec![iref("./page", &[])]);
        assert!(
            scan_imports("const n = \"x\";\nconst m = await import(n);\n").is_empty(),
            "a computed specifier is unknowable statically and is reported as nothing, never guessed"
        );
    }

    /// An unparseable source reports what it can rather than throwing — a sweep over hundreds of records
    /// must not stop at one bad file.
    #[test]
    fn a_broken_source_still_reports_what_it_can() {
        let got = scan_imports("import { X } from \"./x\";\nfunction ( { { {\n");
        assert_eq!(got.len(), 1, "the valid import above the damage is still reported: {got:?}");
    }
}

/// WHAT THE OTHER TWO SCANNERS ANSWER TODAY — a characterization test, not an aspiration.
///
/// Slices 2 and 3 flip [`crate::emit`] and [`crate::harvest`] onto [`scan_imports`]. The value of a flip
/// is the set of answers it CHANGES, and that set is only legible if today's answers are written down
/// before it happens. So this pins the current behaviour of both, defects included, and each defective
/// expectation says so in place.
///
/// It is deliberately not phrased as "these are wrong". A characterization test that asserted the right
/// answer would be red from the moment it was written and would have to be disabled to land, which is how
/// a known defect becomes an ignored one.
#[cfg(test)]
mod existing_scanners {
    use super::scan_imports;
    use crate::harvest::internal_imports;

    /// The four cases emit used to get wrong, now stated as the answers it gives.
    ///
    /// THIS IS THE SAME TEST, UPDATED — not a new one, and not the old one deleted. It was written as a
    /// characterization test asserting emit's WRONG answers (`import_specifiers` was a keyword-SUBSTRING
    /// scan: `./ghost` out of a comment, `./strghost` out of a string literal, and two type-only imports
    /// the bundler erases), so that the defect could not change unnoticed. Slice 2 pointed emit at
    /// `scan_imports` and deleted that scanner, so the four cases keep their place here and their
    /// expectations flip. Reading the diff of this function IS the behaviour change.
    ///
    /// What emit got right — a re-export and a dynamic import — is asserted below, because a flip that
    /// fixed the false positives by losing a true positive would be a worse scanner, not a better one.
    #[test]
    fn emit_no_longer_reports_the_four_things_that_are_not_imports() {
        let specs = |src: &str| -> Vec<String> { scan_imports(src).into_iter().map(|i| i.specifier).collect() };

        assert_eq!(
            specs("// see the note from \"./ghost\" for why\nimport { X } from \"./x\";\n"),
            vec!["./x"],
            "was [./ghost, ./x] — prose is not an import"
        );
        assert_eq!(
            specs("const s = 'from \"./strghost\"';\nimport { X } from \"./x\";\n"),
            vec!["./x"],
            "was [./strghost, ./x] — a string literal is not an import"
        );
        assert!(
            specs("import type { T } from \"./t\";\n").is_empty(),
            "was [./t] — a type-only import is erased by the bundler and never required"
        );
        assert!(
            specs("import { type A, type B } from \"./ab\";\n").is_empty(),
            "was [./ab] — an all-inline-type clause is erased too"
        );

        // What it already got right, and what the flip had to PRESERVE.
        assert_eq!(specs("export { X } from \"./y\";\n"), vec!["./y"], "re-export: still seen");
        assert_eq!(specs("const m = await import(\"./lazy\");\n"), vec!["./lazy"], "dynamic: still seen");
    }

    /// The three forms harvest used to be blind to, now stated as the answers it gives.
    ///
    /// THIS IS THE SAME TEST, UPDATED — not a new one, and not the old one deleted. It was written as a
    /// characterization test asserting that `internal_imports` returned NOTHING for a re-export, an
    /// export-star and a dynamic import, because it walked only the root's `import_statement` children.
    /// Slice 3 made it a projection of `scan_imports_all`, so the three cases keep their place here and
    /// their expectations flip. Reading the diff of this function IS the behaviour change.
    ///
    /// Why it mattered: esbuild compiles a re-export to the same `require()` an import produces, so a
    /// component whose closure needed a re-exported sibling was certified `buildable: true` and then
    /// could not load (#3874).
    #[test]
    fn harvest_now_sees_a_re_export_and_a_dynamic_import() {
        let specs = |src: &str| -> Vec<String> { internal_imports(src).into_iter().map(|i| i.spec).collect() };

        assert_eq!(
            specs("export { ProjectRow } from \"./published/ProjectRow\";\n"),
            vec!["./published/ProjectRow"],
            "was [] — a re-export compiles to the same require an import does (#3874)"
        );
        assert_eq!(specs("export * from \"./a\";\n"), vec!["./a"], "was [] — export-star too");
        assert_eq!(
            specs("export function load() {\n  return import(\"./page\");\n}\n"),
            vec!["./page"],
            "was [] — a dynamic import is an ordinary expression, so the walk cannot stop at the root"
        );

        // What it already got right, and what the flip had to PRESERVE: immune to the two cases that
        // fooled the substring scan, and a type-only import still SEEN and flagged rather than dropped —
        // it is exempt from blocking the closure, not exempt from being a composition edge (#4076).
        assert_eq!(specs("// lifted from \"./ghost\"\nimport { X } from \"./x\";\n"), vec!["./x"]);
        assert!(internal_imports("import type { T } from \"./t\";\n")[0].type_only, "type-only: still flagged");
    }

    /// The roll-up, at zero: on the eleven cases first measured, nothing disagrees with the canonical
    /// scanner any more. Pinning the number through each slice is what kept a partial flip from being
    /// mistaken for a whole one.
    ///
    /// SEVEN → THREE → ZERO. Slice 2 removed emit's four false positives by deleting its scanner
    /// outright; slice 3 removed harvest's three misses by making `internal_imports` a projection of this
    /// one. Neither column went to zero by being fixed in place — both went ABSENT, which is the only
    /// ending that stops them drifting apart again.
    ///
    /// It stays as a REGRESSION test rather than being deleted with the defect it measured: harvest still
    /// has a public `internal_imports` with its own shape (a `type_only` flag, internal-specifiers only),
    /// so it remains possible for someone to reintroduce a walk there, and this is what would notice.
    #[test]
    fn no_scanner_disagrees_with_the_canonical_one_on_any_of_the_eleven_cases() {
        const CASES: &[&str] = &[
            "export { ProjectRow } from \"./published/ProjectRow\";\n",
            "export * from \"./a\";\n",
            "import { X } from \"./x\";\n",
            "import type { T } from \"./t\";\n",
            "import { type A, type B } from \"./ab\";\n",
            "import { type A, b } from \"./ab\";\n",
            "import \"./a.css\";\n",
            "const m = await import(\"./lazy\");\n",
            "// see the note from \"./ghost\" for why\nimport { X } from \"./x\";\n",
            "const s = 'from \"./strghost\"';\nimport { X } from \"./x\";\n",
            "function f() {\n  const m = require(\"./r\");\n}\nimport { X } from \"./x\";\n",
        ];
        let mut harvest_differs = 0;
        for src in CASES {
            let canonical: Vec<String> = scan_imports(src).into_iter().map(|i| i.specifier).collect();
            // Harvest is compared on its NON-type-only imports, which is the fair comparison: its
            // contract is a spec plus a `type_only` FLAG and its caller filters on that, so counting a
            // correctly-flagged type-only import as a disagreement would charge it for being right.
            let harvested: Vec<String> =
                internal_imports(src).into_iter().filter(|i| !i.type_only).map(|i| i.spec).collect();
            if harvested != canonical {
                harvest_differs += 1;
            }
        }
        assert_eq!(harvest_differs, 0, "harvest agrees on every case — it is now a projection of this scanner");
        // Emit's four and harvest's three overlapped nowhere, which is why the count was SEVEN of eleven
        // rather than six — the first pass of this arithmetic said six and this assertion caught it.
        // Both columns are gone now, so the total is zero by the same arithmetic.
        assert_eq!(CASES.len(), 11, "the case set is the one the seven-of-eleven figure was measured over");
    }
}

tests.src:
//! The ONE import scan — what a record's source actually `require()`s once the bundler is done with it.
//!
//! # Why this exists
//!
//! This repo was running THREE import scanners and they disagreed on 7 of the 11 cases first measured,
//! with no one of them right on all:
//!
//! | case              | TS `parseImports`  | [`crate::emit`] `import_specifiers` | [`crate::harvest`] `internal_imports` |
//! |-------------------|--------------------|-------------------------------------|---------------------------------------|
//! | `export … from`   | seen               | seen                                | **MISS**                              |
//! | `export *`        | seen               | seen                                | **MISS**                              |
//! | type-only         | erased             | **FALSE POSITIVE**                   | flagged                               |
//! | dynamic `import()`| **MISS**           | seen                                | **MISS**                              |
//! | `from` in comment | ignored            | **FALSE POSITIVE**                   | ignored                               |
//! | `from` in string  | ignored            | **FALSE POSITIVE**                   | ignored                               |
//!
//! `import_specifiers` WAS a raw keyword-SUBSTRING scan, so prose and string literals read as imports and
//! type-only imports the bundler erases were counted. `internal_imports` WAS tree-sitter and clean but
//! walked only `import_statement`, so every re-export was invisible — the exact gap the TypeScript names
//! as having shipped `projectspage` broken (#3874).
//!
//! BOTH COLUMNS ARE NOW HISTORY. Slice 2 deleted `import_specifiers` and pointed emit's closure walk
//! here; slice 3 made `internal_imports` a projection of [`scan_imports_all`]. Neither was fixed in
//! place, because two implementations of one question is what let them disagree for as long as they did.
//!
//! # What "right" means here, precisely
//!
//! An import counts when the COMPILED module will `require()` it. That is a syntactic question with an
//! exact answer, which is why this is a parser and not a regex:
//!
//! * A re-export IS an import. esbuild compiles `export { X } from "./y"` to the same `require("./y")`,
//!   so a scanner blind to it certifies a closure that cannot load.
//! * A syntactically type-only import is NOT one. `import type { T } from "./t"` and a clause whose every
//!   binding carries the inline `type` modifier are both erased before anything resolves, so the module
//!   need not exist. SYNTACTIC on purpose, never inferred from the target: `import { X } from "./y"` where
//!   `X` happens to be a type is NOT erasable, because esbuild has no type information and keeps it.
//! * A dynamic `import()` IS one, and is the thing the anchored regex cannot see.
//! * A `from` inside a comment or a string is not anything. This is not hypothetical — records in this
//!   tree carry provenance headers that name a specifier in prose.
//!
//! # Its relationship to the TypeScript
//!
//! `importScan.fixtures.json` is generated from the live `parseImports` and this scanner is proved
//! against it case by case, so "right" gets an independent second opinion rather than resting on the
//! author's reading. Two cases diverge DELIBERATELY, and the fixture records the TypeScript's own answer
//! for both so the divergence lives in the artifact instead of in a Rust-only expectation: the dynamic
//! import (the regex cannot see it) and the ordering of a bare import (the TypeScript runs its two
//! regexes in sequence, so a leading side-effect import is reported last). Both are the TypeScript being
//! wrong, and both are pinned so a future edit cannot quietly change which side moved.

use tree_sitter::{Language, Node, Parser};

/// One module specifier a source imports, and the symbols it takes from it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ImportRef {
    pub specifier: String,
    /// Imported names as written on the MODULE's side (`{ a as b }` → `a`). A namespace import is `*`,
    /// a default import is `default`, and a bare side-effect import has none. This is the field the
    /// generated fixture binds, so it means exactly what the TypeScript's `parseImports` means.
    pub symbols: Vec<String>,
    /// The names a consumer should match against a set of KNOWN COMPONENTS — [`symbols`], except that a
    /// default import contributes the LOCAL binding (`import Button from "./Button"` → `Button`, not
    /// `default`) and a namespace import contributes nothing.
    ///
    /// It exists because "which module does this require" and "which component does this reference" are
    /// different questions off the same parse, and harvest asks the second to build its `composes` edges.
    /// Without it a default-imported sibling would silently stop being an edge, since `default` matches no
    /// component name — a regression invisible to the buildability count this slice is measured by.
    /// Namespace imports contribute nothing because harvest has always treated `import * as N` as opaque:
    /// `N.Thing` is a member expression, not a binding it can resolve.
    pub locals: Vec<String>,
    /// Syntactically type-only (`import type …`, or a clause whose every binding carries the inline
    /// `type` modifier), and therefore ERASED before anything resolves.
    ///
    /// [`scan_imports`] never returns one. [`scan_imports_all`] returns it flagged, for the caller that
    /// must still SEE it — harvest reports a type-only import of a sibling as a composition edge while
    /// exempting it from blocking the closure, because the graph's edges describe the source and
    /// buildability describes the bundle (#4076).
    pub type_only: bool,
}

/// Every module specifier `source` will `require()` at runtime, in SOURCE order.
///
/// Returns an empty vec when the source cannot be parsed at all — a scan is a report, and a caller
/// sweeping hundreds of records must not stop at one bad file. (Note that tree-sitter is
/// error-tolerant, so this is close to unreachable in practice: a syntactically broken file still
/// yields a tree, and the imports it *can* see are still reported.)
pub fn scan_imports(source: &str) -> Vec<ImportRef> {
    scan_imports_all(source).into_iter().filter(|i| !i.type_only).collect()
}

/// Every module specifier `source` NAMES, including the syntactically type-only ones the bundler erases,
/// each flagged by [`ImportRef::type_only`].
///
/// [`scan_imports`] is this filtered, and is what a caller asking "what does the compiled module
/// require" wants. This form is for the caller that must also see what the SOURCE says — harvest, whose
/// `composes` edges describe the source while its buildability verdict describes the bundle.
pub fn scan_imports_all(source: &str) -> Vec<ImportRef> {
    let mut parser = Parser::new();
    let language: Language = tree_sitter_typescript::LANGUAGE_TSX.into();
    if parser.set_language(&language).is_err() {
        return Vec::new();
    }
    let Some(tree) = parser.parse(source, None) else { return Vec::new() };
    let src = source.as_bytes();
    let mut out = Vec::new();
    walk(tree.root_node(), src, &mut out);
    out
}

/// Depth-first over the whole tree. `import`/`export` statements are top-level in ESM, but a dynamic
/// `import()` is an ordinary expression and can be anywhere, so the walk cannot stop at the root's
/// children — which is one of the two things `internal_imports` gets wrong.
fn walk(node: Node, src: &[u8], out: &mut Vec<ImportRef>) {
    match node.kind() {
        "import_statement" => {
            if let Some(r) = import_statement(node, src) {
                out.push(r);
            }
            return; // nothing inside an import statement is another import
        }
        "export_statement" => {
            // Only a re-export — one with a `source` — is an import. A plain `export function f() {}`
            // has no source and is not.
            if node.child_by_field_name("source").is_some() {
                if let Some(r) = export_statement(node, src) {
                    out.push(r);
                }
                return;
            }
            // `export function f() { await import("./x") }` — fall through and keep walking.
        }
        "call_expression" => {
            if let Some(r) = dynamic_import(node, src) {
                out.push(r);
                // Keep walking: the ARGUMENT may itself contain another call.
            }
        }
        _ => {}
    }
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        walk(child, src, out);
    }
}

/// `import … from "x"` / `import "x"`. A syntactically type-only import is returned FLAGGED, not
/// dropped — [`scan_imports`] filters it out, so its contract is unchanged.
fn import_statement(node: Node, src: &[u8]) -> Option<ImportRef> {
    let specifier = source_text(node, src)?;
    let type_only = is_type_only(node, src);
    let (mut symbols, mut locals) = (Vec::new(), Vec::new());
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        if child.kind() == "import_clause" {
            clause_symbols(child, src, &mut symbols, &mut locals);
        }
    }
    Some(ImportRef { specifier, symbols, locals, type_only })
}

/// `export { X } from "y"` / `export * from "y"` / `export * as ns from "y"`. `None` when type-only.
fn export_statement(node: Node, src: &[u8]) -> Option<ImportRef> {
    let specifier = source_text(node, src)?;
    let type_only = is_type_only(node, src);
    let mut symbols = Vec::new();
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        match child.kind() {
            // `export * from` — the star is a bare token; `export * as ns from` is a namespace_export.
            // Both take everything, so both are `*`, matching the TypeScript's head-starts-with-`*` rule.
            "*" | "namespace_export" => symbols.push("*".to_string()),
            "export_clause" => named_symbols(child, src, &mut symbols),
            _ => {}
        }
    }
    // A re-export binds nothing locally, so the module-side names ARE the reference set: `export { Row }
    // from "./Row"` references `Row` exactly as an import of it would.
    let locals = symbols.iter().filter(|s| *s != "*").cloned().collect();
    Some(ImportRef { specifier, symbols, locals, type_only })
}

/// `import("x")` with a literal specifier. A computed one (`import(name)`) is unknowable statically and
/// is reported as nothing rather than guessed — the honest answer, and the same one every bundler gives.
fn dynamic_import(node: Node, src: &[u8]) -> Option<ImportRef> {
    let func = node.child_by_field_name("function")?;
    if func.kind() != "import" {
        return None;
    }
    let args = node.child_by_field_name("arguments")?;
    let mut cursor = args.walk();
    for child in args.children(&mut cursor) {
        if child.kind() == "string" {
            return Some(ImportRef {
                specifier: unquote(child.utf8_text(src).ok()?),
                symbols: Vec::new(),
                locals: Vec::new(),
                type_only: false,
            });
        }
    }
    None
}

/// The statement's quoted module specifier, unquoted.
fn source_text(node: Node, src: &[u8]) -> Option<String> {
    Some(unquote(node.child_by_field_name("source")?.utf8_text(src).ok()?))
}

fn unquote(s: &str) -> String {
    s.trim_matches(|c| c == '"' || c == '\'').to_string()
}

/// Is this statement SYNTACTICALLY type-only — `import type { T } from …` / `export type { T } from …`,
/// or a named clause whose every binding carries the inline `type` modifier?
///
/// A clause with a default or namespace binding is never type-only, and an EMPTY named clause is not
/// either: `import {} from "./x"` still emits a require.
fn is_type_only(node: Node, src: &[u8]) -> bool {
    let mut cursor = node.walk();
    let mut named: Option<Node> = None;
    for child in node.children(&mut cursor) {
        match child.kind() {
            // The statement-level `type` keyword, before any clause.
            _ if child.utf8_text(src).map(str::trim) == Ok("type") && child.kind() == "type" => return true,
            "import_clause" => {
                let mut cc = child.walk();
                for g in child.children(&mut cc) {
                    match g.kind() {
                        "named_imports" => named = Some(g),
                        "identifier" | "namespace_import" => return false,
                        _ => {}
                    }
                }
            }
            "export_clause" => named = Some(child),
            "namespace_export" | "*" => return false,
            _ => {}
        }
    }
    let Some(named) = named else { return false };
    let mut any = false;
    let mut nc = named.walk();
    for spec in named.children(&mut nc) {
        if !matches!(spec.kind(), "import_specifier" | "export_specifier") {
            continue;
        }
        any = true;
        if !spec.utf8_text(src).unwrap_or_default().trim_start().starts_with("type ") {
            return false;
        }
    }
    any
}

/// The names an `import_clause` binds, on both sides at once: `out` takes the MODULE-side name (a
/// default import contributes `default`, a namespace import `*`, a named list each binding's exported
/// name), and `locals` takes what a consumer should match against known component names (the default
/// import's LOCAL identifier, nothing for a namespace, and the same exported names for a named list).
///
/// One walk for both, because they are the same parse answering two questions — see [`ImportRef::locals`].
fn clause_symbols(clause: Node, src: &[u8], out: &mut Vec<String>, locals: &mut Vec<String>) {
    let mut cursor = clause.walk();
    for child in clause.children(&mut cursor) {
        match child.kind() {
            "identifier" => {
                out.push("default".to_string());
                if let Ok(t) = child.utf8_text(src) {
                    locals.push(t.trim().to_string());
                }
            }
            "namespace_import" => out.push("*".to_string()),
            "named_imports" => {
                let before = out.len();
                named_symbols(child, src, out);
                locals.extend(out[before..].iter().cloned());
            }
            _ => {}
        }
    }
}

/// Each specifier's module-side name, with an inline `type ` modifier stripped — matching the
/// TypeScript, which keeps a mixed clause and reports its value bindings under their bare names.
fn named_symbols(list: Node, src: &[u8], out: &mut Vec<String>) {
    let mut cursor = list.walk();
    for spec in list.children(&mut cursor) {
        if !matches!(spec.kind(), "import_specifier" | "export_specifier") {
            continue;
        }
        let Some(name) = spec.child_by_field_name("name") else { continue };
        if let Ok(text) = name.utf8_text(src) {
            out.push(text.trim().to_string());
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The fixture is GENERATED from the live TypeScript (`importScan.fixtures.gen.test.ts`), so this
    /// proves Rust equals what the renderer actually does today — not what its author believed it did.
    /// Located by filename under `src/`, the convention the tunnel and planner contracts already use, so
    /// moving a feature slice does not break this test but RENAMING the fixture does (deliberately).
    fn fixture() -> serde_json::Value {
        fn find(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
            let Ok(rd) = std::fs::read_dir(dir) else { return };
            for e in rd.flatten() {
                let p = e.path();
                if p.is_dir() {
                    find(&p, out);
                } else if p.file_name().and_then(|n| n.to_str()) == Some("importScan.fixtures.json") {
                    out.push(p);
                }
            }
        }
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../src");
        let mut found = Vec::new();
        find(&root, &mut found);
        assert_eq!(found.len(), 1, "expected one importScan.fixtures.json, got {found:?}");
        serde_json::from_str(&std::fs::read_to_string(&found[0]).unwrap()).unwrap()
    }

    /// The two labels whose TypeScript answer this scanner deliberately does NOT reproduce, because on
    /// both the TypeScript is wrong. Named by their fixture label so the exemption cannot silently widen
    /// to a case it was never argued for — adding a third requires editing this list and saying why.
    const INTENDED_DIVERGENCES: &[(&str, &str)] = &[
        (
            "a dynamic import — the regex cannot see it",
            "the anchored regex cannot see `import(\"x\")`; a dynamic import IS a require and this scanner reports it",
        ),
        (
            "a bare import BEFORE a named one",
            "the TypeScript runs its two regexes in sequence, so a leading side-effect import is reported LAST; this scanner reports source order",
        ),
    ];

    /// The TypeScript's answer for one case, as `(specifier, symbols)` pairs.
    ///
    /// PROJECTED, because those are the only two things `parseImports` reports and therefore the only two
    /// the generated fixture can bind. `locals` and `type_only` are this scanner's own additions — asked
    /// of the same parse for consumers the TypeScript never had — and are pinned by their own tests
    /// below. Comparing whole `ImportRef`s would require inventing fixture values for fields the
    /// TypeScript has no opinion about, which is how a parity test starts asserting its own assumptions.
    fn parsed(case: &serde_json::Value) -> Vec<(String, Vec<String>)> {
        case["imports"]
            .as_array()
            .expect("imports")
            .iter()
            .map(|i| {
                (
                    i["specifier"].as_str().unwrap().to_string(),
                    i["symbols"].as_array().unwrap().iter().map(|s| s.as_str().unwrap().to_string()).collect(),
                )
            })
            .collect()
    }

    /// The same projection, taken off this scanner.
    fn scanned(source: &str) -> Vec<(String, Vec<String>)> {
        scan_imports(source).into_iter().map(|i| (i.specifier, i.symbols)).collect()
    }

    /// An expected `ImportRef` for the shapes asserted directly below: `locals` mirrors the module-side
    /// symbols minus a namespace `*`, which is exactly what a named import and a re-export produce. A
    /// DEFAULT import is the one shape this cannot express — its local binding is not `default` — and it
    /// has its own test rather than a special case here.
    fn iref(specifier: &str, symbols: &[&str]) -> ImportRef {
        ImportRef {
            specifier: specifier.to_string(),
            symbols: symbols.iter().map(|s| (*s).to_string()).collect(),
            locals: symbols.iter().filter(|s| **s != "*").map(|s| (*s).to_string()).collect(),
            type_only: false,
        }
    }

    /// Reports EVERY mismatch at once rather than dying on the first — when a port is wrong it is
    /// usually wrong in a PATTERN, and one failing assertion hides the shape of it.
    #[test]
    fn the_scanner_matches_the_typescript_case_for_case() {
        let doc = fixture();
        let cases = doc["cases"].as_array().expect("cases");
        assert!(cases.len() >= 25, "fixture shrank to {} cases — regenerate it", cases.len());

        let mut mismatches = Vec::new();
        let mut checked = 0usize;
        for case in cases {
            let label = case["label"].as_str().unwrap();
            if INTENDED_DIVERGENCES.iter().any(|(l, _)| *l == label) {
                continue;
            }
            checked += 1;
            let want = parsed(case);
            let got = scanned(case["source"].as_str().unwrap());
            if got != want {
                mismatches.push(format!("  {label}\n    ts   {want:?}\n    rust {got:?}"));
            }
        }
        assert!(
            checked >= 25,
            "only {checked} cases were actually compared — an exemption list that swallowed the suite \
             would make this test vacuous"
        );
        assert!(
            mismatches.is_empty(),
            "the Rust scanner disagrees with the live TypeScript on {} of {checked} cases:\n{}",
            mismatches.len(),
            mismatches.join("\n")
        );
    }

    /// The exempted cases must ACTUALLY diverge. Without this, an exemption is a place a real regression
    /// can hide: if the scanner were "fixed" to reproduce the TypeScript's bug, the parity test above
    /// would skip it and stay green.
    #[test]
    fn every_intended_divergence_actually_diverges() {
        let doc = fixture();
        let cases = doc["cases"].as_array().expect("cases");
        for (label, why) in INTENDED_DIVERGENCES {
            let case = cases
                .iter()
                .find(|c| c["label"].as_str() == Some(label))
                .unwrap_or_else(|| panic!("no fixture case labelled {label:?} — the exemption is stale"));
            let ts = parsed(case);
            let rust = scanned(case["source"].as_str().unwrap());
            assert_ne!(rust, ts, "{label}: expected to diverge ({why}) but the two now agree");
        }
    }

    /// Each intended divergence, pinned to the value this scanner gives — an inequality alone would let
    /// the answer be anything at all as long as it was not the TypeScript's.
    #[test]
    fn the_divergences_give_the_right_answer_not_merely_a_different_one() {
        let dynamic = scan_imports("const m = await import(\"./lazy\");\n");
        assert_eq!(dynamic, vec![iref("./lazy", &[])]);

        let ordered = scan_imports("import \"./a.css\";\nimport { B } from \"./b\";\n");
        assert_eq!(
            ordered.iter().map(|i| i.specifier.as_str()).collect::<Vec<_>>(),
            vec!["./a.css", "./b"],
            "source order, not regex-pass order"
        );
    }

    /// The three cases the OTHER two Rust scanners get wrong, asserted directly. The parity test covers
    /// them through the fixture, but naming them here is what a reader of slices 2 and 3 comes looking
    /// for — this is the behaviour those flips are buying.
    #[test]
    fn it_fixes_what_the_other_two_rust_scanners_get_wrong() {
        // harvest::internal_imports walks only `import_statement`, so both of these are invisible to it.
        assert_eq!(
            scan_imports("export { ProjectRow } from \"./published/ProjectRow\";\n"),
            vec![iref("./published/ProjectRow", &["ProjectRow"])],
            "a re-export compiles to the same require an import does (#3874)"
        );
        assert_eq!(
            scan_imports("export * from \"./a\";\n"),
            vec![iref("./a", &["*"])]
        );

        // All three of these were false positives in emit's old substring scan.
        assert!(
            scan_imports("// see the note from \"./ghost\" for why\n").is_empty(),
            "prose is not an import — records in this tree carry provenance headers"
        );
        assert!(scan_imports("const s = 'from \"./strghost\"';\n").is_empty(), "a string literal is not an import");
        assert!(
            scan_imports("import type { T } from \"./t\";\n").is_empty(),
            "a type-only import is erased before anything resolves"
        );
    }

    /// Type-only detection is SYNTACTIC, never inferred from the target — esbuild has no type
    /// information, so an import of something that happens to be a type still emits a require.
    #[test]
    fn type_only_is_syntactic_and_a_mixed_clause_survives() {
        assert!(scan_imports("import { type A, type B } from \"./ab\";\n").is_empty());
        assert_eq!(
            scan_imports("import { type A, b } from \"./ab\";\n"),
            vec![iref("./ab", &["A", "b"])],
            "one value binding keeps the whole import"
        );
        assert_eq!(
            scan_imports("import { T } from \"./t\";\n").len(),
            1,
            "a value-syntax import of a type is NOT erasable"
        );
        assert!(scan_imports("export type { T } from \"./t\";\n").is_empty());
        assert_eq!(
            scan_imports("import {} from \"./x\";\n").len(),
            1,
            "an EMPTY clause is not type-only — it still emits a require"
        );
    }

    /// `locals` is what a consumer matches against KNOWN COMPONENT NAMES, and it differs from `symbols`
    /// in exactly two shapes. Both matter to harvest's `composes` edges, and getting either wrong is
    /// invisible to a buildability count — which is the number slice 3 is measured by.
    #[test]
    fn locals_report_the_binding_a_consumer_can_match_not_the_module_side_name() {
        let one = |src: &str| scan_imports(src).into_iter().next().expect("one import");

        // A DEFAULT import: the module-side name is `default`, which matches no component. The local
        // binding is the name the JSX actually renders.
        let d = one("import Button from \"./Button\";\n");
        assert_eq!(d.symbols, vec!["default"], "module side is unchanged — the fixture binds this");
        assert_eq!(d.locals, vec!["Button"], "consumer side is the local binding");

        // A NAMESPACE import is opaque: `N.Thing` is a member expression, not a resolvable binding.
        let n = one("import * as N from \"./mod\";\n");
        assert_eq!(n.symbols, vec!["*"]);
        assert!(n.locals.is_empty(), "a namespace binding names no component");

        // Everywhere else the two agree, including through an alias, where BOTH are the exported name.
        let a = one("import { Row as R } from \"./Row\";\n");
        assert_eq!(a.symbols, vec!["Row"]);
        assert_eq!(a.locals, vec!["Row"]);

        // A re-export binds nothing locally, so its module-side names are the reference set.
        let e = one("export { Row } from \"./Row\";\n");
        assert_eq!(e.locals, vec!["Row"], "a re-export references Row as surely as an import of it does");
    }

    /// `scan_imports_all` is the superset, and `scan_imports` is it filtered — asserted together so the
    /// filtered form's contract cannot drift from the flagged one.
    #[test]
    fn scan_imports_all_reports_the_erased_imports_flagged_and_scan_imports_drops_them() {
        let src = "import type { T } from \"./t\";\nimport { type A, type B } from \"./ab\";\nimport { X } from \"./x\";\n";
        let all = scan_imports_all(src);
        assert_eq!(
            all.iter().map(|i| (i.specifier.as_str(), i.type_only)).collect::<Vec<_>>(),
            vec![("./t", true), ("./ab", true), ("./x", false)],
            "both erased spellings are SEEN and flagged — harvest reports them as composition edges (#4076)"
        );
        assert_eq!(
            scan_imports(src).into_iter().map(|i| i.specifier).collect::<Vec<_>>(),
            vec!["./x"],
            "the filtered form is unchanged: only what the compiled module requires"
        );
        assert!(scan_imports_all("export type { T } from \"./t\";\n")[0].type_only, "a type-only re-export too");
    }

    /// A dynamic import nested inside a function body — the reason the walk cannot stop at the root's
    /// children, and a shape a lazy-loaded page actually has.
    #[test]
    fn a_nested_dynamic_import_is_found_and_a_computed_one_is_not_guessed() {
        let nested = scan_imports("export function load() {\n  return import(\"./page\");\n}\n");
        assert_eq!(nested, vec![iref("./page", &[])]);
        assert!(
            scan_imports("const n = \"x\";\nconst m = await import(n);\n").is_empty(),
            "a computed specifier is unknowable statically and is reported as nothing, never guessed"
        );
    }

    /// An unparseable source reports what it can rather than throwing — a sweep over hundreds of records
    /// must not stop at one bad file.
    #[test]
    fn a_broken_source_still_reports_what_it_can() {
        let got = scan_imports("import { X } from \"./x\";\nfunction ( { { {\n");
        assert_eq!(got.len(), 1, "the valid import above the damage is still reported: {got:?}");
    }
}

/// WHAT THE OTHER TWO SCANNERS ANSWER TODAY — a characterization test, not an aspiration.
///
/// Slices 2 and 3 flip [`crate::emit`] and [`crate::harvest`] onto [`scan_imports`]. The value of a flip
/// is the set of answers it CHANGES, and that set is only legible if today's answers are written down
/// before it happens. So this pins the current behaviour of both, defects included, and each defective
/// expectation says so in place.
///
/// It is deliberately not phrased as "these are wrong". A characterization test that asserted the right
/// answer would be red from the moment it was written and would have to be disabled to land, which is how
/// a known defect becomes an ignored one.
#[cfg(test)]
mod existing_scanners {
    use super::scan_imports;
    use crate::harvest::internal_imports;

    /// The four cases emit used to get wrong, now stated as the answers it gives.
    ///
    /// THIS IS THE SAME TEST, UPDATED — not a new one, and not the old one deleted. It was written as a
    /// characterization test asserting emit's WRONG answers (`import_specifiers` was a keyword-SUBSTRING
    /// scan: `./ghost` out of a comment, `./strghost` out of a string literal, and two type-only imports
    /// the bundler erases), so that the defect could not change unnoticed. Slice 2 pointed emit at
    /// `scan_imports` and deleted that scanner, so the four cases keep their place here and their
    /// expectations flip. Reading the diff of this function IS the behaviour change.
    ///
    /// What emit got right — a re-export and a dynamic import — is asserted below, because a flip that
    /// fixed the false positives by losing a true positive would be a worse scanner, not a better one.
    #[test]
    fn emit_no_longer_reports_the_four_things_that_are_not_imports() {
        let specs = |src: &str| -> Vec<String> { scan_imports(src).into_iter().map(|i| i.specifier).collect() };

        assert_eq!(
            specs("// see the note from \"./ghost\" for why\nimport { X } from \"./x\";\n"),
            vec!["./x"],
            "was [./ghost, ./x] — prose is not an import"
        );
        assert_eq!(
            specs("const s = 'from \"./strghost\"';\nimport { X } from \"./x\";\n"),
            vec!["./x"],
            "was [./strghost, ./x] — a string literal is not an import"
        );
        assert!(
            specs("import type { T } from \"./t\";\n").is_empty(),
            "was [./t] — a type-only import is erased by the bundler and never required"
        );
        assert!(
            specs("import { type A, type B } from \"./ab\";\n").is_empty(),
            "was [./ab] — an all-inline-type clause is erased too"
        );

        // What it already got right, and what the flip had to PRESERVE.
        assert_eq!(specs("export { X } from \"./y\";\n"), vec!["./y"], "re-export: still seen");
        assert_eq!(specs("const m = await import(\"./lazy\");\n"), vec!["./lazy"], "dynamic: still seen");
    }

    /// The three forms harvest used to be blind to, now stated as the answers it gives.
    ///
    /// THIS IS THE SAME TEST, UPDATED — not a new one, and not the old one deleted. It was written as a
    /// characterization test asserting that `internal_imports` returned NOTHING for a re-export, an
    /// export-star and a dynamic import, because it walked only the root's `import_statement` children.
    /// Slice 3 made it a projection of `scan_imports_all`, so the three cases keep their place here and
    /// their expectations flip. Reading the diff of this function IS the behaviour change.
    ///
    /// Why it mattered: esbuild compiles a re-export to the same `require()` an import produces, so a
    /// component whose closure needed a re-exported sibling was certified `buildable: true` and then
    /// could not load (#3874).
    #[test]
    fn harvest_now_sees_a_re_export_and_a_dynamic_import() {
        let specs = |src: &str| -> Vec<String> { internal_imports(src).into_iter().map(|i| i.spec).collect() };

        assert_eq!(
            specs("export { ProjectRow } from \"./published/ProjectRow\";\n"),
            vec!["./published/ProjectRow"],
            "was [] — a re-export compiles to the same require an import does (#3874)"
        );
        assert_eq!(specs("export * from \"./a\";\n"), vec!["./a"], "was [] — export-star too");
        assert_eq!(
            specs("export function load() {\n  return import(\"./page\");\n}\n"),
            vec!["./page"],
            "was [] — a dynamic import is an ordinary expression, so the walk cannot stop at the root"
        );

        // What it already got right, and what the flip had to PRESERVE: immune to the two cases that
        // fooled the substring scan, and a type-only import still SEEN and flagged rather than dropped —
        // it is exempt from blocking the closure, not exempt from being a composition edge (#4076).
        assert_eq!(specs("// lifted from \"./ghost\"\nimport { X } from \"./x\";\n"), vec!["./x"]);
        assert!(internal_imports("import type { T } from \"./t\";\n")[0].type_only, "type-only: still flagged");
    }

    /// The roll-up, at zero: on the eleven cases first measured, nothing disagrees with the canonical
    /// scanner any more. Pinning the number through each slice is what kept a partial flip from being
    /// mistaken for a whole one.
    ///
    /// SEVEN → THREE → ZERO. Slice 2 removed emit's four false positives by deleting its scanner
    /// outright; slice 3 removed harvest's three misses by making `internal_imports` a projection of this
    /// one. Neither column went to zero by being fixed in place — both went ABSENT, which is the only
    /// ending that stops them drifting apart again.
    ///
    /// It stays as a REGRESSION test rather than being deleted with the defect it measured: harvest still
    /// has a public `internal_imports` with its own shape (a `type_only` flag, internal-specifiers only),
    /// so it remains possible for someone to reintroduce a walk there, and this is what would notice.
    #[test]
    fn no_scanner_disagrees_with_the_canonical_one_on_any_of_the_eleven_cases() {
        const CASES: &[&str] = &[
            "export { ProjectRow } from \"./published/ProjectRow\";\n",
            "export * from \"./a\";\n",
            "import { X } from \"./x\";\n",
            "import type { T } from \"./t\";\n",
            "import { type A, type B } from \"./ab\";\n",
            "import { type A, b } from \"./ab\";\n",
            "import \"./a.css\";\n",
            "const m = await import(\"./lazy\");\n",
            "// see the note from \"./ghost\" for why\nimport { X } from \"./x\";\n",
            "const s = 'from \"./strghost\"';\nimport { X } from \"./x\";\n",
            "function f() {\n  const m = require(\"./r\");\n}\nimport { X } from \"./x\";\n",
        ];
        let mut harvest_differs = 0;
        for src in CASES {
            let canonical: Vec<String> = scan_imports(src).into_iter().map(|i| i.specifier).collect();
            // Harvest is compared on its NON-type-only imports, which is the fair comparison: its
            // contract is a spec plus a `type_only` FLAG and its caller filters on that, so counting a
            // correctly-flagged type-only import as a disagreement would charge it for being right.
            let harvested: Vec<String> =
                internal_imports(src).into_iter().filter(|i| !i.type_only).map(|i| i.spec).collect();
            if harvested != canonical {
                harvest_differs += 1;
            }
        }
        assert_eq!(harvest_differs, 0, "harvest agrees on every case — it is now a projection of this scanner");
        // Emit's four and harvest's three overlapped nowhere, which is why the count was SEVEN of eleven
        // rather than six — the first pass of this arithmetic said six and this assertion caught it.
        // Both columns are gone now, so the total is zero by the same arithmetic.
        assert_eq!(CASES.len(), 11, "the case set is the one the seven-of-eleven figure was measured over");
    }
}

implementations.code:
//! The global UI-kit store (#2465) — immutable, versioned kit artifacts shared across blueprints.
//!
//! A blueprint REFERENCES a UI kit (a lockfile-style pin `{ id, version, hash, source? }`) instead
//! of embedding it, so the same kit is stored — and downloaded — exactly once no matter how many
//! blueprints pin it. Layout, one entry per `id@version`:
//!
//! ```text
//! ~/.base-studio-code/kits/<publisher>/<name>/<version>/
//!   manifest.json     # { id, version, sha256, kind, source? }
//!   kit.json          # the artifact (design-files kind: design.dc.html instead)
//! ```
//!
//! (The same `kits/` root also holds the FLAT component-library kit records —
//! `kits/<id>.json`, the `bsc component kit` verbatim-JSON store. The two coexist:
//! versioned entries are publisher DIRECTORIES, flat records are `.json` FILES, and
//! [`KitStore::list`] walks only the directory shape.)
//!
//! Identity is `id` (a publisher-scoped slug, `bsc/react-ui`) + an exact semver `version` + the
//! sha256 of the artifact bytes. A published `id@version` is IMMUTABLE: [`KitStore::add`] refuses to
//! overwrite an existing version with different content (changing a kit means bumping the version),
//! and is an idempotent no-op for identical content. `add` can also verify an expected sha256 BEFORE
//! writing (the resolve flow's fetch verification, #2433 posture) — on mismatch nothing is stored.
//!
//! The PACKAGED default `bsc/react-ui@1.0.0` (the generated `data/components/react-ui.json`, hash
//! sidecar `data/ui/react-ui-kit.meta.json`, both stamped by `reactUiKit.gen.test.ts`) resolves as a
//! store entry WITHOUT being copied at install time: `get`/`artifact`/`list`/`verify` fall back to
//! the packaged bytes (read at runtime by `bsc_util::packaged`) when the entry isn't materialized on
//! disk — so every install has the default kit with zero setup, the same store-lookup →
//! packaged-fallback overlay pattern as `@data`.

use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::path::{Path, PathBuf};

/// The packaged default kit's artifact — the generated `react-ui.json` (see the module docs).
/// CRLF-normalized before hashing/serving: the file is pinned `eol=lf` in .gitattributes, but a
/// pre-pin checkout may still hold it CRLF, and LF is the canonical (hash-recorded) byte form.
///
/// LOADED AT RUNTIME, not `include_str!`'d (see [`bsc_util::packaged`]): at 5.3 MB and ~190 commits
/// a month this file made every record edit recompile this crate, `bsc-component` and `bsc`.
/// Cached in a `OnceLock` and handed out as `&'static str`, so callers are unchanged.
pub fn packaged_kit_json() -> &'static str {
    static V: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    V.get_or_init(|| bsc_util::packaged::read_required("components/react-ui.json")).as_str()
}

/// The packaged kit's hash sidecar `{ id, version, kind, sha256 }` — generated alongside the
/// artifact so the packaged entry's manifest (incl. its content hash) needs no runtime hashing.
///
/// Runtime-loaded for the same reason as [`packaged_kit_json`], even though it is only 156 bytes:
/// it is regenerated in LOCKSTEP with the artifact (186 commits against 190), so embedding it alone
/// would have preserved the entire rebuild cost. Churn, not size, is what decides.
pub fn packaged_kit_meta_json() -> &'static str {
    static V: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    V.get_or_init(|| bsc_util::packaged::read_required("ui/react-ui-kit.meta.json")).as_str()
}

/// The two artifact kinds a store entry can hold (#2465): a component kit (a self-contained kit
/// JSON) or a design-files bundle (a `.dc.html` design document). Sibling artifacts — own id, same
/// store.
pub const KIT_KINDS: &[&str] = &["component-kit", "design-files"];

/// Lowercase hex sha256 of `bytes` — the store's one content-hash form.
pub fn sha256_hex(bytes: &[u8]) -> String {
    Sha256::digest(bytes).iter().map(|b| format!("{b:02x}")).collect()
}

/// The packaged artifact's canonical (LF) bytes.
fn packaged_artifact() -> String {
    packaged_kit_json().replace("\r\n", "\n")
}

/// The packaged entry's manifest, from the embedded sidecar, with `"source": "packaged"` stamped so
/// a reader can tell it apart from a fetched entry. `None` only on a malformed sidecar (guarded by
/// tests, so not in practice).
pub fn packaged_manifest() -> Option<Value> {
    let mut m: Value = serde_json::from_str(packaged_kit_meta_json()).ok()?;
    m.as_object_mut()?.insert("source".into(), json!("packaged"));
    Some(m)
}

/// Validate a store id: a publisher-scoped slug `publisher/name`, each segment lowercase
/// `[a-z0-9-]` starting alphanumeric. Strict (reject, not slugify) — the id IS the identity a hash
/// is pinned against, so silently rewriting it would corrupt the reference.
pub fn validate_id(id: &str) -> Result<(), String> {
    let seg_ok = |s: &str| {
        s.starts_with(|c: char| c.is_ascii_lowercase() || c.is_ascii_digit())
            && s.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
    };
    match id.split('/').collect::<Vec<_>>().as_slice() {
        [publisher, name] if seg_ok(publisher) && seg_ok(name) => Ok(()),
        _ => Err(format!(
            "invalid kit id '{id}' — want a publisher-scoped slug like 'bsc/react-ui' (lowercase [a-z0-9-], one '/')"
        )),
    }
}

/// Validate a version: `[0-9A-Za-z.-]`, starting alphanumeric (so `.`/`..`/empty can never form a
/// path segment). Exact versions only — pins carry no ranges.
pub fn validate_version(version: &str) -> Result<(), String> {
    let ok = version.starts_with(|c: char| c.is_ascii_alphanumeric())
        && version.chars().all(|c| c.is_ascii_alphanumeric() || c == '.' || c == '-');
    if ok { Ok(()) } else { Err(format!("invalid kit version '{version}' — want a semver like '1.0.0'")) }
}

fn validate_kind(kind: &str) -> Result<(), String> {
    if KIT_KINDS.contains(&kind) {
        Ok(())
    } else {
        Err(format!("invalid kit kind '{kind}' — want one of: {}", KIT_KINDS.join(" | ")))
    }
}

/// The artifact's file name for a kind (deterministic from the manifest, so no extra field).
fn artifact_name(kind: &str) -> &'static str {
    if kind == "design-files" { "design.dc.html" } else { "kit.json" }
}

/// Split an `id@version` ref on the LAST `@` (the id itself never carries one, but be forgiving).
pub fn split_ref(kit_ref: &str) -> Result<(&str, &str), String> {
    match kit_ref.rsplit_once('@') {
        Some((id, version)) if !id.is_empty() && !version.is_empty() => Ok((id, version)),
        _ => Err(format!("invalid kit ref '{kit_ref}' — want '<id>@<version>' (e.g. bsc/react-ui@1.0.0)")),
    }
}

/// Refuse a HOLLOW or shapeless release BEFORE the immutable entry is written (#3167). Releases saved a
/// designer's session, but `add` used to accept whatever bytes it was handed — so a silently-failed
/// assembly pipeline could store an empty or componentless "kit". A release must carry a real payload:
///
/// - **any kind:** empty / whitespace-only content is refused (an empty `--file`, or nothing on stdin —
///   the pipeline produced no bytes);
/// - **`component-kit`:** the content must parse as a JSON OBJECT holding a NON-EMPTY `components`
///   array — the exact shape `release add` stores — so a parse failure, a non-object, a missing
///   `components`, or zero components is refused (a silently-failed assembly, never a real kit);
/// - **`design-files`:** an opaque `.dc.html` bundle, so only the non-empty floor applies.
///
/// The `release add` verb calls this before [`KitStore::add`]/[`KitStore::add_verified`], so no path can
/// persist a hollow entry. (The store itself stays content-agnostic — it hashes opaque bytes — so this
/// shape gate lives at the one user-facing entry point, not in the immutable-store primitive.)
pub fn validate_artifact(kind: &str, content: &str) -> Result<(), String> {
    if content.trim().is_empty() {
        return Err(
            "refusing to store an EMPTY release artifact — the release produced no bytes (an empty --file, or nothing on stdin)"
                .to_string(),
        );
    }
    if kind == "component-kit" {
        let value: Value = serde_json::from_str(content).map_err(|e| {
            format!(
                "release artifact is not valid JSON: {e} — a component-kit release must be the kit artifact object {{ id, version, kit, components }}"
            )
        })?;
        let components = value.get("components").and_then(Value::as_array).ok_or_else(|| {
            "release artifact has no `components` array — it isn't a kit artifact ({ id, version, kit, components }); refusing to store a shapeless release"
                .to_string()
        })?;
        if components.is_empty() {
            return Err(
                "release artifact has ZERO components — refusing to store a hollow release (the assembly produced no components)"
                    .to_string(),
            );
        }
    }
    Ok(())
}

/// Assemble a `component-kit` release artifact from a live kit + its components (#3167, the
/// `--from-store` one-shot) — so a release no longer has to be hand-piped through `--file`. Produces the
/// SAME shape `release add --file` expects: a JSON object `{ id, version, kit, components }`, where `kit`
/// is the kit record from the component library and `components` is every component the caller gathered
/// for it. `id`/`version` are the RELEASE's store identity (the positional `add` args), NOT the working
/// kit's own id. Serialized pretty with a trailing newline — the artifact's canonical form (matching the
/// packaged `react-ui.json`). The emptiness floor is [`validate_artifact`], which the `add` verb runs on
/// this result, so an assembly that gathered no components is refused there rather than silently stored.
pub fn assemble_artifact(id: &str, version: &str, kit: Value, components: Vec<Value>) -> String {
    let artifact = json!({ "id": id, "version": version, "kit": kit, "components": components });
    // Pretty + trailing newline mirrors the generator's canonical bytes (`JSON.stringify(…, 2) + "\n"`).
    let mut s = serde_json::to_string_pretty(&artifact).unwrap_or_else(|_| "{}".to_string());
    s.push('\n');
    s
}

/// A handle to the versioned kit store rooted at a directory (`~/.base-studio-code/kits/` by
/// default). All operations resolve store-first, then fall back to the packaged entry.
pub struct KitStore {
    dir: PathBuf,
}

impl KitStore {
    pub fn new(dir: impl Into<PathBuf>) -> Self {
        KitStore { dir: dir.into() }
    }

    /// The default user store at `~/.base-studio-code/kits/`. `Err` when no home dir resolves.
    pub fn open_default() -> Result<Self, String> {
        let base = bsc_util::bsc_base_dir()
            .ok_or("could not resolve a home directory; set HOME/USERPROFILE")?;
        Ok(KitStore::new(base.join("kits")))
    }

    pub fn dir(&self) -> &Path {
        &self.dir
    }

    /// The on-disk entry dir for `id@version` (validated, so it can never escape the store root).
    fn entry_dir(&self, id: &str, version: &str) -> Result<PathBuf, String> {
        validate_id(id)?;
        validate_version(version)?;
        let (publisher, name) = id.split_once('/').expect("validated id has one '/'");
        Ok(self.dir.join(publisher).join(name).join(version))
    }

    /// The manifest of an entry MATERIALIZED on disk, or `None`.
    fn manifest_on_disk(&self, id: &str, version: &str) -> Result<Option<Value>, String> {
        let path = self.entry_dir(id, version)?.join("manifest.json");
        match std::fs::read_to_string(&path) {
            Ok(s) => Ok(Some(
                serde_json::from_str(&s).map_err(|e| format!("corrupt manifest {}: {e}", path.display()))?,
            )),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
            Err(e) => Err(format!("read {}: {e}", path.display())),
        }
    }

    /// Whether `id@version` is the packaged default entry.
    fn is_packaged(id: &str, version: &str) -> bool {
        packaged_manifest().is_some_and(|m| {
            m.get("id").and_then(Value::as_str) == Some(id)
                && m.get("version").and_then(Value::as_str) == Some(version)
        })
    }

    /// One entry's manifest: the on-disk entry, else the packaged fallback, else `None`.
    pub fn get(&self, id: &str, version: &str) -> Result<Option<Value>, String> {
        if let Some(m) = self.manifest_on_disk(id, version)? {
            return Ok(Some(m));
        }
        Ok(if Self::is_packaged(id, version) { packaged_manifest() } else { None })
    }

    /// One entry's artifact text: on-disk, else the packaged fallback, else `None`.
    pub fn artifact(&self, id: &str, version: &str) -> Result<Option<String>, String> {
        if let Some(m) = self.manifest_on_disk(id, version)? {
            let kind = m.get("kind").and_then(Value::as_str).unwrap_or("component-kit");
            let path = self.entry_dir(id, version)?.join(artifact_name(kind));
            return std::fs::read_to_string(&path)
                .map(Some)
                .map_err(|e| format!("read {}: {e}", path.display()));
        }
        Ok(if Self::is_packaged(id, version) { Some(packaged_artifact()) } else { None })
    }

    /// Add `id@version` with the artifact `content`. Computes the sha256; when `expected_sha256` is
    /// given the content is verified BEFORE anything is written (mismatch ⇒ `Err`, no store entry —
    /// the resolve flow's loud rejection). Immutability: an existing `id@version` (on disk or the
    /// packaged entry) with a DIFFERENT hash is refused; identical content is an idempotent no-op.
    /// Returns the entry's manifest.
    pub fn add(
        &self,
        id: &str,
        version: &str,
        kind: &str,
        source: Option<&str>,
        content: &str,
    ) -> Result<Value, String> {
        self.add_verified(id, version, kind, source, content, None)
    }

    /// [`KitStore::add`] with an optional expected sha256 (lowercase hex) verified before writing.
    pub fn add_verified(
        &self,
        id: &str,
        version: &str,
        kind: &str,
        source: Option<&str>,
        content: &str,
        expected_sha256: Option<&str>,
    ) -> Result<Value, String> {
        validate_id(id)?;
        validate_version(version)?;
        validate_kind(kind)?;
        let hash = sha256_hex(content.as_bytes());
        if let Some(expected) = expected_sha256 {
            if !expected.eq_ignore_ascii_case(&hash) {
                return Err(format!(
                    "sha256 mismatch for {id}@{version}: expected {expected}, got {hash} — refusing to store"
                ));
            }
        }
        // Immutability: a published id@version never changes content. `get` also covers the
        // packaged entry, so the embedded default can't be shadowed by different bytes either.
        if let Some(existing) = self.get(id, version)? {
            let existing_hash = existing.get("sha256").and_then(Value::as_str).unwrap_or("");
            if existing_hash.eq_ignore_ascii_case(&hash) {
                return Ok(existing); // identical content — idempotent
            }
            return Err(format!(
                "{id}@{version} already exists with different content (sha256 {existing_hash} vs {hash}) — published versions are immutable; bump the version"
            ));
        }
        let mut manifest = json!({ "id": id, "version": version, "sha256": hash, "kind": kind });
        if let Some(src) = source.filter(|s| !s.is_empty()) {
            manifest["source"] = json!(src);
        }
        let dir = self.entry_dir(id, version)?;
        std::fs::create_dir_all(&dir).map_err(|e| format!("create {}: {e}", dir.display()))?;
        std::fs::write(dir.join(artifact_name(kind)), content)
            .map_err(|e| format!("write artifact: {e}"))?;
        let pretty = serde_json::to_string_pretty(&manifest).map_err(|e| e.to_string())?;
        std::fs::write(dir.join("manifest.json"), pretty).map_err(|e| format!("write manifest: {e}"))?;
        Ok(manifest)
    }

    /// Every entry's manifest: the on-disk `<publisher>/<name>/<version>/manifest.json` walk plus
    /// the packaged entry when it isn't materialized. Sorted by (id, version) for stable output.
    /// Flat `kits/<id>.json` files (the component-library kit records) are ignored by shape.
    pub fn list(&self) -> Vec<Value> {
        let mut out: Vec<Value> = Vec::new();
        let dirs = |p: &Path| -> Vec<PathBuf> {
            std::fs::read_dir(p)
                .map(|rd| rd.flatten().map(|e| e.path()).filter(|p| p.is_dir()).collect())
                .unwrap_or_default()
        };
        for publisher in dirs(&self.dir) {
            for name in dirs(&publisher) {
                for version in dirs(&name) {
                    if let Ok(s) = std::fs::read_to_string(version.join("manifest.json")) {
                        if let Ok(m) = serde_json::from_str::<Value>(&s) {
                            out.push(m);
                        }
                    }
                }
            }
        }
        if let Some(packaged) = packaged_manifest() {
            let same = |m: &Value| {
                m.get("id") == packaged.get("id") && m.get("version") == packaged.get("version")
            };
            if !out.iter().any(same) {
                out.push(packaged);
            }
        }
        let key = |m: &Value| {
            (
                m.get("id").and_then(Value::as_str).unwrap_or("").to_string(),
                m.get("version").and_then(Value::as_str).unwrap_or("").to_string(),
            )
        };
        out.sort_by_key(key);
        out
    }

    /// Remove a materialized entry (no-op when absent on disk). The packaged entry is embedded in
    /// the app and cannot be removed — removing its materialized copy just falls back to it.
    pub fn remove(&self, id: &str, version: &str) -> Result<(), String> {
        let dir = self.entry_dir(id, version)?;
        if dir.exists() {
            std::fs::remove_dir_all(&dir).map_err(|e| format!("remove {}: {e}", dir.display()))?;
        }
        Ok(())
    }

    /// Recompute an entry's artifact hash and check it against its manifest's `sha256`. `Ok(hash)`
    /// when they match; `Err` on a missing entry or a mismatch (a corrupted/tampered artifact).
    pub fn verify(&self, id: &str, version: &str) -> Result<String, String> {
        let manifest = self
            .get(id, version)?
            .ok_or_else(|| format!("{id}@{version} is not in the kit store"))?;
        let artifact = self
            .artifact(id, version)?
            .ok_or_else(|| format!("{id}@{version} has no artifact"))?;
        let recorded = manifest.get("sha256").and_then(Value::as_str).unwrap_or("").to_string();
        let actual = sha256_hex(artifact.as_bytes());
        if recorded.eq_ignore_ascii_case(&actual) {
            Ok(actual)
        } else {
            Err(format!(
                "{id}@{version} FAILS verification: manifest records sha256 {recorded}, artifact hashes to {actual}"
            ))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tmp_store() -> (KitStore, PathBuf) {
        use std::sync::atomic::{AtomicU64, Ordering};
        static N: AtomicU64 = AtomicU64::new(0);
        let dir = std::env::temp_dir().join(format!(
            "bsc-ui-kit-store-{}-{}",
            std::process::id(),
            N.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = std::fs::remove_dir_all(&dir);
        (KitStore::new(dir.clone()), dir)
    }

    #[test]
    fn add_get_artifact_list_remove_round_trips() {
        let (s, dir) = tmp_store();
        let m = s.add("acme/neon", "1.2.0", "component-kit", Some("https://gist.github.com/x"), "{\"kit\":1}\n").unwrap();
        // Manifest shape: id/version/sha256/kind/source.
        assert_eq!(m["id"], "acme/neon");
        assert_eq!(m["version"], "1.2.0");
        assert_eq!(m["kind"], "component-kit");
        assert_eq!(m["source"], "https://gist.github.com/x");
        assert_eq!(m["sha256"].as_str().unwrap(), sha256_hex(b"{\"kit\":1}\n"));

        // On-disk layout: kits/<publisher>/<name>/<version>/{manifest.json, kit.json}.
        let entry = dir.join("acme").join("neon").join("1.2.0");
        assert!(entry.join("manifest.json").is_file());
        assert!(entry.join("kit.json").is_file());

        assert_eq!(s.get("acme/neon", "1.2.0").unwrap().unwrap(), m);
        assert_eq!(s.artifact("acme/neon", "1.2.0").unwrap().as_deref(), Some("{\"kit\":1}\n"));
        assert_eq!(s.get("acme/neon", "9.9.9").unwrap(), None, "unknown version ⇒ None");

        // list = the stored entry + the packaged fallback.
        let ids: Vec<String> = s.list().iter().map(|m| format!("{}@{}", m["id"].as_str().unwrap(), m["version"].as_str().unwrap())).collect();
        assert!(ids.contains(&"acme/neon@1.2.0".to_string()));
        assert!(ids.contains(&"bsc/react-ui@1.0.0".to_string()), "the packaged default is always listed: {ids:?}");

        s.remove("acme/neon", "1.2.0").unwrap();
        assert_eq!(s.get("acme/neon", "1.2.0").unwrap(), None);
        s.remove("acme/neon", "1.2.0").unwrap(); // no-op when absent
    }

    #[test]
    fn add_is_idempotent_for_identical_content_and_refuses_different_content() {
        let (s, _dir) = tmp_store();
        let m1 = s.add("acme/neon", "1.0.0", "component-kit", None, "same").unwrap();
        let m2 = s.add("acme/neon", "1.0.0", "component-kit", None, "same").unwrap();
        assert_eq!(m1, m2, "identical content ⇒ idempotent no-op");
        // Immutability: same id@version, different bytes ⇒ refused, entry untouched.
        let err = s.add("acme/neon", "1.0.0", "component-kit", None, "DIFFERENT").unwrap_err();
        assert!(err.contains("immutable"), "refusal names the immutability rule: {err}");
        assert_eq!(s.artifact("acme/neon", "1.0.0").unwrap().as_deref(), Some("same"));
    }

    #[test]
    fn add_verified_rejects_a_hash_mismatch_without_writing() {
        let (s, _dir) = tmp_store();
        let err = s
            .add_verified("acme/neon", "1.0.0", "component-kit", None, "payload", Some("deadbeef"))
            .unwrap_err();
        assert!(err.contains("sha256 mismatch"), "{err}");
        assert_eq!(s.get("acme/neon", "1.0.0").unwrap(), None, "nothing was stored");
        // The right expected hash goes through (case-insensitive).
        let expected = sha256_hex(b"payload").to_uppercase();
        s.add_verified("acme/neon", "1.0.0", "component-kit", None, "payload", Some(&expected)).unwrap();
    }

    #[test]
    fn verify_passes_a_good_entry_and_fails_a_corrupted_artifact() {
        let (s, dir) = tmp_store();
        s.add("acme/neon", "1.0.0", "component-kit", None, "good bytes").unwrap();
        assert_eq!(s.verify("acme/neon", "1.0.0").unwrap(), sha256_hex(b"good bytes"));
        // Corrupt the artifact on disk — verify must fail loudly.
        std::fs::write(dir.join("acme").join("neon").join("1.0.0").join("kit.json"), "tampered").unwrap();
        let err = s.verify("acme/neon", "1.0.0").unwrap_err();
        assert!(err.contains("FAILS verification"), "{err}");
        // A missing entry is a distinct error.
        assert!(s.verify("acme/none", "1.0.0").unwrap_err().contains("not in the kit store"));
    }

    #[test]
    fn packaged_default_resolves_without_being_materialized() {
        let (s, dir) = tmp_store();
        assert!(!dir.exists(), "nothing on disk");
        let m = s.get("bsc/react-ui", "1.0.0").unwrap().expect("packaged fallback resolves");
        assert_eq!(m["source"], "packaged");
        assert_eq!(m["kind"], "component-kit");
        let artifact = s.artifact("bsc/react-ui", "1.0.0").unwrap().expect("packaged artifact");
        assert_eq!(sha256_hex(artifact.as_bytes()), m["sha256"].as_str().unwrap(), "sidecar hash matches the embedded artifact bytes");
        // …and it verifies like any store entry.
        s.verify("bsc/react-ui", "1.0.0").unwrap();
    }

    #[test]
    fn packaged_sidecar_matches_the_embedded_artifact_and_the_generator_identity() {
        // Drift guard for the generated pair (reactUiKit.gen.test.ts writes both): the sidecar's
        // sha256 is the hash of the artifact's canonical LF bytes, and the identity is the packaged
        // pin every new blueprint gets.
        let meta: Value = serde_json::from_str(packaged_kit_meta_json()).unwrap();
        assert_eq!(meta["id"], "bsc/react-ui");
        assert_eq!(meta["version"], "1.0.0");
        assert_eq!(meta["kind"], "component-kit");
        assert_eq!(
            meta["sha256"].as_str().unwrap(),
            sha256_hex(packaged_artifact().as_bytes()),
            "react-ui-kit.meta.json drifted from react-ui.json — run `UPDATE_KITS=1 npx vitest run reactUiKit.gen`"
        );
        // The artifact self-describes the same identity (stamped by the generator).
        let artifact: Value = serde_json::from_str(&packaged_artifact()).unwrap();
        assert_eq!(artifact["id"], meta["id"]);
        assert_eq!(artifact["version"], meta["version"]);
    }

    #[test]
    fn packaged_entry_is_immutable_too() {
        let (s, _dir) = tmp_store();
        let err = s.add("bsc/react-ui", "1.0.0", "component-kit", None, "not the packaged bytes").unwrap_err();
        assert!(err.contains("immutable"), "{err}");
        // Materializing the EXACT packaged bytes is fine (idempotent with the fallback)…
        s.add("bsc/react-ui", "1.0.0", "component-kit", None, &packaged_artifact()).unwrap();
        // …and list stays deduped: one bsc/react-ui@1.0.0.
        let hits = s.list().iter().filter(|m| m["id"] == "bsc/react-ui" && m["version"] == "1.0.0").count();
        assert_eq!(hits, 1);
    }

    #[test]
    fn design_files_kind_stores_under_its_own_artifact_name() {
        let (s, dir) = tmp_store();
        s.add("acme/neon-design", "0.1.0", "design-files", None, "<!doctype html>…").unwrap();
        assert!(dir.join("acme").join("neon-design").join("0.1.0").join("design.dc.html").is_file());
        assert_eq!(s.artifact("acme/neon-design", "0.1.0").unwrap().as_deref(), Some("<!doctype html>…"));
        s.verify("acme/neon-design", "0.1.0").unwrap();
    }

    #[test]
    fn identity_validation_is_strict() {
        // Ids: publisher-scoped lowercase slugs only — never slugified (identity, not storage).
        for bad in ["react-ui", "a/b/c", "A/b", "a/", "/b", "a/../b", "a b/c", ""] {
            assert!(validate_id(bad).is_err(), "id '{bad}' must be rejected");
        }
        validate_id("bsc/react-ui").unwrap();
        validate_id("acme-corp/kit2").unwrap();
        // Versions: exact, path-safe.
        for bad in ["", ".", "..", "1.0/0", "1.0\\0", "@", "-1"] {
            assert!(validate_version(bad).is_err(), "version '{bad}' must be rejected");
        }
        validate_version("1.0.0").unwrap();
        validate_version("2.0.0-rc.1").unwrap();
        // Kinds: the closed set.
        assert!(validate_kind("blueprint").is_err());
        validate_kind("component-kit").unwrap();
        validate_kind("design-files").unwrap();
        // Refs: id@version.
        assert_eq!(split_ref("bsc/react-ui@1.0.0").unwrap(), ("bsc/react-ui", "1.0.0"));
        assert!(split_ref("bsc/react-ui").is_err());
        assert!(split_ref("@1.0.0").is_err());
    }

    // ── release-hardening: refuse hollow artifacts + assemble from the store (#3167) ─────────────

    #[test]
    fn validate_artifact_refuses_empty_zero_component_and_unparseable() {
        // Empty / whitespace-only content is refused for BOTH kinds (an empty --file / bare stdin).
        for kind in ["component-kit", "design-files"] {
            assert!(validate_artifact(kind, "").unwrap_err().contains("EMPTY"), "empty {kind} refused");
            assert!(validate_artifact(kind, "   \n\t ").unwrap_err().contains("EMPTY"), "whitespace {kind} refused");
        }
        // component-kit: unparseable JSON is refused (a silently-corrupted pipeline output).
        assert!(validate_artifact("component-kit", "{ not json").unwrap_err().contains("not valid JSON"));
        // component-kit: valid JSON but the WRONG shape — no `components` array — is refused.
        assert!(validate_artifact("component-kit", "{\"kit\":true}").unwrap_err().contains("no `components`"));
        assert!(validate_artifact("component-kit", "[1,2,3]").unwrap_err().contains("no `components`"), "a bare array isn't a kit");
        assert!(validate_artifact("component-kit", "\"a string\"").unwrap_err().contains("no `components`"));
        // component-kit: an EMPTY components array is the hollow-release case — refused with a clear reason.
        let hollow = "{\"id\":\"acme/neon\",\"version\":\"1.0.0\",\"kit\":{},\"components\":[]}";
        assert!(validate_artifact("component-kit", hollow).unwrap_err().contains("ZERO components"));
        // A real, shaped component-kit passes.
        let good = "{\"id\":\"acme/neon\",\"version\":\"1.0.0\",\"kit\":{\"id\":\"neon\"},\"components\":[{\"id\":\"btn\",\"kitId\":\"neon\"}]}";
        validate_artifact("component-kit", good).unwrap();
        // design-files: only the non-empty floor applies — opaque HTML passes (no JSON shape demanded).
        validate_artifact("design-files", "<!doctype html>…").unwrap();
    }

    #[test]
    fn assemble_artifact_builds_a_shaped_non_empty_release_that_validates() {
        let kit = json!({ "id": "neon", "name": "neon", "tech": "react", "style": "studio" });
        let components = vec![
            json!({ "id": "btn", "name": "Button", "kitId": "neon" }),
            json!({ "id": "card", "name": "Card", "kitId": "neon" }),
        ];
        // The RELEASE identity (id@version) is the positional args, NOT the working kit's own id.
        let content = assemble_artifact("acme/neon", "2.0.0", kit.clone(), components.clone());
        let parsed: Value = serde_json::from_str(&content).unwrap();
        assert_eq!(parsed["id"], "acme/neon");
        assert_eq!(parsed["version"], "2.0.0");
        assert_eq!(parsed["kit"], kit, "the kit record rides verbatim");
        assert_eq!(parsed["components"].as_array().unwrap().len(), 2, "every gathered component is present");
        assert!(content.ends_with("\n"), "canonical trailing newline");
        // The assembled artifact is exactly the shape the `add` verb's validation gate accepts.
        validate_artifact("component-kit", &content).unwrap();
        // …and a store round-trips it (proving it's a real, verifiable component-kit entry).
        let (s, _dir) = tmp_store();
        s.add("acme/neon", "2.0.0", "component-kit", None, &content).unwrap();
        s.verify("acme/neon", "2.0.0").unwrap();
    }

    #[test]
    fn assemble_artifact_with_no_components_is_caught_by_the_validation_gate() {
        // An assembly that gathered nothing yields an empty `components` array — refused by the gate the
        // `add` verb runs, so a hollow --from-store release is never stored.
        let content = assemble_artifact("acme/neon", "1.0.0", json!({ "id": "neon" }), vec![]);
        assert!(validate_artifact("component-kit", &content).unwrap_err().contains("ZERO components"));
    }
}

tests.src:
//! The global UI-kit store (#2465) — immutable, versioned kit artifacts shared across blueprints.
//!
//! A blueprint REFERENCES a UI kit (a lockfile-style pin `{ id, version, hash, source? }`) instead
//! of embedding it, so the same kit is stored — and downloaded — exactly once no matter how many
//! blueprints pin it. Layout, one entry per `id@version`:
//!
//! ```text
//! ~/.base-studio-code/kits/<publisher>/<name>/<version>/
//!   manifest.json     # { id, version, sha256, kind, source? }
//!   kit.json          # the artifact (design-files kind: design.dc.html instead)
//! ```
//!
//! (The same `kits/` root also holds the FLAT component-library kit records —
//! `kits/<id>.json`, the `bsc component kit` verbatim-JSON store. The two coexist:
//! versioned entries are publisher DIRECTORIES, flat records are `.json` FILES, and
//! [`KitStore::list`] walks only the directory shape.)
//!
//! Identity is `id` (a publisher-scoped slug, `bsc/react-ui`) + an exact semver `version` + the
//! sha256 of the artifact bytes. A published `id@version` is IMMUTABLE: [`KitStore::add`] refuses to
//! overwrite an existing version with different content (changing a kit means bumping the version),
//! and is an idempotent no-op for identical content. `add` can also verify an expected sha256 BEFORE
//! writing (the resolve flow's fetch verification, #2433 posture) — on mismatch nothing is stored.
//!
//! The PACKAGED default `bsc/react-ui@1.0.0` (the generated `data/components/react-ui.json`, hash
//! sidecar `data/ui/react-ui-kit.meta.json`, both stamped by `reactUiKit.gen.test.ts`) resolves as a
//! store entry WITHOUT being copied at install time: `get`/`artifact`/`list`/`verify` fall back to
//! the packaged bytes (read at runtime by `bsc_util::packaged`) when the entry isn't materialized on
//! disk — so every install has the default kit with zero setup, the same store-lookup →
//! packaged-fallback overlay pattern as `@data`.

use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::path::{Path, PathBuf};

/// The packaged default kit's artifact — the generated `react-ui.json` (see the module docs).
/// CRLF-normalized before hashing/serving: the file is pinned `eol=lf` in .gitattributes, but a
/// pre-pin checkout may still hold it CRLF, and LF is the canonical (hash-recorded) byte form.
///
/// LOADED AT RUNTIME, not `include_str!`'d (see [`bsc_util::packaged`]): at 5.3 MB and ~190 commits
/// a month this file made every record edit recompile this crate, `bsc-component` and `bsc`.
/// Cached in a `OnceLock` and handed out as `&'static str`, so callers are unchanged.
pub fn packaged_kit_json() -> &'static str {
    static V: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    V.get_or_init(|| bsc_util::packaged::read_required("components/react-ui.json")).as_str()
}

/// The packaged kit's hash sidecar `{ id, version, kind, sha256 }` — generated alongside the
/// artifact so the packaged entry's manifest (incl. its content hash) needs no runtime hashing.
///
/// Runtime-loaded for the same reason as [`packaged_kit_json`], even though it is only 156 bytes:
/// it is regenerated in LOCKSTEP with the artifact (186 commits against 190), so embedding it alone
/// would have preserved the entire rebuild cost. Churn, not size, is what decides.
pub fn packaged_kit_meta_json() -> &'static str {
    static V: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    V.get_or_init(|| bsc_util::packaged::read_required("ui/react-ui-kit.meta.json")).as_str()
}

/// The two artifact kinds a store entry can hold (#2465): a component kit (a self-contained kit
/// JSON) or a design-files bundle (a `.dc.html` design document). Sibling artifacts — own id, same
/// store.
pub const KIT_KINDS: &[&str] = &["component-kit", "design-files"];

/// Lowercase hex sha256 of `bytes` — the store's one content-hash form.
pub fn sha256_hex(bytes: &[u8]) -> String {
    Sha256::digest(bytes).iter().map(|b| format!("{b:02x}")).collect()
}

/// The packaged artifact's canonical (LF) bytes.
fn packaged_artifact() -> String {
    packaged_kit_json().replace("\r\n", "\n")
}

/// The packaged entry's manifest, from the embedded sidecar, with `"source": "packaged"` stamped so
/// a reader can tell it apart from a fetched entry. `None` only on a malformed sidecar (guarded by
/// tests, so not in practice).
pub fn packaged_manifest() -> Option<Value> {
    let mut m: Value = serde_json::from_str(packaged_kit_meta_json()).ok()?;
    m.as_object_mut()?.insert("source".into(), json!("packaged"));
    Some(m)
}

/// Validate a store id: a publisher-scoped slug `publisher/name`, each segment lowercase
/// `[a-z0-9-]` starting alphanumeric. Strict (reject, not slugify) — the id IS the identity a hash
/// is pinned against, so silently rewriting it would corrupt the reference.
pub fn validate_id(id: &str) -> Result<(), String> {
    let seg_ok = |s: &str| {
        s.starts_with(|c: char| c.is_ascii_lowercase() || c.is_ascii_digit())
            && s.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
    };
    match id.split('/').collect::<Vec<_>>().as_slice() {
        [publisher, name] if seg_ok(publisher) && seg_ok(name) => Ok(()),
        _ => Err(format!(
            "invalid kit id '{id}' — want a publisher-scoped slug like 'bsc/react-ui' (lowercase [a-z0-9-], one '/')"
        )),
    }
}

/// Validate a version: `[0-9A-Za-z.-]`, starting alphanumeric (so `.`/`..`/empty can never form a
/// path segment). Exact versions only — pins carry no ranges.
pub fn validate_version(version: &str) -> Result<(), String> {
    let ok = version.starts_with(|c: char| c.is_ascii_alphanumeric())
        && version.chars().all(|c| c.is_ascii_alphanumeric() || c == '.' || c == '-');
    if ok { Ok(()) } else { Err(format!("invalid kit version '{version}' — want a semver like '1.0.0'")) }
}

fn validate_kind(kind: &str) -> Result<(), String> {
    if KIT_KINDS.contains(&kind) {
        Ok(())
    } else {
        Err(format!("invalid kit kind '{kind}' — want one of: {}", KIT_KINDS.join(" | ")))
    }
}

/// The artifact's file name for a kind (deterministic from the manifest, so no extra field).
fn artifact_name(kind: &str) -> &'static str {
    if kind == "design-files" { "design.dc.html" } else { "kit.json" }
}

/// Split an `id@version` ref on the LAST `@` (the id itself never carries one, but be forgiving).
pub fn split_ref(kit_ref: &str) -> Result<(&str, &str), String> {
    match kit_ref.rsplit_once('@') {
        Some((id, version)) if !id.is_empty() && !version.is_empty() => Ok((id, version)),
        _ => Err(format!("invalid kit ref '{kit_ref}' — want '<id>@<version>' (e.g. bsc/react-ui@1.0.0)")),
    }
}

/// Refuse a HOLLOW or shapeless release BEFORE the immutable entry is written (#3167). Releases saved a
/// designer's session, but `add` used to accept whatever bytes it was handed — so a silently-failed
/// assembly pipeline could store an empty or componentless "kit". A release must carry a real payload:
///
/// - **any kind:** empty / whitespace-only content is refused (an empty `--file`, or nothing on stdin —
///   the pipeline produced no bytes);
/// - **`component-kit`:** the content must parse as a JSON OBJECT holding a NON-EMPTY `components`
///   array — the exact shape `release add` stores — so a parse failure, a non-object, a missing
///   `components`, or zero components is refused (a silently-failed assembly, never a real kit);
/// - **`design-files`:** an opaque `.dc.html` bundle, so only the non-empty floor applies.
///
/// The `release add` verb calls this before [`KitStore::add`]/[`KitStore::add_verified`], so no path can
/// persist a hollow entry. (The store itself stays content-agnostic — it hashes opaque bytes — so this
/// shape gate lives at the one user-facing entry point, not in the immutable-store primitive.)
pub fn validate_artifact(kind: &str, content: &str) -> Result<(), String> {
    if content.trim().is_empty() {
        return Err(
            "refusing to store an EMPTY release artifact — the release produced no bytes (an empty --file, or nothing on stdin)"
                .to_string(),
        );
    }
    if kind == "component-kit" {
        let value: Value = serde_json::from_str(content).map_err(|e| {
            format!(
                "release artifact is not valid JSON: {e} — a component-kit release must be the kit artifact object {{ id, version, kit, components }}"
            )
        })?;
        let components = value.get("components").and_then(Value::as_array).ok_or_else(|| {
            "release artifact has no `components` array — it isn't a kit artifact ({ id, version, kit, components }); refusing to store a shapeless release"
                .to_string()
        })?;
        if components.is_empty() {
            return Err(
                "release artifact has ZERO components — refusing to store a hollow release (the assembly produced no components)"
                    .to_string(),
            );
        }
    }
    Ok(())
}

/// Assemble a `component-kit` release artifact from a live kit + its components (#3167, the
/// `--from-store` one-shot) — so a release no longer has to be hand-piped through `--file`. Produces the
/// SAME shape `release add --file` expects: a JSON object `{ id, version, kit, components }`, where `kit`
/// is the kit record from the component library and `components` is every component the caller gathered
/// for it. `id`/`version` are the RELEASE's store identity (the positional `add` args), NOT the working
/// kit's own id. Serialized pretty with a trailing newline — the artifact's canonical form (matching the
/// packaged `react-ui.json`). The emptiness floor is [`validate_artifact`], which the `add` verb runs on
/// this result, so an assembly that gathered no components is refused there rather than silently stored.
pub fn assemble_artifact(id: &str, version: &str, kit: Value, components: Vec<Value>) -> String {
    let artifact = json!({ "id": id, "version": version, "kit": kit, "components": components });
    // Pretty + trailing newline mirrors the generator's canonical bytes (`JSON.stringify(…, 2) + "\n"`).
    let mut s = serde_json::to_string_pretty(&artifact).unwrap_or_else(|_| "{}".to_string());
    s.push('\n');
    s
}

/// A handle to the versioned kit store rooted at a directory (`~/.base-studio-code/kits/` by
/// default). All operations resolve store-first, then fall back to the packaged entry.
pub struct KitStore {
    dir: PathBuf,
}

impl KitStore {
    pub fn new(dir: impl Into<PathBuf>) -> Self {
        KitStore { dir: dir.into() }
    }

    /// The default user store at `~/.base-studio-code/kits/`. `Err` when no home dir resolves.
    pub fn open_default() -> Result<Self, String> {
        let base = bsc_util::bsc_base_dir()
            .ok_or("could not resolve a home directory; set HOME/USERPROFILE")?;
        Ok(KitStore::new(base.join("kits")))
    }

    pub fn dir(&self) -> &Path {
        &self.dir
    }

    /// The on-disk entry dir for `id@version` (validated, so it can never escape the store root).
    fn entry_dir(&self, id: &str, version: &str) -> Result<PathBuf, String> {
        validate_id(id)?;
        validate_version(version)?;
        let (publisher, name) = id.split_once('/').expect("validated id has one '/'");
        Ok(self.dir.join(publisher).join(name).join(version))
    }

    /// The manifest of an entry MATERIALIZED on disk, or `None`.
    fn manifest_on_disk(&self, id: &str, version: &str) -> Result<Option<Value>, String> {
        let path = self.entry_dir(id, version)?.join("manifest.json");
        match std::fs::read_to_string(&path) {
            Ok(s) => Ok(Some(
                serde_json::from_str(&s).map_err(|e| format!("corrupt manifest {}: {e}", path.display()))?,
            )),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
            Err(e) => Err(format!("read {}: {e}", path.display())),
        }
    }

    /// Whether `id@version` is the packaged default entry.
    fn is_packaged(id: &str, version: &str) -> bool {
        packaged_manifest().is_some_and(|m| {
            m.get("id").and_then(Value::as_str) == Some(id)
                && m.get("version").and_then(Value::as_str) == Some(version)
        })
    }

    /// One entry's manifest: the on-disk entry, else the packaged fallback, else `None`.
    pub fn get(&self, id: &str, version: &str) -> Result<Option<Value>, String> {
        if let Some(m) = self.manifest_on_disk(id, version)? {
            return Ok(Some(m));
        }
        Ok(if Self::is_packaged(id, version) { packaged_manifest() } else { None })
    }

    /// One entry's artifact text: on-disk, else the packaged fallback, else `None`.
    pub fn artifact(&self, id: &str, version: &str) -> Result<Option<String>, String> {
        if let Some(m) = self.manifest_on_disk(id, version)? {
            let kind = m.get("kind").and_then(Value::as_str).unwrap_or("component-kit");
            let path = self.entry_dir(id, version)?.join(artifact_name(kind));
            return std::fs::read_to_string(&path)
                .map(Some)
                .map_err(|e| format!("read {}: {e}", path.display()));
        }
        Ok(if Self::is_packaged(id, version) { Some(packaged_artifact()) } else { None })
    }

    /// Add `id@version` with the artifact `content`. Computes the sha256; when `expected_sha256` is
    /// given the content is verified BEFORE anything is written (mismatch ⇒ `Err`, no store entry —
    /// the resolve flow's loud rejection). Immutability: an existing `id@version` (on disk or the
    /// packaged entry) with a DIFFERENT hash is refused; identical content is an idempotent no-op.
    /// Returns the entry's manifest.
    pub fn add(
        &self,
        id: &str,
        version: &str,
        kind: &str,
        source: Option<&str>,
        content: &str,
    ) -> Result<Value, String> {
        self.add_verified(id, version, kind, source, content, None)
    }

    /// [`KitStore::add`] with an optional expected sha256 (lowercase hex) verified before writing.
    pub fn add_verified(
        &self,
        id: &str,
        version: &str,
        kind: &str,
        source: Option<&str>,
        content: &str,
        expected_sha256: Option<&str>,
    ) -> Result<Value, String> {
        validate_id(id)?;
        validate_version(version)?;
        validate_kind(kind)?;
        let hash = sha256_hex(content.as_bytes());
        if let Some(expected) = expected_sha256 {
            if !expected.eq_ignore_ascii_case(&hash) {
                return Err(format!(
                    "sha256 mismatch for {id}@{version}: expected {expected}, got {hash} — refusing to store"
                ));
            }
        }
        // Immutability: a published id@version never changes content. `get` also covers the
        // packaged entry, so the embedded default can't be shadowed by different bytes either.
        if let Some(existing) = self.get(id, version)? {
            let existing_hash = existing.get("sha256").and_then(Value::as_str).unwrap_or("");
            if existing_hash.eq_ignore_ascii_case(&hash) {
                return Ok(existing); // identical content — idempotent
            }
            return Err(format!(
                "{id}@{version} already exists with different content (sha256 {existing_hash} vs {hash}) — published versions are immutable; bump the version"
            ));
        }
        let mut manifest = json!({ "id": id, "version": version, "sha256": hash, "kind": kind });
        if let Some(src) = source.filter(|s| !s.is_empty()) {
            manifest["source"] = json!(src);
        }
        let dir = self.entry_dir(id, version)?;
        std::fs::create_dir_all(&dir).map_err(|e| format!("create {}: {e}", dir.display()))?;
        std::fs::write(dir.join(artifact_name(kind)), content)
            .map_err(|e| format!("write artifact: {e}"))?;
        let pretty = serde_json::to_string_pretty(&manifest).map_err(|e| e.to_string())?;
        std::fs::write(dir.join("manifest.json"), pretty).map_err(|e| format!("write manifest: {e}"))?;
        Ok(manifest)
    }

    /// Every entry's manifest: the on-disk `<publisher>/<name>/<version>/manifest.json` walk plus
    /// the packaged entry when it isn't materialized. Sorted by (id, version) for stable output.
    /// Flat `kits/<id>.json` files (the component-library kit records) are ignored by shape.
    pub fn list(&self) -> Vec<Value> {
        let mut out: Vec<Value> = Vec::new();
        let dirs = |p: &Path| -> Vec<PathBuf> {
            std::fs::read_dir(p)
                .map(|rd| rd.flatten().map(|e| e.path()).filter(|p| p.is_dir()).collect())
                .unwrap_or_default()
        };
        for publisher in dirs(&self.dir) {
            for name in dirs(&publisher) {
                for version in dirs(&name) {
                    if let Ok(s) = std::fs::read_to_string(version.join("manifest.json")) {
                        if let Ok(m) = serde_json::from_str::<Value>(&s) {
                            out.push(m);
                        }
                    }
                }
            }
        }
        if let Some(packaged) = packaged_manifest() {
            let same = |m: &Value| {
                m.get("id") == packaged.get("id") && m.get("version") == packaged.get("version")
            };
            if !out.iter().any(same) {
                out.push(packaged);
            }
        }
        let key = |m: &Value| {
            (
                m.get("id").and_then(Value::as_str).unwrap_or("").to_string(),
                m.get("version").and_then(Value::as_str).unwrap_or("").to_string(),
            )
        };
        out.sort_by_key(key);
        out
    }

    /// Remove a materialized entry (no-op when absent on disk). The packaged entry is embedded in
    /// the app and cannot be removed — removing its materialized copy just falls back to it.
    pub fn remove(&self, id: &str, version: &str) -> Result<(), String> {
        let dir = self.entry_dir(id, version)?;
        if dir.exists() {
            std::fs::remove_dir_all(&dir).map_err(|e| format!("remove {}: {e}", dir.display()))?;
        }
        Ok(())
    }

    /// Recompute an entry's artifact hash and check it against its manifest's `sha256`. `Ok(hash)`
    /// when they match; `Err` on a missing entry or a mismatch (a corrupted/tampered artifact).
    pub fn verify(&self, id: &str, version: &str) -> Result<String, String> {
        let manifest = self
            .get(id, version)?
            .ok_or_else(|| format!("{id}@{version} is not in the kit store"))?;
        let artifact = self
            .artifact(id, version)?
            .ok_or_else(|| format!("{id}@{version} has no artifact"))?;
        let recorded = manifest.get("sha256").and_then(Value::as_str).unwrap_or("").to_string();
        let actual = sha256_hex(artifact.as_bytes());
        if recorded.eq_ignore_ascii_case(&actual) {
            Ok(actual)
        } else {
            Err(format!(
                "{id}@{version} FAILS verification: manifest records sha256 {recorded}, artifact hashes to {actual}"
            ))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tmp_store() -> (KitStore, PathBuf) {
        use std::sync::atomic::{AtomicU64, Ordering};
        static N: AtomicU64 = AtomicU64::new(0);
        let dir = std::env::temp_dir().join(format!(
            "bsc-ui-kit-store-{}-{}",
            std::process::id(),
            N.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = std::fs::remove_dir_all(&dir);
        (KitStore::new(dir.clone()), dir)
    }

    #[test]
    fn add_get_artifact_list_remove_round_trips() {
        let (s, dir) = tmp_store();
        let m = s.add("acme/neon", "1.2.0", "component-kit", Some("https://gist.github.com/x"), "{\"kit\":1}\n").unwrap();
        // Manifest shape: id/version/sha256/kind/source.
        assert_eq!(m["id"], "acme/neon");
        assert_eq!(m["version"], "1.2.0");
        assert_eq!(m["kind"], "component-kit");
        assert_eq!(m["source"], "https://gist.github.com/x");
        assert_eq!(m["sha256"].as_str().unwrap(), sha256_hex(b"{\"kit\":1}\n"));

        // On-disk layout: kits/<publisher>/<name>/<version>/{manifest.json, kit.json}.
        let entry = dir.join("acme").join("neon").join("1.2.0");
        assert!(entry.join("manifest.json").is_file());
        assert!(entry.join("kit.json").is_file());

        assert_eq!(s.get("acme/neon", "1.2.0").unwrap().unwrap(), m);
        assert_eq!(s.artifact("acme/neon", "1.2.0").unwrap().as_deref(), Some("{\"kit\":1}\n"));
        assert_eq!(s.get("acme/neon", "9.9.9").unwrap(), None, "unknown version ⇒ None");

        // list = the stored entry + the packaged fallback.
        let ids: Vec<String> = s.list().iter().map(|m| format!("{}@{}", m["id"].as_str().unwrap(), m["version"].as_str().unwrap())).collect();
        assert!(ids.contains(&"acme/neon@1.2.0".to_string()));
        assert!(ids.contains(&"bsc/react-ui@1.0.0".to_string()), "the packaged default is always listed: {ids:?}");

        s.remove("acme/neon", "1.2.0").unwrap();
        assert_eq!(s.get("acme/neon", "1.2.0").unwrap(), None);
        s.remove("acme/neon", "1.2.0").unwrap(); // no-op when absent
    }

    #[test]
    fn add_is_idempotent_for_identical_content_and_refuses_different_content() {
        let (s, _dir) = tmp_store();
        let m1 = s.add("acme/neon", "1.0.0", "component-kit", None, "same").unwrap();
        let m2 = s.add("acme/neon", "1.0.0", "component-kit", None, "same").unwrap();
        assert_eq!(m1, m2, "identical content ⇒ idempotent no-op");
        // Immutability: same id@version, different bytes ⇒ refused, entry untouched.
        let err = s.add("acme/neon", "1.0.0", "component-kit", None, "DIFFERENT").unwrap_err();
        assert!(err.contains("immutable"), "refusal names the immutability rule: {err}");
        assert_eq!(s.artifact("acme/neon", "1.0.0").unwrap().as_deref(), Some("same"));
    }

    #[test]
    fn add_verified_rejects_a_hash_mismatch_without_writing() {
        let (s, _dir) = tmp_store();
        let err = s
            .add_verified("acme/neon", "1.0.0", "component-kit", None, "payload", Some("deadbeef"))
            .unwrap_err();
        assert!(err.contains("sha256 mismatch"), "{err}");
        assert_eq!(s.get("acme/neon", "1.0.0").unwrap(), None, "nothing was stored");
        // The right expected hash goes through (case-insensitive).
        let expected = sha256_hex(b"payload").to_uppercase();
        s.add_verified("acme/neon", "1.0.0", "component-kit", None, "payload", Some(&expected)).unwrap();
    }

    #[test]
    fn verify_passes_a_good_entry_and_fails_a_corrupted_artifact() {
        let (s, dir) = tmp_store();
        s.add("acme/neon", "1.0.0", "component-kit", None, "good bytes").unwrap();
        assert_eq!(s.verify("acme/neon", "1.0.0").unwrap(), sha256_hex(b"good bytes"));
        // Corrupt the artifact on disk — verify must fail loudly.
        std::fs::write(dir.join("acme").join("neon").join("1.0.0").join("kit.json"), "tampered").unwrap();
        let err = s.verify("acme/neon", "1.0.0").unwrap_err();
        assert!(err.contains("FAILS verification"), "{err}");
        // A missing entry is a distinct error.
        assert!(s.verify("acme/none", "1.0.0").unwrap_err().contains("not in the kit store"));
    }

    #[test]
    fn packaged_default_resolves_without_being_materialized() {
        let (s, dir) = tmp_store();
        assert!(!dir.exists(), "nothing on disk");
        let m = s.get("bsc/react-ui", "1.0.0").unwrap().expect("packaged fallback resolves");
        assert_eq!(m["source"], "packaged");
        assert_eq!(m["kind"], "component-kit");
        let artifact = s.artifact("bsc/react-ui", "1.0.0").unwrap().expect("packaged artifact");
        assert_eq!(sha256_hex(artifact.as_bytes()), m["sha256"].as_str().unwrap(), "sidecar hash matches the embedded artifact bytes");
        // …and it verifies like any store entry.
        s.verify("bsc/react-ui", "1.0.0").unwrap();
    }

    #[test]
    fn packaged_sidecar_matches_the_embedded_artifact_and_the_generator_identity() {
        // Drift guard for the generated pair (reactUiKit.gen.test.ts writes both): the sidecar's
        // sha256 is the hash of the artifact's canonical LF bytes, and the identity is the packaged
        // pin every new blueprint gets.
        let meta: Value = serde_json::from_str(packaged_kit_meta_json()).unwrap();
        assert_eq!(meta["id"], "bsc/react-ui");
        assert_eq!(meta["version"], "1.0.0");
        assert_eq!(meta["kind"], "component-kit");
        assert_eq!(
            meta["sha256"].as_str().unwrap(),
            sha256_hex(packaged_artifact().as_bytes()),
            "react-ui-kit.meta.json drifted from react-ui.json — run `UPDATE_KITS=1 npx vitest run reactUiKit.gen`"
        );
        // The artifact self-describes the same identity (stamped by the generator).
        let artifact: Value = serde_json::from_str(&packaged_artifact()).unwrap();
        assert_eq!(artifact["id"], meta["id"]);
        assert_eq!(artifact["version"], meta["version"]);
    }

    #[test]
    fn packaged_entry_is_immutable_too() {
        let (s, _dir) = tmp_store();
        let err = s.add("bsc/react-ui", "1.0.0", "component-kit", None, "not the packaged bytes").unwrap_err();
        assert!(err.contains("immutable"), "{err}");
        // Materializing the EXACT packaged bytes is fine (idempotent with the fallback)…
        s.add("bsc/react-ui", "1.0.0", "component-kit", None, &packaged_artifact()).unwrap();
        // …and list stays deduped: one bsc/react-ui@1.0.0.
        let hits = s.list().iter().filter(|m| m["id"] == "bsc/react-ui" && m["version"] == "1.0.0").count();
        assert_eq!(hits, 1);
    }

    #[test]
    fn design_files_kind_stores_under_its_own_artifact_name() {
        let (s, dir) = tmp_store();
        s.add("acme/neon-design", "0.1.0", "design-files", None, "<!doctype html>…").unwrap();
        assert!(dir.join("acme").join("neon-design").join("0.1.0").join("design.dc.html").is_file());
        assert_eq!(s.artifact("acme/neon-design", "0.1.0").unwrap().as_deref(), Some("<!doctype html>…"));
        s.verify("acme/neon-design", "0.1.0").unwrap();
    }

    #[test]
    fn identity_validation_is_strict() {
        // Ids: publisher-scoped lowercase slugs only — never slugified (identity, not storage).
        for bad in ["react-ui", "a/b/c", "A/b", "a/", "/b", "a/../b", "a b/c", ""] {
            assert!(validate_id(bad).is_err(), "id '{bad}' must be rejected");
        }
        validate_id("bsc/react-ui").unwrap();
        validate_id("acme-corp/kit2").unwrap();
        // Versions: exact, path-safe.
        for bad in ["", ".", "..", "1.0/0", "1.0\\0", "@", "-1"] {
            assert!(validate_version(bad).is_err(), "version '{bad}' must be rejected");
        }
        validate_version("1.0.0").unwrap();
        validate_version("2.0.0-rc.1").unwrap();
        // Kinds: the closed set.
        assert!(validate_kind("blueprint").is_err());
        validate_kind("component-kit").unwrap();
        validate_kind("design-files").unwrap();
        // Refs: id@version.
        assert_eq!(split_ref("bsc/react-ui@1.0.0").unwrap(), ("bsc/react-ui", "1.0.0"));
        assert!(split_ref("bsc/react-ui").is_err());
        assert!(split_ref("@1.0.0").is_err());
    }

    // ── release-hardening: refuse hollow artifacts + assemble from the store (#3167) ─────────────

    #[test]
    fn validate_artifact_refuses_empty_zero_component_and_unparseable() {
        // Empty / whitespace-only content is refused for BOTH kinds (an empty --file / bare stdin).
        for kind in ["component-kit", "design-files"] {
            assert!(validate_artifact(kind, "").unwrap_err().contains("EMPTY"), "empty {kind} refused");
            assert!(validate_artifact(kind, "   \n\t ").unwrap_err().contains("EMPTY"), "whitespace {kind} refused");
        }
        // component-kit: unparseable JSON is refused (a silently-corrupted pipeline output).
        assert!(validate_artifact("component-kit", "{ not json").unwrap_err().contains("not valid JSON"));
        // component-kit: valid JSON but the WRONG shape — no `components` array — is refused.
        assert!(validate_artifact("component-kit", "{\"kit\":true}").unwrap_err().contains("no `components`"));
        assert!(validate_artifact("component-kit", "[1,2,3]").unwrap_err().contains("no `components`"), "a bare array isn't a kit");
        assert!(validate_artifact("component-kit", "\"a string\"").unwrap_err().contains("no `components`"));
        // component-kit: an EMPTY components array is the hollow-release case — refused with a clear reason.
        let hollow = "{\"id\":\"acme/neon\",\"version\":\"1.0.0\",\"kit\":{},\"components\":[]}";
        assert!(validate_artifact("component-kit", hollow).unwrap_err().contains("ZERO components"));
        // A real, shaped component-kit passes.
        let good = "{\"id\":\"acme/neon\",\"version\":\"1.0.0\",\"kit\":{\"id\":\"neon\"},\"components\":[{\"id\":\"btn\",\"kitId\":\"neon\"}]}";
        validate_artifact("component-kit", good).unwrap();
        // design-files: only the non-empty floor applies — opaque HTML passes (no JSON shape demanded).
        validate_artifact("design-files", "<!doctype html>…").unwrap();
    }

    #[test]
    fn assemble_artifact_builds_a_shaped_non_empty_release_that_validates() {
        let kit = json!({ "id": "neon", "name": "neon", "tech": "react", "style": "studio" });
        let components = vec![
            json!({ "id": "btn", "name": "Button", "kitId": "neon" }),
            json!({ "id": "card", "name": "Card", "kitId": "neon" }),
        ];
        // The RELEASE identity (id@version) is the positional args, NOT the working kit's own id.
        let content = assemble_artifact("acme/neon", "2.0.0", kit.clone(), components.clone());
        let parsed: Value = serde_json::from_str(&content).unwrap();
        assert_eq!(parsed["id"], "acme/neon");
        assert_eq!(parsed["version"], "2.0.0");
        assert_eq!(parsed["kit"], kit, "the kit record rides verbatim");
        assert_eq!(parsed["components"].as_array().unwrap().len(), 2, "every gathered component is present");
        assert!(content.ends_with("\n"), "canonical trailing newline");
        // The assembled artifact is exactly the shape the `add` verb's validation gate accepts.
        validate_artifact("component-kit", &content).unwrap();
        // …and a store round-trips it (proving it's a real, verifiable component-kit entry).
        let (s, _dir) = tmp_store();
        s.add("acme/neon", "2.0.0", "component-kit", None, &content).unwrap();
        s.verify("acme/neon", "2.0.0").unwrap();
    }

    #[test]
    fn assemble_artifact_with_no_components_is_caught_by_the_validation_gate() {
        // An assembly that gathered nothing yields an empty `components` array — refused by the gate the
        // `add` verb runs, so a hollow --from-store release is never stored.
        let content = assemble_artifact("acme/neon", "1.0.0", json!({ "id": "neon" }), vec![]);
        assert!(validate_artifact("component-kit", &content).unwrap_err().contains("ZERO components"));
    }
}

